def set_gui_state(**kwargs):
    with _GUI_LOCK:
        _GUI_STATE.update(kwargs)

def get_gui_state():
    with _GUI_LOCK:
        return dict(_GUI_STATE)

def set_gui_action(action):
    set_gui_state(last_action=action)
    dbg(f"GUI ACTION context={action}")

def dump_all_threads(reason, extra=""):
    try:
        with open(HANG_LOG, "a", encoding="utf-8") as fp:
            fp.write("\n" + "=" * 110 + "\n")
            fp.write(time.strftime("%Y-%m-%d %H:%M:%S") + "\n")
            fp.write(f"REASON: {reason}\n")
            if extra:
                fp.write(extra + "\n")
            fp.write("=" * 110 + "\n")

            frames = sys._current_frames()
            for thread in threading.enumerate():
                fp.write(
                    f"\n--- THREAD name={thread.name} ident={thread.ident} "
                    f"daemon={thread.daemon} ---\n"
                )
                frame = frames.get(thread.ident)
                if frame is None:
                    fp.write("<no Python frame>\n")
                else:
                    fp.write("".join(traceback.format_stack(frame)))
            fp.flush()
        dbg(f"THREAD DUMP written reason={reason}")
    except Exception:
        try:
            logging.exception("dump_all_threads failed")
        except Exception:
            pass

def windows_hung_status(hwnd):
    if os.name != "nt" or not hwnd:
        return None
    try:
        user32 = ctypes.windll.user32
        return bool(user32.IsHungAppWindow(ctypes.c_void_p(int(hwnd))))
    except Exception:
        return None

def dbg(message):
    try:
        logging.debug(message)
    except Exception:
        pass

def set_draw_state(**kwargs):
    with _DRAW_LOCK:
        _DRAW_STATE.update(kwargs)

def get_draw_state():
    with _DRAW_LOCK:
        return dict(_DRAW_STATE)

def watchdog_loop():
    """
    Background watchdog.

    It monitors two independent things:

    1. draw_ring execution time
       - catches a Python callback stuck inside Ring View drawing.

    2. GUI mainloop heartbeat
       - App schedules a Tk `after(250, ...)` heartbeat.
       - if that heartbeat stops for > 2 seconds, the Tk event loop is blocked,
         even if draw_ring already returned.
       - this is the important detector for Windows "Not Responding".
    """
    last_draw_dump_started = -1.0

    while True:
        time.sleep(0.50)
        now = time.monotonic()

        # --------------------------------------------------------------
        # A. Ring draw watchdog
        # --------------------------------------------------------------
        draw = get_draw_state()
        if draw["active"]:
            elapsed = now - draw["started"]
            if elapsed >= 3.0 and draw["started"] != last_draw_dump_started:
                last_draw_dump_started = draw["started"]
                gui = get_gui_state()
                extra = (
                    f"draw_elapsed={elapsed:.2f}s "
                    f"draw_view={draw['view']} draw_stage={draw['stage']} "
                    f"last_gui_action={gui['last_action']} "
                    f"last_gui_view={gui['last_view']}"
                )
                dump_all_threads("RING_DRAW_STALL", extra)

        # --------------------------------------------------------------
        # B. Whole Tk event-loop heartbeat watchdog
        # --------------------------------------------------------------
        gui = get_gui_state()
        if not gui["enabled"] or gui["last_heartbeat"] <= 0:
            continue

        stale = now - gui["last_heartbeat"]

        if stale >= 2.0:
            if not gui["stall_dumped"]:
                hung = windows_hung_status(gui["hwnd"])
                extra = (
                    f"heartbeat_stale={stale:.2f}s "
                    f"heartbeat_seq={gui['heartbeat_seq']} "
                    f"last_view={gui['last_view']} "
                    f"last_action={gui['last_action']} "
                    f"hwnd={gui['hwnd']} "
                    f"IsHungAppWindow={hung} "
                    f"draw_active={draw['active']} "
                    f"draw_stage={draw['stage']}"
                )
                set_gui_state(
                    stall_dumped=True,
                    stall_started=now,
                )
                dbg("GUI HEARTBEAT STALL detected " + extra)
                dump_all_threads("GUI_EVENT_LOOP_STALL", extra)

        else:
            # If heartbeat came back after a stall, log the recovery.
            if gui["stall_dumped"]:
                duration = now - gui["stall_started"]
                dbg(
                    f"GUI HEARTBEAT RECOVERED stall_window={duration:.2f}s "
                    f"seq={gui['heartbeat_seq']} view={gui['last_view']} "
                    f"action={gui['last_action']}"
                )
                set_gui_state(
                    stall_dumped=False,
                    stall_started=0.0,
                )

threading.Thread(
    target=watchdog_loop,
    name="FullGUIWatchdog",
    daemon=True,
).start()

