# Technology check data comes from the existing private setup profile.
# Load before defining functions; do not silently fall back to built-in names.
_IOPADT_LITERAL_TOKENS = {}

def _iopadt_expand_text(text):
    """Resolve installed name tokens without altering the surrounding algorithm."""
    for key, value in _IOPADT_LITERAL_TOKENS.items():
        text = text.replace("__IOPADT_" + key + "__", value)
    if "__IOPADT_LITERAL_" in text:
        raise ValueError("Missing private ioPADt literal token; update the installed profile.")
    return text

def _load_iopadt_rules():
    path = Path(os.environ.get("IOPADT_RULES_FILE", str(APP_DIR.parents[2] / "setup" / "config" / "private" / "ioPADt.rules.json")))
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        global _IOPADT_LITERAL_TOKENS
        _IOPADT_LITERAL_TOKENS = data.get("literal_tokens", {})
        if not _IOPADT_LITERAL_TOKENS or not all(isinstance(k, str) and isinstance(v, str) for k, v in _IOPADT_LITERAL_TOKENS.items()):
            raise ValueError("Required ioPADt literal_tokens are missing or invalid.")
    except (OSError, ValueError) as exc:
        raise RuntimeError("ioPADt rules profile is missing or invalid: " + str(path)) from exc
    required = {"schema_version", "profile_id", "corner_master_family", "master_roles", "master_normalization_pattern", "query_master_families", "query_confirmed_families", "signatures", "rail_defs", "rail_cut_at_boundary", "domain_exclusive_pins", "domain_consistent_pins", "domain_column_pins", "expected_rail_pins", "ground_expectations", "literal_tokens"}
    if not isinstance(data, dict) or set(data) != required or data["schema_version"] != 1:
        raise ValueError("Unsupported or incomplete ioPADt rules profile")
    signatures = data["signatures"]
    if not isinstance(signatures, dict) or set(signatures) != {"boundary_pg_exact", "rte_signal_exact", "signal_required", "power_signal_exact", "power_pg_required"}:
        raise ValueError("Incomplete pin-signature rules")
    if len(signatures["signal_required"]) != 2 or len(data["ground_expectations"]) != 2:
        raise ValueError("The existing signal and ground checks each require two configured pins")
    lists = list(signatures.values()) + [data[k] for k in ("query_master_families", "query_confirmed_families", "domain_exclusive_pins", "domain_consistent_pins")]
    for items in lists:
        if not isinstance(items, list) or not items or any(not isinstance(v, str) or not v for v in items) or len(items) != len(set(items)):
            raise ValueError("Rule lists must contain unique nonempty names")
    for key in ("master_roles", "domain_column_pins", "expected_rail_pins", "ground_expectations"):
        mapping = data[key]
        if not isinstance(mapping, dict) or not mapping or any(not isinstance(k, str) or not k or not isinstance(v, str) or not v for k, v in mapping.items()):
            raise ValueError("Rule mappings must contain nonempty string keys/values")
    rails = {"CORE POWER", "IO POWER", _iopadt_expand_text("__IOPADT_LITERAL_002__")}
    if set(data["rail_defs"]) != rails or set(data["rail_cut_at_boundary"]) != rails or set(data["expected_rail_pins"]) != rails:
        raise ValueError("Existing rail identities must be preserved")
    for cfg in data["rail_defs"].values():
        if not isinstance(cfg, dict) or set(cfg) != {"source_role", "carrier_kind", "carrier_pin", "label"} or cfg["carrier_kind"] not in {"pg", "pin"} or any(not isinstance(v, str) or not v for v in cfg.values()):
            raise ValueError("Invalid rail carrier rule")
    if any(type(v) is not bool for v in data["rail_cut_at_boundary"].values()):
        raise ValueError("Boundary cut controls must be boolean")
    if set(data["domain_exclusive_pins"]) & set(data["domain_consistent_pins"]):
        raise ValueError("Exclusive/consistent pin roles must not overlap")
    if not isinstance(data["corner_master_family"], str) or not data["corner_master_family"] or not isinstance(data["profile_id"], str) or not data["profile_id"]:
        raise ValueError("Profile identity and corner master are required")
    if not isinstance(data["master_normalization_pattern"], str):
        raise ValueError("Master normalization pattern must be a string")
    re.compile(data["master_normalization_pattern"])
    if data["master_normalization_pattern"] != r"^(.*)_([HV])$":
        raise ValueError("Native Tcl/Python H/V normalization must remain aligned in this release")
    # Query Tcl currently preserves the established H/V expansion algorithm.
    # Reject Tcl metacharacters rather than injecting unchecked profile strings.
    for name in data["query_master_families"] + data["query_confirmed_families"] + [data["corner_master_family"]]:
        if not re.fullmatch(r"[A-Za-z0-9_]+", name):
            raise ValueError("Query master families must be exact simple identifiers")
    return data

IOPADT_RULES = _load_iopadt_rules()

