def decode_text(path):
    raw = path.read_bytes()
    for enc in ("utf-8-sig", "utf-8", "cp950", "cp1252", "latin-1"):
        try:
            return raw.decode(enc), enc
        except UnicodeDecodeError:
            pass
    return raw.decode("utf-8", errors="replace"), "utf-8/replace"

def parse_io_file(path):
    text, enc = decode_text(path)
    entries = []
    counts = defaultdict(int)
    current_side = ""
    side_re = re.compile(r"^\(\s*(top|right|bottom|left)\s*$", re.I)
    corner_re = re.compile(r"^\(\s*(topright|topleft|bottomright|bottomleft)\s*$", re.I)
    inst_re = re.compile(
        r"^\(\s*inst\b.*?\bname\s*=\s*(?:\"([^\"]+)\"|'([^']+)'|([^\s\)]+))",
        re.I,
    )
    diag = {"encoding": enc, "inst_lines_seen": 0, "side_instances_parsed": 0}

    for ln, line in enumerate(text.splitlines(), 1):
        t = line.strip()
        if not t or t.startswith("#"):
            continue
        m = side_re.match(t)
        if m:
            current_side = m.group(1).lower()
            continue
        if corner_re.match(t):
            current_side = ""
            continue
        if re.match(r"^\(\s*inst\b", t, re.I):
            diag["inst_lines_seen"] += 1
            m = inst_re.match(t)
            if not m:
                continue
            name = m.group(1) or m.group(2) or m.group(3)
            if not current_side:
                continue
            counts[current_side] += 1
            entries.append(IOEntry(name, current_side, counts[current_side], ln, t))
            diag["side_instances_parsed"] += 1

    if not entries:
        raise ValueError(f"No side IO instances parsed. Encoding={enc}.")
    return entries, diag

def parse_io_corner_names(path):
    """Return IO_FILE corner-cell instance names without adding them to Ring order."""
    text, _ = decode_text(path)
    corner_re = re.compile(r"^\(\s*(topright|topleft|bottomright|bottomleft)\s*$", re.I)
    side_re = re.compile(r"^\(\s*(top|right|bottom|left)\s*$", re.I)
    inst_re = re.compile(
        r"^\(\s*inst\b.*?\bname\s*=\s*(?:\"([^\"]+)\"|'([^']+)'|([^\s\)]+))",
        re.I,
    )
    in_corner = False
    out = []
    seen = set()
    for line in text.splitlines():
        t = line.strip()
        if not t or t.startswith("#"):
            continue
        if corner_re.match(t):
            in_corner = True
            continue
        if side_re.match(t):
            in_corner = False
            continue
        if in_corner and re.match(r"^\(\s*inst\b", t, re.I):
            m = inst_re.match(t)
            if not m:
                continue
            name = m.group(1) or m.group(2) or m.group(3)
            if name and name not in seen:
                seen.add(name)
                out.append(name)
    return out


def parse_io_corner_map(path):
    """Return {topright,topleft,bottomright,bottomleft: instance_name}."""
    text, _ = decode_text(path)
    corner_re = re.compile(r"^\(\s*(topright|topleft|bottomright|bottomleft)\s*$", re.I)
    side_re = re.compile(r"^\(\s*(top|right|bottom|left)\s*$", re.I)
    inst_re = re.compile(
        r'^\(\s*inst\b.*?\bname\s*=\s*(?:"([^"]+)"|\'([^\']+)\'|([^\s\)]+))',
        re.I,
    )
    current_corner = ""
    out = {}
    for line in text.splitlines():
        t = line.strip()
        if not t or t.startswith("#"):
            continue
        m = corner_re.match(t)
        if m:
            current_corner = m.group(1).lower()
            continue
        if side_re.match(t):
            current_corner = ""
            continue
        if current_corner and re.match(r"^\(\s*inst\b", t, re.I):
            m = inst_re.match(t)
            if not m:
                continue
            name = m.group(1) or m.group(2) or m.group(3)
            if name:
                out[current_corner] = name
                current_corner = ""
    return out


def normalize_master(exact_master):
    m = re.match(IOPADT_RULES["master_normalization_pattern"], exact_master, re.I)
    if m:
        return m.group(1), m.group(2).upper()
    return exact_master, ""

def classify_from_master_and_pins(exact_master, pg_pins, pins):
    family, _ = normalize_master(exact_master)
    if family in CONFIRMED_MASTER_ROLE:
        return CONFIRMED_MASTER_ROLE[family], f"confirmed master family {family}"

    pg = set(pg_pins)
    sig = set(pins)
    if pg == set(IOPADT_RULES["signatures"]["boundary_pg_exact"]) and not sig:
        return _iopadt_expand_text("__IOPADT_LITERAL_003__"), "actual pin signature"
    if sig == set(IOPADT_RULES["signatures"]["rte_signal_exact"]):
        return _iopadt_expand_text("__IOPADT_LITERAL_002__"), "actual pin signature"
    if IOPADT_RULES["signatures"]["signal_required"][0] in sig and IOPADT_RULES["signatures"]["signal_required"][1] in sig:
        return "SIGNAL", "actual functional pin signature"
    if sig == set(IOPADT_RULES["signatures"]["power_signal_exact"]) and set(IOPADT_RULES["signatures"]["power_pg_required"]).issubset(pg):
        return "POWER_UNKNOWN", "power-pad signature; master family not confirmed"
    return "UNKNOWN", "unclassified actual master/pin signature"

def tcl_braced(value):
    return "{" + value.replace("\\", "\\\\").replace("{", "\\{").replace("}", "\\}") + "}"

def generate_query_tcl(entries, output_path="./TT_iopad_query_result.tsv", extra_names=None, discover_all=False):
    unique = []
    seen = set()
    for e in (entries or []):
        if e.name not in seen:
            seen.add(e.name)
            unique.append(e.name)
    for name in (extra_names or []):
        if name and name not in seen:
            seen.add(name)
            unique.append(name)

    inst_lines = "\n".join(
        f"lappend ::TT_IOPAD_QUERY_INSTS {tcl_braced(name)}"
        for name in unique
    )
    output_literal = tcl_braced(output_path)
    discover_flag = 1 if discover_all else 0

    return _iopadt_expand_text(f'''# =============================================================================
# AUTO-GENERATED BY ioPADt __IOPADT_LITERAL_001__ TOOL V128
# =============================================================================
# Existing IO_FILE: explicit instance query.
# No IO_FILE: discover confirmed __IOPADT_LITERAL_001__/__IOPADT_LITERAL_002__/__IOPADT_LITERAL_003__ families directly from Innovus,
#             discover four geometric corner instances, then emit the same TSV.
# READ-ONLY connectivity/domain query. NO DB modification.
# =============================================================================

set ::TT_IOPAD_QUERY_INSTS {{}}
{inst_lines}
set ::TT_IOPAD_QUERY_OUTPUT_PATH {output_literal}
set ::TT_IOPAD_QUERY_DISCOVER_ALL {discover_flag}
set ::TT_IOPAD_DISCOVERY_META [dict create]

proc TTQ_escape {{value}} {{
    return [string map [list "\\\\" "\\\\\\\\" "\\t" "\\\\t" "\\n" "\\\\n" "\\r" "\\\\r"] $value]
}}

proc TTQ_put {{fp fields}} {{
    set out {{}}
    foreach f $fields {{ lappend out [TTQ_escape $f] }}
    puts $fp [join $out "\\t"]
}}

proc TTQ_bbox4 {{bbox}} {{
    set flat [string map [list "{{" " " "}}" " "] $bbox]
    set nums {{}}
    foreach tok [split $flat] {{
        if {{[string is double -strict $tok]}} {{ lappend nums $tok }}
    }}
    if {{[llength $nums] < 4}} {{ return {{}} }}
    return [lrange $nums 0 3]
}}

proc TTQ_nums {{value}} {{
    set flat [string map [list "{{" " " "}}" " " "," " "] $value]
    set nums {{}}
    foreach tok [split $flat] {{
        if {{[string is double -strict $tok]}} {{ lappend nums $tok }}
    }}
    return $nums
}}

proc TTQ_exact_base_cell {{master}} {{
    set matches {{}}
    catch {{set matches [get_db base_cells $master]}}
    foreach B $matches {{
        set n {{}}
        if {{![catch {{set n [get_db $B .name]}}] && $n eq $master}} {{ return $B }}
    }}
    return {{}}
}}

proc TTQ_master_geometry {{master}} {{
    # Return {{bbox size source}}. Every attribute probe is guarded because
    # Innovus/library releases expose base-cell dimensions with slightly
    # different attribute spellings. A failed optional probe must never break
    # QUERY_IOPAD.
    set B [TTQ_exact_base_cell $master]
    if {{$B eq {{}}}} {{ return [list {{}} {{}} BASE_CELL_NOT_FOUND] }}

    set bbox {{}}
    if {{![catch {{set bbox [get_db $B .bbox]}}]}} {{
        set b [TTQ_bbox4 $bbox]
        if {{[llength $b] == 4}} {{
            lassign $b x1 y1 x2 y2
            set w [expr {{abs(double($x2)-double($x1))}}]
            set h [expr {{abs(double($y2)-double($y1))}}]
            if {{$w > 0.0 && $h > 0.0}} {{ return [list $bbox [list $w $h] BASE_CELL_BBOX] }}
        }}
    }}

    set size {{}}
    if {{![catch {{set size [get_db $B .size]}}]}} {{
        set n [TTQ_nums $size]
        if {{[llength $n] >= 2}} {{
            set w [expr {{abs(double([lindex $n 0]))}}]
            set h [expr {{abs(double([lindex $n 1]))}}]
            if {{$w > 0.0 && $h > 0.0}} {{ return [list {{}} [list $w $h] BASE_CELL_SIZE] }}
        }}
    }}

    foreach attrs {{{{.size_x .size_y}} {{.width .height}}}} {{
        lassign $attrs ax ay
        set x {{}}; set y {{}}
        if {{![catch {{set x [get_db $B $ax]}}] && ![catch {{set y [get_db $B $ay]}}]
            && [string is double -strict $x] && [string is double -strict $y]}} {{
            set w [expr {{abs(double($x))}}]
            set h [expr {{abs(double($y))}}]
            if {{$w > 0.0 && $h > 0.0}} {{ return [list {{}} [list $w $h] BASE_CELL_ATTRS] }}
        }}
    }}
    return [list {{}} {{}} BASE_CELL_GEOMETRY_UNAVAILABLE]
}}

proc TTQ_obj_name {{obj}} {{
    if {{$obj eq {{}}}} {{ return {{}} }}
    set n {{}}
    if {{![catch {{set n [get_db $obj .name]}}] && $n ne {{}}}} {{ return $n }}
    return $obj
}}

proc TTQ_pin_net_names {{P}} {{
    set nets {{}}
    set ok 0
    if {{![catch {{set nets [get_db $P .net.name]}}]}} {{ set ok 1 }}
    if {{!$ok}} {{
        set N {{}}
        if {{![catch {{set N [get_db $P .net]}}]}} {{
            set out {{}}
            foreach n $N {{
                set name [TTQ_obj_name $n]
                if {{$name ne {{}}}} {{ lappend out $name }}
            }}
            set nets $out
            set ok 1
        }}
    }}
    return [list $nets $ok]
}}

proc TTQ_inst_power_domain {{I}} {{
    foreach attr {{.power_domain.name .power_domain}} {{
        set value {{}}
        if {{![catch {{set value [get_db $I $attr]}}]}} {{
            if {{$value eq {{}}}} {{ return [list {{}} 1 $attr] }}
            if {{$attr eq ".power_domain"}} {{ set value [TTQ_obj_name $value] }}
            return [list $value 1 $attr]
        }}
    }}
    return [list {{}} 0 UNAVAILABLE]
}}

proc TTQ_first_attr {{obj attrs}} {{
    foreach attr $attrs {{
        set value {{}}
        if {{![catch {{set value [get_db $obj $attr]}}]}} {{
            if {{$value ne {{}}}} {{ return [list $value 1 $attr] }}
        }}
    }}
    return [list {{}} 0 UNAVAILABLE]
}}

proc TTQ_emit_power_domains {{fp}} {{
    set pds {{}}
    catch {{set pds [get_db power_domains]}}
    set names {{}}
    foreach PD $pds {{
        set name [TTQ_obj_name $PD]
        if {{$name eq {{}}}} {{ continue }}
        lappend names $name
        lassign [TTQ_first_attr $PD {{.primary_power_net.name .primary_power_net}}] pp ppok ppsrc
        lassign [TTQ_first_attr $PD {{.primary_ground_net.name .primary_ground_net}}] pg pgok pgsrc
        lassign [TTQ_first_attr $PD {{.available_supply_nets.name .available_supply_nets}}] av avok avsrc
        TTQ_put $fp [list META power_domain::${{name}}::primary_power $pp]
        TTQ_put $fp [list META power_domain::${{name}}::primary_ground $pg]
        TTQ_put $fp [list META power_domain::${{name}}::available_supply_nets $av]
        TTQ_put $fp [list META power_domain::${{name}}::query_sources "$ppsrc;$pgsrc;$avsrc"]
    }}
    TTQ_put $fp [list META power_domain_names $names]
    TTQ_put $fp [list META power_domain_count [llength $names]]
}}


proc TTQ_emit_master_pg_types {{fp master}} {{
    # V128.17: preload exact library PG-pin polarity once per master.
    # pg_type is authoritative library evidence (primary_power/primary_ground/etc.).
    set emitted 0
    set cells {{}}
    if {{![catch {{set cells [get_lib_cells $master]}}] && [llength $cells] > 0}} {{
        foreach C $cells {{
            set pgpins {{}}
            if {{[catch {{set pgpins [get_lib_pg_pins -of_objects $C]}}]}} {{ continue }}
            foreach LP $pgpins {{
                set pname {{}}
                set ptype {{}}
                catch {{set pname [get_property $LP name]}}
                catch {{set ptype [get_property $LP pg_type]}}
                if {{$pname eq {{}} || $ptype eq {{}}}} {{ continue }}
                TTQ_put $fp [list META master_pg_type::${{master}}::${{pname}} $ptype]
                incr emitted
            }}
        }}
    }}
    if {{$emitted == 0}} {{
        # Common-UI fallback for environments where get_lib_* is not exposed.
        set bcs {{}}
        catch {{set bcs [get_db base_cells $master]}}
        foreach C $bcs {{
            set pgpins {{}}
            catch {{set pgpins [get_db $C .pg_pins]}}
            foreach LP $pgpins {{
                set pname {{}}
                set ptype {{}}
                catch {{set pname [get_db $LP .name]}}
                catch {{set ptype [get_db $LP .pg_type]}}
                set pname [lindex [split $pname /] end]
                if {{$pname eq {{}} || $ptype eq {{}}}} {{ continue }}
                TTQ_put $fp [list META master_pg_type::${{master}}::${{pname}} $ptype]
                incr emitted
            }}
        }}
    }}
    return $emitted
}}

proc TTQ_preload_pad_master_candidates {{master_candidates_var}} {{
    upvar 1 $master_candidates_var master_candidates
    # Finite configured Library technology __IOPADT_LITERAL_001__ families. Query these exact canonical/H/V
    # masters once so every floorplan/offset/repair calculation reuses one
    # authoritative master-geometry catalog rather than rediscovering per __IOPADT_LITERAL_001__.
    foreach family {{{" ".join(IOPADT_RULES["query_master_families"])}}} {{
        foreach master [list $family ${{family}}_H ${{family}}_V] {{
            if {{[TTQ_exact_base_cell $master] ne {{}}}} {{
                dict set master_candidates $master 1
            }}
        }}
    }}
}}

proc TTQ_point_box_distance {{px py b}} {{
    lassign $b x1 y1 x2 y2
    if {{$x1 > $x2}} {{ set t $x1; set x1 $x2; set x2 $t }}
    if {{$y1 > $y2}} {{ set t $y1; set y1 $y2; set y2 $t }}
    set dx 0.0
    set dy 0.0
    if {{$px < $x1}} {{ set dx [expr {{$x1-$px}}] }} elseif {{$px > $x2}} {{ set dx [expr {{$px-$x2}}] }}
    if {{$py < $y1}} {{ set dy [expr {{$y1-$py}}] }} elseif {{$py > $y2}} {{ set dy [expr {{$py-$y2}}] }}
    return [expr {{$dx+$dy}}]
}}

proc TTQ_discover_inst_names {{}} {{
    set all_insts [get_db insts]
    set confirmed {{{" ".join(IOPADT_RULES["query_confirmed_families"])}}}
    set names {{}}
    set seen [dict create]
    set ring_objs {{}}
    set corner_objs {{}}
    set min_x {{}}; set min_y {{}}; set max_x {{}}; set max_y {{}}

    foreach I $all_insts {{
        set master [get_db $I .base_cell.name]
        set family $master
        regexp {{^(.*)_([HV])$}} $master _ family _variant
        if {{$family eq "{IOPADT_RULES["corner_master_family"]}"}} {{ lappend corner_objs $I; continue }}
        if {{[lsearch -exact $confirmed $family] < 0}} {{ continue }}
        set name [get_db $I .name]
        if {{![dict exists $seen $name]}} {{
            dict set seen $name 1
            lappend names $name
            lappend ring_objs $I
        }}
        set b [TTQ_bbox4 [get_db $I .bbox]]
        if {{[llength $b] != 4}} {{ continue }}
        lassign $b x1 y1 x2 y2
        set lx [expr {{min(double($x1),double($x2))}}]
        set ly [expr {{min(double($y1),double($y2))}}]
        set hx [expr {{max(double($x1),double($x2))}}]
        set hy [expr {{max(double($y1),double($y2))}}]
        if {{$min_x eq {{}} || $lx < $min_x}} {{ set min_x $lx }}
        if {{$min_y eq {{}} || $ly < $min_y}} {{ set min_y $ly }}
        if {{$max_x eq {{}} || $hx > $max_x}} {{ set max_x $hx }}
        if {{$max_y eq {{}} || $hy > $max_y}} {{ set max_y $hy }}
    }}

    if {{[llength $names] < 4 || $min_x eq {{}}}} {{
        error "DB bootstrap discovery found too few confirmed __IOPADT_LITERAL_001__/__IOPADT_LITERAL_002__/__IOPADT_LITERAL_003__ instances"
    }}

    set targets [dict create \\
        bottomleft [list $min_x $min_y] \\
        bottomright [list $max_x $min_y] \\
        topleft [list $min_x $max_y] \\
        topright [list $max_x $max_y]]
    set best [dict create]

    foreach I $corner_objs {{
        set name [get_db $I .name]
        if {{[dict exists $seen $name]}} {{ continue }}
        set b [TTQ_bbox4 [get_db $I .bbox]]
        if {{[llength $b] != 4}} {{ continue }}
        lassign $b x1 y1 x2 y2
        set area [expr {{abs((double($x2)-double($x1))*(double($y2)-double($y1)))}}]
        foreach key [dict keys $targets] {{
            lassign [dict get $targets $key] px py
            set d [TTQ_point_box_distance $px $py $b]
            if {{![dict exists $best $key]}} {{
                dict set best $key [list $d $area $name]
            }} else {{
                lassign [dict get $best $key] bd ba bn
                if {{$d < $bd || ($d == $bd && $area > $ba)}} {{
                    dict set best $key [list $d $area $name]
                }}
            }}
        }}
    }}

    foreach key {{topright topleft bottomleft bottomright}} {{
        if {{![dict exists $best $key]}} {{ error "Unable to discover corner $key" }}
        set cname [lindex [dict get $best $key] 2]
        if {{[dict exists $seen $cname]}} {{ error "Corner discovery duplicate: $cname" }}
        dict set seen $cname 1
        lappend names $cname
        dict set ::TT_IOPAD_DISCOVERY_META bootstrap_corner_$key $cname
    }}
    dict set ::TT_IOPAD_DISCOVERY_META discovery_mode ALL_DB_IOPAD
    dict set ::TT_IOPAD_DISCOVERY_META bootstrap_ring_candidate_count [expr {{[llength $names]-4}}]
    return $names
}}

proc TT_IOPAD_QUERY {{}} {{
    if {{$::TT_IOPAD_QUERY_DISCOVER_ALL}} {{
        set ::TT_IOPAD_QUERY_INSTS [TTQ_discover_inst_names]
    }}

    set output_path [file normalize $::TT_IOPAD_QUERY_OUTPUT_PATH]
    file mkdir [file dirname $output_path]
    set fp [open $output_path w]
    fconfigure $fp -translation lf -encoding utf-8

    TTQ_put $fp [list META schema {QUERY_RESULT_SCHEMA}]
    TTQ_put $fp [list META producer ioPADt_V128_generated_query_tcl]
    TTQ_put $fp [list META connectivity_queried 1]
    TTQ_put $fp [list META role_inferred_from_instance_name 0]
    TTQ_put $fp [list META requested_instance_count [llength $::TT_IOPAD_QUERY_INSTS]]
    foreach key [dict keys $::TT_IOPAD_DISCOVERY_META] {{
        TTQ_put $fp [list META $key [dict get $::TT_IOPAD_DISCOVERY_META $key]]
    }}

    set design_area {{}}
    set design_area_query_ok 1
    set design_area_query_error {{}}
    if {{[catch {{set design_area [get_db current_design .area]}} design_area_query_error]}} {{
        set design_area {{}}
        set design_area_query_ok 0
    }}
    TTQ_put $fp [list META current_design_area $design_area]
    TTQ_put $fp [list META current_design_area_query_ok $design_area_query_ok]
    TTQ_put $fp [list META current_design_area_source {{get_db current_design .area}}]
    if {{!$design_area_query_ok}} {{ TTQ_put $fp [list META current_design_area_query_error $design_area_query_error] }}

    # V128 read-only UPF/Global-Net context. __IOPADT_LITERAL_004__-only IO-domain inference
    # remains a Python policy; __IOPADT_LITERAL_005__ is optional evidence, never a prerequisite.
    TTQ_emit_power_domains $fp

    set found_count 0
    set missing_count 0
    set pin_connectivity_query_count 0
    set pin_connectivity_query_fail_count 0
    set power_domain_query_count 0
    set power_domain_query_fail_count 0
    set master_candidates [dict create]
    TTQ_preload_pad_master_candidates master_candidates
    foreach requested $::TT_IOPAD_QUERY_INSTS {{
        set matches {{}}
        catch {{set matches [get_db insts $requested]}}
        set I {{}}
        foreach cand $matches {{
            if {{[get_db $cand .name] eq $requested}} {{ set I $cand; break }}
        }}
        if {{[llength $I] == 0}} {{ incr missing_count; TTQ_put $fp [list MISSING $requested]; continue }}
        incr found_count
        set actual_name [get_db $I .name]
        set master [get_db $I .base_cell.name]
        dict set master_candidates $master 1
        if {{[regexp {{^(.*)_([HV])$}} $master _ mfam mvar]}} {{
            dict set master_candidates ${{mfam}}_H 1
            dict set master_candidates ${{mfam}}_V 1
        }}
        set is_pad [get_db $I .is_pad]
        set place_status [get_db $I .place_status]
        set orient [get_db $I .orient]
        set location [get_db $I .location]
        set bbox [get_db $I .bbox]
        set pg_objs [get_db $I .pg_pins]
        set pin_objs [get_db $I .pins]
        set pg_names {{}}
        foreach P $pg_objs {{ catch {{lappend pg_names [get_db $P .name]}} }}
        set pin_names {{}}
        foreach P $pin_objs {{ catch {{lappend pin_names [get_db $P .name]}} }}
        TTQ_put $fp [list INST $requested $actual_name $master $is_pad $place_status $orient $location $bbox $pg_names $pin_names]

        lassign [TTQ_inst_power_domain $I] inst_pd inst_pd_ok inst_pd_source
        incr power_domain_query_count
        if {{!$inst_pd_ok}} {{ incr power_domain_query_fail_count }}
        TTQ_put $fp [list PDINST $requested $actual_name $inst_pd $inst_pd_ok $inst_pd_source]

        set emitted_pin [dict create]
        foreach P $pg_objs {{
            set pname [get_db $P .name]
            set pname [lindex [split $pname /] end]
            if {{$pname eq {{}} || [dict exists $emitted_pin $pname]}} {{ continue }}
            dict set emitted_pin $pname 1
            lassign [TTQ_pin_net_names $P] pnets pok
            incr pin_connectivity_query_count
            if {{!$pok}} {{ incr pin_connectivity_query_fail_count }}
            TTQ_put $fp [list PIN $requested $actual_name $pname PG $pnets $pok]
        }}
        foreach P $pin_objs {{
            set pname [get_db $P .name]
            set pname [lindex [split $pname /] end]
            if {{$pname eq {{}} || [dict exists $emitted_pin $pname]}} {{ continue }}
            dict set emitted_pin $pname 1
            lassign [TTQ_pin_net_names $P] pnets pok
            incr pin_connectivity_query_count
            if {{!$pok}} {{ incr pin_connectivity_query_fail_count }}
            TTQ_put $fp [list PIN $requested $actual_name $pname SIGNAL $pnets $pok]
        }}
    }}

    # V128: emit one preloaded exact library-geometry catalog for all finite
    # H/V siblings when they exist. This is required for simulated repair PADs
    # (e.g. FILL_IN_CELL_RTE_BOUNDARY_PAD_054 on LEFT/RIGHT) that have no instance bbox yet.
    set master_geom_found 0
    set master_geom_missing 0
    foreach master [lsort [dict keys $master_candidates]] {{
        lassign [TTQ_master_geometry $master] mbbox msize msource
        if {{$msize ne {{}}}} {{
            TTQ_put $fp [list META master_size::$master $msize]
            if {{$mbbox ne {{}}}} {{ TTQ_put $fp [list META master_bbox::$master $mbbox] }}
            TTQ_put $fp [list META master_geometry_source::$master $msource]
            incr master_geom_found
        }} else {{
            incr master_geom_missing
        }}
        TTQ_emit_master_pg_types $fp $master
    }}
    TTQ_put $fp [list META master_geometry_found_count $master_geom_found]
    TTQ_put $fp [list META master_geometry_missing_count $master_geom_missing]
    TTQ_put $fp [list META pin_connectivity_query_count $pin_connectivity_query_count]
    TTQ_put $fp [list META pin_connectivity_query_fail_count $pin_connectivity_query_fail_count]
    TTQ_put $fp [list META power_domain_query_count $power_domain_query_count]
    TTQ_put $fp [list META power_domain_query_fail_count $power_domain_query_fail_count]
    TTQ_put $fp [list META global_net_mapping_source PAD_PIN_NET]
    TTQ_put $fp [list META global_net_mapping_count $pin_connectivity_query_count]

    TTQ_put $fp [list META found_instance_count $found_count]
    TTQ_put $fp [list META missing_instance_count $missing_count]
    close $fp
    puts ""
    puts "======================================================================"
    puts " ioPADt/__IOPADT_LITERAL_001__ QUERY V128"
    puts "======================================================================"
    puts "Output              : $output_path"
    puts "Discovery mode      : $::TT_IOPAD_QUERY_DISCOVER_ALL"
    puts "Requested instances : [llength $::TT_IOPAD_QUERY_INSTS]"
    puts "Found               : $found_count"
    puts "Missing             : $missing_count"
    puts "Design modified     : NO"
    puts "======================================================================"
    return $output_path
}}

TT_IOPAD_QUERY
''')
def unescape_tsv(s):
    out = []
    i = 0
    while i < len(s):
        if s[i] == "\\" and i + 1 < len(s):
            n = s[i+1]
            if n == "t":
                out.append("\t"); i += 2; continue
            if n == "n":
                out.append("\n"); i += 2; continue
            if n == "r":
                out.append("\r"); i += 2; continue
            if n == "\\":
                out.append("\\"); i += 2; continue
        out.append(s[i]); i += 1
    return "".join(out)

def leaf_pin_names(field):
    if not field.strip():
        return []
    return [token.rsplit("/", 1)[-1] for token in field.split()]

def query_result_schema_state(meta):
    """Return CURRENT / LEGACY / UNSUPPORTED for a parsed query-result META map."""
    schema = str((meta or {}).get("schema", "")).strip()
    if schema == QUERY_RESULT_SCHEMA:
        return "CURRENT", schema
    if schema in QUERY_RESULT_LEGACY_SCHEMAS:
        return "LEGACY", schema
    return "UNSUPPORTED", schema


def require_supported_query_result_schema(meta, source_label="TSV"):
    """
    Validate the structural query-result contract.

    V125 intentionally accepts legacy V8 so a stale generated Query Tcl or a
    not-yet-reloaded Innovus bridge does not hard-fail Refresh/Load TSV. V8
    does not contain current_design_area metadata, so Floorplan Bound remains
    UNKNOWN until the user regenerates with the current V9 producer.
    """
    state, schema = query_result_schema_state(meta)
    if state == "UNSUPPORTED":
        got = schema or "<missing>"
        raise ValueError(
            f"{source_label} schema is unsupported: {got}. "
            f"Current={QUERY_RESULT_SCHEMA}; legacy accepted="
            + ",".join(sorted(QUERY_RESULT_LEGACY_SCHEMAS))
        )
    return state, schema


def load_result(path):
    """Parse V10 (and accepted legacy) query results.

    V10 adds read-only Innovus DB connectivity/domain evidence:
      PIN    requested actual pin kind net-list query-ok
      PDINST requested actual domain query-ok source
    Power-domain supply metadata remains in META so it is preserved even when
    the current IO_FILE does not contain an instance from every domain.
    """
    facts = {}
    meta = {}
    pending_pin_rows = defaultdict(list)
    pending_pdinst = {}

    for line in path.read_text(encoding="utf-8-sig", errors="replace").splitlines():
        if not line.strip():
            continue
        f = [unescape_tsv(x) for x in line.split("\t")]
        if f[0] == "META" and len(f) >= 3:
            meta[f[1]] = f[2]
            continue
        if f[0] == "MISSING" and len(f) >= 2:
            facts[f[1]] = DBFact(requested_name=f[1], found=False)
            continue
        if f[0] == "PIN" and len(f) >= 7:
            # net field is a Tcl-style whitespace list of names. Net names in
            # this project do not contain whitespace; keep every name so
            # ambiguous/multi-net evidence is visible to the checker.
            requested = f[1]
            pending_pin_rows[requested].append({
                "actual": f[2],
                "pin": f[3],
                "kind": f[4],
                "nets": [x for x in f[5].split() if x],
                "ok": str(f[6]).strip() not in ("", "0", "false", "False"),
            })
            continue
        if f[0] == "PDINST" and len(f) >= 6:
            pending_pdinst[f[1]] = {
                "actual": f[2],
                "domain": f[3],
                "ok": str(f[4]).strip() not in ("", "0", "false", "False"),
                "source": f[5],
            }
            continue
        if f[0] != "INST" or len(f) < 11:
            continue

        exact_master = f[3]
        pg = leaf_pin_names(f[9])
        pins = leaf_pin_names(f[10])
        family, variant = normalize_master(exact_master)
        role, basis = classify_from_master_and_pins(exact_master, pg, pins)

        facts[f[1]] = DBFact(
            requested_name=f[1], found=True,
            exact_master=exact_master, master_family=family, variant=variant,
            role=role, role_basis=basis,
            is_pad=f[4], place_status=f[5], orient=f[6],
            location=f[7], bbox=f[8], pg_pins=pg, pins=pins
        )

    for requested, rows in pending_pin_rows.items():
        fact = facts.get(requested)
        if fact is None:
            fact = DBFact(requested_name=requested, found=True)
            facts[requested] = fact
        for row in rows:
            fact.pin_nets[row["pin"]] = list(row["nets"])
            fact.pin_kinds[row["pin"]] = row["kind"]
            fact.pin_net_query_ok[row["pin"]] = bool(row["ok"])

    for requested, row in pending_pdinst.items():
        fact = facts.get(requested)
        if fact is None:
            fact = DBFact(requested_name=requested, found=True)
            facts[requested] = fact
        fact.power_domain = row["domain"]
        fact.power_domain_query_ok = bool(row["ok"])
        fact.power_domain_source = row["source"]

    return facts, meta


def parse_location_xy(location_text):
    """
    Parse the verified Innovus .location format:
      {100.0 1804.032}
    Returns (x, y) or None.
    """
    if not location_text:
        return None
    nums = re.findall(r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)", str(location_text))
    if len(nums) < 2:
        return None
    try:
        return float(nums[0]), float(nums[1])
    except ValueError:
        return None



def parse_bbox_wh(bbox_text):
    """
    Parse verified Innovus instance .bbox:
      {x1 y1 x2 y2}

    Returns (width, height) from bbox extents.

    NOTE:
      Width/height are used for __IOPADT_LITERAL_001__ footprint audit only.
      BBox coordinates are NOT used for Ring ordering.
    """
    if not bbox_text:
        return None

    nums = re.findall(
        r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)",
        str(bbox_text),
    )

    if len(nums) < 4:
        return None

    try:
        x1, y1, x2, y2 = map(
            float,
            nums[:4],
        )
    except Exception:
        return None

    return (
        abs(x2 - x1),
        abs(y2 - y1),
    )



def parse_bbox_xyxy(bbox_text):
    """Return (x1,y1,x2,y2) from an Innovus bbox value, or None."""
    if not bbox_text:
        return None
    nums = re.findall(r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)", str(bbox_text))
    if len(nums) < 4:
        return None
    try:
        x1, y1, x2, y2 = map(float, nums[:4])
    except ValueError:
        return None
    return (min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2))


def build_bootstrap_io_text(facts, meta=None):
    """
    Build a legal IO_FILE seed from DB-discovery facts.

    Discovery is geometry based: confirmed __IOPADT_LITERAL_001__/__IOPADT_LITERAL_002__/__IOPADT_LITERAL_003__ master families form
    the four side populations; the four corner instances are supplied by the
    discovery producer when available, otherwise selected from UNKNOWN facts by
    proximity to the four ring intersections. Side order in IO_FILE is low to
    high X for TOP/BOTTOM and low to high Y for LEFT/RIGHT, matching the
    authoritative Innovus IO_FILE emission convention used by this tool.
    """
    meta = dict(meta or {})
    ring_roles = {"SIGNAL", _iopadt_expand_text("__IOPADT_LITERAL_002__"), "CORE_POWER", "IO_POWER", _iopadt_expand_text("__IOPADT_LITERAL_003__"), "POWER_UNKNOWN"}
    declared_corner_names = {
        str(meta.get("bootstrap_corner_" + key, "") or "").strip()
        for key in ("topright", "topleft", "bottomleft", "bottomright")
    }
    declared_corner_names.discard("")
    for _name, _fact in (facts or {}).items():
        _family, _variant = normalize_master(getattr(_fact, "exact_master", ""))
        if _family == CONFIRMED_CORNER_MASTER_FAMILY:
            declared_corner_names.add(str(_name))
    ring = []
    unknown = []
    for name, fact in (facts or {}).items():
        if not getattr(fact, "found", False):
            continue
        box = parse_bbox_xyxy(getattr(fact, "bbox", ""))
        if box is None:
            continue
        rec = (str(name), fact, box)
        if str(name) in declared_corner_names:
            unknown.append(rec)
        elif getattr(fact, "role", "UNKNOWN") in ring_roles:
            ring.append(rec)
        else:
            unknown.append(rec)

    if len(ring) < 4:
        raise ValueError(_iopadt_expand_text("Innovus discovery did not find enough confirmed __IOPADT_LITERAL_001__/__IOPADT_LITERAL_002__ instances to build an IO_FILE."))

    min_x = min(r[2][0] for r in ring)
    min_y = min(r[2][1] for r in ring)
    max_x = max(r[2][2] for r in ring)
    max_y = max(r[2][3] for r in ring)

    side_rows = {s: [] for s in ("top", "right", "bottom", "left")}
    for name, fact, box in ring:
        x1, y1, x2, y2 = box
        distances = {
            "top": abs(max_y - y2),
            "right": abs(max_x - x2),
            "bottom": abs(y1 - min_y),
            "left": abs(x1 - min_x),
        }
        side = min(distances, key=lambda k: distances[k])
        loc = parse_location_xy(getattr(fact, "location", ""))
        coord = (loc[0] if side in ("top", "bottom") else loc[1]) if loc else (
            x1 if side in ("top", "bottom") else y1
        )
        side_rows[side].append((float(coord), name, fact, box))

    for side in side_rows:
        side_rows[side].sort(key=lambda r: (r[0], r[1]))
        if not side_rows[side]:
            raise ValueError(f"Innovus discovery produced no {side.upper()} PADs; bootstrap IO_FILE is unsafe.")

    corner_targets = {
        "bottomleft": (min_x, min_y),
        "bottomright": (max_x, min_y),
        "topleft": (min_x, max_y),
        "topright": (max_x, max_y),
    }
    corner_names = {}
    for key in corner_targets:
        v = str(meta.get("bootstrap_corner_" + key, "") or "").strip()
        if v and v in facts and getattr(facts[v], "found", False):
            corner_names[key] = v

    def point_box_distance(pt, box):
        px, py = pt
        x1, y1, x2, y2 = box
        dx = 0.0 if x1 <= px <= x2 else min(abs(px-x1), abs(px-x2))
        dy = 0.0 if y1 <= py <= y2 else min(abs(py-y1), abs(py-y2))
        return dx + dy

    available_unknown = list(unknown)
    for key, target in corner_targets.items():
        if key in corner_names:
            continue
        if not available_unknown:
            raise ValueError("Innovus discovery did not provide four corner instances for bootstrap IO_FILE.")
        best = min(
            available_unknown,
            key=lambda r: (
                point_box_distance(target, r[2]),
                -((r[2][2]-r[2][0]) * (r[2][3]-r[2][1])),
                r[0],
            ),
        )
        corner_names[key] = best[0]
        available_unknown = [r for r in available_unknown if r[0] != best[0]]

    if len(set(corner_names.values())) != 4:
        raise ValueError("Corner discovery is ambiguous; four unique corner instances are required.")

    def corner_line(key):
        name = corner_names[key]
        fact = facts[name]
        orient = str(getattr(fact, "orient", "") or "").strip()
        extra = f' orientation={orient}' if orient and orient.upper() not in ("R0", "N") else ""
        return f'\t(inst name="{name}"{extra})'

    def side_lines(side):
        rows = side_rows[side]
        out = []
        for idx, (coord, name, _fact, _box) in enumerate(rows):
            attr = ""
            if idx == 0 or idx == len(rows)-1:
                attr = f" offset={coord:.3f}"
            out.append(f'\t(inst name="{name}"{attr})')
        return out

    order = [
        ("topright", None), ("top", "top"), ("topleft", None),
        ("left", "left"), ("bottomleft", None), ("bottom", "bottom"),
        ("bottomright", None), ("right", "right"),
    ]
    lines = [
        "###############################################################",
        "# Generated by ioPADt V128 from live/manual Innovus DB discovery",
        _iopadt_expand_text(f"# Confirmed side __IOPADT_LITERAL_001__/__IOPADT_LITERAL_002__ count: {len(ring)}"),
        "# Source IO_FILE: NONE (bootstrap mode)",
        "###############################################################",
        "",
        "(globals",
        "    version = 3",
        "    io_order = default",
        ")",
        "(iopad",
    ]
    for key, side in order:
        lines.append(f"    ({key}")
        if side is None:
            lines.append(corner_line(key))
        else:
            lines.extend(side_lines(side))
        lines.append("    )")
    lines.append(")")
    lines.append("")
    return "\n".join(lines), {
        "side_counts": {s: len(side_rows[s]) for s in side_rows},
        "corner_names": corner_names,
        "ring_count": len(ring),
    }

SIDE_TO_INNOVUS = {
    "top": "N",
    "right": "E",
    "bottom": "S",
    "left": "W",
}

# V119 floorplan bound-mode analysis.
# The user-defined decision threshold is 70%. The IO-defined floorplan area
# is computed from the minimum configured library token-driven die W/H after subtracting [請填入本地確認的尺寸]
# on BOTH sides of each dimension, i.e. (W-600)*(H-600).
FLOORPLAN_CORE_BOUND_THRESHOLD = 0.70
IO_FLOORPLAN_DIMENSION_SHRINK = 600.0
# V125: physical clearance required between adjacent side PADs. The same
# value is used by offset validation, side redistribution and IO-bound sizing.
PAD_MIN_SPACING = 15.0


def parse_first_float(value):
    """Return the first numeric scalar in an Innovus/meta value."""
    if value is None:
        return None
    m = re.search(r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?", str(value))
    if not m:
        return None
    try:
        return float(m.group(0))
    except ValueError:
        return None


def compute_floorplan_bound_mode(
    design_area,
    io_ring_area,
    side_inputs,
    threshold=FLOORPLAN_CORE_BOUND_THRESHOLD,
    shrink=IO_FLOORPLAN_DIMENSION_SHRINK,
    min_spacing=PAD_MIN_SPACING,
):
    """
    V125 decision engine. No DB placement location is used for sizing.

    Per side minimum length:
      first_offset + sum(__IOPADT_LITERAL_001__ widths) + min_spacing * PAD_count + end_corner_width

    PAD_count spacing slots mean (N-1) mandatory inter-__IOPADT_LITERAL_001__ gaps plus one final
    __IOPADT_LITERAL_001__-to-ending-corner clearance. first_offset already owns the start-corner
    to first-__IOPADT_LITERAL_001__ placement anchor and is therefore not double-counted.
    """
    result = {
        "ok": False, "reason": "", "design_area": design_area,
        "io_ring_area": io_ring_area, "core_cell_area": None,
        "side_min_lengths": {}, "min_die_width": None, "min_die_height": None,
        "io_floorplan_inner_width": None, "io_floorplan_inner_height": None,
        "io_floorplan_decision_area": None, "ratio": None,
        "threshold": float(threshold), "mode": "UNKNOWN",
        "suggested_die_width": None, "suggested_die_height": None,
        "suggested_utilization": None, "min_spacing": float(min_spacing),
    }
    if design_area is None or design_area <= 0:
        result["reason"] = "CURRENT_DESIGN_AREA_UNAVAILABLE"; return result
    if io_ring_area is None or io_ring_area < 0:
        result["reason"] = "IO_RING_AREA_UNAVAILABLE"; return result
    core_cell_area = float(design_area) - float(io_ring_area)
    if core_cell_area < 0:
        result["reason"] = "CORE_CELL_AREA_NEGATIVE"; return result
    result["core_cell_area"] = core_cell_area

    side_min = {}
    for side in ("top", "right", "bottom", "left"):
        item = side_inputs.get(side) if isinstance(side_inputs, dict) else None
        if not item:
            result["reason"] = f"SIDE_DATA_MISSING:{side}"; return result
        if not item.get("span_complete", False):
            missing = [str(x) for x in (item.get("missing_geometry_masters") or []) if str(x)]
            corner_reason = str(item.get("end_corner_reason", "") or "")
            detail = ",".join(missing[:6])
            if len(missing) > 6:
                detail += f",+{len(missing)-6}_more"
            if not detail and corner_reason and corner_reason != "PASS":
                detail = corner_reason
            result["reason"] = f"PAD_WIDTH_UNKNOWN:{side}" + (f":{detail}" if detail else "")
            return result
        first_offset = item.get("first_offset")
        total_length = item.get("total_length")
        end_corner_width = item.get("end_corner_width")
        count = int(item.get("count", 0) or 0)
        vals = (first_offset, total_length, end_corner_width)
        if any(v is None for v in vals):
            result["reason"] = f"OFFSET_OR_WIDTH_UNKNOWN:{side}"; return result
        if any(float(v) < 0 for v in vals) or count < 0:
            result["reason"] = f"NEGATIVE_GEOMETRY_VALUE:{side}"; return result
        side_min[side] = (
            float(first_offset) + float(total_length)
            + float(min_spacing) * count + float(end_corner_width)
        )

    min_die_width = max(side_min["top"], side_min["bottom"])
    min_die_height = max(side_min["left"], side_min["right"])
    inner_w = min_die_width - float(shrink)
    inner_h = min_die_height - float(shrink)
    if inner_w <= 0 or inner_h <= 0:
        result["reason"] = "IO_FLOORPLAN_INNER_DIMENSION_NONPOSITIVE"; return result
    decision_area = inner_w * inner_h
    if decision_area <= 0:
        result["reason"] = "IO_FLOORPLAN_DECISION_AREA_NONPOSITIVE"; return result
    ratio = core_cell_area / decision_area
    mode = "CORE_CELL_BOUND" if ratio > float(threshold) else "IO_BOUND"
    result.update({
        "ok": True, "reason": "PASS", "side_min_lengths": side_min,
        "min_die_width": min_die_width, "min_die_height": min_die_height,
        "io_floorplan_inner_width": inner_w, "io_floorplan_inner_height": inner_h,
        "io_floorplan_decision_area": decision_area, "ratio": ratio, "mode": mode,
        "suggested_die_width": min_die_width if mode == "IO_BOUND" else None,
        "suggested_die_height": min_die_height if mode == "IO_BOUND" else None,
        "suggested_utilization": float(threshold) if mode == "CORE_CELL_BOUND" else None,
    })
    return result


# Physical clockwise Ring and Innovus IO_FILE emission orders differ on RIGHT/BOTTOM.
IOFILE_REVERSE_FROM_CLOCKWISE_SIDES = frozenset({"right", "bottom"})


def iofile_side_entries_from_clockwise_ring(ordered):
    """
    Convert a physical clockwise ring into Innovus IO_FILE side-section order.

    This does not mutate `ordered` or entry.side. It only changes the order
    within RIGHT and BOTTOM for serialization/offset diagnostics.
    """
    by_side = {
        side: [e for e in ordered if str(e.side).lower() == side]
        for side in ("top", "right", "bottom", "left")
    }

    for side in IOFILE_REVERSE_FROM_CLOCKWISE_SIDES:
        by_side[side] = list(reversed(by_side[side]))

    return by_side


SIDE_SEQUENCE_CLOCKWISE = ("top", "right", "bottom", "left")


def repartition_clockwise_ring_by_side_counts(ordered, target_counts):
    """
    Return a deep-copied physical clockwise ring with new side boundaries.

    The cyclic __IOPADT_LITERAL_001__ order is preserved exactly. Only entry.side / entry.ordinal
    are reassigned. The first physical ring entry remains the TOP-side start
    anchor; counts then consume TOP, RIGHT, BOTTOM, LEFT in clockwise order.
    """
    items = copy.deepcopy(list(ordered or []))
    counts = {}

    for side in SIDE_SEQUENCE_CLOCKWISE:
        raw = target_counts.get(side, 0)
        if isinstance(raw, bool):
            raise ValueError(f"Invalid {side} count: {raw!r}")
        try:
            value = int(raw)
        except Exception as exc:
            raise ValueError(f"Invalid {side} count: {raw!r}") from exc
        if value < 0:
            raise ValueError(f"{side} count cannot be negative: {value}")
        counts[side] = value

    if sum(counts.values()) != len(items):
        raise ValueError(
            "Side-count total mismatch: "
            f"requested={sum(counts.values())} ring={len(items)}"
        )

    cursor = 0
    for side in SIDE_SEQUENCE_CLOCKWISE:
        for ordinal in range(1, counts[side] + 1):
            entry = items[cursor]
            entry.side = side
            entry.ordinal = ordinal
            cursor += 1

    return items


def redistribute_ring_counts_and_anchor_offsets(
    ordered,
    offsets,
    target_counts,
    span_resolver,
    min_spacing=PAD_MIN_SPACING,
):
    """Redistribute side counts while preserving order and >=15-unit __IOPADT_LITERAL_001__ gaps."""
    items = list(ordered or [])
    if not items:
        raise ValueError("Cannot redistribute an empty Ring.")
    if span_resolver is None:
        raise ValueError("Redistribution requires a final-master width resolver.")
    normalized_counts = {}
    for side in SIDE_SEQUENCE_CLOCKWISE:
        try: value = int(target_counts.get(side, 0))
        except Exception as exc: raise ValueError(f"Invalid {side} count: {target_counts.get(side)!r}") from exc
        if value < 2:
            raise ValueError(f"{side.upper()} needs at least 2 PADs to preserve separate FIRST/LAST corner offsets.")
        normalized_counts[side] = value
    if sum(normalized_counts.values()) != len(items):
        raise ValueError(f"Side-count total mismatch: requested={sum(normalized_counts.values())} ring={len(items)}")

    old_by_side = iofile_side_entries_from_clockwise_ring(items)
    anchor_values = {}; old_anchor_ids = set()
    for side in SIDE_SEQUENCE_CLOCKWISE:
        side_items = old_by_side.get(side, [])
        if len(side_items) < 2: raise ValueError(f"Current {side.upper()} side has fewer than 2 PADs; cannot capture corner anchors.")
        first_id, last_id = side_items[0].name, side_items[-1].name
        _first_raw = offsets.get(first_id, "")
        _last_raw = offsets.get(last_id, "")
        first_offset = "" if _first_raw is None else str(_first_raw).strip()
        old_last_offset = "" if _last_raw is None else str(_last_raw).strip()
        if not first_offset: raise ValueError(f"{side.upper()} FIRST corner anchor offset missing: {first_id}.")
        try: float(first_offset)
        except ValueError as exc: raise ValueError(f"{side.upper()} FIRST corner anchor offset is not numeric: {first_offset!r}") from exc
        anchor_values[side] = {"first_id": first_id, "last_id": last_id, "first_offset": first_offset, "old_last_offset": old_last_offset}
        old_anchor_ids.update((first_id, last_id))

    new_items = repartition_clockwise_ring_by_side_counts(items, normalized_counts)
    new_by_side = iofile_side_entries_from_clockwise_ring(new_items)
    new_offsets = dict(offsets or {})
    for internal in old_anchor_ids: new_offsets[internal] = ""

    def _fmt(v):
        value = float(v)
        if abs(value) < 1e-12: value = 0.0
        s = f"{value:.6f}".rstrip("0").rstrip(".")
        return s if s else "0"

    anchor_moves = {}
    for side in SIDE_SEQUENCE_CLOCKWISE:
        side_items = new_by_side[side]
        new_first, new_last = side_items[0].name, side_items[-1].name
        values = anchor_values[side]; first_value = float(values["first_offset"])
        prefix = 0.0
        for entry in side_items[:-1]:
            span = span_resolver(entry)
            if span is None: raise ValueError(_iopadt_expand_text(f"{side.upper()} final-master width unknown for {entry.name}; cannot recompute LAST offset. Refresh __IOPADT_LITERAL_001__ DB first."))
            span = float(span)
            if span < 0: raise ValueError(_iopadt_expand_text(f"{side.upper()} negative __IOPADT_LITERAL_001__ width for {entry.name}: {span}"))
            prefix += span
        gap_count = max(0, len(side_items)-1)
        new_last_offset = _fmt(first_value + prefix + float(min_spacing)*gap_count)
        new_offsets[new_first] = values["first_offset"]
        new_offsets[new_last] = new_last_offset
        anchor_moves[side] = {
            "old_first": values["first_id"], "new_first": new_first,
            "first_offset": values["first_offset"], "old_last": values["last_id"],
            "new_last": new_last, "old_last_offset": values["old_last_offset"],
            "last_offset": new_last_offset,
            "last_offset_formula": "first_offset + sum(widths before last) + PAD_MIN_SPACING*(N-1)",
            "min_spacing": float(min_spacing),
        }
    return new_items, new_offsets, {"counts": normalized_counts, "anchor_moves": anchor_moves, "min_spacing": float(min_spacing)}
def canonical_ring_entries(entries, facts=None):
    """
    Build the authoritative physical clockwise __IOPADT_LITERAL_001__-ring traversal.

    V92 AUTHORITY RULE
    ------------------
    IO_FILE owns Ring topology and order.

    Innovus DB location / bbox / orient / place_status are NEVER used to
    reorder the Ring. Live DB queries can occur before IO placement, after
    placement, or at an intermediate checkpoint, so physical geometry cannot
    be the topology authority.

    Clockwise traversal is derived from IO_FILE side + ordinal only:

      TOP    : IO_FILE ordinal ascending
      RIGHT  : IO_FILE ordinal descending
      BOTTOM : IO_FILE ordinal descending
      LEFT   : IO_FILE ordinal ascending

    This preserves the frozen clockwise traversal:

      TOP L->R
      RIGHT T->B
      BOTTOM R->L
      LEFT B->T

    DB geometry remains available for diagnostics only.

    NOTE: this is physical CLOCKWISE order, not IO_FILE side emission order.
    RIGHT/BOTTOM are reversed again when serializing/checking offsets.
    """
    by_side = {
        "top": [],
        "right": [],
        "bottom": [],
        "left": [],
    }

    for entry in entries:
        if entry.side in by_side:
            by_side[entry.side].append(entry)

    def ordered_side(side):
        ordered = sorted(
            by_side[side],
            key=lambda entry: entry.ordinal,
        )

        if side in (
            "right",
            "bottom",
        ):
            ordered = list(
                reversed(ordered)
            )

        return ordered

    top = ordered_side("top")
    right = ordered_side("right")
    bottom = ordered_side("bottom")
    left = ordered_side("left")

    ordered = (
        top
        + right
        + bottom
        + left
    )

    dbg(
        "RING_ORDER authority=IO_FILE "
        f"TOP[{len(top)}] RIGHT[{len(right)}] "
        f"BOTTOM[{len(bottom)}] LEFT[{len(left)}]"
    )

    def n(entry):
        return (
            entry.name
            if entry
            else "<none>"
        )

    if top and right:
        dbg(
            "RING_CORNER TOP->RIGHT : "
            f"{n(top[-1])} -> {n(right[0])}"
        )

    if right and bottom:
        dbg(
            "RING_CORNER RIGHT->BOTTOM : "
            f"{n(right[-1])} -> {n(bottom[0])}"
        )

    if bottom and left:
        dbg(
            "RING_CORNER BOTTOM->LEFT : "
            f"{n(bottom[-1])} -> {n(left[0])}"
        )

    if left and top:
        dbg(
            "RING_CORNER LEFT->TOP : "
            f"{n(left[-1])} -> {n(top[0])}"
        )

    return ordered


def audit_db_geometry_against_iofile_ring(
    ordered,
    facts,
):
    """
    Informational-only Innovus geometry snapshot.

    The result is never used to sort/reorder the Ring.
    """
    rows = []

    for ring_index, entry in enumerate(
        ordered
    ):
        fact = facts.get(
            entry.name
        )

        if (
            fact is None
            or not fact.found
        ):
            continue

        xy = parse_location_xy(
            fact.location
        )

        rows.append({
            "ring_index": ring_index,
            "instance": entry.name,
            "side": entry.side,
            "ordinal": entry.ordinal,
            "location_valid": bool(
                xy is not None
            ),
            "x": (
                float(xy[0])
                if xy is not None
                else None
            ),
            "y": (
                float(xy[1])
                if xy is not None
                else None
            ),
            "place_status": str(
                fact.place_status
            ),
            "orient": str(
                fact.orient
            ),
        })

    usable = sum(
        1
        for row in rows
        if row["location_valid"]
    )

    dbg(
        "DB_GEOMETRY_AUDIT "
        f"found={len(rows)}/{len(ordered)} "
        f"usable_locations={usable} "
        "authority=INFORMATION_ONLY"
    )

    return rows


RAIL_DEFS = IOPADT_RULES["rail_defs"]

# Current electrical policy:
# all three modeled rails propagate along the ring and stop at configured library token.
# This is explicit so it is not hidden inside the algorithm.
RAIL_CUT_AT_RAILCUT = IOPADT_RULES["rail_cut_at_boundary"]


def fact_carries_rail(d, rail_name):
    if not d or not d.found:
        return False

    cfg = RAIL_DEFS[rail_name]
    if cfg["carrier_kind"] == "pg":
        return cfg["carrier_pin"] in set(d.pg_pins)
    return cfg["carrier_pin"] in set(d.pins)


def build_io_domains_from_ring(ordered, facts):
    """
    Split a CIRCULAR ring into __IOPADT_LITERAL_003__-to-__IOPADT_LITERAL_003__ IO Domains.

    Clockwise numbering policy
    --------------------------
    canonical_ring_entries() starts at the physical TOP-LEFT side and walks:

      TOP L->R
      RIGHT T->B
      BOTTOM R->L
      LEFT B->T
      then wraps back to TOP-LEFT

    D1 is defined as the IO Domain containing ring[0].
    D2, D3, ... then advance clockwise around the ring.

    This prevents the old visual numbering:
      D8 -> D1 -> D2 ...
    near the TOP side.

    Critical head/tail detail:
      the domain spanning ordered[-1] -> ordered[0] is a normal domain,
      not a special broken linear-list case.
    """
    if not ordered:
        return [], {}

    cut_indices = [
        i for i, e in enumerate(ordered)
        if facts[e.name].role == _iopadt_expand_text("__IOPADT_LITERAL_003__")
    ]

    if not cut_indices:
        groups = [("", "", list(ordered))]
    else:
        raw_groups = []
        n = len(ordered)

        for k, cut_i in enumerate(cut_indices):
            next_cut_i = cut_indices[(k + 1) % len(cut_indices)]

            members = []
            i = (cut_i + 1) % n
            while i != next_cut_i:
                members.append(ordered[i])
                i = (i + 1) % n

            raw_groups.append((
                ordered[cut_i].name,
                ordered[next_cut_i].name,
                members,
            ))

        # --------------------------------------------------------------
        # Rotate domain list so the domain encountered at ring[0] is D1.
        #
        # If ring[0] itself is a configured library token, then D1 is the domain immediately
        # clockwise AFTER that configured library token.
        # Otherwise D1 is the unique domain whose members contain ring[0].
        # --------------------------------------------------------------
        start_name = ordered[0].name
        start_role = facts[start_name].role
        rotate_at = 0

        if start_role == _iopadt_expand_text("__IOPADT_LITERAL_003__"):
            for idx, (start_cut, _, _) in enumerate(raw_groups):
                if start_cut == start_name:
                    rotate_at = idx
                    break
        else:
            found = False
            for idx, (_, _, members) in enumerate(raw_groups):
                if any(e.name == start_name for e in members):
                    rotate_at = idx
                    found = True
                    break

            # Extremely defensive fallback: if ring[0] is not in members due
            # to malformed input, use the wrap-around group whose arc crosses 0.
            if not found:
                for idx, (start_cut, end_cut, _) in enumerate(raw_groups):
                    si = next(
                        (j for j, e in enumerate(ordered) if e.name == start_cut),
                        None
                    )
                    ei = next(
                        (j for j, e in enumerate(ordered) if e.name == end_cut),
                        None
                    )
                    if si is not None and ei is not None and si > ei:
                        rotate_at = idx
                        break

        groups = raw_groups[rotate_at:] + raw_groups[:rotate_at]

    domain_by_name = {}

    for domain_id, (_, _, members) in enumerate(groups, 1):
        for e in members:
            domain_by_name[e.name] = domain_id

    # configured library token cells themselves sit BETWEEN domains. For click/debug purposes,
    # map each configured library token to the clockwise domain that starts after it.
    for domain_id, (start_cut, _, _) in enumerate(groups, 1):
        if start_cut:
            domain_by_name[start_cut] = domain_id

    dbg(
        "IO_DOMAIN CLOCKWISE ORDER: "
        + ", ".join(
            f"D{idx}:{start or 'RING'}->{end or 'RING'}"
            for idx, (start, end, _) in enumerate(groups, 1)
        )
    )

    if groups:
        first_start, first_end, first_members = groups[0]
        dbg(
            f"IO_DOMAIN D1 anchor ring0={ordered[0].name} "
            f"boundary={first_start}->{first_end} "
            f"members={len(first_members)}"
        )

    return groups, domain_by_name


def propagate_one_rail_circular(ordered, facts, rail_name):
    """
    True circular graph propagation.

    Graph:
      each non-__IOPADT_LITERAL_003__ ring cell i has two physical neighbors:
        (i - 1) % N
        (i + 1) % N

    Source:
      actual role from master/pin classification.

    Stop:
      __IOPADT_LITERAL_003__ is a boundary for this rail when RAIL_CUT_AT_RAILCUT[rail] is True.

    We deliberately propagate THROUGH ordinary cells even if that particular
    master does not expose the selected rail as a pin.  The ring topology is
    continuous until __IOPADT_LITERAL_003__; carrier pins are used only to decide which cells
    require/check that rail.

    Returns a source-set per ring cell, so Expected Connectivity and Ring View
    can use exactly the same electrical result.
    """
    n = len(ordered)
    result = {
        "rail": rail_name,
        "sources": set(),
        "carriers": set(),
        "powered": set(),
        "floating": set(),
        "source_map": {},
        "visited_nodes": set(),
    }

    if n == 0:
        return result

    name_to_idx = {e.name: i for i, e in enumerate(ordered)}

    source_names = [
        e.name for e in ordered
        if facts[e.name].role == RAIL_DEFS[rail_name]["source_role"]
    ]

    carrier_names = {
        e.name for e in ordered
        if facts[e.name].role != _iopadt_expand_text("__IOPADT_LITERAL_003__")
        and fact_carries_rail(facts[e.name], rail_name)
    }

    source_map = {e.name: set() for e in ordered}
    cut_at_railcut = RAIL_CUT_AT_RAILCUT[rail_name]

    for source_name in source_names:
        source_idx = name_to_idx[source_name]

        # One visited set per source so we preserve which source can reach a cell.
        seen = set()
        stack = [source_idx]

        while stack:
            idx = stack.pop()
            if idx in seen:
                continue
            seen.add(idx)

            e = ordered[idx]
            d = facts[e.name]

            # A source should never itself be configured library token, but keep this safe.
            if d.role == _iopadt_expand_text("__IOPADT_LITERAL_003__") and idx != source_idx and cut_at_railcut:
                continue

            source_map[e.name].add(source_name)

            # THE IMPORTANT PART:
            # both neighbors use modulo N, therefore ordered[-1] <-> ordered[0].
            for nb in ((idx - 1) % n, (idx + 1) % n):
                if nb in seen:
                    continue

                nb_e = ordered[nb]
                nb_d = facts[nb_e.name]

                # Do not enter/cross a configured library token on a cuttable rail.
                if cut_at_railcut and nb_d.role == _iopadt_expand_text("__IOPADT_LITERAL_003__"):
                    continue

                stack.append(nb)

    powered = {
        name for name in carrier_names
        if source_map.get(name)
    }
    floating = carrier_names - powered

    result.update({
        "sources": set(source_names),
        "carriers": set(carrier_names),
        "powered": powered,
        "floating": floating,
        "source_map": source_map,
        "visited_nodes": {
            name for name, srcs in source_map.items() if srcs
        },
    })

    # Explicit head/tail diagnostics.
    head = ordered[0]
    tail = ordered[-1]
    head_role = facts[head.name].role
    tail_role = facts[tail.name].role
    edge_blocked = (
        cut_at_railcut
        and (head_role == _iopadt_expand_text("__IOPADT_LITERAL_003__") or tail_role == _iopadt_expand_text("__IOPADT_LITERAL_003__"))
    )

    dbg(
        f"RAIL_PROP {rail_name}: "
        f"sources={len(source_names)} carriers={len(carrier_names)} "
        f"powered={len(powered)} floating={len(floating)} "
        f"head_tail={tail.name}<->{head.name} "
        f"edge={'BLOCKED_BY_RAILCUT' if edge_blocked else 'CONNECTED'}"
    )

    return result


def build_electrical_model(entries, facts):
    """
    Single source of truth for:
      - circular physical order
      - IO Domain numbering
      - Core/IO/__IOPADT_LITERAL_002__ propagation
      - FLOAT issues

    No Ring View shortcut and no "global IO power" shortcut.
    """
    physical = canonical_ring_entries(
        entries,
        facts,
    )

    # V92: DB geometry/status is informational only.
    # Never feed it back into Ring topology/order.
    audit_db_geometry_against_iofile_ring(
        physical,
        facts,
    )

    ordered = [
        e for e in physical
        if e.name in facts and facts[e.name].found
    ]

    if not ordered:
        return [], [], {}, {}

    groups, domain_by_name = build_io_domains_from_ring(ordered, facts)

    rail_models = {
        rail: propagate_one_rail_circular(ordered, facts, rail)
        for rail in ("CORE POWER", "IO POWER", _iopadt_expand_text("__IOPADT_LITERAL_002__"))
    }

    segments = []

    for domain_id, (start_cut, end_cut, members) in enumerate(groups, 1):
        member_names = [e.name for e in members]

        roles = defaultdict(list)
        unknowns = []

        for e in members:
            role = facts[e.name].role
            roles[role].append(e.name)
            if role in ("UNKNOWN", "POWER_UNKNOWN"):
                unknowns.append(e.name)

        core = roles["CORE_POWER"]
        io = roles["IO_POWER"]
        rte = roles[_iopadt_expand_text("__IOPADT_LITERAL_002__")]
        sig = roles["SIGNAL"]

        issues = []

        for rail_name in ("CORE POWER", "IO POWER", _iopadt_expand_text("__IOPADT_LITERAL_002__")):
            model = rail_models[rail_name]
            carriers = [
                name for name in member_names
                if name in model["carriers"]
            ]
            floating = [
                name for name in carriers
                if name in model["floating"]
            ]

            if floating:
                pin_name = RAIL_DEFS[rail_name]["carrier_pin"]
                issues.append(
                    _iopadt_expand_text(f"{rail_name} FLOAT: {len(floating)}/{len(carriers)} "
                    f"rail cells with {pin_name} are unreachable from any "
                    f"{rail_name} source before __IOPADT_LITERAL_003__; cells=")
                    + ", ".join(floating)
                )

        # Preserve previous diagnostics for now.
        # V38 source-count rule:
        #   CORE POWER : up to 2 source PADs per domain are legal
        #   IO POWER   : up to 2 source PADs per domain are legal
        #   configured library token        : only 1 source configured library token per domain is legal
        if len(core) > 2:
            issues.append(f"Too many Core Power sources ({len(core)} > 2)")
        if len(io) > 2:
            issues.append(f"Too many IO Power sources ({len(io)} > 2)")
        if len(rte) > 1:
            issues.append(_iopadt_expand_text(f"Multiple __IOPADT_LITERAL_002__ sources ({len(rte)} > 1)"))
        if unknowns:
            issues.append(f"Unclassified cells ({len(unknowns)})")
        if not members:
            issues.append(_iopadt_expand_text("Empty __IOPADT_LITERAL_003__-to-__IOPADT_LITERAL_003__ IO Domain"))

        segments.append(Segment(
            domain_id,
            start_cut or "",
            end_cut or "",
            member_names,
            core,
            io,
            rte,
            sig,
            unknowns,
            "PASS" if not issues else "CHECK",
            issues,
        ))

    return ordered, segments, rail_models, domain_by_name


def build_segments(entries, facts):
    # Compatibility wrapper for any old caller.
    _, segments, _, _ = build_electrical_model(entries, facts)
    return segments


def expected_rows(seg, facts, rail_models):
    """
    Expected Connectivity is derived from the SAME propagation result used by
    Ring View and Issues.
    """
    out = []

    rail_to_field = IOPADT_RULES["expected_rail_pins"]

    for name in seg.members:
        d = facts[name]
        pg = set(d.pg_pins)
        pins = set(d.pins)
        exp = {}

        ground_pins = tuple(IOPADT_RULES["ground_expectations"])
        if ground_pins[0] in pg:
            exp[ground_pins[0]] = IOPADT_RULES["ground_expectations"][ground_pins[0]]
        if ground_pins[1] in pg:
            exp[ground_pins[1]] = IOPADT_RULES["ground_expectations"][ground_pins[1]]

        for rail_name, field in rail_to_field.items():
            model = rail_models.get(rail_name, {})
            carriers = model.get("carriers", set())

            if name not in carriers:
                continue

            sources = sorted(
                model.get("source_map", {}).get(name, set())
            )

            if sources:
                exp[field] = (
                    f"{rail_name.replace(' ', '_')}_SOURCE("
                    + ",".join(sources)
                    + ")"
                )
            else:
                exp[field] = "FLOAT"

        out.append((name, d.role, exp))

    return out



RAIL_UI_ORDER = (_iopadt_expand_text("__IOPADT_LITERAL_002__"), "IO POWER", "CORE POWER")

# V129: pins settable/repairable at IO-Domain (D1..D8, configured library token-cut group)
# granularity from the new "IO Domain Sources" per-domain editor.
# configured library token/configured library token/configured library token/configured library token/configured library token must each be UNIQUE across different IO
# Domains. configured library token is expected to be consistent WITHIN one IO Domain but is
# explicitly NOT required to be unique BETWEEN IO Domains (multiple
# domains sharing one configured library token rail is normal).
#
# V129 CORRECTION (2nd pass): configured library token was added, found to be a no-op (it is a
# SIGNAL pin, not a PG pin - see classify_from_master_and_pins, `sig =
# set(pins)`), reverted, then re-added correctly:
#   - _global_net_compare_design() now synthesizes pin_results["configured library token"] for
#     configured library token-role rows directly from the live-queried d.pin_nets["configured library token"]
#     evidence (that data was already being captured by load_result() for
#     every pin regardless of PG/SIGNAL kind; it just was not being
#     surfaced under this framework before). This makes Check/the table
#     display work via the SAME generic pin_results consumers as configured library token.
#   - Repair is NOT the same mechanism as configured library token/configured library token/configured library token/configured library token
#     though: those are managed via connect_global_net (a declarative PG
#     rules file). configured library token has no such rules file - it is fixed with a direct
#     imperative `connect_pin -inst <pad> -pin configured library token -net <target>` (plus a
#     `create_net` if the target doesn't exist yet), generated fresh and
#     appended to the Apply Global Net payload - see
#     _global_net_auto_repair_rte_signal /
#     _global_net_rte_apply_tcl_block. It does not touch the configured library token-role configured library token
#     instance itself or its configured library token-side private tie net; that remains
#     entirely owned by ioPADt's own IO/DB-patch Auto Repair.
GLOBAL_NET_DOMAIN_EXCLUSIVE_PINS = tuple(IOPADT_RULES["domain_exclusive_pins"])
GLOBAL_NET_DOMAIN_CONSISTENT_ONLY_PINS = tuple(IOPADT_RULES["domain_consistent_pins"])
GLOBAL_NET_DOMAIN_SETTABLE_PINS = (
    GLOBAL_NET_DOMAIN_EXCLUSIVE_PINS + GLOBAL_NET_DOMAIN_CONSISTENT_ONLY_PINS
)

# IO Domain Sources tree column key -> Global Net pin name. "rte_net" is
# used instead of "rte" because that key is already taken by the
# unrelated existing "configured library token Source configured library token" column.
IO_DOMAIN_TREE_COLUMN_TO_PIN = IOPADT_RULES["domain_column_pins"]


def domain_rail_info(seg, rail_name, rail_models):
    """
    Summarize one rail inside one IO Domain from the actual propagation result.

    sources:
      actual source PADs that can reach at least one carrier cell in this domain.

    floating:
      carrier cells in this domain unreachable from every source.

    carriers:
      cells in this domain that actually expose the selected rail pin.
    """
    model = rail_models.get(rail_name, {})
    model_carriers = set(model.get("carriers", set()))
    model_floating = set(model.get("floating", set()))
    source_map = model.get("source_map", {})

    carriers = [
        name for name in seg.members
        if name in model_carriers
    ]

    floating = [
        name for name in carriers
        if name in model_floating
    ]

    sources = set()
    for name in carriers:
        sources.update(source_map.get(name, set()))

    # A source configured library token itself is normally a carrier. Keep this fallback for
    # unusual library masters whose source role exists without the carrier pin.
    local_role_sources = {
        _iopadt_expand_text("__IOPADT_LITERAL_002__"): seg.rte_sources,
        "IO POWER": seg.io_sources,
        "CORE POWER": seg.core_sources,
    }.get(rail_name, [])

    for source_name in local_role_sources:
        if source_name in model.get("sources", set()):
            sources.add(source_name)

    return {
        "rail": rail_name,
        "carriers": carriers,
        "floating": floating,
        "sources": sorted(sources),
    }


def domain_source_display(seg, rail_name, rail_models):
    info = domain_rail_info(seg, rail_name, rail_models)

    if info["sources"]:
        return ", ".join(info["sources"])

    if info["carriers"]:
        return "MISSING"

    return "N/A"


def build_rail_violation_rows(segments, rail_models):
    """
    Build Issues in RAIL-FIRST order instead of free-form domain-first text.

    Row fields:
      rail
      violation
      domain_id
      boundary
      sources
      affected
    """
    rows = []

    source_attr = {
        _iopadt_expand_text("__IOPADT_LITERAL_002__"): "rte_sources",
        "IO POWER": "io_sources",
        "CORE POWER": "core_sources",
    }

    # Rail violations first, in explicit UI order.
    for rail_name in RAIL_UI_ORDER:
        for seg in segments:
            info = domain_rail_info(seg, rail_name, rail_models)
            boundary = f"{seg.start_cut or 'RING'} -> {seg.end_cut or 'RING'}"

            if info["floating"]:
                rows.append({
                    "rail": rail_name,
                    "violation": "FLOAT",
                    "domain_id": seg.seg_id,
                    "boundary": boundary,
                    "sources": ", ".join(info["sources"]) if info["sources"] else "MISSING",
                    "affected": ", ".join(info["floating"]),
                })

            local_sources = list(getattr(seg, source_attr[rail_name]))

            # V38 source-count rule.
            max_sources = 1 if rail_name == _iopadt_expand_text("__IOPADT_LITERAL_002__") else 2

            if len(local_sources) > max_sources:
                rows.append({
                    "rail": rail_name,
                    "violation": "MULTIPLE_SOURCE",
                    "domain_id": seg.seg_id,
                    "boundary": boundary,
                    "sources": ", ".join(local_sources),
                    "affected": (
                        f"{len(local_sources)} source PADs in this IO Domain "
                        f"(allowed <= {max_sources})"
                    ),
                })

    # Keep non-rail structural issues visible, but place them after rail issues.
    for seg in segments:
        boundary = f"{seg.start_cut or 'RING'} -> {seg.end_cut or 'RING'}"

        if seg.unknowns:
            rows.append({
                "rail": "SYSTEM",
                "violation": "UNCLASSIFIED",
                "domain_id": seg.seg_id,
                "boundary": boundary,
                "sources": "-",
                "affected": ", ".join(seg.unknowns),
            })

        if not seg.members:
            rows.append({
                "rail": "SYSTEM",
                "violation": "EMPTY_DOMAIN",
                "domain_id": seg.seg_id,
                "boundary": boundary,
                "sources": "-",
                "affected": "No cells between adjacent RAILCUTs",
            })

    return rows



def ring_perimeter_s(x, y, side, left_x, right_x, top_y, bottom_y):
    """
    Convert a point on the rectangular __IOPADT_LITERAL_001__-ring outline to one clockwise
    perimeter coordinate.

    Clockwise origin = TOP-LEFT.

      TOP    : left  -> right
      RIGHT  : top   -> bottom
      BOTTOM : right -> left
      LEFT   : bottom-> top
    """
    w = float(right_x - left_x)
    h = float(bottom_y - top_y)

    if side == "top":
        return float(x - left_x)

    if side == "right":
        return w + float(y - top_y)

    if side == "bottom":
        return w + h + float(right_x - x)

    if side == "left":
        return w + h + w + float(bottom_y - y)

    raise ValueError(f"Unknown ring side: {side}")


def ring_perimeter_xy(s, left_x, right_x, top_y, bottom_y):
    """
    Inverse of ring_perimeter_s().
    Returns (x, y, side) for a clockwise perimeter coordinate.
    """
    w = float(right_x - left_x)
    h = float(bottom_y - top_y)
    perimeter = 2.0 * (w + h)

    if perimeter <= 0:
        raise ValueError("Invalid ring geometry")

    s = float(s) % perimeter

    if s < w:
        return left_x + s, top_y, "top"

    s -= w
    if s < h:
        return right_x, top_y + s, "right"

    s -= h
    if s < w:
        return right_x - s, bottom_y, "bottom"

    s -= w
    return left_x, bottom_y - s, "left"


def validate_domain_marker_clockwise_order(
    segments,
    markers_by_id,
    left_x,
    right_x,
    top_y,
    bottom_y,
):
    """
    Validate that D1, D2, ... marker geometry advances clockwise.
    """
    if not segments:
        return {
            "ok": True,
            "ordered_ids": [],
            "distances": [],
            "detail": "NO_DOMAINS",
        }

    ids = [
        int(seg.seg_id)
        for seg in segments
    ]

    missing = [
        domain_id
        for domain_id in ids
        if domain_id not in markers_by_id
    ]

    if missing:
        return {
            "ok": False,
            "ordered_ids": ids,
            "distances": [],
            "detail": (
                "MISSING_MARKER "
                + ",".join(
                    "D" + str(x)
                    for x in missing
                )
            ),
        }

    w = float(
        right_x - left_x
    )
    h = float(
        bottom_y - top_y
    )
    perimeter = 2.0 * (
        w + h
    )

    first_id = ids[0]
    first = markers_by_id[
        first_id
    ]

    s0 = ring_perimeter_s(
        first["x"],
        first["y"],
        first["side"],
        left_x,
        right_x,
        top_y,
        bottom_y,
    )

    distances = []

    for domain_id in ids:
        marker = markers_by_id[
            domain_id
        ]

        s = ring_perimeter_s(
            marker["x"],
            marker["y"],
            marker["side"],
            left_x,
            right_x,
            top_y,
            bottom_y,
        )

        distances.append(
            (
                domain_id,
                (s - s0) % perimeter,
            )
        )

    eps = 1.0e-6

    for idx in range(
        1,
        len(distances),
    ):
        if (
            distances[idx][1]
            + eps
            < distances[idx - 1][1]
        ):
            return {
                "ok": False,
                "ordered_ids": ids,
                "distances": distances,
                "detail": (
                    f"D{distances[idx][0]} marker moved backward "
                    f"({distances[idx][1]:.3f} < "
                    f"{distances[idx - 1][1]:.3f})"
                ),
            }

    return {
        "ok": True,
        "ordered_ids": ids,
        "distances": distances,
        "detail": "PASS",
    }


def compute_domain_boundary_midpoint(
    seg,
    ring_xy,
    left_x,
    right_x,
    top_y,
    bottom_y,
):
    """
    Marker-only domain geometry.

    IMPORTANT:
      This does NOT use electrical propagation and does NOT require member PADs.

    Every IO Domain is defined by:
      start __IOPADT_LITERAL_003__ -> clockwise ring arc -> end __IOPADT_LITERAL_003__

    Therefore the marker is based primarily on the two __IOPADT_LITERAL_003__ boundaries.

    Works for:
      - 0 __IOPADT_LITERAL_001__ domain
      - 1 __IOPADT_LITERAL_001__ domain
      - many-__IOPADT_LITERAL_001__ domain
      - corner-spanning domain
      - head/tail wrap-around domain
    """
    start_pos = ring_xy.get(seg.start_cut)
    end_pos = ring_xy.get(seg.end_cut)

    if start_pos is not None and end_pos is not None:
        sx, sy, sside = start_pos
        ex, ey, eside = end_pos

        s0 = ring_perimeter_s(
            sx, sy, sside,
            left_x, right_x, top_y, bottom_y
        )
        s1 = ring_perimeter_s(
            ex, ey, eside,
            left_x, right_x, top_y, bottom_y
        )

        w = float(right_x - left_x)
        h = float(bottom_y - top_y)
        perimeter = 2.0 * (w + h)

        clockwise_distance = (s1 - s0) % perimeter
        midpoint_s = (s0 + clockwise_distance / 2.0) % perimeter

        px, py, pside = ring_perimeter_xy(
            midpoint_s,
            left_x, right_x, top_y, bottom_y
        )

        return {
            "x": float(px),
            "y": float(py),
            "side": pside,
            "method": "RAILCUT_BOUNDARY_MIDPOINT",
            "clockwise_distance": clockwise_distance,
            "member_count": len(seg.members),
        }

    # -----------------------------------------------------------------
    # Defensive fallback only if a configured library token coordinate is unavailable.
    # Still guarantee a marker whenever any member/boundary is drawable.
    # -----------------------------------------------------------------
    visible = []
    for name in seg.members:
        if name in ring_xy:
            x, y, side = ring_xy[name]
            visible.append((float(x), float(y), side, name))

    if visible:
        # For one-configured library token domain this is exactly the configured library token position.
        # For many PADs use the middle visible configured library token.
        mid = visible[len(visible) // 2]
        return {
            "x": mid[0],
            "y": mid[1],
            "side": mid[2],
            "method": "MEMBER_FALLBACK",
            "clockwise_distance": 0.0,
            "member_count": len(seg.members),
        }

    for name in (seg.start_cut, seg.end_cut):
        if name and name in ring_xy:
            x, y, side = ring_xy[name]
            return {
                "x": float(x),
                "y": float(y),
                "side": side,
                "method": "ONE_BOUNDARY_FALLBACK",
                "clockwise_distance": 0.0,
                "member_count": len(seg.members),
            }

    return None



def _algorithm_selftest():
    """
    Head/tail regression test.

    Ring:
      SRC, A, CUT1, B, C, CUT2, D, E

    The wrap-around IO Domain is:
      CUT2 -> D -> E -> SRC -> A -> CUT1

    Therefore SRC MUST power D and E across list tail->head.
    B/C must remain blocked by CUT1/CUT2.
    """
    def fact(name, role, pg=None, pins=None):
        return DBFact(
            requested_name=name,
            found=True,
            exact_master=name,
            master_family=name,
            variant="",
            role=role,
            role_basis="selftest",
            pg_pins=pg or [],
            pins=pins or [],
        )

    ordered = [
        IOEntry("SRC", "top", 1, 1, ""),
        IOEntry("A", "top", 2, 2, ""),
        IOEntry("CUT1", "top", 3, 3, ""),
        IOEntry("B", "right", 1, 4, ""),
        IOEntry("C", "right", 2, 5, ""),
        IOEntry("CUT2", "bottom", 1, 6, ""),
        IOEntry("D", "left", 1, 7, ""),
        IOEntry("E", "left", 2, 8, ""),
    ]

    facts = {
        "SRC": fact("SRC", "CORE_POWER", [_iopadt_expand_text("__IOPADT_LITERAL_006__")]),
        "A": fact("A", "SIGNAL", [_iopadt_expand_text("__IOPADT_LITERAL_006__")]),
        "CUT1": fact("CUT1", _iopadt_expand_text("__IOPADT_LITERAL_003__")),
        "B": fact("B", "SIGNAL", [_iopadt_expand_text("__IOPADT_LITERAL_006__")]),
        "C": fact("C", "SIGNAL", [_iopadt_expand_text("__IOPADT_LITERAL_006__")]),
        "CUT2": fact("CUT2", _iopadt_expand_text("__IOPADT_LITERAL_003__")),
        "D": fact("D", "SIGNAL", [_iopadt_expand_text("__IOPADT_LITERAL_006__")]),
        "E": fact("E", "SIGNAL", [_iopadt_expand_text("__IOPADT_LITERAL_006__")]),
    }

    model = propagate_one_rail_circular(ordered, facts, "CORE POWER")

    assert "SRC" in model["powered"]
    assert "A" in model["powered"]

    # These two prove list tail -> head circular connectivity.
    assert "D" in model["powered"]
    assert "E" in model["powered"]

    # These are across configured library token and must stay isolated.
    assert "B" in model["floating"]
    assert "C" in model["floating"]

    groups, domain_by_name = build_io_domains_from_ring(ordered, facts)

    # D/E and SRC/A must be the SAME wrap-around IO Domain.
    assert domain_by_name["D"] == domain_by_name["E"]
    assert domain_by_name["E"] == domain_by_name["SRC"]
    assert domain_by_name["SRC"] == domain_by_name["A"]

    # Clockwise numbering rule: ring[0]=SRC is inside D1.
    assert domain_by_name["SRC"] == 1
    assert domain_by_name["A"] == 1
    assert domain_by_name["D"] == 1
    assert domain_by_name["E"] == 1

    dbg(
        _iopadt_expand_text("RING ALGORITHM SELFTEST PASS: "
        "tail<->head propagation works, __IOPADT_LITERAL_003__ blocks correctly, "
        "and wrap-around domain is D1")
    )


_algorithm_selftest()


def write_runtime_validation_log(
    output_path,
    physical_ring,
    segments,
    facts,
    rail_models,
    domain_by_name,
):
    """
    Write a deterministic validation report from the ACTUAL loaded TSV facts.

    This is intentionally independent of Canvas rendering.  It lets us compare:
      electrical model truth
      vs
      what the Ring View displays.
    """
    p = Path(output_path)
    lines = []
    A = lines.append

    A("=" * 108)
    A(_iopadt_expand_text("ioPADt __IOPADT_LITERAL_001__ ALGORITHM RUNTIME VALIDATION"))
    A("=" * 108)
    A(f"Ring cells : {len(physical_ring)}")
    A(f"IO Domains: {len(segments)}")
    A("")

    by_side = {
        side: [e for e in physical_ring if e.side == side]
        for side in ("top", "right", "bottom", "left")
    }

    A("CLOCKWISE PHYSICAL ORDER")
    A("-" * 108)
    A("TOP    : left -> right")
    A("RIGHT  : top -> bottom")
    A("BOTTOM : right -> left")
    A("LEFT   : bottom -> top")
    A("")

    if all(by_side[s] for s in by_side):
        A("CORNER EDGES")
        A(f"TOP->RIGHT    : {by_side['top'][-1].name} -> {by_side['right'][0].name}")
        A(f"RIGHT->BOTTOM : {by_side['right'][-1].name} -> {by_side['bottom'][0].name}")
        A(f"BOTTOM->LEFT  : {by_side['bottom'][-1].name} -> {by_side['left'][0].name}")
        A(f"LEFT->TOP     : {by_side['left'][-1].name} -> {by_side['top'][0].name}")
        A(f"HEAD/TAIL     : {physical_ring[-1].name} <-> {physical_ring[0].name}")
        A("")

    A("CANVAS MAPPING POLICY")
    A("-" * 108)
    A("TOP    canonical list -> canvas LEFT->RIGHT         reverse=False")
    A("RIGHT  canonical list -> canvas TOP->BOTTOM         reverse=False")
    A("BOTTOM canonical list -> canvas RIGHT->LEFT         reverse=True")
    A("LEFT   canonical list -> canvas BOTTOM->TOP         reverse=True")
    A("")

    A("CLOCKWISE IO DOMAIN / SOURCE / FLOAT TABLE")
    A("-" * 108)

    for seg in segments:
        boundary = f"{seg.start_cut or 'RING'} -> {seg.end_cut or 'RING'}"
        A(f"D{seg.seg_id}: {boundary}  members={len(seg.members)}")

        for rail in (_iopadt_expand_text("__IOPADT_LITERAL_002__"), "IO POWER", "CORE POWER"):
            model = rail_models.get(rail, {})
            carriers = set(model.get("carriers", set()))
            floating = set(model.get("floating", set()))
            source_map = model.get("source_map", {})

            domain_carriers = [n for n in seg.members if n in carriers]
            domain_float = [n for n in domain_carriers if n in floating]

            reachable_sources = set()
            for n in domain_carriers:
                reachable_sources.update(source_map.get(n, set()))

            local_role_sources = {
                _iopadt_expand_text("__IOPADT_LITERAL_002__"): list(seg.rte_sources),
                "IO POWER": list(seg.io_sources),
                "CORE POWER": list(seg.core_sources),
            }[rail]

            A(
                f"    {rail:<10} "
                f"local_sources={local_role_sources or ['<none>']} "
                f"reachable_sources={sorted(reachable_sources) or ['<none>']} "
                f"carriers={len(domain_carriers)} "
                f"float={len(domain_float)}"
            )

        A("")

    # Basic invariants.
    errors = []

    ids = [s.seg_id for s in segments]
    if ids != list(range(1, len(segments) + 1)):
        errors.append(f"domain IDs are not contiguous: {ids}")

    mapped_members = {
        n for n in domain_by_name
        if n in {e.name for e in physical_ring}
    }
    non_railcut_names = {
        e.name for e in physical_ring
        if facts[e.name].role != _iopadt_expand_text("__IOPADT_LITERAL_003__")
    }
    if not non_railcut_names.issubset(mapped_members):
        missing = sorted(non_railcut_names - mapped_members)
        errors.append(_iopadt_expand_text(f"non-__IOPADT_LITERAL_003__ cells missing domain mapping: {missing}"))

    A("INVARIANTS")
    A("-" * 108)
    if errors:
        for err in errors:
            A("FAIL: " + err)
    else:
        A("PASS: domain IDs contiguous")
        A(_iopadt_expand_text("PASS: every non-__IOPADT_LITERAL_003__ ring cell belongs to an IO Domain"))
        A("PASS: head/tail is represented as a circular ring edge")
        A("PASS: Bottom/Left Canvas mapping matches clockwise physical direction")

    A("=" * 108)
    p.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return str(p)



