# REPAIR PLANNER HELPERS
# =============================================================================

def clone_db_fact_for_instance(exemplar, new_name):
    d = copy.deepcopy(exemplar)
    d.requested_name = new_name
    d.found = True
    d.location = ""
    d.bbox = ""
    d.place_status = "SIMULATED"
    return d


def normalize_repair_ordinals(ordered):
    counts = defaultdict(int)
    for e in ordered:
        counts[e.side] += 1
        e.ordinal = counts[e.side]
    return ordered


def build_electrical_model_from_physical_order(ordered, facts):
    """
    Repair simulation adapter.

    The electrical algorithm is frozen.
    User edits the already-physical clockwise ring order, so this adapter
    skips canonical_ring_entries() but reuses the same:
      build_io_domains_from_ring()
      propagate_one_rail_circular()
      RAIL_DEFS / RAIL_CUT_AT_RAILCUT
    """
    ordered = [
        e for e in ordered
        if e.name in facts and facts[e.name].found
    ]

    if not ordered:
        return [], [], {}, {}

    groups, domain_by_name = build_io_domains_from_ring(ordered, facts)

    rail_models = {
        rail: propagate_one_rail_circular(ordered, facts, rail)
        for rail in ("CORE POWER", "IO POWER", _iopadt_expand_text("__IOPADT_LITERAL_002__"))
    }

    segments = []

    for domain_id, (start_cut, end_cut, members) in enumerate(groups, 1):
        member_names = [e.name for e in members]
        roles = defaultdict(list)
        unknowns = []

        for e in members:
            role = facts[e.name].role
            roles[role].append(e.name)
            if role in ("UNKNOWN", "POWER_UNKNOWN"):
                unknowns.append(e.name)

        core = roles["CORE_POWER"]
        io = roles["IO_POWER"]
        rte = roles[_iopadt_expand_text("__IOPADT_LITERAL_002__")]
        sig = roles["SIGNAL"]

        issues = []

        for rail_name in ("CORE POWER", "IO POWER", _iopadt_expand_text("__IOPADT_LITERAL_002__")):
            model = rail_models[rail_name]
            carriers = [
                name for name in member_names
                if name in model["carriers"]
            ]
            floating = [
                name for name in carriers
                if name in model["floating"]
            ]

            if floating:
                pin_name = RAIL_DEFS[rail_name]["carrier_pin"]
                issues.append(
                    _iopadt_expand_text(f"{rail_name} FLOAT: {len(floating)}/{len(carriers)} "
                    f"rail cells with {pin_name} are unreachable from any "
                    f"{rail_name} source before __IOPADT_LITERAL_003__; cells=")
                    + ", ".join(floating)
                )

        # Same source-count legality as authoritative base model.
        if len(core) > 2:
            issues.append(
                f"Too many Core Power sources ({len(core)} > 2)"
            )
        if len(io) > 2:
            issues.append(
                f"Too many IO Power sources ({len(io)} > 2)"
            )
        if len(rte) > 1:
            issues.append(
                _iopadt_expand_text(f"Multiple __IOPADT_LITERAL_002__ sources ({len(rte)} > 1)")
            )
        if unknowns:
            issues.append(f"Unclassified cells ({len(unknowns)})")
        if not members:
            issues.append(_iopadt_expand_text("Empty __IOPADT_LITERAL_003__-to-__IOPADT_LITERAL_003__ IO Domain"))

        segments.append(Segment(
            domain_id,
            start_cut or "",
            end_cut or "",
            member_names,
            core,
            io,
            rte,
            sig,
            unknowns,
            "PASS" if not issues else "CHECK",
            issues,
        ))

    return ordered, segments, rail_models, domain_by_name


def repair_master_catalog(entries, facts):
    """
    Exact masters observed in the REAL loaded TSV/model.
    No instance-name guessing.
    """
    by_master = {}
    side_by_name = {e.name: e.side for e in entries}

    for name, d in facts.items():
        if not d.found or not d.exact_master:
            continue

        rec = by_master.setdefault(d.exact_master, {
            "exact_master": d.exact_master,
            "family": d.master_family,
            "variant": d.variant,
            "role": d.role,
            "sides": set(),
            "instances": [],
            "exemplar": d,
        })

        side = side_by_name.get(name)
        if side:
            rec["sides"].add(side)
        rec["instances"].append(name)

    return sorted(
        by_master.values(),
        key=lambda r: (
            r["role"],
            r["family"],
            r["exact_master"],
        )
    )


def repair_violation_rows(segments, rail_models):
    return build_rail_violation_rows(segments, rail_models)


def repair_float_sets(rail_models):
    return {
        rail: set(rail_models.get(rail, {}).get("floating", set()))
        for rail in (_iopadt_expand_text("__IOPADT_LITERAL_002__"), "IO POWER", "CORE POWER")
    }


def repair_delta_rows(before_models, after_models, after_domain_by_name):
    rows = []
    before = repair_float_sets(before_models)
    after = repair_float_sets(after_models)

    for rail in (_iopadt_expand_text("__IOPADT_LITERAL_002__"), "IO POWER", "CORE POWER"):
        fixed = sorted(before[rail] - after[rail])
        new = sorted(after[rail] - before[rail])
        remaining = sorted(after[rail] & before[rail])

        for status, names in (
            ("FIXED", fixed),
            ("NEW", new),
            ("REMAINING", remaining),
        ):
            if not names:
                continue

            by_domain = defaultdict(list)
            for name in names:
                by_domain[after_domain_by_name.get(name, "-")].append(name)

            for domain_id, cells in sorted(
                by_domain.items(),
                key=lambda kv: (999999 if kv[0] == "-" else int(kv[0]))
            ):
                rows.append({
                    "status": status,
                    "rail": rail,
                    "domain": "-" if domain_id == "-" else f"D{domain_id}",
                    "count": len(cells),
                    "cells": ", ".join(cells),
                })

    return rows


def repair_side_master_warning(exact_master, target_side, catalog):
    for rec in catalog:
        if rec["exact_master"] == exact_master:
            if target_side in rec["sides"]:
                return ""
            seen = ", ".join(sorted(rec["sides"])) or "<none>"
            return (
                f"Master {exact_master} has not been observed on {target_side}; "
                f"observed side(s): {seen}. H/V/geometry must be checked."
            )
    return f"Master {exact_master} is not in the loaded master catalog."


def insert_relative(ordered, moving_or_new_entry, anchor_name, place_after):
    anchor_idx = next(
        (i for i, e in enumerate(ordered) if e.name == anchor_name),
        None
    )
    if anchor_idx is None:
        raise ValueError(f"Anchor not found: {anchor_name}")

    insert_idx = anchor_idx + (1 if place_after else 0)
    ordered.insert(insert_idx, moving_or_new_entry)
    return normalize_repair_ordinals(ordered)


def unique_repair_name(base, existing_names):
    base = re.sub(r"[^A-Za-z0-9_]+", "_", base.strip())
    if not base:
        base = "NEW_IOPAD"

    if base not in existing_names:
        return base

    i = 1
    while f"{base}_{i}" in existing_names:
        i += 1
    return f"{base}_{i}"


class GlobalNetCommandValidationError(ValueError):
    """
    Validation failure with explicit editor field ownership.

    `fields` uses V82 editor keys such as:
      net, type, pin, inst, single, hinst, pd, netbase, region,
      all, nonhier, override, netlist_override.
    """
    def __init__(self, fields, message):
        if isinstance(fields, str):
            fields = [fields]

        self.fields = [
            str(field)
            for field in (fields or [])
            if str(field)
        ]
        self.message = str(message)
        super().__init__(self.message)


