    # ------------------------------------------------------------------
    # V128.3 Copyable UI layer
    # ------------------------------------------------------------------
    def _clipboard_set_text(self, text):
        """Write text to the OS clipboard, hardened against the flaky-X11
        failure mode reported across multiple dialogs (Apply/Check popups,
        Issue lists, Global Net editor): clipboard_append() can silently
        lose ownership if the window that owns the CLIPBOARD selection loses
        focus / is destroyed before another app's SelectionRequest is
        serviced, and update_idletasks() alone does not guarantee Tk has
        actually processed that request. There is no log signal for this
        failure mode (the old code path never raised), so the button looked
        "broken" with nothing to diagnose.

        This version: (1) forces a full update() so pending X11 selection
        events are actually serviced before returning, not just idle tasks;
        (2) retries once on any exception; (3) if the clipboard still cannot
        be confirmed, ALWAYS falls back to writing the text to a file under
        build/clipboard_fallback/ and reports that path in the status bar,
        so "Copy All" never just silently does nothing.
        """
        text = str(text if text is not None else "")

        def _try_once():
            self.clipboard_clear()
            self.clipboard_append(text)
            # Full update(), not just update_idletasks(): only update()
            # drains the X11 event queue enough for SelectionRequest/
            # SelectionNotify to actually be serviced before this returns.
            self.update()
            # Best-effort confirmation: some Tk/X11 combinations support
            # reading back the CLIPBOARD selection immediately; if they
            # don't, this simply can't confirm and we fall through to the
            # file fallback rather than claim false success.
            try:
                readback = self.clipboard_get()
            except Exception:
                return True  # cannot confirm either way; assume success
            return readback == text

        for attempt in (1, 2):
            try:
                if _try_once():
                    return True
            except Exception:
                logging.exception(
                    "clipboard write failed attempt=%d", attempt
                )

        # Both attempts failed (or could not be confirmed as failing safe) -
        # never leave the user with a silently-broken button. Write the
        # exact same text to a file they can open/paste from instead.
        try:
            fallback_dir = RUNTIME_BUILD_DIR / "clipboard_fallback"
            fallback_dir.mkdir(parents=True, exist_ok=True)
            stamp = (
                time.strftime("%Y%m%d_%H%M%S")
                + f"_{time.time_ns() % 1000000000:09d}"
            )
            fallback_path = fallback_dir / f"copy_{stamp}.txt"
            fallback_path.write_text(text, encoding="utf-8")
            self.status.set(
                "Clipboard write could not be confirmed; wrote the same "
                f"text to {fallback_path} instead."
            )
            logging.warning(
                "clipboard fallback used, wrote %s", fallback_path
            )
        except Exception:
            logging.exception("clipboard fallback file write also failed")
        return False

    def _copyable_dialog(
        self,
        title,
        message,
        *,
        kind="info",
        parent=None,
        ask=False,
        default=None,
        **_unused,
    ):
        """Tk modal whose text is selectable/copyable.

        Native tkinter.messagebox labels cannot be selected on many Linux/X11
        desktops.  ioPADt diagnostics are frequently copied into APR/debug
        handoffs, so every info/warning/error/yes-no dialog uses a read-only
        Text widget, Ctrl+A/C, right-click Copy, and an explicit Copy All
        button.
        """
        parent = parent if parent is not None else self
        message = str(message if message is not None else "")
        title = str(title if title is not None else "ioPADt")
        result = {"value": False if ask else "ok"}

        win = tk.Toplevel(parent)
        win.title(title)
        try:
            win.transient(parent)
        except Exception:
            pass
        win.resizable(True, True)

        outer = ttk.Frame(win, padding=12)
        outer.pack(fill="both", expand=True)
        outer.rowconfigure(1, weight=1)
        outer.columnconfigure(0, weight=1)

        kind_upper = str(kind or "info").upper()
        if kind_upper == "ERROR":
            header = "ERROR"
        elif kind_upper == "WARNING":
            header = "WARNING"
        elif ask:
            header = "CONFIRM"
        else:
            header = "INFO"

        ttk.Label(
            outer,
            text=header + " — " + title,
            font=("Segoe UI", 10, "bold"),
        ).grid(row=0, column=0, sticky="w", pady=(0, 8))

        text_frame = ttk.Frame(outer)
        text_frame.grid(row=1, column=0, sticky="nsew")
        text_frame.rowconfigure(0, weight=1)
        text_frame.columnconfigure(0, weight=1)

        lines = message.splitlines() or [""]
        longest = max((len(x) for x in lines), default=40)
        width = max(52, min(110, longest + 4))
        height = max(8, min(28, len(lines) + 4))
        body = tk.Text(
            text_frame,
            wrap="word",
            width=width,
            height=height,
            undo=False,
            exportselection=True,
        )
        ybar = ttk.Scrollbar(text_frame, orient="vertical", command=body.yview)
        xbar = ttk.Scrollbar(text_frame, orient="horizontal", command=body.xview)
        body.configure(yscrollcommand=ybar.set, xscrollcommand=xbar.set)
        body.grid(row=0, column=0, sticky="nsew")
        ybar.grid(row=0, column=1, sticky="ns")
        xbar.grid(row=1, column=0, sticky="ew")
        body.insert("1.0", message)
        body.mark_set("insert", "1.0")

        # Read-only behaviour while retaining mouse selection/navigation.
        def readonly_key(event):
            ctrl = bool(event.state & 0x4)
            key = str(event.keysym).lower()
            if ctrl and key == "c":
                return None
            if ctrl and key == "a":
                body.tag_add("sel", "1.0", "end-1c")
                body.mark_set("insert", "1.0")
                body.see("1.0")
                return "break"
            if key in {
                "left", "right", "up", "down", "home", "end",
                "prior", "next", "escape", "tab", "iso_left_tab",
            }:
                return None
            return "break"

        body.bind("<KeyPress>", readonly_key, add="+")

        def copy_selected(_event=None):
            try:
                value = body.get("sel.first", "sel.last")
            except tk.TclError:
                value = ""
            if value:
                self._clipboard_set_text(value)
            return "break"

        def copy_all(_event=None):
            # Include the title so pasted debug reports remain self-describing.
            self._clipboard_set_text(title + "\n\n" + message)
            return "break"

        body.bind("<Control-c>", copy_selected, add="+")
        body.bind("<Control-C>", copy_selected, add="+")
        body.bind("<Control-a>", lambda e: (body.tag_add("sel", "1.0", "end-1c"), "break")[1], add="+")
        body.bind("<Control-A>", lambda e: (body.tag_add("sel", "1.0", "end-1c"), "break")[1], add="+")

        popup = tk.Menu(win, tearoff=False)
        popup.add_command(label="Copy", command=lambda: copy_selected())
        popup.add_command(label="Copy All", command=lambda: copy_all())
        body.bind(
            "<Button-3>",
            lambda e: (popup.tk_popup(e.x_root, e.y_root), "break")[1],
            add="+",
        )

        buttons = ttk.Frame(outer)
        buttons.grid(row=2, column=0, sticky="e", pady=(10, 0))
        ttk.Button(buttons, text="Copy All", command=copy_all).pack(side="left", padx=(0, 8))

        def finish(value):
            result["value"] = value
            try:
                win.grab_release()
            except Exception:
                pass
            win.destroy()

        if ask:
            yes_btn = ttk.Button(buttons, text="Yes", command=lambda: finish(True))
            no_btn = ttk.Button(buttons, text="No", command=lambda: finish(False))
            yes_btn.pack(side="left", padx=(0, 6))
            no_btn.pack(side="left")
            win.protocol("WM_DELETE_WINDOW", lambda: finish(False))
            win.bind("<Escape>", lambda _e: finish(False))
            if str(default or "").lower() in ("no", "cancel"):
                no_btn.focus_set()
            else:
                yes_btn.focus_set()
        else:
            ok_btn = ttk.Button(buttons, text="OK", command=lambda: finish("ok"))
            ok_btn.pack(side="left")
            win.protocol("WM_DELETE_WINDOW", lambda: finish("ok"))
            win.bind("<Escape>", lambda _e: finish("ok"))
            ok_btn.focus_set()

        # Conservative geometry: large enough for diagnostics, still movable.
        try:
            win.update_idletasks()
            req_w = max(560, min(980, win.winfo_reqwidth()))
            req_h = max(300, min(720, win.winfo_reqheight()))
            px = int(parent.winfo_rootx() + max(20, (parent.winfo_width() - req_w) / 2))
            py = int(parent.winfo_rooty() + max(20, (parent.winfo_height() - req_h) / 2))
            win.geometry(f"{req_w}x{req_h}+{px}+{py}")
        except Exception:
            pass

        try:
            win.grab_set()
        except Exception:
            pass
        body.focus_set()
        win.wait_window()
        return result["value"]

    def _show_copyable_info(self, title, message, **kwargs):
        return self._copyable_dialog(title, message, kind="info", **kwargs)

    def _show_copyable_warning(self, title, message, **kwargs):
        return self._copyable_dialog(title, message, kind="warning", **kwargs)

    def _show_copyable_error(self, title, message, **kwargs):
        return self._copyable_dialog(title, message, kind="error", **kwargs)

    def _ask_copyable_yesno(self, title, message, **kwargs):
        return bool(self._copyable_dialog(title, message, kind="question", ask=True, **kwargs))

    def _widget_label_text(self, widget):
        try:
            varname = str(widget.cget("textvariable") or "")
            if varname:
                return str(widget.getvar(varname))
        except Exception:
            pass
        try:
            return str(widget.cget("text") or "")
        except Exception:
            return ""

    def _label_copy_menu(self, event):
        text = self._widget_label_text(event.widget)
        if not text:
            return None
        menu = tk.Menu(self, tearoff=False)
        menu.add_command(label="Copy Text", command=lambda: self._clipboard_set_text(text))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            try:
                menu.grab_release()
            except Exception:
                pass
        return "break"

    def _copy_treeview_selection(self, event):
        tree = event.widget
        try:
            selected = list(tree.selection())
            if not selected:
                focus = tree.focus()
                selected = [focus] if focus else []
            if not selected:
                return "break"

            cols = list(tree.cget("columns") or ())
            headers = []
            include_tree = any(str(tree.item(i, "text") or "") for i in selected)
            if include_tree:
                headers.append(str(tree.heading("#0", "text") or "Object"))
            headers.extend(str(tree.heading(c, "text") or c) for c in cols)
            rows = []
            if headers:
                rows.append("\t".join(headers))
            for item in selected:
                vals = []
                if include_tree:
                    vals.append(str(tree.item(item, "text") or ""))
                vals.extend(str(v) for v in (tree.item(item, "values") or ()))
                rows.append("\t".join(vals))
            self._clipboard_set_text("\n".join(rows))
        except Exception:
            logging.exception("Treeview copy failed")
        return "break"

    def _issue_tree_widget(self, tree_or_frame):
        return getattr(tree_or_frame, "tree", tree_or_frame)

    def _issue_tree_text(self, tree_or_frame, selected_only=True):
        """Return a complete tab-separated issue report suitable for copy/paste."""
        tree = self._issue_tree_widget(tree_or_frame)
        if tree is None:
            return ""
        try:
            items = list(tree.selection()) if selected_only else list(tree.get_children(""))
            if selected_only and not items:
                focus = tree.focus()
                items = [focus] if focus else []
            if not items:
                return ""
            cols = list(tree.cget("columns") or ())
            headers = [str(tree.heading(c, "text") or c) for c in cols]
            lines = ["\t".join(headers)] if headers else []
            for iid in items:
                vals = [str(v) for v in (tree.item(iid, "values") or ())]
                lines.append("\t".join(vals))
            return "\n".join(lines)
        except Exception:
            logging.exception("Issue tree text export failed")
            return ""

    def _copy_issue_tree(self, tree_or_frame, selected_only=True):
        text = self._issue_tree_text(tree_or_frame, selected_only=selected_only)
        if text:
            self._clipboard_set_text(text)
            self.status.set(
                "Copied selected issue(s) to clipboard."
                if selected_only else "Copied all visible issues to clipboard."
            )
            return True
        self.status.set("No issue row is available to copy.")
        return False

    def _open_issue_tree_detail(self, tree_or_frame, title="Issue Detail"):
        tree = self._issue_tree_widget(tree_or_frame)
        if tree is None:
            return False
        try:
            selected = list(tree.selection())
            iid = selected[0] if selected else tree.focus()
            if not iid:
                self.status.set("Select an issue row first.")
                return False
            cols = list(tree.cget("columns") or ())
            vals = list(tree.item(iid, "values") or ())
            lines = []
            for idx, col in enumerate(cols):
                head = str(tree.heading(col, "text") or col)
                value = str(vals[idx]) if idx < len(vals) else ""
                lines.append(f"{head}: {value}")
            self._show_copyable_info(title, "\n".join(lines))
            return True
        except Exception as exc:
            logging.exception("Open issue detail failed")
            self._show_copyable_error("Issue Detail", str(exc))
            return False

    def _add_issue_copy_buttons(self, parent, tree_or_frame, title):
        bar = ttk.Frame(parent)
        ttk.Button(
            bar, text="Open Detail",
            command=lambda: self._open_issue_tree_detail(tree_or_frame, title),
        ).pack(side="left")
        ttk.Button(
            bar, text="Copy Selected",
            command=lambda: self._copy_issue_tree(tree_or_frame, selected_only=True),
        ).pack(side="left", padx=(6,0))
        ttk.Button(
            bar, text="Copy All",
            command=lambda: self._copy_issue_tree(tree_or_frame, selected_only=False),
        ).pack(side="left", padx=(6,0))
        return bar

    def _install_interface_copy_bindings(self):
        """Make non-editable UI diagnostics copy-friendly.

        - All app dialogs are custom selectable dialogs (wrappers above).
        - Right-click any Label -> Copy Text.
        - Ctrl+C in any Treeview -> tab-separated selected rows.
        - Issue panes also expose Open Detail / Copy Selected / Copy All.
        Existing Entry/Text copy behaviour is left untouched.
        """
        for klass in ("TLabel", "Label"):
            try:
                self.bind_class(klass, "<Button-3>", self._label_copy_menu, add="+")
            except Exception:
                logging.exception("label copy binding failed class=%s", klass)
        try:
            self.bind_class("Treeview", "<Control-c>", self._copy_treeview_selection, add="+")
            self.bind_class("Treeview", "<Control-C>", self._copy_treeview_selection, add="+")
        except Exception:
            logging.exception("Treeview copy binding failed")
        dbg("COPYABLE UI enabled dialogs+labels+treeviews")

    def _global_net_check_copy_report(self):
        """Plain-text post-apply report suitable for clipboard/paste."""
        comp = self.global_net_last_check_result
        if not isinstance(comp, dict):
            return "No detailed Global Net check result is available."

        lines = [
            self.global_net_check_text.get(),
            (
                "checked={checked} pass={passed} fail={failed} warning={warning} info={info} "
                "policy={policy} railcut_supply_fail={railcut_fail} railcut_supply_checked={railcut_checked} "
                "physical={physical} db_connectivity={db} save_errors={save}"
            ).format(
                checked=comp.get("checked_count", 0),
                passed=comp.get("pass_count", 0),
                failed=comp.get("fail_count", 0),
                warning=comp.get("warning_count", 0),
                info=comp.get("info_count", 0),
                policy=comp.get("policy_issue_count", 0),
                railcut_fail=comp.get("railcut_supply_issue_count", 0),
                railcut_checked=comp.get("railcut_supply_checked_count", 0),
                physical=comp.get("physical_issue_count", 0),
                db=comp.get("db_connectivity_issue_count", 0),
                save=comp.get("save_error_count", 0),
            ),
        ]

        io_pd = comp.get("io_power_domain", {})
        if isinstance(io_pd, dict):
            lines.append(
                "IO_DOMAIN: status={status} domain={domain} reason={reason}".format(
                    status=io_pd.get("status", "-"),
                    domain=io_pd.get("domain", "-") or "-",
                    reason=io_pd.get("reason", "-") or "-",
                )
            )

        railcut_checks = list(comp.get("railcut_supply_checks", []) or [])
        if railcut_checks:
            lines.append("")
            lines.append(_iopadt_expand_text("__IOPADT_LITERAL_003__ SUPPLY SEGMENT CHECKS (__IOPADT_LITERAL_004__ / __IOPADT_LITERAL_005__ ONLY)"))
            for item in railcut_checks:
                lines.append(
                    "D{domain} {pin} {status} boundary={start}->{end} "
                    "exposing={exposing} resolved={resolved} unresolved={unresolved} nets={nets}".format(
                        domain=item.get("domain_id", "-"),
                        pin=item.get("pin", "-"),
                        status=item.get("status", "-"),
                        start=item.get("start_cut", "-"),
                        end=item.get("end_cut", "-"),
                        exposing=item.get("exposing_count", 0),
                        resolved=item.get("resolved_count", 0),
                        unresolved=item.get("unresolved_count", 0),
                        nets="/".join(item.get("nets", []) or []) or "-",
                    )
                )

        db_issues = list(comp.get("db_connectivity_issues", []) or [])
        if db_issues:
            lines.append("")
            lines.append("DB CONNECTIVITY ISSUES")
            for idx, item in enumerate(db_issues, 1):
                lines.append(
                    "[{idx}] {issue} instance={obj} master={master} pin={pin} "
                    "expected_net={expected} actual_net={actual} "
                    "expected_domain={ed} actual_domain={ad} reason={detail}".format(
                        idx=idx,
                        issue=item.get("issue", "GLOBAL_NET_MISMATCH"),
                        obj=item.get("object", "-"),
                        master=item.get("master", "-"),
                        pin=item.get("pin", "-"),
                        expected=item.get("expected", "-"),
                        actual=item.get("actual", "-"),
                        ed=item.get("expected_domain", "-"),
                        ad=item.get("actual_domain", "-"),
                        detail=item.get("detail", ""),
                    )
                )

        for key, heading in (
            ("policy_issues", "POLICY ISSUES"),
            ("physical_issues", "PHYSICAL ISSUES"),
        ):
            items = list(comp.get(key, []) or [])
            if items:
                lines.append("")
                lines.append(heading)
                for idx, item in enumerate(items, 1):
                    if isinstance(item, dict):
                        parts = [f"{k}={v}" for k, v in item.items() if v not in (None, "", [], {})]
                        lines.append(f"[{idx}] " + " | ".join(parts))
                    else:
                        lines.append(f"[{idx}] {item}")

        save = comp.get("save_validation", {})
        errors = list(save.get("errors", []) or []) if isinstance(save, dict) else []
        if errors:
            lines.append("")
            lines.append("SAVE / GENERATED TCL ERRORS")
            for idx, item in enumerate(errors, 1):
                if isinstance(item, dict):
                    parts = [f"{k}={v}" for k, v in item.items() if v not in (None, "", [], {})]
                    lines.append(f"[{idx}] " + " | ".join(parts))
                else:
                    lines.append(f"[{idx}] {item}")

        failed_pads = [
            row for row in (comp.get("pads", {}) or {}).values()
            if isinstance(row, dict) and row.get("status") == "FAIL"
        ]
        if failed_pads:
            lines.append("")
            lines.append(_iopadt_expand_text("FAILED __IOPADT_LITERAL_001__ SUMMARY"))
            for idx, row in enumerate(failed_pads, 1):
                lines.append(
                    "[{idx}] instance={instance} master={master} role={role} side={side} reasons={reasons}".format(
                        idx=idx,
                        instance=row.get("instance", "-"),
                        master=row.get("master", "-"),
                        role=row.get("role", "-"),
                        side=row.get("side", "-"),
                        reasons=",".join(row.get("blocking_reasons", []) or row.get("reasons", []) or []),
                    )
                )
        return "\n".join(lines)

    def _validate_tk_root_chain(self):
        """
        Validate that Tkinter's widget-parent chain is not corrupted.

        The App root must keep its inherited `master` as None.
        Application data must never overwrite that attribute.
        """
        if getattr(self, "master", None) is not None:
            raise RuntimeError(
                "TK ROOT INVARIANT FAIL: App.master must be None."
            )

        candidates = [
            getattr(self, "nb", None),
            getattr(self, "canvas", None),
            getattr(self, "master_tree", None),
        ]

        for widget in candidates:
            if widget is None:
                continue

            seen = set()
            w = widget
            steps = 0

            while w is not None:
                oid = id(w)
                if oid in seen:
                    raise RuntimeError(
                        "TK ROOT INVARIANT FAIL: master cycle detected "
                        f"at {type(w).__name__}"
                    )
                seen.add(oid)

                if w is self:
                    break

                w = getattr(w, "master", None)
                steps += 1

                if steps > 64:
                    raise RuntimeError(
                        "TK ROOT INVARIANT FAIL: master chain too deep"
                    )

            if w is not self:
                raise RuntimeError(
                    "TK ROOT INVARIANT FAIL: widget does not resolve to App"
                )

        dbg("TK ROOT INVARIANT PASS: App.master=None and widget chains acyclic")

    def _gui_heartbeat(self):
        now = time.monotonic()
        state = get_gui_state()
        prev = state["last_heartbeat"]
        seq = state["heartbeat_seq"] + 1

        try:
            view = self.ring_view.get()
        except Exception:
            view = state["last_view"]

        set_gui_state(
            last_heartbeat=now,
            heartbeat_seq=seq,
            last_view=view,
        )

        # Do not spam the log every 250 ms.
        # Log once per ~5 seconds, and log any unexpectedly late heartbeat.
        delta = now - prev if prev else 0.0
        if seq == 1:
            dbg(
                f"GUI HEARTBEAT FIRST seq={seq} delta={delta:.3f}s "
                f"view={view} action={get_gui_state()['last_action']}"
            )
        elif seq % 20 == 0:
            dbg(
                f"GUI HEARTBEAT seq={seq} delta={delta:.3f}s "
                f"view={view} action={get_gui_state()['last_action']}"
            )
        elif delta > 0.75:
            dbg(
                f"GUI HEARTBEAT LATE seq={seq} delta={delta:.3f}s "
                f"view={view} action={get_gui_state()['last_action']}"
            )

        self.after(250, self._gui_heartbeat)

