    def _ring_panel_build(
        self,
        key,
        parent,
        detached=False,
    ):
        if key == "current_issues":
            return self._build_current_issues_panel(
                parent,
                detached=detached,
            )

        if key == "repair":
            return self._build_repair_panel(
                parent,
                detached=detached,
            )

        raise KeyError(key)

    def _ring_panel_forget_docked_frame(self, key):
        frame = self.ring_panel_frames.pop(key, None)

        if frame is None:
            return

        try:
            panes = tuple(
                str(p)
                for p in self.ring_side_paned.panes()
            )
            if str(frame) in panes:
                self.ring_side_paned.forget(frame)
        except Exception:
            pass

        try:
            frame.destroy()
        except Exception:
            pass

        self._ring_panel_clear_drag_commands(key)

    def _ring_panel_destroy_detached_window(self, key):
        win = self.ring_panel_windows.pop(key, None)

        if win is None:
            return

        try:
            if win.winfo_exists():
                win.destroy()
        except Exception:
            pass

    def _ring_panel_after_rebuild(self, key):
        if key == "current_issues":
            try:
                self._refresh_combined_issue_views()
            except Exception:
                logging.exception(
                    "Current Issues refresh after panel rebuild failed"
                )

        elif key == "repair":
            try:
                if self.ring_view.get() == "GLOBAL NET":
                    self._global_net_repair_refresh()
                else:
                    self._ring_update_repair_panel_mode_ui()
                    self._ring_update_master_choices()
                    self._ring_refresh_selection_label()
            except Exception:
                logging.exception(
                    "Repair panel refresh after rebuild failed"
                )

    def _ring_add_docked_panel(self, key):
        self._ring_show_side_dock()

        frame = self._ring_panel_build(
            key,
            self.ring_side_paned,
            detached=False,
        )
        self.ring_panel_frames[key] = frame

        # Preserve stable order: Current Issues above Repair.
        if key == "current_issues":
            try:
                self.ring_side_paned.insert(
                    0,
                    frame,
                    weight=1,
                )
            except Exception:
                self.ring_side_paned.add(
                    frame,
                    weight=1,
                )
        else:
            self.ring_side_paned.add(
                frame,
                weight=1,
            )

        self.ring_panel_state[key] = "docked"
        self._ring_panel_after_rebuild(key)

        def restore_vertical_split():
            try:
                if len(self.ring_side_paned.panes()) >= 2:
                    self.ring_side_paned.sashpos(
                        0,
                        max(180, int(self.ring_side_sash_position)),
                    )
            except Exception:
                pass

        self.after_idle(restore_vertical_split)

    def _safe_detached_tool_window(self, title):
        self._validate_tk_root_chain()
        win = tk.Toplevel(self)
        win.title(title)
        # Intentionally NOT transient: user requested an independent tool window.
        return win

    def _detach_ring_panel(
        self,
        key,
        root_x=None,
        root_y=None,
    ):
        if self.ring_panel_state.get(key) == "detached":
            win = self.ring_panel_windows.get(key)
            try:
                if win and win.winfo_exists():
                    win.lift()
                    win.focus_force()
            except Exception:
                pass
            return

        # Save side split before removing one pane.
        try:
            if len(self.ring_side_paned.panes()) >= 2:
                self.ring_side_sash_position = max(
                    180,
                    int(self.ring_side_paned.sashpos(0)),
                )
        except Exception:
            pass

        self._ring_panel_forget_docked_frame(key)
        self._ring_hide_side_dock_if_empty()

        win = self._safe_detached_tool_window(
            self._ring_panel_title(key)
        )
        self.ring_panel_windows[key] = win

        if key == "current_issues":
            default_size = "760x520"
        else:
            default_size = "480x620"

        if root_x is not None and root_y is not None:
            win.geometry(
                f"{default_size}+{max(0, int(root_x)-80)}"
                f"+{max(0, int(root_y)-30)}"
            )
        else:
            win.geometry(default_size)

        frame = self._ring_panel_build(
            key,
            win,
            detached=True,
        )
        frame.pack(fill="both", expand=True)

        self.ring_panel_state[key] = "detached"

        win.protocol(
            "WM_DELETE_WINDOW",
            lambda k=key: self._hide_ring_panel(k),
        )

        self._ring_panel_after_rebuild(key)
        self._refresh_window_menu()

    def _dock_ring_panel(self, key):
        if self.ring_panel_state.get(key) == "docked":
            return

        self._ring_panel_destroy_detached_window(key)

        # Old detached content is destroyed with its Toplevel.
        if key == "current_issues":
            self.ring_issues = None
        elif key == "repair":
            self.ring_master_combo = None
            self.ring_selection_label = None

        self._ring_add_docked_panel(key)
        self._refresh_window_menu()

    def _hide_ring_panel(self, key):
        state = self.ring_panel_state.get(key)

        if state == "docked":
            try:
                if len(self.ring_side_paned.panes()) >= 2:
                    self.ring_side_sash_position = max(
                        180,
                        int(self.ring_side_paned.sashpos(0)),
                    )
            except Exception:
                pass

            self._ring_panel_forget_docked_frame(key)

        elif state == "detached":
            self._ring_panel_destroy_detached_window(key)

        if key == "current_issues":
            self.ring_issues = None
        elif key == "repair":
            self.ring_master_combo = None
            self.ring_selection_label = None

        self.ring_panel_state[key] = "hidden"
        self._ring_hide_side_dock_if_empty()
        self._refresh_window_menu()

    def _show_hidden_ring_panel(self, key):
        if self.ring_panel_state.get(key) != "hidden":
            return

        self._ring_add_docked_panel(key)
        self._refresh_window_menu()

    def _refresh_window_menu(self):
        """
        Window lists every currently hidden restorable panel:
          - Ring child panels
          - Global Net page panels
        """
        menu = getattr(self, "window_menu", None)

        if menu is None:
            return

        menu.delete(0, "end")

        menu.add_command(
            label="Runtime / Debug Log",
            command=self._open_log_window,
        )
        menu.add_separator()

        entries = []

        for key in ("current_issues", "repair"):
            if self.ring_panel_state.get(key) == "hidden":
                entries.append((
                    self._ring_panel_title(key),
                    lambda k=key: self._show_hidden_ring_panel(k),
                ))

        gn_titles = {
            "problems": "Global Net - Problems",
            "commands": "Global Net - Commands",
            "audit": _iopadt_expand_text("Global Net - POWER __IOPADT_LITERAL_001__ Audit"),
        }

        for key in (
            "problems",
            "commands",
            "audit",
        ):
            if (
                getattr(self, "global_net_main_paned", None) is not None
                and not self._global_net_panel_is_visible(key)
            ):
                entries.append((
                    gn_titles[key],
                    lambda k=key: self._global_net_show_panel(k),
                ))

        if not entries:
            menu.add_command(
                label="No Hidden Panels",
                state="disabled",
            )
            return

        for label, command in entries:
            menu.add_command(
                label=label,
                command=command,
            )

    def _rebuild_repair_panel_for_view(self):
        state = self.ring_panel_state.get("repair")

        if state == "hidden":
            return

        if state == "docked":
            old_frame = self.ring_panel_frames.pop(
                "repair",
                None,
            )

            if old_frame is not None:
                try:
                    panes = tuple(
                        str(p)
                        for p in self.ring_side_paned.panes()
                    )

                    if str(old_frame) in panes:
                        self.ring_side_paned.forget(old_frame)
                except Exception:
                    pass

                try:
                    old_frame.destroy()
                except Exception:
                    pass

            self.ring_master_combo = None
            self.ring_selection_label = None
            self.global_net_all_cmd_tree = None
            self.global_net_repair_mapping_tree = None
            self.global_net_repair_pin_frame = None
            self.global_net_repair_scroll_canvas = None
            self.global_net_repair_scroll_content = None
            self.global_net_repair_scroll_window = None
            self._global_net_repair_clear_scroll_commands()
            self._ring_panel_clear_drag_commands("repair")

            new_frame = self._ring_panel_build(
                "repair",
                self.ring_side_paned,
                detached=False,
            )
            self.ring_panel_frames["repair"] = new_frame
            self.ring_side_paned.add(
                new_frame,
                weight=1,
            )
            self._ring_panel_after_rebuild("repair")
            return

        if state == "detached":
            win = self.ring_panel_windows.get("repair")

            if win is None:
                return

            try:
                if not win.winfo_exists():
                    return
            except Exception:
                return

            for child in list(win.winfo_children()):
                try:
                    child.destroy()
                except Exception:
                    pass

            win.title(self._ring_panel_title("repair"))

            self.ring_master_combo = None
            self.ring_selection_label = None
            self.global_net_all_cmd_tree = None
            self.global_net_repair_mapping_tree = None
            self.global_net_repair_pin_frame = None
            self.global_net_repair_scroll_canvas = None
            self.global_net_repair_scroll_content = None
            self.global_net_repair_scroll_window = None
            self._global_net_repair_clear_scroll_commands()

            new_frame = self._ring_panel_build(
                "repair",
                win,
                detached=True,
            )
            new_frame.pack(
                fill="both",
                expand=True,
            )
            self._ring_panel_after_rebuild("repair")

    def _menu_recheck_current_design(self):
        if self.entries and self.facts:
            self.run_check(
                False,
                rebuild_working_copy=False,
            )
            self.nb.select(self.tab_ring)
            return

        self._show_copyable_warning(
            "Check Current Design",
            "Load CHIP.io and Innovus TSV first.",
        )


    def _io_pad_live_validation(self):
        if (not self.repair_entries or not self.repair_facts or not self.repair_segments or not self.repair_rail_models):
            return {"ok": False, "blocking": 1, "reason": "working model is not ready", "rail":0,"duplicate":0,"create_hv":0,"missing":0,"unknown":0,"db_name":0,"offset_spacing":0,"offset_geometry_unknown":0,"anchor_order":0,"anchor_order_unknown":0}
        summary = self._edited_check_issue_summary(); db_patch = self._db_patch_diff()
        rail_n=len(summary["rail_violations"]); dup_n=len(summary["duplicate_groups"]); create_hv_n=len(summary["create_hv_rows"])
        missing_n=len(summary["missing_facts"]); unknown_n=len(summary["unknown_roles"]); db_name_n=len(db_patch["duplicate_final_names"])
        side_rows = self._pad_geometry_side_summary_rows()
        offset_spacing_n = sum(1 for s in side_rows if s.get("count",0)>1 and s.get("span_pass") is False)
        offset_geometry_unknown_n = sum(
            1 for s in side_rows
            if s.get("count",0)>1 and (s.get("span_pass") is None or not s.get("span_complete", False))
        )
        anchor_order_n = sum(1 for s in side_rows if s.get("anchor_order_ok") is False)
        anchor_order_unknown_n = sum(
            1 for s in side_rows if s.get("count",0)>1 and s.get("anchor_order_ok") is None
        )
        blocking = (rail_n + dup_n + missing_n + unknown_n + db_name_n
                    + offset_spacing_n + offset_geometry_unknown_n
                    + anchor_order_n + anchor_order_unknown_n)
        return {"ok": blocking==0, "blocking":blocking, "reason":"", "rail":rail_n,"duplicate":dup_n,"create_hv":create_hv_n,
                "missing":missing_n,"unknown":unknown_n,"db_name":db_name_n,"offset_spacing":offset_spacing_n,
                "offset_geometry_unknown":offset_geometry_unknown_n,"anchor_order":anchor_order_n,
                "anchor_order_unknown":anchor_order_unknown_n}
    def _refresh_live_io_validation(
        self,
        reason="working copy updated",
    ):
        live = self._io_pad_live_validation()
        ok = bool(live["ok"])

        self.edited_check_passed = ok
        self.edited_checked_fingerprint = (
            self._edited_state_fingerprint()
            if self.repair_entries
            else ""
        )

        # Compute the live geometry status here too. V125 restores blocking
        # FIRST/LAST anchor-order and 15-unit spacing checks while keeping the
        # obsolete 300-unit local SIDE_MARGIN_NO_PASS policy retired.
        try:
            geometry_unknown_wh_n = sum(
                1
                for r in self._pad_geometry_rows()
                if r["width"] is None or r["height"] is None
            )
            geometry_risk_sides_n = sum(
                1
                for s in self._pad_geometry_side_summary_rows()
                if s["violation_count"] > 0
                or not s.get("span_complete", False)
                or s.get("anchor_order_ok") is None
                or s.get("anchor_order_ok") is False
                or s.get("span_pass") is None
                or s.get("span_pass") is False
                or (
                    s["offset_margin"] is not None
                    and s["offset_margin"] < 0
                )
            )
            geometry_status_text = (
                "geometry=CHECKED "
                f"unknown_wh={geometry_unknown_wh_n} "
                f"risk_sides={geometry_risk_sides_n}"
            )
            geometry_checked = True
        except Exception:
            logging.exception(
                "Geometry status computation failed"
            )
            geometry_status_text = "geometry=CHECK_FAILED"
            geometry_checked = False

        self.edited_check_result = {
            "status": "PASS" if ok else "FAIL",
            "fingerprint": self.edited_checked_fingerprint,
            "blocking_issue_count": int(
                live["blocking"]
            ),
            "rail_violation_count": int(
                live["rail"]
            ),
            "duplicate_name_group_count": int(
                live["duplicate"]
            ),
            "create_hv_mismatch_count": int(
                live["create_hv"]
            ),
            "missing_fact_count": int(
                live["missing"]
            ),
            "unknown_role_count": int(
                live["unknown"]
            ),
            "db_patch_name_conflict_count": int(
                live["db_name"]
            ),
            "offset_spacing_error_count": int(live.get("offset_spacing", 0)),
            "offset_geometry_unknown_count": int(live.get("offset_geometry_unknown", 0)),
            "offset_anchor_order_error_count": int(live.get("anchor_order", 0)),
            "offset_anchor_order_unknown_count": int(live.get("anchor_order_unknown", 0)),
            "geometry_checked": geometry_checked,
        }

        if ok:
            self.edited_check_status.set(
                "IO STATUS: PASS | "
                f"cells={len(self.repair_entries)} "
                f"domains={len(self.repair_segments)} "
                f"| {geometry_status_text}"
            )
            self.ring_repair_message.set(
                "IO working copy PASS. "
                "IO_FILE Save and Global Net editing are available."
            )
        else:
            self.edited_check_status.set(
                "IO STATUS: FAIL | "
                f"rail={live['rail']} "
                f"duplicate={live['duplicate']} "
                f"create_hv={live['create_hv']} "
                f"missing={live['missing']} "
                f"unknown={live['unknown']} "
                f"db_name={live['db_name']} "
                f"offset_spacing={live.get('offset_spacing',0)} "
                f"geometry_unknown={live.get('offset_geometry_unknown',0)} "
                f"anchor_order={live.get('anchor_order',0)} "
                f"anchor_unknown={live.get('anchor_order_unknown',0)} "
                f"| {geometry_status_text}"
            )
            self.ring_repair_message.set(
                "IO working copy has blocking issue(s). "
                "See IO FILE Issues."
            )

        if hasattr(self, "save_edited_button"):
            self.save_edited_button.configure(
                state="normal" if ok else "disabled"
            )

        self._global_net_update_save_state()

        dbg(
            "LIVE IO VALIDATION "
            f"ok={ok} blocking={live['blocking']} "
            f"reason={reason}"
        )

        return ok

    def _io_pad_check_current_passed(self):
        """
        Compatibility name retained for Global Net edit gates.

        V76 no longer depends on a manually pressed Check Edited Result.
        """
        return bool(
            self._io_pad_live_validation()["ok"]
        )

    def _require_io_pad_pass_for_global_net_edit(
        self,
        parent=None,
        interactive=True,
    ):
        if self._io_pad_check_current_passed():
            return True

        live = self._io_pad_live_validation()
        msg = (
            "Global Net editing is locked because the current IO working "
            "copy has blocking issue(s). No manual Check Edited Result is "
            "required; repair the IO issue and the editor unlocks automatically. "
            f"blocking={live['blocking']}"
        )
        self.global_net_status.set(
            "GLOBAL NET EDIT LOCKED: current IO working copy has blocking issue(s)."
        )
        self.global_net_repair_status.set(
            "GLOBAL NET EDIT LOCKED: current IO working copy has blocking issue(s)."
        )

        if interactive:
            self._show_copyable_warning(
                "Global Net Edit Locked",
                msg,
                parent=parent,
            )
        return False

    def _global_net_update_save_state(self):
        io_ok = self._io_pad_check_current_passed()
        commit_enabled = bool(self.global_net_path and io_ok)
        export_enabled = (
            self.global_net_check_state == "PASS"
            and self.global_net_last_check_result is not None
            and io_ok
        )

        for attr, enabled in (
            ("global_net_save_button", commit_enabled),
            ("global_net_export_button", export_enabled),
        ):
            button = getattr(self, attr, None)
            if button is None:
                continue
            try:
                button.configure(
                    state="normal" if enabled else "disabled"
                )
            except Exception:
                pass

    def _register_global_net_check_button(
        self,
        button,
    ):
        if button is None:
            return button

        try:
            button._gn_check_base_text = str(
                button.cget("text")
            )
        except Exception:
            button._gn_check_base_text = "Check"

        self.global_net_check_buttons.append(
            button
        )
        self._global_net_refresh_check_indicator()
        return button

    def _register_global_net_check_label(
        self,
        label,
    ):
        if label is None:
            return label

        self.global_net_check_labels.append(
            label
        )
        self._global_net_refresh_check_indicator()
        return label

    def _global_net_refresh_check_indicator(self):
        """
        V78:
          STALE = unverified Global Net command changes.
          - Red status text.
          - Check button becomes Check* / Check Global Net*.
        """
        stale = (
            self.global_net_check_state == "STALE"
        )

        alive_buttons = []

        for button in self.global_net_check_buttons:
            try:
                if not button.winfo_exists():
                    continue

                base = str(
                    getattr(
                        button,
                        "_gn_check_base_text",
                        "Check",
                    )
                )
                button.configure(
                    text=(
                        base + "*"
                        if stale
                        else base
                    )
                )
                alive_buttons.append(button)
            except Exception:
                pass

        self.global_net_check_buttons = (
            alive_buttons
        )

        alive_labels = []

        for label in self.global_net_check_labels:
            try:
                if not label.winfo_exists():
                    continue

                label.configure(
                    foreground=(
                        "#c00000"
                        if stale
                        else ""
                    )
                )
                alive_labels.append(label)
            except Exception:
                pass

        self.global_net_check_labels = (
            alive_labels
        )

    def _set_global_net_apply_state(self, state, apply_result=None, check_result=None):
        allowed = {
            "GLOBAL_NET_CLEAN", "GLOBAL_NET_DIRTY", "GLOBAL_NET_APPLYING",
            "GLOBAL_NET_CHECKING", "GLOBAL_NET_PASS", "GLOBAL_NET_FAIL",
        }
        state = str(state or "GLOBAL_NET_CLEAN").upper()
        if state not in allowed:
            state = "GLOBAL_NET_FAIL"
        self.global_net_apply_state = state
        if apply_result is not None:
            self.global_net_apply_result = str(apply_result)
        if check_result is not None:
            self.global_net_postcheck_result = str(check_result)
        short = state.replace("GLOBAL_NET_", "")
        self.global_net_apply_text.set(
            f"GLOBAL NET: {short} | APPLY RESULT: {self.global_net_apply_result} "
            f"| CHECK RESULT: {self.global_net_postcheck_result}"
        )
        self._refresh_pending_apply_state_display()

    def _refresh_pending_apply_state_display(self):
        io_required = bool(getattr(self, "repair_plan", None))
        gn_required = self.global_net_apply_state in (
            "GLOBAL_NET_DIRTY", "GLOBAL_NET_APPLYING", "GLOBAL_NET_CHECKING",
        )
        self.pending_apply_text.set(
            "IO Layout: " + ("APPLY REQUIRED" if io_required else "CLEAN")
            + " | Global Net: "
            + ("APPLY REQUIRED" if gn_required else "CLEAN")
        )

    def _global_net_set_check_state(
        self,
        state,
        detail="",
        clear_result=False,
    ):
        state = str(state or "NOT_CHECKED").upper()

        if state not in ("NOT_CHECKED", "STALE", "PASS", "FAIL"):
            state = "NOT_CHECKED"

        self.global_net_check_state = state

        if clear_result:
            self.global_net_last_check_result = None

        suffix = (
            " | " + str(detail)
            if str(detail or "").strip()
            else ""
        )
        self.global_net_check_text.set(
            f"GLOBAL NET CHECK: {state}{suffix}"
        )
        self._global_net_refresh_check_indicator()
        self._global_net_update_save_state()

    def _global_net_mark_check_stale(self, reason="working copy edited"):
        if not (self.global_net_path or self.global_net_lines):
            self._global_net_set_check_state(
                "NOT_CHECKED",
                clear_result=True,
            )
            return

        # Preserve last checked result so the Problems views do not
        # become empty merely because a command was added/edited.
        self._global_net_set_check_state(
            "STALE",
            "UNCHECKED CHANGES | " + str(reason),
            clear_result=False,
        )
        self._set_global_net_apply_state(
            "GLOBAL_NET_DIRTY",
            apply_result="PENDING",
            check_result="STALE",
        )
        self.global_net_repair_effective.set(
            "GLOBAL NET CHECK: STALE — press Check Global Net."
        )
        self._refresh_combined_issue_views()
        self._global_net_sync_generated_preview_if_open()

    def _global_net_sync_generated_preview_if_open(self):
        """Keep Generated Tcl preview synchronized unless it has manual edits."""
        try:
            win = self.global_net_generated_tcl_window
            editor = self.global_net_generated_tcl_text
            if win is None or editor is None or not win.winfo_exists():
                return
            if bool(editor.edit_modified()):
                self.global_net_generated_tcl_status.set(
                    "Generated Tcl Preview: STALE because manual editor text is pending; press Apply/OK or Reload Current Preview."
                )
                return
            art = self._global_net_canonical_artifacts()
            current = editor.get("1.0", "end-1c")
            if current != art["source_tcl"]:
                editor.delete("1.0", "end")
                editor.insert("1.0", art["source_tcl"])
            editor.edit_modified(False)
            self.global_net_generated_tcl_status.set(
                "Generated Tcl Preview: SYNCED canonical sha256=" + art["source_sha256"]
            )
        except Exception as exc:
            dbg(f"GLOBAL_NET_GENERATED_PREVIEW_SYNC_FAIL error={exc}")

    def _global_net_checked_result(self):
        if (
            self.global_net_check_state in ("PASS", "FAIL")
            and self.global_net_last_check_result is not None
        ):
            return self.global_net_last_check_result

        return None

    def _global_net_display_result(self):
        """
        Cached result for UI painting only.

        If the check is stale/not checked, return a lightweight placeholder.
        This function must NEVER invoke _global_net_compare_design().
        """
        comp = self._global_net_checked_result()

        if comp is not None:
            return comp

        return {
            "loaded": bool(
                self.global_net_path or self.global_net_lines
            ),
            "source": (
                str(self.global_net_path)
                if self.global_net_path
                else "<in-memory>"
            ),
            "model": (
                "CHECK "
                + self.global_net_check_state
                + " — PRESS CHECK GLOBAL NET"
            ),
            "pads": {},
            "checked_count": 0,
            "pass_count": 0,
            "fail_count": 0,
            "warning_count": 0,
            "info_count": 0,
            "active_rule_count": len(
                self._global_net_all_pg_rules()
            ),
            "io_power_domain": (
                self._global_net_io_power_domain_info()
            ),
            "fallback_needed": False,
            "policy_issues": [],
            "policy_issue_count": 0,
            "railcut_supply_checks": [],
            "railcut_supply_checked_count": 0,
            "railcut_supply_issue_count": 0,
            "physical_issues": [],
            "physical_issue_count": 0,
            "db_connectivity_issues": [],
            "db_connectivity_issue_count": 0,
            "db_connectivity_queried": False,
        }

    def _menu_check_global_net(self, force_db_actual=False, post_apply=False, interactive=True):
        """
        Explicit Global Net + physical power + live DB connectivity comparison.

        Edits do not call this method. Post-apply calls it only after a fresh
        QUERY_GLOBAL_NET response has replaced DB evidence.
        """
        if not self.entries or not self.facts:
            if interactive:
                self._show_copyable_warning(
                    "Check Global Net",
                    "Load CHIP.io and Innovus TSV first.",
                )
            return False

        if not (self.global_net_path or self.global_net_lines):
            if interactive:
                self._show_copyable_warning(
                    "Check Global Net",
                    "Load global_net.tcl first.",
                )
            return False

        self.global_net_check_text.set(
            "GLOBAL NET CHECK: CHECKING..."
        )
        self.update_idletasks()

        try:
            # Exactly one authoritative comparison for this manual check.
            comp = self._global_net_compare_design(force_db_actual=force_db_actual)

            # V77: Check Global Net also validates the exact Tcl that Save
            # would write, including target overlap and create-net companion.
            checked_text = self._render_global_net_text()
            save_validation = (
                self._global_net_check_save_readiness(
                    checked_text
                )
            )
            comp["save_validation"] = save_validation
            comp["save_error_count"] = int(
                save_validation["error_count"]
            )
            comp["save_warning_count"] = int(
                save_validation["warning_count"]
            )
            comp["checked_text_signature"] = (
                save_validation["text_signature"]
            )

            self.global_net_last_check_result = comp

            failed = (
                int(comp.get("fail_count", 0)) > 0
                or int(comp.get("policy_issue_count", 0)) > 0
                or int(comp.get("physical_issue_count", 0)) > 0
                or int(comp.get("db_connectivity_issue_count", 0)) > 0
                or int(comp.get("save_error_count", 0)) > 0
            )
            state = "FAIL" if failed else "PASS"

            self._global_net_set_check_state(
                state,
                (
                    f"checked={comp['checked_count']} "
                    f"pass={comp['pass_count']} "
                    f"fail={comp['fail_count']} "
                    f"warning={comp.get('warning_count', 0)} "
                    f"info={comp.get('info_count', 0)} "
                    f"policy={comp.get('policy_issue_count', 0)} "
                    f"railcutSupplyFail={comp.get('railcut_supply_issue_count', 0)} "
                    f"railcutSupplyChk={comp.get('railcut_supply_checked_count', 0)} "
                    f"physical={comp.get('physical_issue_count', 0)} "
                    f"dbConn={comp.get('db_connectivity_issue_count', 0)} "
                    f"saveErr={comp.get('save_error_count', 0)} "
                    f"saveWarn={comp.get('save_warning_count', 0)}"
                ),
                clear_result=False,
            )

            # Consumers below use global_net_last_check_result only.
            self._refresh_combined_issue_views()
            self._global_net_repair_refresh()

            if (
                hasattr(self, "ring_view")
                and self.ring_view.get() == "GLOBAL NET"
            ):
                self.draw_ring()

            msg = self.global_net_check_text.get()
            self.status.set(msg)
            self.global_net_status.set(msg)
            self.global_net_repair_status.set(msg)
            return state == "PASS"

        except Exception as exc:
            self.global_net_last_check_result = None
            self._global_net_set_check_state(
                "FAIL",
                "CHECK ERROR: " + str(exc),
                clear_result=True,
            )
            self.global_net_status.set(
                self.global_net_check_text.get()
            )
            self.global_net_repair_status.set(
                self.global_net_check_text.get()
            )
            if interactive:
                self._show_copyable_error(
                    "Check Global Net",
                    str(exc),
                )
            return False


    def _menu_run_base_io_check(self):
        if not self.entries or not self.facts:
            self._show_copyable_warning(
                _iopadt_expand_text("Base IO __IOPADT_LITERAL_001__ Check"),
                "Load CHIP.io and Innovus TSV first.",
            )
            return

        if self.repair_plan:
            ok = self._ask_copyable_yesno(
                "Rebuild Working Copy",
                "This rebuilds the working copy from the loaded base design "
                "and discards current in-memory repair edits.\n\nContinue?",
            )
            if not ok:
                return

        self.run_check(
            False,
            rebuild_working_copy=True,
        )
        self.nb.select(self.tab_ring)

    def _menu_open_iopad_guide(self):
        guide = APP_DIR / "IOPAD說明.md"

        if not guide.exists():
            self._show_copyable_error(
                "IOPAD Guide",
                f"Guide not found:\n{guide}",
            )
            return

        try:
            if os.name == "nt" and hasattr(os, "startfile"):
                os.startfile(str(guide))
            else:
                import webbrowser
                webbrowser.open(guide.as_uri())
        except Exception as exc:
            self._show_copyable_error(
                "IOPAD Guide",
                f"Cannot open IOPAD說明.md:\n{exc}",
            )

    def _menu_about(self):
        self._show_copyable_info(
            "About ioPADt Tool",
            APP_TITLE
            + "\n\nDockable Current Issues + Repair Panel"
            + "\nIO_FILE + Innovus TSV + Global Net Tcl"
            + "\nPhysical CORE/IO power comparison"
            + "\n\nAUTO_READ_IO_FILE = NO",
        )

    def _build_menubar(self):
        menubar = tk.Menu(self, tearoff=False)
        self.config(menu=menubar)
        self.app_menubar = menubar

        file_menu = tk.Menu(menubar, tearoff=False)
        menubar.add_cascade(label="File", menu=file_menu)

        file_menu.add_command(
            label="Load CHIP.io...",
            command=self.load_io,
        )
        file_menu.add_command(
            label="Generate Innovus Query Tcl...",
            command=self.save_tcl,
        )
        file_menu.add_command(
            label="Load Innovus TSV...",
            command=self.load_tsv,
        )
        file_menu.add_command(
            label="Load Global Net Tcl...",
            command=self.load_global_net_tcl,
        )

        file_menu.add_separator()
        file_menu.add_command(
            label="Save Tool State",
            command=self.save_tool_session,
        )
        file_menu.add_command(
            label="Load Last Tool State",
            command=self.load_last_tool_session,
        )
        file_menu.add_command(
            label="Load Tool State...",
            command=self.load_tool_session,
        )

        file_menu.add_separator()

        export_menu = tk.Menu(
            file_menu,
            tearoff=False,
        )

        file_menu.add_cascade(
            label="Export Outputs",
            menu=export_menu,
        )

        export_menu.add_command(
            label="Export All Available Outputs...",
            command=self._export_all_outputs,
        )

        export_menu.add_separator()

        export_menu.add_command(
            label="Export IO_FILE Bundle...",
            command=lambda: self._safe_ring_command(
                "menu_export_io_bundle",
                self._export_edited_io_file,
            ),
        )

        export_menu.add_command(
            label="Export Global Net Bundle...",
            command=self.export_global_net_tcl,
        )

        export_menu.add_command(
            label="Export Innovus Query Tcl...",
            command=self.save_tcl,
        )

        file_menu.add_separator()
        file_menu.add_command(
            label="Exit",
            command=self.destroy,
        )

        # Window only restores child interfaces that were closed.
