    def _notebook_tab_drag_press(self, x, y):
        try:
            idx = int(
                self.nb.index(
                    f"@{int(float(x))},{int(float(y))}"
                )
            )
            tabs = list(self.nb.tabs())
            self.notebook_drag_tab = (
                tabs[idx]
                if 0 <= idx < len(tabs)
                else ""
            )
        except Exception:
            self.notebook_drag_tab = ""
        return ""

    def _notebook_tab_drag_motion(self, x, y):
        tab = str(self.notebook_drag_tab or "")

        if not tab:
            return ""

        try:
            target = int(
                self.nb.index(
                    f"@{int(float(x))},{int(float(y))}"
                )
            )
            tabs = list(self.nb.tabs())

            if tab not in tabs:
                self.notebook_drag_tab = ""
                return ""

            current = tabs.index(tab)

            if target != current:
                self.nb.insert(target, tab)
                self.nb.select(tab)

        except Exception:
            pass

        return ""

    def _notebook_tab_drag_release(self):
        self.notebook_drag_tab = ""
        return ""

    def _install_notebook_tab_drag_reorder(self):
        """
        Drag Notebook tab headers to reorder them.

        Tcl-level bindings are used to preserve the no-Python-Event invariant.
        """
        try:
            cmd_press = self.register(
                self._notebook_tab_drag_press
            )
            cmd_motion = self.register(
                self._notebook_tab_drag_motion
            )
            cmd_release = self.register(
                self._notebook_tab_drag_release
            )

            self.notebook_tab_drag_tcl_commands.extend([
                cmd_press,
                cmd_motion,
                cmd_release,
            ])

            self.tk.call(
                "bind",
                self.nb._w,
                "<ButtonPress-1>",
                f"{cmd_press} %x %y",
            )
            self.tk.call(
                "bind",
                self.nb._w,
                "<B1-Motion>",
                f"{cmd_motion} %x %y",
            )
            self.tk.call(
                "bind",
                self.nb._w,
                "<ButtonRelease-1>",
                f"{cmd_release}",
            )
        except Exception:
            logging.exception(
                "Notebook tab drag binding failed"
            )

    # =================================================================
    # V86 Linux Local Innovus Interface
    # =================================================================

    def _innovus_local_bridge_dir(self):
        raw = self.innovus_bridge_dir.get().strip()
        if not raw:
            raise ValueError(
                "Innovus Local Bridge Dir cannot be empty."
            )

        return Path(
            os.path.expandvars(
                os.path.expanduser(raw)
            )
        ).resolve()

    def _innovus_local_request(
        self,
        operation,
        payload="",
        timeout=30.0,
    ):
        """
        Same-host filesystem mailbox protocol.

        GUI atomically creates request_<id>.req.
        Innovus writes response_<id>.rsp.
        No TCP / host / port / token exists.
        """
        bridge_dir = self._innovus_local_bridge_dir()
        ready = bridge_dir / "bridge.ready"

        if not ready.exists():
            raise RuntimeError(
                "Innovus local bridge is not ready. "
                "Source TT_flow_iopad_interface_start.tcl in the "
                "current Innovus session first.\n"
                f"Expected: {ready}"
            )

        request_id = (
            f"{os.getpid()}_"
            f"{time.time_ns()}_"
            f"{threading.get_ident()}"
        )

        req_tmp = bridge_dir / f"request_{request_id}.req.tmp"
        req = bridge_dir / f"request_{request_id}.req"
        rsp = bridge_dir / f"response_{request_id}.rsp"

        encoded = base64.b64encode(
            str(payload).encode("utf-8")
        ).decode("ascii")

        req_tmp.write_text(
            "TTIOPAD_LOCAL1\t"
            + request_id
            + "\t"
            + str(operation)
            + "\t"
            + encoded
            + "\n",
            encoding="ascii",
        )
        req_tmp.replace(req)

        dbg(
            "INNOVUS LOCAL request "
            f"id={request_id} op={operation} dir={bridge_dir}"
        )
        self._runtime_log_event(
            "BRIDGE REQUEST",
            (
                f"id={request_id}\n"
                f"op={operation}\n"
                f"bridge_dir={bridge_dir}\n"
                f"payload_bytes={len(str(payload).encode('utf-8'))}"
            ),
        )

        deadline = time.monotonic() + float(timeout)

        try:
            while True:
                if rsp.exists():
                    raw = rsp.read_text(
                        encoding="ascii",
                        errors="strict",
                    ).splitlines()

                    if not raw:
                        raise RuntimeError(
                            "Innovus local bridge returned an empty response."
                        )

                    fields = raw[0].split("\t", 3)

                    if (
                        len(fields) != 4
                        or fields[0] != "TTIOPAD_LOCAL1"
                        or fields[1] != request_id
                    ):
                        raise RuntimeError(
                            "Invalid Innovus local bridge response."
                        )

                    response = base64.b64decode(
                        fields[3].encode("ascii"),
                        validate=False,
                    ).decode(
                        "utf-8",
                        errors="replace",
                    )

                    if fields[2] != "OK":
                        raise RuntimeError(
                            response
                            or "Innovus local bridge returned ERROR."
                        )

                    dbg(
                        "INNOVUS LOCAL response "
                        f"id={request_id} op={operation} "
                        f"bytes={len(response.encode('utf-8'))}"
                    )
                    self._runtime_log_event(
                        "BRIDGE RESPONSE",
                        (
                            f"id={request_id}\n"
                            f"op={operation}\n"
                            f"status=OK\n"
                            f"response_bytes={len(response.encode('utf-8'))}\n"
                            f"{response}"
                        ),
                    )
                    return response

                if time.monotonic() >= deadline:
                    raise TimeoutError(
                        "Timed out waiting for Innovus local bridge response "
                        f"for {operation}."
                    )

                time.sleep(0.05)

        finally:
            for path in (req_tmp, req, rsp):
                try:
                    if path.exists():
                        path.unlink()
                except Exception:
                    pass

    def _short_one_line(
        self,
        message,
        limit=140,
    ):
        one = " ".join(
            str(message or "").split()
        )

        if len(one) <= int(limit):
            return one

        return (
            one[:max(1, int(limit) - 1)]
            + "…"
        )

    def _set_innovus_status(
        self,
        message,
    ):
        """
        Main-window Innovus status is intentionally short and single-line.

        Full request/response/error detail belongs in the Log Window.
        """
        self.innovus_status.set(
            self._short_one_line(
                message,
                150,
            )
        )

    def _runtime_log_event(
        self,
        category,
        message,
    ):
        """
        Append one event to the persistent runtime log and, when open,
        the dedicated Log Window.

        Safe to call from the bridge worker thread.
        """
        now = time.time()
        stamp = time.strftime(
            "%Y-%m-%d %H:%M:%S",
            time.localtime(now),
        )
        ms = int(
            (now - int(now)) * 1000
        )

        block = (
            f"{stamp}.{ms:03d} "
            f"[{str(category)}]\n"
            f"{str(message or '')}\n"
            + ("-" * 96)
            + "\n"
        )

        try:
            with self._runtime_log_lock:
                self._runtime_log_buffer.append(
                    block
                )

                if (
                    len(self._runtime_log_buffer)
                    > self._runtime_log_limit
                ):
                    self._runtime_log_buffer = (
                        self._runtime_log_buffer[
                            -self._runtime_log_limit:
                        ]
                    )

                with open(
                    self.runtime_log_path,
                    "a",
                    encoding="utf-8",
                ) as fp:
                    fp.write(block)
        except Exception:
            logging.exception(
                "Runtime log append failed"
            )

        def update_widget():
            widget = getattr(
                self,
                "log_runtime_text",
                None,
            )

            if (
                widget is None
                or not widget.winfo_exists()
            ):
                return

            try:
                widget.configure(
                    state="normal"
                )
                widget.insert(
                    "end",
                    block,
                )
                widget.see(
                    "end"
                )
                widget.configure(
                    state="disabled"
                )
            except Exception:
                pass

        try:
            if (
                threading.get_ident()
                == self._tk_thread_ident
            ):
                update_widget()
            else:
                self.after(
                    0,
                    update_widget,
                )
        except Exception:
            pass

    def _tail_text_file(
        self,
        path,
        max_bytes=1024 * 1024,
    ):
        path = Path(path)

        if not path.exists():
            return (
                "<file does not exist>\n"
                + str(path)
                + "\n"
            )

        try:
            raw = path.read_bytes()

            if len(raw) > int(max_bytes):
                raw = raw[-int(max_bytes):]
                prefix = (
                    "<showing tail only>\n"
                )
            else:
                prefix = ""

            return (
                prefix
                + raw.decode(
                    "utf-8",
                    errors="replace",
                )
            )
        except Exception as exc:
            return (
                "<failed to read log>\n"
                + str(path)
                + "\n"
                + str(exc)
                + "\n"
            )

    def _log_window_set_text(
        self,
        widget,
        content,
    ):
        if (
            widget is None
            or not widget.winfo_exists()
        ):
            return

        widget.configure(
            state="normal"
        )
        widget.delete(
            "1.0",
            "end",
        )
        widget.insert(
            "1.0",
            content,
        )
        widget.see(
            "end"
        )
        widget.configure(
            state="disabled"
        )

    def _log_window_refresh_files(
        self,
    ):
        self._log_window_set_text(
            self.log_runtime_text,
            self._tail_text_file(
                self.runtime_log_path,
            ),
        )

        self._log_window_set_text(
            self.log_debug_text,
            self._tail_text_file(
                DEBUG_LOG,
            ),
        )

    def _log_window_copy_widget(
        self,
        widget,
        label,
        selected_only=False,
    ):
        # V128.27: Runtime/Debug used the raw Tk clipboard path while the
        # viewers are disabled Text widgets.  On Linux/X11 this made both
        # Ctrl+C and Copy Runtime unreliable.  Reuse the hardened clipboard
        # helper already used by the rest of ioPADt.
        if (
            widget is None
            or not widget.winfo_exists()
        ):
            return "break"

        try:
            if selected_only:
                try:
                    content = widget.get("sel.first", "sel.last")
                except tk.TclError:
                    content = widget.get("1.0", "end-1c")
            else:
                content = widget.get("1.0", "end-1c")

            if self._clipboard_set_text(content):
                self.status.set(f"Copied {label} to clipboard.")
        except Exception as exc:
            self._show_copyable_error("Copy Log", str(exc))

        return "break"

    def _log_window_copy_runtime(
        self,
    ):
        return self._log_window_copy_widget(
            getattr(self, "log_runtime_text", None),
            "Runtime / Innovus log",
            selected_only=False,
        )

    def _log_window_copy_debug(
        self,
    ):
        return self._log_window_copy_widget(
            getattr(self, "log_debug_text", None),
            "Python Debug log",
            selected_only=False,
        )

    def _close_log_window(
        self,
    ):
        win = getattr(
            self,
            "log_window",
            None,
        )

        try:
            if (
                win is not None
                and win.winfo_exists()
            ):
                win.destroy()
        except Exception:
            pass

        self.log_window = None
        self.log_runtime_text = None
        self.log_debug_text = None

    def _open_log_window(
        self,
    ):
        """
        Dedicated resizable log/debug Toplevel.

        This intentionally keeps traceback-sized text out of every main
        application panel, preventing geometry deformation.
        """
        win = getattr(
            self,
            "log_window",
            None,
        )

        if (
            win is not None
            and win.winfo_exists()
        ):
            win.deiconify()
            win.lift()
            win.focus_force()
            self._log_window_refresh_files()
            return win

        win = tk.Toplevel(
            self
        )
        self.log_window = win

        win.title(
            "ioPADt - Runtime / Debug Log"
        )
        win.geometry(
            "1120x680"
        )
        win.minsize(
            760,
            420,
        )
        win.protocol(
            "WM_DELETE_WINDOW",
            self._close_log_window,
        )

        head = ttk.Frame(
            win,
            padding=8,
        )
        head.pack(
            fill="x"
        )

        ttk.Label(
            head,
            text=(
                "Runtime: "
                + str(self.runtime_log_path)
            ),
        ).pack(
            side="left",
            fill="x",
            expand=True,
        )

        ttk.Button(
            head,
            text="Refresh",
            command=self._log_window_refresh_files,
        ).pack(
            side="right",
            padx=(6, 0),
        )

        ttk.Button(
            head,
            text="Copy Debug",
            command=self._log_window_copy_debug,
        ).pack(
            side="right",
            padx=(6, 0),
        )

        ttk.Button(
            head,
            text="Copy Runtime",
            command=self._log_window_copy_runtime,
        ).pack(
            side="right",
        )

        nb = ttk.Notebook(
            win
        )
        nb.pack(
            fill="both",
            expand=True,
            padx=8,
            pady=(0, 8),
        )

        runtime_frame = ttk.Frame(
            nb
        )
        debug_frame = ttk.Frame(
            nb
        )

        nb.add(
            runtime_frame,
            text="Runtime / Innovus",
        )
        nb.add(
            debug_frame,
            text="Python Debug",
        )

        def make_text(parent):
            parent.rowconfigure(
                0,
                weight=1,
            )
            parent.columnconfigure(
                0,
                weight=1,
            )

            widget = tk.Text(
                parent,
                wrap="none",
                font=(
                    "TkFixedFont",
                    9,
                ),
                state="disabled",
            )
            sx = ttk.Scrollbar(
                parent,
                orient="horizontal",
                command=widget.xview,
            )
            sy = ttk.Scrollbar(
                parent,
                orient="vertical",
                command=widget.yview,
            )
            widget.configure(
                xscrollcommand=sx.set,
                yscrollcommand=sy.set,
            )

            widget.grid(
                row=0,
                column=0,
                sticky="nsew",
            )

            # V128.27: disabled Text class bindings are not reliable on the
            # target X11/Tk setup.  Explicitly give the viewer focus and copy
            # the selected text through ioPADt's hardened clipboard helper.
            widget.bind(
                "<Button-1>",
                lambda _event, w=widget: w.focus_set(),
                add="+",
            )
            widget.bind(
                "<Control-c>",
                lambda _event, w=widget: self._log_window_copy_widget(
                    w,
                    "selected log text",
                    selected_only=True,
                ),
            )
            widget.bind(
                "<Control-C>",
                lambda _event, w=widget: self._log_window_copy_widget(
                    w,
                    "selected log text",
                    selected_only=True,
                ),
            )

            sy.grid(
                row=0,
                column=1,
                sticky="ns",
            )
            sx.grid(
                row=1,
                column=0,
                sticky="ew",
            )

            return widget

        self.log_runtime_text = make_text(
            runtime_frame
        )
        self.log_debug_text = make_text(
            debug_frame
        )

        self._log_window_refresh_files()

        return win

    def _innovus_set_busy(
        self,
        busy,
        message="",
    ):
        self.innovus_busy = bool(busy)

        if message:
            self._set_innovus_status(message)

        for button in getattr(
            self,
            "innovus_action_buttons",
            [],
        ):
            try:
                button.configure(
                    state="disabled" if busy else "normal"
                )
            except Exception:
                pass

    def _innovus_run_async(
        self,
        operation_name,
        worker,
        success_callback=None,
    ):
        if self.innovus_busy:
            self._set_innovus_status(
                "INNOVUS LOCAL: BUSY"
            )
            return False

        self._innovus_set_busy(
            True,
            "INNOVUS LOCAL: RUNNING " + operation_name,
        )
        self._runtime_log_event(
            "OPERATION START",
            operation_name,
        )

        def run():
            try:
                result = worker()
            except Exception as exc:
                err = str(exc)
                logging.exception(
                    "Innovus local operation failed: "
                    + operation_name
                )
                self.after(
                    0,
                    lambda: self._innovus_async_error(
                        operation_name,
                        err,
                    ),
                )
                return

            self.after(
                0,
                lambda: self._innovus_async_success(
                    operation_name,
                    result,
                    success_callback,
                ),
            )

        threading.Thread(
            target=run,
            name=(
                "IOPAD_Innovus_Local_"
                + re.sub(
                    r"[^A-Za-z0-9]+",
                    "_",
                    operation_name,
                )
            ),
            daemon=True,
        ).start()

        return True

    def _innovus_async_error(
        self,
        operation_name,
        error_text,
    ):
        full_error = str(
            error_text or ""
        )

        self._runtime_log_event(
            "OPERATION ERROR",
            (
                str(operation_name)
                + "\n"
                + full_error
            ),
        )

        if str(operation_name) == "APPLY GLOBAL NET + VERIFY":
            apply_was_pass = self.global_net_apply_result == "PASS"
            self._set_global_net_apply_state(
                "GLOBAL_NET_FAIL",
                apply_result=(
                    "PASS" if apply_was_pass else "FAIL"
                ),
                check_result=("FAIL" if apply_was_pass else "NOT_RUN"),
            )

        self._innovus_set_busy(
            False,
            (
                "INNOVUS LOCAL: ERROR | "
                + str(operation_name)
                + " | see Log Window"
            ),
        )

        # Long Tcl tracebacks stay in the dedicated window, not the main GUI.
        self._open_log_window()

        self._show_copyable_error(
            "Innovus Local Interface Error",
            (
                str(operation_name)
                + " failed.\n\n"
                + self._short_one_line(
                    full_error,
                    260,
                )
                + "\n\nFull details are in the Log Window."
            ),
        )

    def _innovus_async_success(
        self,
        operation_name,
        result,
        success_callback,
    ):
        try:
            self._runtime_log_event(
                "OPERATION OK",
                (
                    str(operation_name)
                    + "\n"
                    + str(result or "")
                ),
            )

            if success_callback:
                success_callback(result)

            self._innovus_set_busy(
                False,
                "INNOVUS LOCAL: OK | " + operation_name,
            )
        except Exception as exc:
            logging.exception(
                "Innovus local success callback failed"
            )
            self._innovus_async_error(
                operation_name,
                str(exc),
            )

    def _innovus_ping(self):
        return self._innovus_run_async(
            "CHECK BRIDGE",
            lambda: self._innovus_local_request(
                "PING",
                "",
                timeout=5.0,
            ),
            lambda response: self._set_innovus_status(
                "INNOVUS LOCAL: READY | " + response
            ),
        )

    def _innovus_query_instance_payload(self):
        if not self.entries:
            return ""
        unique = []
        seen = set()
        for entry in self.entries:
            if entry.name not in seen:
                seen.add(entry.name); unique.append(entry.name)
        for name in self.io_corner_names:
            if name not in seen:
                seen.add(name); unique.append(name)
        return "\n".join(unique)
    def _innovus_refresh_pad_db(self):
        discovery_mode = not bool(self.entries)
        payload = "" if discovery_mode else self._innovus_query_instance_payload()
        operation = "DISCOVER_IOPAD" if discovery_mode else "QUERY_IOPAD"

        def worker():
            return self._innovus_local_request(operation, payload, timeout=120.0 if discovery_mode else 60.0)

        def success(tsv_text):
            cache = self.innovus_bridge_cache
            cache.parent.mkdir(parents=True, exist_ok=True)
            cache.write_text(tsv_text, encoding="utf-8")
            facts, meta = load_result(cache)
            schema_state, schema = require_supported_query_result_schema(meta, "Innovus local bridge TSV")
            self.meta = meta; self.result_path = cache
            dbg(
                "FLOORPLAN_DB_META "
                f"schema={schema or '<missing>'} "
                f"area_raw={meta.get('current_design_area','<missing>')!r} "
                f"area_query_ok={meta.get('current_design_area_query_ok','<missing>')} "
                f"area_source={meta.get('current_design_area_source','<missing>')} "
                f"master_geom_found={meta.get('master_geometry_found_count','<missing>')} "
                f"master_geom_missing={meta.get('master_geometry_missing_count','<missing>')}"
            )
            if discovery_mode:
                # Nothing to preserve yet: entries/repair_entries are still
                # empty, so a full bootstrap + rebuild is exactly right here.
                self.facts = facts
                self._bootstrap_io_from_current_facts("Innovus live discovery")
                self._refresh_floorplan_mode_display()
                self.run_check(False, rebuild_working_copy=True)
            else:
                # V129 FIX: this branch previously did the same blunt
                # `self.facts = facts` + `run_check(..., rebuild_working_copy
                # =True)` as discovery_mode. rebuild_working_copy=True calls
                # _repair_initialize_from_current(), which unconditionally
                # does `self.repair_entries = deepcopy(self.physical_ring)` -
                # i.e. it throws away whatever the user was currently
                # editing in Ring View (moves, offsets, adds/deletes not yet
                # Saved/Applied) and replaces it with the ORIGINAL loaded
                # IO_FILE model. That is exactly the reported bug: "Refresh
                # configured library token DB" silently reverted the floorplan to an old state
                # instead of refreshing DB evidence on top of what Ring View
                # currently shows.
                #
                # Fix: reuse the same non-destructive merge already used
                # after Apply Global Net
                # (_merge_live_db_facts_without_resetting_io_working_copy),
                # which updates self.facts/pin connectivity/domain evidence
                # for every instance while leaving self.repair_entries (the
                # live Ring View geometry/positions) completely untouched.
                self._merge_live_db_facts_without_resetting_io_working_copy(
                    facts, meta
                )
                if self.repair_entries:
                    self._repair_simulate()
                else:
                    # No working copy exists yet even though entries is
                    # non-empty (e.g. right after Load, before the first
                    # Check/Refresh) - initialize once; there is nothing
                    # in-progress to lose.
                    self._repair_initialize_from_current()
            schema_note = "" if schema_state == "CURRENT" else f" | LEGACY {schema}"
            self.result_label.set(
                "TSV: INNOVUS LOCAL | "
                f"found={meta.get('found_instance_count','?')} missing={meta.get('missing_instance_count','?')}"
                + (" | DB BOOTSTRAP" if discovery_mode else "") + schema_note
            )
            self._refresh_floorplan_mode_display()
            self._set_innovus_status(
                _iopadt_expand_text("INNOVUS LOCAL: __IOPADT_LITERAL_001__ DB REFRESHED") + (" / IO_FILE BOOTSTRAPPED" if discovery_mode else "")
                + f" | found={meta.get('found_instance_count','?')} missing={meta.get('missing_instance_count','?')}"
            )

        return self._innovus_run_async(_iopadt_expand_text("DISCOVER __IOPADT_LITERAL_001__ DB") if discovery_mode else _iopadt_expand_text("REFRESH __IOPADT_LITERAL_001__ DB"), worker, success)
    def _innovus_current_db_patch_text(self):
        if not self.repair_entries:
            raise ValueError(
                "No IO working copy is available."
            )

        if not self._refresh_live_io_validation(
            "Innovus DB patch local-interface preflight"
        ):
            raise ValueError(
                "Current IO working copy has blocking issue(s)."
            )

        return self._render_innovus_db_patch_tcl(
            Path("CHIP_IOPAD_EDITED_BY_GUI.io")
        )

    def _prepare_innovus_db_and_io_apply(
        self,
    ):
        """
        Prepare one explicit local Innovus apply.

        V117 (first/last IO_FILE anchors are legal; middle offset is a WARNING):
          a middle-side offset is reported (geometry report, Issues,
          runtime log) but no longer prevents Apply - Innovus itself is
          the actual authority on whether a given offset placement is
          legal (IMPFP-3108 is raised by read_io_file, not guessed here
          in advance), and offset can be legal on more positions than
          just the side's first emitted IO. If Innovus does still
          reject it via IMPFP-3108 on read_io_file below, THAT still
          blocks (no fallback IO_FILE, no retry, no auto-clear) - this
          tool still never guesses or auto-fixes an offset for you.
        Sequence:
          1. write __IOPADT_LITERAL_001__ geometry report from verified instance .bbox
          2. write primary checked IO_FILE
          3. DB patch -> do_swap_io -> read primary IO_FILE
          4. if Innovus reports IMPFP-3108 on that read, BLOCK.
        """
        if not self.repair_entries:
            raise ValueError(
                "No IO working copy is available."
            )

        offset_violations = (
            self._nonfirst_offset_violation_rows()
        )

        if offset_violations:
            geometry_report = (
                self._build_pad_geometry_report()
            )

            self.pad_geometry_report_path.write_text(
                geometry_report,
                encoding="utf-8",
            )

            self._refresh_pad_geometry_tree()

            detail = "\n".join(
                (
                    f"{row['innovus_side']} #{row['side_index']} "
                    f"{row['instance']} offset={row['offset']} "
                    + (
                        f"W={row['width']:.3f} H={row['height']:.3f}"
                        if row['width'] is not None
                        and row['height'] is not None
                        else "W/H=UNKNOWN"
                    )
                )
                for row in offset_violations
            )

            self._runtime_log_event(
                "IMPFP-3108 MIDDLE_OFFSET WARNING (non-blocking)",
                (
                    _iopadt_expand_text(f"{len(offset_violations)} __IOPADT_LITERAL_001__(s) have an offset on "
                    "a middle side position. This no longer blocks "
                    "Apply - offset can legally exist on positions other "
                    "than the first/last IO_FILE anchor positions. If Innovus rejects "
                    "it via IMPFP-3108 on read_io_file, that will still "
                    "block below (no fallback, no retry, no auto-clear). "
                    "Nothing was auto-fixed.\n")
                    + detail
                ),
            )

        if not self._refresh_live_io_validation(
            "Innovus DB + IO_FILE local-interface preflight"
        ):
            raise ValueError(
                "Current IO working copy has blocking issue(s)."
            )

        bridge_dir = self._innovus_local_bridge_dir()

        io_path = (
            bridge_dir
            / "TT_iopad_apply_current.io"
        )

        io_text = self._render_edited_io_text(
            clear_all_offsets=False,
        )

        def atomic_write_checked(
            path,
            text,
        ):
            tmp = Path(
                str(path) + ".tmp"
            )
            tmp.write_text(
                text,
                encoding="utf-8",
            )
            tmp.replace(
                path
            )

            disk = path.read_text(
                encoding="utf-8",
            )

            if disk != text:
                raise RuntimeError(
                    "IO_FILE write verification failed: "
                    + str(path)
                )

        atomic_write_checked(
            io_path,
            io_text,
        )

        # V128.11: the checked runtime .io now exists. Prepare the three
        # domain-scoped Global-Net pins in GUI memory only. No Innovus DB
        # mutation is allowed here; the user must still press Apply Global Net.
        if self.global_net_path or self.global_net_lines:
            try:
                self._global_net_auto_prepare_domain_supplies_pending(
                    reason="checked runtime IO_FILE emitted"
                )
            except Exception as exc:
                logging.exception(
                    "Automatic pending Global-Net repair after IO_FILE emission failed"
                )
                dbg(
                    "GLOBAL_NET_AUTO_PREPARE_IO_EMIT ERROR "
                    + str(exc)
                )

        geometry_report = (
            self._build_pad_geometry_report()
        )

        self.pad_geometry_report_path.write_text(
            geometry_report,
            encoding="utf-8",
        )

        self._runtime_log_event(
            _iopadt_expand_text("__IOPADT_LITERAL_001__ GEOMETRY / IMPFP-3108 PREFLIGHT"),
            (
                "offset_violations=0 (blocked above otherwise)\n"
                f"primary_io={io_path}\n"
                f"geometry_report={self.pad_geometry_report_path}\n\n"
                + geometry_report
            ),
        )

        db_patch = self._render_innovus_db_patch_tcl(
            io_path
        )

        db_patch_for_apply = db_patch.replace(
            'puts "NEXT STEP: read the edited IO_FILE, then run project snap/floorplan/IO checks as applicable."',
            'puts "NEXT STEP: combined wrapper will invoke project redo_IO now."',
        )

        # V129: every DB-mutating block emitted here is wrapped in the
        # sha256 apply-once guard (see _pkg_guarded_tcl_block docstring).
        # This covers both the patch bundled from a loaded *.ioPKG.tar
        # (applied FIRST, exactly as the package's own db_patch.tcl) and
        # this run's freshly generated patch (applied SECOND, on top).
        db_patch_blocks = []
        if self.io_pkg_bundled_patch_text:
            bundled_sha = hashlib.sha256(
                self.io_pkg_bundled_patch_text.encode("utf-8")
            ).hexdigest()
            db_patch_blocks.append(
                "# --- BUNDLED PATCH FROM LOADED ioPKG.tar "
                f"(source={self.io_pkg_bundled_source_label}) ---"
            )
            db_patch_blocks.append(
                self._pkg_guarded_tcl_block(
                    bundled_sha,
                    "ioPKG bundled DB patch",
                    self.io_pkg_bundled_patch_text,
                )
            )

        fresh_sha = hashlib.sha256(
            db_patch_for_apply.encode("utf-8")
        ).hexdigest()
        db_patch_blocks.append(
            "# --- FRESH GUI-GENERATED PATCH FOR THIS APPLY ---"
        )
        db_patch_blocks.append(
            self._pkg_guarded_tcl_block(
                fresh_sha,
                "ioPADt generated DB patch",
                db_patch_for_apply,
            )
        )
        db_patch_for_apply = "\n\n".join(db_patch_blocks)

        q = self._tcl_brace

        lines = [
            "# =====================================================================",
            "# ioPADt GUI - APPLY DB + IO_FILE",
            "# =====================================================================",
            "# V128 formal project integration.",
            "# Sequence:",
            "#   1) Apply generated DB patch",
            "#   2) Call the project-owned redo_IO <IO_FILE>",
            "# Direct read_io_file is intentionally NOT emitted by the GUI wrapper.",
            "# =====================================================================",
            "",
            f"set ::TT_IOPAD_APPLY_IO_FILE {q(str(io_path))}",
            "",
            "if {![file exists $::TT_IOPAD_APPLY_IO_FILE]} {",
            '    error "Required edited IO_FILE does not exist: $::TT_IOPAD_APPLY_IO_FILE"',
            "}",
            "if {![file readable $::TT_IOPAD_APPLY_IO_FILE]} {",
            '    error "Required edited IO_FILE is not readable: $::TT_IOPAD_APPLY_IO_FILE"',
            "}",
            "if {![llength [info commands redo_IO]]} {",
            '    error "Required project command redo_IO is unavailable. Source the main APR flow before Apply DB + Read IO."',
            "}",
            "",
            'puts "ioPADt APPLY DB + READ IO begin"',
            'puts "Primary IO_FILE = $::TT_IOPAD_APPLY_IO_FILE"',
            "",
            "# ---------------------------------------------------------------------",
            "# DB PATCH",
            "# ---------------------------------------------------------------------",
            db_patch_for_apply,
            "",
            "# ---------------------------------------------------------------------",
            "# PROJECT-OWNED IO RELOAD",
            "# ---------------------------------------------------------------------",
            'puts "REDO_IO_PRIMARY $::TT_IOPAD_APPLY_IO_FILE"',
            "redo_IO $::TT_IOPAD_APPLY_IO_FILE",
            "",
            'puts "ioPADt REDO_IO PASS"',
            'puts "ioPADt APPLY DB + READ IO PASS"',
            "",
            'set _tt_apply_result [join [list "APPLY_DB_AND_IO_FILE=PASS" "REDO_IO=PASS" "IO_FILE=$::TT_IOPAD_APPLY_IO_FILE"] "\n"]',
            "",
            "puts $_tt_apply_result",
            'puts "NEXT STEP: run the project floorplan/IO checks as applicable."',
            "",
            "set _tt_apply_result",
            "",
        ]

        script = "\n".join(
            lines
        )

        io_sha = hashlib.sha256(
            io_text.encode(
                "utf-8"
            )
        ).hexdigest()

        script_sha = hashlib.sha256(
            script.encode(
                "utf-8"
            )
        ).hexdigest()

        self.last_apply_io_path = io_path

        try:
            self.last_db_and_io_apply_path.write_text(
                script,
                encoding="utf-8",
            )
            self.last_db_patch_path.write_text(
                db_patch,
                encoding="utf-8",
            )
        except Exception:
            logging.exception(
                "Failed to persist DB + IO_FILE apply artifacts"
            )

        self._refresh_pad_geometry_tree()

        return {
            "script": script,
            "db_patch": db_patch,
            "io_text": io_text,
            "io_path": io_path,
            "io_sha256": io_sha,
            "script_sha256": script_sha,
            "geometry_report": geometry_report,
        }


    def _innovus_apply_db_patch(self):
        """
        Explicit user-triggered mutation:

          DB patch -> read checked edited IO_FILE
        """
        try:
            prepared = (
                self._prepare_innovus_db_and_io_apply()
            )
        except Exception as exc:
            self._runtime_log_event(
                "DB + IO_FILE PREPARE ERROR",
                str(exc),
            )
            self._show_copyable_error(
                "Apply DB + Read IO",
                str(exc),
            )
            return False

        script = prepared[
            "script"
        ]
        apply_sha = prepared[
            "script_sha256"
        ]
        io_path = prepared[
            "io_path"
        ]
        io_sha = prepared[
            "io_sha256"
        ]

        if (
            self.innovus_db_patch_last_success_sha
            == apply_sha
        ):
            self._runtime_log_event(
                "DB + IO_FILE GUARD",
                (
                    "This exact DB + IO_FILE apply already completed "
                    "successfully in the current GUI session."
                ),
            )
            self._show_copyable_info(
                "Apply DB + Read IO",
                (
                    "This exact DB + redo_IO apply was already reported "
                    "successful.\n\n"
                    "Refresh/reload the authoritative design state before "
                    "applying the same result again."
                ),
            )
            return False

        self._runtime_log_event(
            "DB + IO_FILE PAYLOAD",
            (
                f"apply_sha256={apply_sha}\n"
                f"io_sha256={io_sha}\n"
                f"io_file={io_path}\n"
                f"geometry_report={self.pad_geometry_report_path}\n"
                f"apply_tcl={self.last_db_and_io_apply_path}\n"
                f"db_patch_tcl={self.last_db_patch_path}"
            ),
        )

        if not self._ask_copyable_yesno(
            "Apply DB + Read IO",
            (
                "This will MODIFY the current local Innovus DB.\n\n"
                "Sequence:\n"
                "1. Apply generated DB patch\n"
                "2. Call project redo_IO using the checked edited IO_FILE\n\n"
                f"IO_FILE:\n{io_path}\n\n"
                "DB behavior:\n"
                "- compatible existing CREATE target: SKIP\n"
                "- already absent DELETE target: SKIP\n"
                "- incompatible existing target: ERROR\n\n"
                "Continue?"
            ),
        ):
            return False

        def success(response):
            self.innovus_db_patch_last_success_sha = apply_sha

            self._runtime_log_event(
                "DB + IO_FILE SUCCESS",
                (
                    f"apply_sha256={apply_sha}\n"
                    f"io_sha256={io_sha}\n"
                    f"io_file={io_path}\n"
                    + str(response or "")
                ),
            )

            self._show_copyable_info(
                "Apply DB + Read IO",
                (
                    "DB patch and project redo_IO completed successfully.\n\n"
                    f"Applied IO_FILE:\n{io_path}\n\n"
                    + "Next: run the project snap/floorplan/IO checks as applicable.\n"
                    + _iopadt_expand_text("__IOPADT_LITERAL_001__ geometry report:\n")
                    + str(self.pad_geometry_report_path)
                    + "\n\nFull Innovus response is available in the Log Window."
                ),
            )

        return self._innovus_run_async(
            "APPLY DB + READ IO",
            lambda: self._innovus_local_request(
                "APPLY_DB_AND_IO_FILE",
                script,
                timeout=180.0,
            ),
            success,
        )

    def _global_net_apply_wrapper_from_canonical_source(self, source_tcl, source_sha256=""):
        """Wrap one canonical Global Net source text for Innovus execution.

        V128.20 invariant: Save / Export / Generated-Tcl Preview / Session
        artifact / Apply Global Net all consume the SAME canonical source Tcl.
        Apply is allowed to add only this execution wrapper around that exact
        source block; it must not independently re-render or rewrite mappings.
        """
        source_tcl = str(source_tcl or "")
        sha = str(source_sha256 or self._global_net_final_text_signature(source_tcl))
        # V129: the canonical source block (including its inline managed
        # create-net patch) is wrapped in the sha256 apply-once guard, same
        # mechanism used for the IO DB patch. The per-net create_net calls
        # are already idempotent-guarded individually, but full command
        # edits (global_net_full_cmd_edits) are free-form Tcl the GUI does
        # not fully control, so this is defense-in-depth against a verbatim
        # replay (e.g. Apply Global Net run twice, or a GnetPKG.tar's
        # payload sourced more than once in the same Innovus session).
        guarded_source_block = self._pkg_guarded_tcl_block(
            sha,
            "Global Net canonical source",
            "# >>> EXACT CANONICAL GLOBAL NET SOURCE BEGIN\n"
            + source_tcl.rstrip()
            + "\n# <<< EXACT CANONICAL GLOBAL NET SOURCE END",
        )
        parts = [
            "# ================================================================",
            "# ioPADt GUI - INNOVUS GLOBAL NET APPLY",
            "# ================================================================",
            "# V128.20: canonical-source synchronized Apply payload.",
            f"# CANONICAL_GLOBAL_NET_SOURCE_SHA256={sha}",
            "# Global-Net-only mutation. NEVER calls redo_IO/read_io_file.",
            'puts "ioPADt GLOBAL NET APPLY begin"',
            f'puts "ioPADt GLOBAL NET canonical_sha256={sha}"',
            "",
            guarded_source_block,
            "",
            "# Reconcile actual PG connectivity with the current rules.",
            "# This is especially important after netlist-imported PG connections.",
            "if {[llength [info commands commit_global_net_rules]] > 0} {",
            '    puts "ioPADt GLOBAL NET APPLY commit_global_net_rules"',
            "    commit_global_net_rules",
            "} else {",
            '    puts "**WARN: commit_global_net_rules is unavailable; relying on connect_global_net immediate connectivity."',
            "}",
            "",
            'puts "ioPADt GLOBAL NET APPLY COMMANDS COMPLETE"',
            "",
        ]
        script = "\n".join(parts)
        if re.search(r"(?m)^\s*(?:redo_IO|read_io_file)\b", script):
            raise ValueError(
                "Safety violation: Apply Global Net payload contains redo_IO/read_io_file."
            )
        return script

    def _global_net_canonical_artifacts(self):
        """Return the one authoritative generated Global Net source/apply pair.

        The function intentionally performs every deterministic normalization
        exactly once: working text -> exact-domain netlist overrides ->
        save-readiness/new-net discovery -> bound idempotent create-net patch.
        Every output path must call this function instead of rebuilding its own
        variant.
        """
        if not (self.global_net_path or self.global_net_lines):
            raise ValueError("Load Global Net Tcl first.")

        working_text = self._render_global_net_text()
        promoted_text = self._global_net_promote_exact_domain_pg_overrides(working_text)
        save_validation = self._global_net_check_save_readiness(promoted_text)
        if int(save_validation.get("error_count", 0) or 0) > 0:
            raise ValueError(
                "Global Net Tcl has blocking save/readiness error(s). "
                "Fix them before generation/apply."
            )

        new_nets = list(save_validation.get("new_nets", []))
        source_tcl = self._global_net_source_commit_text(promoted_text, new_nets)
        # V128.25: one canonical global_net.tcl now owns ALL persistent configured library token
        # state as well: the round-trip target metadata, the executable
        # create_net/connect_pin connectivity, then dont_touch preservation.
        # Apply therefore executes exactly what Save/Export writes instead of
        # appending an apply-only configured library token connectivity patch that was lost on disk.
        source_tcl = self._global_net_bind_rte_pending_targets_block(source_tcl)
        source_tcl = self._global_net_bind_rte_connectivity_block(source_tcl)
        source_tcl = self._global_net_bind_rte_dont_touch_block(source_tcl)
        source_sha256 = self._global_net_final_text_signature(source_tcl)
        apply_tcl = self._global_net_apply_wrapper_from_canonical_source(
            source_tcl, source_sha256
        )
        dbg(
            "GLOBAL_NET_CANONICAL_RENDER "
            f"sha256={source_sha256} new_nets={len(new_nets)} "
            f"source_bytes={len(source_tcl.encode('utf-8'))} "
            f"apply_bytes={len(apply_tcl.encode('utf-8'))}"
        )
        return {
            "working_text": working_text,
            "promoted_text": promoted_text,
            "source_tcl": source_tcl,
            "source_sha256": source_sha256,
            "apply_tcl": apply_tcl,
            "save_validation": save_validation,
            "new_nets": new_nets,
        }

    def _innovus_current_global_net_text(self):
        """Return Apply Global Net payload built from the canonical source Tcl."""
        return self._global_net_canonical_artifacts()["apply_tcl"]

    def _merge_live_db_facts_without_resetting_io_working_copy(self, facts, meta):
        """Install fresh Innovus DB evidence without consuming pending IO edits."""
        self.facts = facts
        self.meta = meta

        # Keep the user's independent IO-layout working copy intact. For PADs
        # that still exist in both models, update only live DB connectivity and
        # domain evidence. Geometry/master of simulated IO edits remains owned
        # by repair_facts until Apply DB + Read IO is explicitly pressed.
        if self.repair_facts:
            for name, fresh in facts.items():
                current = self.repair_facts.get(name)
                if current is None:
                    continue
                current.pin_nets = copy.deepcopy(fresh.pin_nets)
                current.pin_kinds = copy.deepcopy(fresh.pin_kinds)
                current.pin_net_query_ok = copy.deepcopy(fresh.pin_net_query_ok)
                current.power_domain = fresh.power_domain
                current.power_domain_query_ok = fresh.power_domain_query_ok
                current.power_domain_source = fresh.power_domain_source

        self._rebuild_loaded_base_io_model()
        self._refresh_floorplan_mode_display()

    def _backup_file_to_sibling_dot_backup(self, path):
        """Copy an existing file into a `.backup/` folder created next to
        it (NOT the ioPADt/build/backup/ convention used elsewhere) -
        creates `.backup/` if it doesn't exist yet. Returns the backup
        path, or None if there was no existing file to back up."""
        path = Path(path)
        if not path.is_file():
            return None
        backup_dir = path.parent / ".backup"
        backup_dir.mkdir(parents=True, exist_ok=True)
        stamp = (
            time.strftime("%Y%m%d_%H%M%S")
            + f"_{time.time_ns() % 1000000000:09d}"
        )
        backup_path = backup_dir / f"{path.stem}_{stamp}{path.suffix}"
        shutil.copy2(str(path), str(backup_path))
        return backup_path

    def _global_net_adopt_canonical_source_after_apply(self, source_tcl, source_path=None):
        """V128.26: make the in-memory Global Net model match the exact Tcl
        that Apply just wrote to disk.

        Before this fix, Apply updated the source file but left global_net_lines
        / global_net_original_text on the pre-canonical working copy. A later
        Save Tool State therefore frequently serialized the older state even
        though the file and Innovus DB were newer.
        """
        raw = str(source_tcl or "")
        if not raw:
            return
        if source_path:
            try:
                self.global_net_source_path = Path(source_path).resolve()
            except Exception:
                pass
        self.global_net_lines = raw.splitlines(keepends=True)
        if raw and not self.global_net_lines:
            self.global_net_lines = [raw]
        self.global_net_original_text = raw
        self.global_net_original_lines = copy.deepcopy(self.global_net_lines)
        self.global_net_full_cmd_edits = []
        self.global_net_full_cmd_edit_seq = 0
        self.global_net_cmd_editor_target = None

        # Canonical source carries the authoritative persisted configured library token targets.
        for domain_id, net in self._global_net_parse_rte_pending_targets_block(raw).items():
            self.global_net_domain_pin_manual_targets[(str(domain_id), _iopadt_expand_text("__IOPADT_LITERAL_002__"))] = str(net)

        self._global_net_detect_rules()
        self._global_net_clear_undo()
        try:
            self._global_net_refresh_tree()
            self._global_net_repair_refresh()
        except Exception:
            logging.exception("V128.26 canonical Global Net in-memory refresh failed")
        dbg(
            "GLOBAL_NET_ADOPT_APPLIED_CANONICAL "
            f"bytes={len(raw.encode('utf-8'))} "
            f"sha256={hashlib.sha256(raw.encode('utf-8')).hexdigest()}"
        )

    def _innovus_apply_global_net(self):
        try:
            canonical = self._global_net_canonical_artifacts()
            script = canonical["apply_tcl"]
        except Exception as exc:
            self._show_copyable_error("Apply Global Net to Innovus", str(exc))
            return False

        # V128.25: configured library token create_net/connect_pin is now embedded in the
        # canonical source_tcl itself, so Apply/Save/Export all consume the
        # same executable connectivity.  Keep using the generator here only
        # to derive dialog/report metadata; DO NOT append it again or the same
        # connect_pin commands would execute twice.
        _rte_block, rte_applied_domains, rte_notes = (
            self._global_net_rte_apply_tcl_block(include_protection=False)
        )

        # V128.24: always run one live-DB protection pass AFTER the managed
        # configured library token connect/create block.  This is deliberately outside the
        # canonical-source apply-once guard, so Apply Global Net itself
        # reasserts preservation even when the GUI's cached configured library token facts are
        # empty/stale or a target net was just created above.
        script = (
            script.rstrip("\n")
            + "\n\n"
            + self._global_net_rte_runtime_dont_touch_tcl_block()
        )

        if not self.entries:
            self._show_copyable_error(
                "Apply Global Net to Innovus",
                _iopadt_expand_text("No IO/__IOPADT_LITERAL_001__ model is loaded. Load/Discover __IOPADT_LITERAL_001__ DB first so post-apply verification can re-query the same __IOPADT_LITERAL_001__ set."),
            )
            return False

        payload = self._innovus_query_instance_payload()
        if not payload.strip():
            self._show_copyable_error("Apply Global Net to Innovus", _iopadt_expand_text("No __IOPADT_LITERAL_001__ instances are available for verification."))
            return False

        rte_dialog_note = (
            (
                _iopadt_expand_text("\n"
                f"__IOPADT_LITERAL_002__ (SIGNAL pin, connect_pin): {len(rte_applied_domains)} IO "
                "Domain(s) with a recorded target will also be connected in "
                "this same Apply: ")
                + ", ".join(f"D{d}" for d in rte_applied_domains) + "\n"
            )
            if rte_applied_domains
            else ""
        )
        if not self._ask_copyable_yesno(
            "Apply Global Net to Innovus",
            (
                _iopadt_expand_text("This modifies Global Net connectivity in the current Innovus session, "
                "AND updates the on-disk Global Net source file.\n\n"
                "Sequence:\n"
                "1. Apply current GUI Global Net Tcl (connect_global_net) "
                "+ any __IOPADT_LITERAL_002__ connect_pin changes below\n"
                "2. Re-query Innovus __IOPADT_LITERAL_001__ pin connectivity/domain state\n"
                "3. Rebuild the DB-backed Global Net model\n"
                "4. Run post-apply Global Net Check\n"
                "5. Back up the existing source file to a sibling .backup/ "
                "folder (created if missing), then overwrite it with the "
                "applied Tcl\n")
                + rte_dialog_note
                + _iopadt_expand_text("\nThis operation does NOT call redo_IO or read_io_file, "
                "and never touches an __IOPADT_LITERAL_002__-role __IOPADT_LITERAL_001__ instance or its __IOPADT_LITERAL_007__-side "
                "private tie net.\n\nContinue?")
            ),
        ):
            return False

        self._set_global_net_apply_state(
            "GLOBAL_NET_APPLYING", apply_result="RUNNING", check_result="PENDING"
        )
        current_sig = str(canonical["source_sha256"])

        def worker():
            # Stage 1: DB mutation. If this raises, APPLY RESULT is FAIL.
            apply_response = self._innovus_local_request(
                "APPLY_GLOBAL_NET", script, timeout=120.0
            )
            # Stage 2 is deliberately captured separately. Once Stage 1
            # returned OK we must never relabel the apply itself as FAIL just
            # because post-apply re-query/check failed.
            try:
                query_response = self._innovus_local_request(
                    "QUERY_GLOBAL_NET", payload, timeout=90.0
                )
                query_error = ""
            except Exception as exc:
                query_response = ""
                query_error = str(exc)
            return {
                "apply_response": apply_response,
                "query_tsv": query_response,
                "query_error": query_error,
                "signature": current_sig,
            }

        def success(result):
            self._set_global_net_apply_state(
                "GLOBAL_NET_CHECKING", apply_result="PASS", check_result="RUNNING"
            )

            # V129: Apply now also syncs the on-disk Global Net source file
            # to exactly what was just pushed to Innovus (previously Apply
            # only touched the DB; Save was the only thing that touched
            # disk). Any existing file at that path is backed up to a
            # sibling .backup/ folder first (created if missing) - this is
            # deliberately a DIFFERENT backup location from the
            # ioPADt/build/backup/ convention Save/Export use, per request.
            src_path = self.global_net_source_path or self.global_net_path
            if src_path:
                try:
                    backup_path = self._backup_file_to_sibling_dot_backup(
                        src_path
                    )
                    Path(src_path).write_text(
                        canonical["source_tcl"], encoding="utf-8"
                    )
                    # V128.26: the file just became authoritative. Keep the
                    # in-memory working/original model on the exact same
                    # canonical text BEFORE Save Tool State can run.
                    self._global_net_adopt_canonical_source_after_apply(
                        canonical["source_tcl"], src_path
                    )
                    file_sync_note = (
                        f"Source file updated: {src_path}\n"
                        + (
                            f"Backup of prior version: {backup_path}\n"
                            if backup_path
                            else "No prior file existed at that path; nothing to back up.\n"
                        )
                    )
                    self._runtime_log_event(
                        "GLOBAL NET APPLY SOURCE SYNC",
                        f"path={src_path} backup={backup_path}",
                    )
                except Exception as exc:
                    file_sync_note = (
                        f"WARNING: DB apply succeeded but updating the "
                        f"source file failed: {exc}\n"
                    )
                    logging.exception(
                        "Failed to sync Global Net source file after Apply"
                    )
            else:
                file_sync_note = (
                    "No Global Net source path is loaded; the on-disk file "
                    "was NOT updated (DB apply still succeeded).\n"
                )

            rte_note = ""
            if rte_applied_domains:
                rte_note = (
                    _iopadt_expand_text(f"__IOPADT_LITERAL_002__ connect_pin applied for: ")
                    + ", ".join(f"D{d}" for d in rte_applied_domains) + "\n"
                )
            if _rte_block:
                rte_note += (
                    _iopadt_expand_text("__IOPADT_LITERAL_002__ IO-ring optimization protection included "
                    "(set_dont_touch on detected __IOPADT_LITERAL_002__ nets).\n")
                )
            if rte_notes:
                rte_note += _iopadt_expand_text("__IOPADT_LITERAL_002__ skipped: ") + " | ".join(rte_notes) + "\n"
            file_sync_note += rte_note

            if result.get("query_error"):
                self.global_net_last_applied_signature = str(result["signature"])
                self._global_net_set_check_state(
                    "FAIL", "POST-APPLY DB QUERY FAILED", clear_result=True
                )
                self._set_global_net_apply_state(
                    "GLOBAL_NET_FAIL", apply_result="PASS", check_result="FAIL"
                )
                self._runtime_log_event(
                    "GLOBAL NET POST-APPLY QUERY FAIL", str(result.get("query_error"))
                )
                self._show_copyable_warning(
                    "Apply Global Net - Verification Failed",
                    "APPLY RESULT: PASS\nGLOBAL NET CHECK: FAIL\n\n"
                    + file_sync_note
                    + "\nGlobal Net Tcl executed successfully, but the mandatory fresh Innovus "
                    "re-query failed. No old Python-memory connectivity was used.\n\n"
                    "QUERY ERROR:\n" + str(result.get("query_error", "")) + "\n\n"
                    "Review the Log Window and re-run Apply/Check after the query issue is fixed."
                )
                return
            cache = RUNTIME_BUILD_DIR / "TT_iopad_global_net_postapply.tsv"
            cache.write_text(result["query_tsv"], encoding="utf-8")
            facts, meta = load_result(cache)
            require_supported_query_result_schema(meta, "Post-apply Global Net query")
            if str(meta.get("connectivity_queried", "0")).strip() != "1":
                raise RuntimeError(
                    "Post-apply query did not return live pin connectivity evidence."
                )
            qcount = int(float(str(meta.get("pin_connectivity_query_count", "0") or "0")))
            if qcount <= 0:
                raise RuntimeError(
                    _iopadt_expand_text("Post-apply query returned no __IOPADT_LITERAL_001__ pin connectivity records.")
                )
            self._merge_live_db_facts_without_resetting_io_working_copy(facts, meta)

            ok = bool(self._menu_check_global_net(
                force_db_actual=True, post_apply=True, interactive=False
            ))
            self.global_net_last_applied_signature = str(result["signature"])
            if ok:
                self._set_global_net_apply_state(
                    "GLOBAL_NET_PASS", apply_result="PASS", check_result="PASS"
                )
                self._show_copyable_info(
                    "Apply Global Net",
                    "APPLY RESULT: PASS\nGLOBAL NET CHECK: PASS\n\n"
                    + file_sync_note
                    + "\nChanges were applied, Innovus DB was re-queried, and post-apply verification passed.\n"
                    "redo_IO was NOT called.",
                )
            else:
                self._set_global_net_apply_state(
                    "GLOBAL_NET_FAIL", apply_result="PASS", check_result="FAIL"
                )
                self._show_copyable_warning(
                    "Apply Global Net - Verification Failed",
                    "APPLY RESULT: PASS\nGLOBAL NET CHECK: FAIL\n\n"
                    + file_sync_note
                    + "\nGlobal Net changes were applied, but post-apply verification failed.\n"
                    "The diagnostic text below is selectable and Copy All is available.\n\n"
                    + self._global_net_check_copy_report(),
                )

        return self._innovus_run_async(
            "APPLY GLOBAL NET + VERIFY", worker, success
        )

    def _build(self):
        top = ttk.Frame(self,padding=10)
        top.pack(fill="x")
        ttk.Label(top,text=_iopadt_expand_text("ioPADt __IOPADT_LITERAL_001__ Tool"),font=("Segoe UI",15,"bold")).pack(side="left")
        act = ttk.Frame(top); act.pack(side="right")
        ttk.Button(act,text="1. Load CHIP.io (Optional)",command=self.load_io).pack(side="left",padx=3)
        ttk.Button(act,text="2. Generate Tcl",command=self.save_tcl).pack(side="left",padx=3)
        ttk.Button(act,text="3. Load TSV",command=self.load_tsv).pack(side="left",padx=3)
        ttk.Button(
            act,
            text="4. Load Global Net",
            command=self.load_global_net_tcl,
        ).pack(side="left", padx=3)
        ttk.Button(
            act,
            text=_iopadt_expand_text("5. Run IO __IOPADT_LITERAL_001__ Check (ALL)"),
            command=self.run_check,
        ).pack(side="left", padx=3)
        ttk.Button(
            act,
            text="Save Tool State",
            command=self.save_tool_session,
        ).pack(side="left", padx=(10,3))
        ttk.Button(
            act,
            text="Load Last State",
            command=self.load_last_tool_session,
        ).pack(side="left", padx=3)

        top_status = ttk.Frame(
            self,
            padding=(10,0,10,6),
        )
        top_status.pack(fill="x")
        ttk.Label(
            top_status,
            textvariable=self.full_check_status,
            font=("Segoe UI", 9, "bold"),
        ).pack(
            side="right",
            anchor="e",
        )

        iface = ttk.LabelFrame(
            self,
            text="Innovus Local Interface",
            padding=8,
        )
        iface.pack(
            fill="x",
            padx=10,
            pady=(0,6),
        )

        ttk.Label(
            iface,
            text="Bridge Dir:",
        ).pack(side="left")

        ttk.Entry(
            iface,
            width=54,
            textvariable=self.innovus_bridge_dir,
        ).pack(
            side="left",
            padx=(4,10),
            fill="x",
            expand=True,
        )

        self.innovus_action_buttons = []

        for label, command in (
            ("Check Bridge", self._innovus_ping),
            (_iopadt_expand_text("Refresh __IOPADT_LITERAL_001__ DB"), self._innovus_refresh_pad_db),
            ("Apply DB + Read IO", self._innovus_apply_db_patch),
            ("Apply Global Net", self._innovus_apply_global_net),
        ):
            button = ttk.Button(
                iface,
                text=label,
                command=command,
            )
            button.pack(
                side="left",
                padx=3,
            )
            self.innovus_action_buttons.append(button)

        # Log is intentionally NOT part of innovus_action_buttons so it stays
        # available while a bridge operation is running.
        ttk.Button(
            iface,
            text="Log",
            command=self._open_log_window,
        ).pack(
            side="left",
            padx=(6, 3),
        )

        ttk.Label(
            iface,
            textvariable=self.pending_apply_text,
            font=("Segoe UI", 8, "bold"),
        ).pack(side="right", padx=(8,4))

        self.innovus_status_label = ttk.Label(
            iface,
            textvariable=self.innovus_status,
            font=("Segoe UI",9,"bold"),
            width=44,
            anchor="w",
        )
        self.innovus_status_label.pack(
            side="right",
            padx=(10,0),
        )

        pf = ttk.LabelFrame(self,text="Innovus TSV output path",padding=8)
        pf.pack(fill="x",padx=10,pady=(0,8))
        ttk.Entry(pf,textvariable=self.tsv_output_path).pack(side="left",fill="x",expand=True)
        ttk.Label(pf,text="Innovus/Linux path embedded into generated Tcl").pack(side="left",padx=(10,0))

        info = ttk.Frame(self,padding=(10,0,10,8)); info.pack(fill="x")
        ttk.Label(info,textvariable=self.io_label).pack(anchor="w")
        ttk.Label(info,textvariable=self.result_label).pack(anchor="w")
        ttk.Label(
            info,
            textvariable=self.session_status,
            font=("Segoe UI", 8, "bold"),
        ).pack(anchor="w")

        self.nb = ttk.Notebook(self)
        self.nb.pack(fill="both",expand=True,padx=10,pady=(0,8))

        self.tab_ring=ttk.Frame(self.nb)
        self.tab_offset=ttk.Frame(self.nb)
        self.tab_issues=ttk.Frame(self.nb); self.tab_domains=ttk.Frame(self.nb)
        self.tab_repair=ttk.Frame(self.nb)
        self.tab_expected=ttk.Frame(self.nb)
        self.tab_match=ttk.Frame(self.nb); self.tab_master=ttk.Frame(self.nb)
        self.tab_pins=ttk.Frame(self.nb); self.tab_diag=ttk.Frame(self.nb)
        self.tab_geometry=ttk.Frame(self.nb)
        self.tab_global_net=ttk.Frame(self.nb)

        self._build_menubar()

        self.nb.add(self.tab_ring,text="Ring View")
        self.nb.add(self.tab_issues,text="Issues")
        self.nb.add(self.tab_global_net,text="Global Net")
        self.nb.add(self.tab_offset,text="Ring Offset")
        # V129: merged "IO Domain" + "IO Domain Sources" into this one tab
        # (they showed almost the same per-domain data; this one now has
        # both the read-only health/count columns AND the editable Global
        # Net Set/Repair columns+buttons, so there is no more duplicate).
        self.nb.add(self.tab_domains,text="IO Domain")
        self.nb.add(self.tab_geometry,text=_iopadt_expand_text("__IOPADT_LITERAL_001__ Geometry"))
        self.nb.add(self.tab_diag,text="Diagnostics")

        self._install_notebook_tab_drag_reorder()

        # ==============================================================
        # V55 Ring View top controls
        # Manual repair UI lives in the dockable Repair Panel.
        # ==============================================================
