    def _tree_embedded(self, parent, specs):
        frame = ttk.Frame(parent)
        cols = [x[0] for x in specs]
        tree = ttk.Treeview(frame, columns=cols, show="headings")

        for key, head, width in specs:
            tree.heading(key, text=head)
            tree.column(key, width=width, anchor="w")

        sx = ttk.Scrollbar(frame, orient="horizontal", command=tree.xview)
        sy = ttk.Scrollbar(frame, orient="vertical", command=tree.yview)
        tree.configure(xscrollcommand=sx.set, yscrollcommand=sy.set)

        tree.grid(row=0,column=0,sticky="nsew")
        sy.grid(row=0,column=1,sticky="ns")
        sx.grid(row=1,column=0,sticky="ew")
        frame.rowconfigure(0,weight=1)
        frame.columnconfigure(0,weight=1)

        # Proxy only the small Treeview API used by Repair Planner.
        frame.tree = tree
        frame.get_children = tree.get_children
        frame.delete = tree.delete
        frame.insert = tree.insert
        frame.selection = tree.selection
        frame.item = tree.item
        frame.tag_configure = tree.tag_configure
        return frame

    def _tree(self,parent,specs):
        f=ttk.Frame(parent,padding=8); f.pack(fill="both",expand=True)
        cols=[x[0] for x in specs]
        t=ttk.Treeview(f,columns=cols,show="headings")
        for k,h,w in specs:
            t.heading(k,text=h); t.column(k,width=w,anchor="w")
        sx=ttk.Scrollbar(f,orient="horizontal",command=t.xview)
        sy=ttk.Scrollbar(f,orient="vertical",command=t.yview)
        t.configure(xscrollcommand=sx.set,yscrollcommand=sy.set)
        t.grid(row=0,column=0,sticky="nsew"); sy.grid(row=0,column=1,sticky="ns"); sx.grid(row=1,column=0,sticky="ew")
        f.rowconfigure(0,weight=1); f.columnconfigure(0,weight=1)
        return t

    # =================================================================
    # V46 Global Net Tcl editor
    # =================================================================

    def _gn_unquote_word(self, value):
        s = str(value or "").strip()
        if len(s) >= 2 and (
            (s[0] == "{" and s[-1] == "}")
            or (s[0] == '"' and s[-1] == '"')
        ):
            return s[1:-1]
        return s

    def _gn_quote_word(self, value):
        s = str(value or "")
        if not s:
            return "{}"
        if re.search(r'[\s{}";]', s):
            return "{" + s.replace("}", "\\}") + "}"
        return s

    def _gn_logical_commands(self, source_text):
        """
        Yield (start_line, logical_command) while joining Tcl backslash
        continuations. This is sufficient for the project's global_net.tcl
        command style and keeps comments/inactive commands excluded.
        """
        out = []
        buf = ""
        start_line = None

        for ln, raw in enumerate(str(source_text).splitlines(), 1):
            line = raw.rstrip("\r\n")

            if start_line is None:
                start_line = ln

            stripped = line.rstrip()

            if stripped.endswith("\\"):
                buf += stripped[:-1] + " "
                continue

            buf += line
            cmd = buf.strip()

            if cmd and not cmd.startswith("#"):
                out.append((start_line, cmd))

            buf = ""
            start_line = None

        if buf.strip():
            cmd = buf.strip()
            if not cmd.startswith("#"):
                out.append((start_line or 1, cmd))

        return out

    def _gn_parse_any_connect_line(self, line):
        """
        Parse one ACTIVE connect_global_net command for display/audit.

        Unlike the electrical checker parser, this accepts every Innovus
        -type supported by the user-supplied command help:
          pg_pin / tie_hi / tie_lo / net

        It also retains selectors/flags even when they are not relevant to
        __IOPADT_LITERAL_001__ pg_pin comparison.
        """
        body = " ".join(
            str(line).replace("\\\n", " ").split()
        )

        if not body or body.startswith("#"):
            return None

        if not re.match(r'^connect_global_net(?:\s|$)', body):
            return None

        word = r'(\{[^}]*\}|"[^"]*"|\S+)'

        # Optional positional global-net name. If the first word after the
        # command starts with '-', it is an option and the net name is absent.
        rest = body[len("connect_global_net"):].lstrip()
        net_raw = ""

        if rest:
            mm = re.match(word, rest)

            if mm:
                first = mm.group(1)

                if not str(first).startswith("-"):
                    net_raw = first

        def opt(name):
            mm = re.search(
                r'(?<!\S)'
                + re.escape(name)
                + r'\s+'
                + word,
                body,
            )

            return (
                self._gn_unquote_word(mm.group(1))
                if mm
                else ""
            )

        def flag(name):
            return bool(
                re.search(
                    r'(?<!\S)'
                    + re.escape(name)
                    + r'(?!\S)',
                    body,
                )
            )

        rule_type = (
            opt("-type") or "pg_pin"
        ).lower()

        if rule_type not in (
            "pg_pin",
            "tie_hi",
            "tie_lo",
            "net",
        ):
            # Still list the command instead of hiding it.
            rule_type = rule_type or "<unknown>"

        return {
            "net": (
                self._gn_unquote_word(net_raw)
                if net_raw
                else ""
            ),
            "type": rule_type,
            "pin": opt("-pin_base_name"),
            "inst": opt("-inst_base_name"),
            "power_domain": opt("-power_domain"),
            "hinst": opt("-hinst"),
            "single_inst": opt("-single_inst"),
            "net_base_name": opt("-net_base_name"),
            "region": opt("-region"),
            "all": flag("-all"),
            "auto_tie": flag("-auto_tie"),
            "disconnect": flag("-disconnect"),
            "non_hierarchical": flag("-non_hierarchical"),
            "override": flag("-override"),
            "netlist_override": flag("-netlist_override"),
            "verbose": flag("-verbose"),
            "command": body,
        }

    def _gn_parse_connect_line(self, line):
        """
        Electrical-checker parser.

        Only active -type pg_pin commands with a usable pin selector are
        consumed by __IOPADT_LITERAL_001__ Global Net electrical comparison. Other
        connect_global_net commands remain visible in the V58 all-command
        lists but do not become pg_pin coverage rules.
        """
        parsed = self._gn_parse_any_connect_line(line)

        if parsed is None:
            return None

        if parsed.get("type") != "pg_pin":
            return None

        pin = str(parsed.get("pin", "") or "")

        if not pin:
            if parsed.get("all"):
                pin = "*"
            else:
                return None

        out = dict(parsed)
        out["pin"] = pin
        out["inst"] = (
            str(parsed.get("inst", "") or "")
            or "*"
        )
        return out

    def _gn_replace_option_word(self, line, option, value):
        word = r'(\{[^}]*\}|"[^"]*"|\S+)'
        replacement = option + " " + self._gn_quote_word(value)
        out, n = re.subn(
            r'(?<!\S)' + re.escape(option) + r'\s+' + word,
            replacement,
            line,
            count=1,
        )
        return out, n

    def _gn_update_line_fields(self, line, net, pin, inst, override):
        newline = ""
        body = str(line)
        if body.endswith("\r\n"):
            body, newline = body[:-2], "\r\n"
        elif body.endswith("\n"):
            body, newline = body[:-1], "\n"

        word = r'(\{[^}]*\}|"[^"]*"|\S+)'
        body, n = re.subn(
            r'^(\s*connect_global_net\s+)' + word,
            lambda m: m.group(1) + self._gn_quote_word(net),
            body,
            count=1,
        )
        if n != 1:
            raise ValueError("Selected line is not connect_global_net")

        body, n_pin = self._gn_replace_option_word(
            body, "-pin_base_name", pin
        )
        body, n_inst = self._gn_replace_option_word(
            body, "-inst_base_name", inst
        )
        if n_pin != 1 or n_inst != 1:
            raise ValueError(
                _iopadt_expand_text("POWER __IOPADT_LITERAL_001__ rule must contain "
                "-pin_base_name and -inst_base_name")
            )

        has_override = bool(
            re.search(r'(?<!\S)-override(?!\S)', body)
        )
        if override and not has_override:
            body = body.rstrip() + " -override"
        elif not override and has_override:
            body = re.sub(
                r'\s+-override(?!\S)', "", body, count=1
            )

        return body + newline

    def _global_net_power_pad_names(self):
        names = []

        if self.repair_entries and self.repair_facts:
            entries = self.repair_entries
            facts = self.repair_facts
            display = self._repair_display_name
        else:
            entries = self.physical_ring or self.entries
            facts = self.facts
            display = lambda x: x

        for e in entries or []:
            d = facts.get(e.name) if facts else None
            if d is None or not d.found:
                continue
            if d.role not in ("CORE_POWER", "IO_POWER"):
                continue
            names.append((display(e.name), d.role))

        return sorted(set(names))

    def _global_net_match_power_pads(self, pattern):
        result = []
        for name, role in self._global_net_power_pad_names():
            try:
                hit = fnmatch.fnmatchcase(name, pattern)
            except Exception:
                hit = False
            if hit:
                result.append((name, role))
        return result

    # =================================================================
    # V50 Design vs Global Net comparison for Ring View
    # =================================================================

    def _global_net_panel_is_visible(
        self,
        name,
    ):
        paned = self.global_net_main_paned
        frame = self.global_net_panel_frames.get(name)

        if paned is None or frame is None:
            return False

        try:
            return str(frame) in {
                str(x)
                for x in paned.panes()
            }
        except Exception:
            return False

    def _global_net_hide_panel(
        self,
        name,
    ):
        paned = self.global_net_main_paned
        frame = self.global_net_panel_frames.get(name)

        if paned is None or frame is None:
            return

        if not self._global_net_panel_is_visible(name):
            return

        try:
            paned.forget(frame)
            self._refresh_window_menu()
        except Exception:
            logging.exception(
                f"Failed to hide Global Net panel: {name}"
            )

    def _global_net_show_panel(
        self,
        name,
    ):
        paned = self.global_net_main_paned
        frame = self.global_net_panel_frames.get(name)

        if paned is None or frame is None:
            return

        if self._global_net_panel_is_visible(name):
            return

        order = self.global_net_panel_order
        visible = [
            panel_name
            for panel_name in order
            if self._global_net_panel_is_visible(
                panel_name
            )
        ]

        target_order = order.index(name)
        insert_index = sum(
            1
            for panel_name in visible
            if order.index(panel_name) < target_order
        )

        try:
            paned.insert(
                insert_index,
                frame,
                weight=self.global_net_panel_weights.get(
                    name,
                    1,
                ),
            )
        except Exception:
            try:
                paned.add(
                    frame,
                    weight=self.global_net_panel_weights.get(
                        name,
                        1,
                    ),
                )
            except Exception:
                logging.exception(
                    f"Failed to show Global Net panel: {name}"
                )

        self._refresh_window_menu()

    def _global_net_internal_from_display_name(self, display_name):
        display_name = str(display_name or "").strip()

        if not display_name:
            return ""

        facts = (
            self.repair_facts
            if self.repair_facts
            else self.facts
        )

        for internal in facts:
            shown = (
                self._repair_display_name(internal)
                if self.repair_facts
                else internal
            )

            if shown == display_name:
                return internal

        return ""

    def _global_net_command_context_menu(
        self,
        root_x,
        root_y,
        local_y,
    ):
        frame = getattr(
            self,
            "global_net_tab_all_cmd_tree",
            None,
        )

        if frame is None:
            return ""

        tree = frame.tree

        try:
            iid = tree.identify_row(
                int(float(local_y))
            )
        except Exception:
            iid = ""

        if iid:
            tree.selection_set(iid)
            tree.focus(iid)

        selected = bool(
            self._global_net_cmd_editor_selected_row()
        )
        editable = self._io_pad_check_current_passed()

        menu = tk.Menu(self, tearoff=0)

        menu.add_command(
            label="New Command...",
            state="normal" if editable else "disabled",
            command=lambda: self._global_net_open_full_editor_popup(
                "new"
            ),
        )

        menu.add_separator()

        for label, command in (
            (
                "Edit Selected...",
                lambda: self._global_net_open_full_editor_popup(
                    "selected"
                ),
            ),
            (
                "Duplicate Selected",
                self._global_net_cmd_editor_duplicate,
            ),
            (
                "Delete Selected",
                self._global_net_cmd_editor_delete_from_table,
            ),
            (
                "Move Up",
                self._global_net_move_selected_command_up,
            ),
            (
                "Move Down",
                self._global_net_move_selected_command_down,
            ),
        ):
            menu.add_command(
                label=label,
                state=(
                    "normal"
                    if editable and selected
                    else "disabled"
                ),
                command=command,
            )

        menu.add_separator()

        menu.add_command(
            label="Edit Full Generated Tcl...",
            state="normal" if editable else "disabled",
            command=self._global_net_open_generated_tcl_editor,
        )

        menu.add_separator()

        menu.add_command(
            label="Undo",
            state="normal" if editable else "disabled",
            command=self.undo_global_net_tcl,
        )
        menu.add_command(
            label="Reset",
            state="normal" if editable else "disabled",
            command=self.reset_global_net_tcl,
        )
        menu.add_command(
            label="Check Global Net",
            command=self._menu_check_global_net,
        )

        try:
            menu.tk_popup(
                int(float(root_x)),
                int(float(root_y)),
            )
        finally:
            try:
                menu.grab_release()
            except Exception:
                pass

        return ""

    def _global_net_issue_context_menu(
        self,
        root_x,
        root_y,
        local_y,
    ):
        frame = getattr(
            self,
            "global_net_page_issues",
            None,
        )

        if frame is None:
            return ""

        tree = frame.tree

        try:
            iid = tree.identify_row(
                int(float(local_y))
            )
        except Exception:
            iid = ""

        values = ()

        if iid:
            tree.selection_set(iid)
            tree.focus(iid)
            values = tree.item(
                iid,
                "values",
            ) or ()

        object_name = (
            str(values[2]).strip()
            if len(values) >= 3
            else ""
        )
        pin = (
            str(values[3]).strip()
            if len(values) >= 4
            else ""
        )

        # Multi-object issue rows are not safe for a single-configured library token edit.
        internal = ""

        if (
            object_name
            and object_name != "-"
            and "," not in object_name
        ):
            internal = self._global_net_internal_from_display_name(
                object_name
            )

        facts = (
            self.repair_facts
            if self.repair_facts
            else self.facts
        )
        fact = facts.get(internal) if internal else None

        pin_ok = bool(
            fact
            and pin in set(fact.pg_pins or [])
        )

        editable = self._io_pad_check_current_passed()

        menu = tk.Menu(self, tearoff=0)

        menu.add_command(
            label="Open Copyable Detail",
            state="normal" if iid else "disabled",
            command=lambda: self._open_issue_tree_detail(
                frame, "GLOBAL NET Issue Detail"
            ),
        )
        menu.add_command(
            label="Copy Selected Issue",
            state="normal" if iid else "disabled",
            command=lambda: self._copy_issue_tree(frame, selected_only=True),
        )
        menu.add_command(
            label="Copy All Issues",
            command=lambda: self._copy_issue_tree(frame, selected_only=False),
        )
        menu.add_separator()

        menu.add_command(
            label=_iopadt_expand_text("Edit This __IOPADT_LITERAL_001__ / Pin..."),
            state=(
                "normal"
                if editable and internal and pin_ok
                else "disabled"
            ),
            command=lambda: self._global_net_open_issue_pad_pin(
                internal,
                pin,
            ),
        )

        menu.add_command(
            label="Auto Repair Global Net...",
            state="normal" if editable else "disabled",
            command=self._global_net_auto_repair,
        )

        menu.add_separator()

        menu.add_command(
            label="Check Global Net",
            command=self._menu_check_global_net,
        )

        try:
            menu.tk_popup(
                int(float(root_x)),
                int(float(root_y)),
            )
        finally:
            try:
                menu.grab_release()
            except Exception:
                pass

        return ""

    def _global_net_open_issue_pad_pin(
        self,
        internal,
        pin,
    ):
        if not internal or not pin:
            return False

        self.global_net_repair_selected_internal = internal
        self.global_net_repair_pin.set(pin)
        self._global_net_repair_refresh()
        self._global_net_open_single_pad_dialog()
        return True

    def _install_global_net_context_bindings(self):
        """
        Right-click support for the Global Net page without Python Event objects.
        """
        bindings = []

        cmd_frame = getattr(
            self,
            "global_net_tab_all_cmd_tree",
            None,
        )

        if cmd_frame is not None:
            cmd = self.register(
                self._global_net_command_context_menu
            )
            self.global_net_context_tcl_commands.append(cmd)
            self.tk.call(
                "bind",
                cmd_frame.tree._w,
                "<Button-3>",
                f"{cmd} %X %Y %y",
            )
            bindings.append("commands")

        issue_frame = getattr(
            self,
            "global_net_page_issues",
            None,
        )

        if issue_frame is not None:
            cmd = self.register(
                self._global_net_issue_context_menu
            )
            self.global_net_context_tcl_commands.append(cmd)
            self.tk.call(
                "bind",
                issue_frame.tree._w,
                "<Button-3>",
                f"{cmd} %X %Y %y",
            )
            bindings.append("issues")

        dbg(
            "GLOBAL NET context bindings: "
            + ",".join(bindings)
        )

    def _global_net_active_parsed_rules(self):
        """Editable POWER __IOPADT_LITERAL_001__ rules only; editor scope remains unchanged."""
        rows = []
        for r in self.global_net_rules:
            if r.get("deleted"):
                continue
            parsed = self._gn_parse_connect_line(r.get("line", ""))
            if not parsed:
                continue
            row = dict(parsed)
            row.update({
                "id": r["id"],
                "added": bool(r.get("added")),
                "order": len(rows),
            })
            rows.append(row)
        return rows

    # =================================================================
    # V62 Full connect_global_net command editor
    # =================================================================

    def _gn_normalize_command_text(self, command):
        return " ".join(
            str(command or "")
            .replace("\\\r\n", " ")
            .replace("\\\n", " ")
            .split()
        )

    def _gn_logical_command_spans(self, source_text):
        source = str(source_text or "")
        physical = source.splitlines(keepends=True)
        spans = []
        offset = 0
        start_offset = 0
        start_line = 1
        buf = ""
        logical_start = None

        for idx, raw in enumerate(physical, 1):
            if logical_start is None:
                logical_start = idx
                start_line = idx
                start_offset = offset
                buf = ""

            line_noeol = raw.rstrip("\r\n")
            stripped = line_noeol.rstrip()

            if stripped.endswith("\\"):
                buf += stripped[:-1] + " "
                offset += len(raw)
                continue

            buf += line_noeol
            end_offset = offset + len(raw)
            command = buf.strip()

            if command and not command.startswith("#"):
                spans.append({
                    "start_line": start_line,
                    "end_line": idx,
                    "start": start_offset,
                    "end": end_offset,
                    "command": command,
                    "norm": self._gn_normalize_command_text(command),
                    "raw": source[start_offset:end_offset],
                })

            logical_start = None
            buf = ""
            offset = end_offset

        if logical_start is not None:
            command = buf.strip()

            if command and not command.startswith("#"):
                spans.append({
                    "start_line": start_line,
                    "end_line": len(physical),
                    "start": start_offset,
                    "end": len(source),
                    "command": command,
                    "norm": self._gn_normalize_command_text(command),
                    "raw": source[start_offset:],
                })

        return spans

    def _global_net_apply_full_cmd_edits(self, source_text):
        rendered = str(source_text or "")

        for edit in self.global_net_full_cmd_edits:
            target_norm = str(edit.get("target_norm", "") or "")

            if not target_norm:
                continue

            spans = [
                s
                for s in self._gn_logical_command_spans(rendered)
                if s["norm"] == target_norm
            ]

            if not spans:
                logging.warning(
                    "Global Net full-command overlay target missing: %s",
                    target_norm,
                )
                continue

            hint = int(edit.get("line_hint", 0) or 0)

            if hint > 0:
                target = min(
                    spans,
                    key=lambda s: abs(
                        int(s["start_line"]) - hint
                    ),
                )
            else:
                target = spans[0]

            replacement = str(edit.get("replacement", "") or "")

            if replacement and not replacement.endswith("\n"):
                replacement += "\n"

            rendered = (
                rendered[:target["start"]]
                + replacement
                + rendered[target["end"]:]
            )

        return rendered

    def _global_net_cmd_editor_clear_fields(self):
        self.global_net_cmd_net.set("")
        self.global_net_cmd_type.set("pg_pin")
        self.global_net_cmd_pin.set("")
        self.global_net_cmd_inst.set("")
        self.global_net_cmd_single.set("")
        self.global_net_cmd_hinst.set("")
        self.global_net_cmd_pd.set("")
        self.global_net_cmd_netbase.set("")
        self.global_net_cmd_region.set("")
        self.global_net_cmd_all.set(False)
        self.global_net_cmd_autotie.set(False)
        self.global_net_cmd_disconnect.set(False)
        self.global_net_cmd_netlist_override.set(False)
        self.global_net_cmd_nonhier.set(False)
        self.global_net_cmd_override.set(False)
        self.global_net_cmd_verbose.set(False)

        self._global_net_cmd_editor_clear_validation_markers()
    def _global_net_cmd_editor_new(self):
        self.global_net_cmd_editor_target = None
        self.global_net_cmd_editor_selected.set(
            "Selected Command: <NEW>"
        )
        self._global_net_cmd_editor_clear_fields()
        self._global_net_cmd_editor_update_preview()
        self.global_net_status.set(
            "Global Net Command Editor: NEW command"
        )

    def _global_net_current_instance_catalog(self):
        """
        Current final/working instance names and facts used for manual-command
        selector validation.
        """
        use_repair = bool(
            self.repair_entries
            and self.repair_facts
        )

        facts = (
            self.repair_facts
            if use_repair
            else self.facts
        )

        out = []

        for internal, fact in facts.items():
            if fact is None or not fact.found:
                continue

            display = (
                self._repair_display_name(internal)
                if use_repair
                else internal
            )

            out.append({
                "internal": internal,
                "name": str(display),
                "fact": fact,
            })

        return out

    def _global_net_known_power_domains(self):
        """
        Conservative Power Domain catalog.

        We intentionally do not invent an unsupported Innovus DB query here.
        A PD is considered known only if it already exists in the originally
        loaded active connect_global_net Tcl. This catches typos/nonexistent
        names without pretending the __IOPADT_LITERAL_001__ TSV contains domain membership.
        """
        domains = set()

        for _line_no, command in self._gn_logical_commands(
            self.global_net_original_text
        ):
            parsed = self._gn_parse_any_connect_line(
                command
            )

            if parsed is None:
                continue

            pd = str(
                parsed.get("power_domain", "")
                or ""
            ).strip()

            if pd:
                domains.add(pd)

        return domains

    def _global_net_validate_manual_command(
        self,
        line,
    ):
        """
        Pre-commit validation for manually added/updated commands.

        V82 raises field-aware errors so the editor can place a red * and a
        small red reason directly under every offending field/option.
        """
        parsed = self._gn_parse_any_connect_line(
            line
        )

        if parsed is None:
            raise GlobalNetCommandValidationError(
                "net",
                "Command is not a valid active connect_global_net command.",
            )

        catalog = (
            self._global_net_current_instance_catalog()
        )

        if not catalog:
            raise GlobalNetCommandValidationError(
                ["single", "inst", "pin"],
                _iopadt_expand_text("Cannot validate command: no current Innovus __IOPADT_LITERAL_001__/instance facts are loaded."),
            )

        single = str(
            parsed.get("single_inst", "")
            or ""
        ).strip()

        if single:
            exact = [
                row
                for row in catalog
                if (
                    row["name"] == single
                    or self._gn_instance_leaf(
                        row["name"]
                    ) == single
                )
            ]

            if not exact:
                raise GlobalNetCommandValidationError(
                    "single",
                    _iopadt_expand_text("-single_inst does not exist in the current IO/__IOPADT_LITERAL_001__ "
                    f"instance set: {single}"),
                )

        pd = str(
            parsed.get("power_domain", "")
            or ""
        ).strip()

        if pd:
            known_pd = (
                self._global_net_known_power_domains()
            )

            if pd not in known_pd:
                known_text = (
                    ", ".join(
                        sorted(known_pd)
                    )
                    if known_pd
                    else "<none found in original Global Net Tcl>"
                )

                raise GlobalNetCommandValidationError(
                    "pd",
                    "-power_domain is not a known Power Domain from the "
                    f"original loaded Global Net Tcl: {pd}. "
                    f"Known: {known_text}",
                )

        instance_matches = []

        for row in catalog:
            if self._gn_rule_matches_instance(
                parsed,
                row["name"],
                row["fact"],
            ):
                instance_matches.append(row)

        selector_fields = (
            self._global_net_cmd_editor_active_selector_fields(
                parsed
            )
        )

        has_instance_selector = bool(
            selector_fields
        )

        if (
            has_instance_selector
            and not instance_matches
        ):
            raise GlobalNetCommandValidationError(
                selector_fields,
                _iopadt_expand_text("Instance selector combination matches zero current "
                "IO/__IOPADT_LITERAL_001__ instances."),
            )

        if parsed.get("type") != "pg_pin":
            return True

        pin_pattern = str(
            parsed.get("pin", "")
            or ""
        ).strip()

        if parsed.get("all"):
            pin_matches = [
                (row, pin)
                for row in (
                    instance_matches
                    if has_instance_selector
                    else catalog
                )
                for pin in set(
                    row["fact"].pg_pins or []
                )
            ]

            if not pin_matches:
                raise GlobalNetCommandValidationError(
                    ["all"] + selector_fields,
                    _iopadt_expand_text("-all matches no actual PG pin on the selected "
                    "IO/__IOPADT_LITERAL_001__ instances."),
                )

            return True

        global_pin_matches = []

        for row in catalog:
            for pin in set(
                row["fact"].pg_pins or []
            ):
                if self._gn_rule_matches_pin(
                    parsed,
                    pin,
                ):
                    global_pin_matches.append(
                        (row, pin)
                    )

        if not global_pin_matches:
            raise GlobalNetCommandValidationError(
                "pin",
                _iopadt_expand_text("-pin_base_name matches no actual PG pin on any current "
                f"IO/__IOPADT_LITERAL_001__ instance: {pin_pattern}"),
            )

        target_rows = (
            instance_matches
            if has_instance_selector
            else catalog
        )

        actual_targets = []

        for row in target_rows:
            for pin in set(
                row["fact"].pg_pins or []
            ):
                if self._gn_rule_matches_pin(
                    parsed,
                    pin,
                ):
                    actual_targets.append(
                        (row["name"], pin)
                    )

        if not actual_targets:
            raise GlobalNetCommandValidationError(
                ["pin"] + selector_fields,
                _iopadt_expand_text("The command selector combination matches zero actual "
                "IO/__IOPADT_LITERAL_001__ PG-pin targets."),
            )

        return True

    def _global_net_cmd_editor_clear_validation_markers(self):
        widgets = getattr(
            self,
            "global_net_cmd_validation_widgets",
            {},
        )

        for item in widgets.values():
            try:
                item["error_var"].set("")
            except Exception:
                pass

            try:
                item["star"].grid_remove()
            except Exception:
                try:
                    item["star"].pack_forget()
                except Exception:
                    pass

    def _global_net_cmd_editor_show_validation_error(
        self,
        exc,
    ):
        widgets = getattr(
            self,
            "global_net_cmd_validation_widgets",
            {},
        )

        if not widgets:
            return

        self._global_net_cmd_editor_clear_validation_markers()

        if isinstance(
            exc,
            GlobalNetCommandValidationError,
        ):
            fields = list(exc.fields)
            message = exc.message
        else:
            message = str(exc) or type(exc).__name__
            fields = []

            # Fallback mapping for errors raised by lower-level Tcl builders.
            low = message.lower()

            if "region requires" in low:
                fields = ["region"]
            elif "global net name is required" in low:
                fields = ["net"]
            elif "pg_pin requires pin base" in low:
                fields = ["pin"]

        if not fields:
            fields = ["net"]

        for field in fields:
            item = widgets.get(field)

            if item is None:
                continue

            try:
                item["error_var"].set(
                    message
                )
            except Exception:
                pass

            try:
                item["star"].grid()
            except Exception:
                try:
                    item["star"].pack(
                        side="left",
                        padx=(3,0),
                    )
                except Exception:
                    pass

    def _global_net_cmd_editor_active_selector_fields(
        self,
        parsed,
    ):
        fields = []

        if str(
            parsed.get("single_inst", "")
            or ""
        ).strip():
            fields.append("single")

        if str(
            parsed.get("inst", "")
            or ""
        ).strip():
            fields.append("inst")

        if str(
            parsed.get("hinst", "")
            or ""
        ).strip():
            fields.append("hinst")

        if str(
            parsed.get("region", "")
            or ""
        ).strip():
            fields.append("region")

        if parsed.get("non_hierarchical"):
            fields.append("nonhier")

        return fields

    def _global_net_cmd_editor_build_line(self):
        self._global_net_cmd_editor_clear_validation_markers()

        try:
            net = self.global_net_cmd_net.get().strip()
            rule_type = self.global_net_cmd_type.get().strip()
            pin = self.global_net_cmd_pin.get().strip()

            if (
                not net
                and not self.global_net_cmd_disconnect.get()
            ):
                raise GlobalNetCommandValidationError(
                    "net",
                    "Global Net Name is required unless -disconnect is enabled.",
                )

            if (
                rule_type == "pg_pin"
                and not pin
                and not self.global_net_cmd_all.get()
            ):
                raise GlobalNetCommandValidationError(
                    ["pin", "all"],
                    "pg_pin requires Pin Base Name, or enable -all.",
                )

            region = (
                self.global_net_cmd_region.get().strip()
            )

            if region:
                nums = self._gn_numbers(
                    region
                )

                if len(nums) != 4:
                    raise GlobalNetCommandValidationError(
                        "region",
                        "Region requires exactly four numbers: x1 y1 x2 y2.",
                    )

            line = self._gn_build_command(
                net=net,
                rule_type=rule_type,
                pin=pin,
                inst_base_name=self.global_net_cmd_inst.get().strip(),
                single_inst=self.global_net_cmd_single.get().strip(),
                hinst=self.global_net_cmd_hinst.get().strip(),
                power_domain=self.global_net_cmd_pd.get().strip(),
                net_base_name=self.global_net_cmd_netbase.get().strip(),
                region=region,
                all_flag=self.global_net_cmd_all.get(),
                auto_tie=self.global_net_cmd_autotie.get(),
                disconnect=self.global_net_cmd_disconnect.get(),
                netlist_override=self.global_net_cmd_netlist_override.get(),
                non_hierarchical=self.global_net_cmd_nonhier.get(),
                override=self.global_net_cmd_override.get(),
                verbose=self.global_net_cmd_verbose.get(),
            )

            self._global_net_validate_manual_command(
                line
            )

            self._global_net_cmd_editor_clear_validation_markers()
            return line

        except Exception as exc:
            self._global_net_cmd_editor_show_validation_error(
                exc
            )
            raise

    def _global_net_cmd_editor_update_preview(self):
        """
        Build preview only. Never mutate/clear user fields and never raise
        into Tk's event loop.
        """
        try:
            line = self._global_net_cmd_editor_build_line()
            self.global_net_cmd_editor_preview.set(line.strip())
            self.global_net_status.set(
                "Global Net Command Preview: PASS"
            )
            return True
        except Exception as exc:
            msg = str(exc) or type(exc).__name__
            self.global_net_cmd_editor_preview.set(
                "<PREVIEW FAILED> " + msg
            )
            self.global_net_status.set(
                "Global Net Command Preview failed: " + msg
            )
            return False

    def _global_net_cmd_editor_load_row(self, row):
        if not row:
            self._global_net_cmd_editor_new()
            return

        self.global_net_cmd_editor_target = {
            "id": row.get("id", ""),
            "line": int(row.get("line", 0) or 0),
            "command": row.get("command", ""),
            "norm": self._gn_normalize_command_text(
                row.get("command", "")
            ),
        }

        self.global_net_cmd_editor_selected.set(
            "Selected Command: "
            + str(row.get("id", ""))
            + " | line="
            + str(row.get("line", "-"))
        )

        self.global_net_cmd_net.set(str(row.get("net", "") or ""))
        self.global_net_cmd_type.set(
            str(row.get("type", "pg_pin") or "pg_pin")
        )
        self.global_net_cmd_pin.set(str(row.get("pin", "") or ""))
        self.global_net_cmd_inst.set(str(row.get("inst", "") or ""))
        self.global_net_cmd_single.set(
            str(row.get("single_inst", "") or "")
        )
        self.global_net_cmd_hinst.set(
            str(row.get("hinst", "") or "")
        )
        self.global_net_cmd_pd.set(
            str(row.get("power_domain", "") or "")
        )
        self.global_net_cmd_netbase.set(
            str(row.get("net_base_name", "") or "")
        )
        self.global_net_cmd_region.set(
            str(row.get("region", "") or "")
        )
        self.global_net_cmd_all.set(bool(row.get("all")))
        self.global_net_cmd_autotie.set(bool(row.get("auto_tie")))
        self.global_net_cmd_disconnect.set(bool(row.get("disconnect")))
        self.global_net_cmd_netlist_override.set(
            bool(row.get("netlist_override"))
        )
        self.global_net_cmd_nonhier.set(
            bool(row.get("non_hierarchical"))
        )
        self.global_net_cmd_override.set(bool(row.get("override")))
        self.global_net_cmd_verbose.set(bool(row.get("verbose")))

        self._global_net_cmd_editor_clear_validation_markers()
        self._global_net_cmd_editor_update_preview()
        self.global_net_status.set(
            "Loaded full connect_global_net command into editor."
        )

    def _global_net_cmd_editor_selected_row(self):
        tree = getattr(
            self,
            "global_net_tab_all_cmd_tree",
            None,
        )

        if tree is None:
            return None

        try:
            selection = tree.selection()
        except Exception:
            return None

        if not selection:
            return None

        iid = selection[0]
        row = self.global_net_all_cmd_cache.get(iid)

        if row is not None:
            return row

        for r in self._global_net_all_commands():
            if r.get("id") == iid:
                return r

        return None

    def _global_net_cmd_editor_load_selected(self):
        row = self._global_net_cmd_editor_selected_row()

        if row is None:
            self.global_net_status.set(
                "Select one command in All ACTIVE connect_global_net Commands."
            )
            return

        self._global_net_cmd_editor_load_row(row)

    def _global_net_cmd_editor_add(self):
        """Return True only if a command was actually added."""
        if not self.global_net_path:
            self.global_net_status.set(
                "Load Global Net Tcl first."
            )
            return False
        try:
            line = self._global_net_cmd_editor_build_line()
            rid = self._global_net_append_gui_command(
                line,
                "GN_FULL_CMD_EDITOR_ADD",
            )
            self.global_net_cmd_editor_target = None
            self.global_net_cmd_editor_selected.set(
                f"Added Command: {rid}"
            )
            self.global_net_cmd_editor_preview.set(line.strip())
            self.global_net_status.set(
                f"Added full command {rid} (in memory)"
            )
            return True
        except Exception as exc:
            msg = str(exc) or type(exc).__name__
            self.global_net_status.set(
                "Add Global Net Command failed: " + msg
            )
            self.global_net_cmd_editor_preview.set(
                "<ADD FAILED> " + msg
            )
            return False

    def _global_net_cmd_editor_add_overlay(
        self,
        replacement,
        action,
    ):
        target = self.global_net_cmd_editor_target

        if not target:
            raise ValueError(
                "Load one existing command first."
            )

        self._global_net_push_undo(action)
        self.global_net_full_cmd_edit_seq += 1
        self.global_net_full_cmd_edits.append({
            "id": f"GNCMD{self.global_net_full_cmd_edit_seq:04d}",
            "target_norm": str(target.get("norm", "") or ""),
            "line_hint": int(target.get("line", 0) or 0),
            "replacement": str(replacement or ""),
        })

    def _global_net_cmd_editor_update(self):
        if not self._require_io_pad_pass_for_global_net_edit():
            return False

        """Return True only after a successful update overlay."""
        try:
            line = self._global_net_cmd_editor_build_line()
            target = self.global_net_cmd_editor_target
            if not target:
                raise ValueError(
                    "Select and Load an existing command before Update."
                )
            old_id = target.get("id", "")
            self._global_net_cmd_editor_add_overlay(
                line,
                "Update full connect_global_net command",
            )
            self.global_net_cmd_editor_target = None
            self.global_net_cmd_editor_selected.set(
                f"Updated Command: {old_id}"
            )
            self._global_net_mark_check_stale(
                "command updated"
            )
            self._global_net_refresh_tree()
            self._global_net_repair_refresh()
            self.global_net_cmd_editor_preview.set(line.strip())
            self.global_net_status.set(
                f"Updated {old_id} (in memory)"
            )
            return True
        except Exception as exc:
            msg = str(exc) or type(exc).__name__
            self.global_net_status.set(
                "Update Global Net Command failed: " + msg
            )
            self.global_net_cmd_editor_preview.set(
                "<UPDATE FAILED> " + msg
            )
            return False

    def _global_net_cmd_editor_duplicate(self):
        row = self._global_net_cmd_editor_selected_row()
        if row is None and self.global_net_cmd_editor_target:
            row = {
                "command": self.global_net_cmd_editor_target.get(
                    "command", ""
                )
            }
        if row is None:
            self.global_net_status.set(
                "Duplicate failed: select one command first."
            )
            return False
        command = str(row.get("command", "") or "").strip()
        if not command:
            self.global_net_status.set(
                "Duplicate failed: selected command is empty."
            )
            return False
        try:
            rid = self._global_net_append_gui_command(
                command + "\\n",
                "GN_FULL_CMD_EDITOR_DUPLICATE",
            )
            self.global_net_status.set(
                f"Duplicated command as {rid}."
            )
            return True
        except Exception as exc:
            msg = str(exc) or type(exc).__name__
            self.global_net_status.set(
                "Duplicate Global Net Command failed: " + msg
            )
            return False

    def _global_net_cmd_editor_delete(
        self,
        prefer_table_selection=False,
    ):
        if not self._require_io_pad_pass_for_global_net_edit():
            return False

        """
        Main-tab deletion always uses the CURRENT All Commands selection.
        Popup deletion uses its loaded popup target.
        Effective Tcl is verified before success is reported.
        """
        if prefer_table_selection:
            row = self._global_net_cmd_editor_selected_row()

            if row is None:
                self.global_net_status.set(
                    "Delete failed: select one command in All Commands first."
                )
                return False

            self._global_net_cmd_editor_load_row(row)

        target = self.global_net_cmd_editor_target

        if target is None:
            row = self._global_net_cmd_editor_selected_row()

            if row is not None:
                self._global_net_cmd_editor_load_row(row)
                target = self.global_net_cmd_editor_target

        if not target:
            self.global_net_status.set(
                "Delete failed: select/load a command first."
            )
            return False

        target_norm = str(
            target.get("norm", "") or ""
        )

        before_count = sum(
            1
            for r in self._global_net_all_commands()
            if self._gn_normalize_command_text(
                r.get("command", "")
            ) == target_norm
        )

        if before_count <= 0:
            self.global_net_status.set(
                "Delete failed: selected command is no longer active."
            )
            return False

        old_overlay_len = len(
            self.global_net_full_cmd_edits
        )
        old_undo_len = len(
            self.global_net_undo_stack
        )
        old_seq = self.global_net_full_cmd_edit_seq
        old_target = copy.deepcopy(
            self.global_net_cmd_editor_target
        )

        try:
            old_id = target.get("id", "")

            self._global_net_cmd_editor_add_overlay(
                "",
                "Delete full connect_global_net command",
            )

            after_count = sum(
                1
                for r in self._global_net_all_commands()
                if self._gn_normalize_command_text(
                    r.get("command", "")
                ) == target_norm
            )

            if after_count != before_count - 1:
                raise RuntimeError(
                    "effective Tcl verification failed: "
                    f"{before_count}->{after_count}"
                )

            self.global_net_cmd_editor_target = None
            self.global_net_cmd_editor_selected.set(
                f"Deleted Command: {old_id}"
            )

            self._global_net_mark_check_stale(
                "command deleted"
            )
            self._global_net_refresh_tree()
            self._global_net_repair_refresh()

            self.global_net_status.set(
                f"Deleted {old_id} from effective Global Net Tcl."
            )
            return True

        except Exception as exc:
            self.global_net_full_cmd_edits = (
                self.global_net_full_cmd_edits[
                    :old_overlay_len
                ]
            )
            self.global_net_undo_stack = (
                self.global_net_undo_stack[
                    :old_undo_len
                ]
            )
            self.global_net_full_cmd_edit_seq = old_seq
            self.global_net_cmd_editor_target = old_target
            self._global_net_update_history_text()

            self.global_net_status.set(
                "Delete Global Net Command failed: "
                + (str(exc) or type(exc).__name__)
            )
            return False

    def _global_net_cmd_editor_delete_from_table(self):
        return self._global_net_cmd_editor_delete(
            prefer_table_selection=True,
        )


    def _global_net_cmd_editor_recheck(self):
        return self._menu_check_global_net()


    def _global_net_editor_selection_changed(self):
        row = self._global_net_cmd_editor_selected_row()

        if row is not None:
            self._global_net_cmd_editor_load_row(row)

        return ""

    def _global_net_install_editor_tree_binding(self, tree):
        if tree is None:
            return

        def callback():
            return self._global_net_editor_selection_changed()

        cmd = self.register(callback)
        self.global_net_editor_tcl_commands.append(cmd)
        self.tk.call(
            "bind",
            tree.tree._w,
            "<<TreeviewSelect>>",
            cmd,
        )

    def _global_net_close_full_editor_popup(self):
        win = self.global_net_full_editor_window

        if win is None:
            return

        try:
            if win.winfo_exists():
                win.destroy()
        except Exception:
            pass

        self.global_net_full_editor_window = None
        self.global_net_cmd_validation_widgets = {}

