    def _global_net_full_editor_commit_add(self):
        """Add and keep all current fields/options on both success/failure."""
        success = self._global_net_cmd_editor_add()
        if success:
            self.global_net_status.set(
                self.global_net_status.get()
                + " | Input preserved for next command."
            )
        return success

    def _global_net_full_editor_commit_update(self):
        success = self._global_net_cmd_editor_update()
        if success:
            self._global_net_close_full_editor_popup()
        return success

    def _global_net_full_editor_commit_duplicate(self):
        success = self._global_net_cmd_editor_duplicate()
        if success:
            self._global_net_close_full_editor_popup()
        return success

    def _global_net_full_editor_commit_delete(self):
        success = self._global_net_cmd_editor_delete()
        if success:
            self._global_net_close_full_editor_popup()
        return success

    # =================================================================
    # V73 final generated-Tcl editor / ordering / validation
    # =================================================================

    def _global_net_commit_full_text(
        self,
        new_text,
        action,
    ):
        """
        Rebase the Global Net working copy onto an explicitly edited/reordered
        final Tcl text while preserving the originally-loaded baseline for
        Reset and new-net detection.
        """
        if not self._require_io_pad_pass_for_global_net_edit(
            interactive=False,
        ):
            raise PermissionError(
                _iopadt_expand_text("IO __IOPADT_LITERAL_001__ Check must be current PASS before Global Net edit.")
            )

        if not self.global_net_path:
            raise ValueError(
                "Load Global Net Tcl before editing generated Tcl."
            )

        new_text = str(new_text or "")

        if new_text and not new_text.endswith("\n"):
            new_text += "\n"

        current = self._render_global_net_text()

        if new_text == current:
            return False

        self._global_net_push_undo(action)

        self.global_net_lines = new_text.splitlines(
            keepends=True
        )
        self.global_net_full_cmd_edits = []
        self.global_net_full_cmd_edit_seq = 0
        self.global_net_cmd_editor_target = None
        self.global_net_selected_id = ""

        # Re-detect the compact editable subset from the newly authoritative
        # working text. All-command views always parse the full logical Tcl.
        self._global_net_detect_rules()

        self._global_net_mark_check_stale(
            "generated Tcl working copy changed"
        )
        self._global_net_refresh_tree()
        self._global_net_repair_refresh()

        self.global_net_status.set(
            f"{action}: applied to Global Net working copy."
        )
        return True

    def _global_net_connect_spans(self, source_text):
        """
        Active connect_global_net logical-command spans only.
        """
        out = []

        for span in self._gn_logical_command_spans(
            source_text
        ):
            parsed = self._gn_parse_any_connect_line(
                span["command"]
            )

            if parsed is None:
                continue

            row = dict(span)
            row["parsed"] = parsed
            out.append(row)

        return out

    def _global_net_move_selected_command(
        self,
        delta,
    ):
        """
        Move the selected active connect_global_net command one position Up or
        Down in the final generated Tcl.

        Non-connect_global_net text between the two commands remains exactly in
        place; only the two logical command blocks exchange positions.
        """
        row = self._global_net_cmd_editor_selected_row()

        if row is None:
            self.global_net_status.set(
                "Move command failed: select one command first."
            )
            return False

        source = self._render_global_net_text()
        spans = self._global_net_connect_spans(source)

        if not spans:
            self.global_net_status.set(
                "Move command failed: no active connect_global_net command."
            )
            return False

        target_norm = self._gn_normalize_command_text(
            row.get("command", "")
        )
        line_hint = int(row.get("line", 0) or 0)

        matches = [
            (idx, span)
            for idx, span in enumerate(spans)
            if span["norm"] == target_norm
        ]

        if not matches:
            self.global_net_status.set(
                "Move command failed: selected command is no longer active."
            )
            return False

        if line_hint > 0:
            idx, selected = min(
                matches,
                key=lambda item: abs(
                    int(item[1]["start_line"])
                    - line_hint
                ),
            )
        else:
            idx, selected = matches[0]

        next_idx = idx + int(delta)

        if next_idx < 0 or next_idx >= len(spans):
            self.global_net_status.set(
                "Move command: already at requested boundary."
            )
            return False

        other = spans[next_idx]

        first, second = (
            (other, selected)
            if other["start"] < selected["start"]
            else (selected, other)
        )

        middle = source[
            first["end"]:
            second["start"]
        ]

        swapped = (
            source[:first["start"]]
            + second["raw"]
            + middle
            + first["raw"]
            + source[second["end"]:]
        )

        direction = "Up" if int(delta) < 0 else "Down"

        changed = self._global_net_commit_full_text(
            swapped,
            f"Move Global Net Command {direction}",
        )

        if changed:
            self.global_net_status.set(
                f"Moved selected connect_global_net command {direction}."
            )

        return changed

    def _global_net_move_selected_command_up(self):
        return self._global_net_move_selected_command(-1)

    def _global_net_move_selected_command_down(self):
        return self._global_net_move_selected_command(1)

    def _global_net_final_rules_from_text(
        self,
        source_text,
    ):
        rows = []

        for order, (line_no, command) in enumerate(
            self._gn_logical_commands(
                str(source_text or "")
            )
        ):
            parsed = self._gn_parse_connect_line(
                command
            )

            if parsed is None:
                continue

            if parsed.get("disconnect"):
                continue

            row = dict(parsed)
            row.update({
                "id": f"FINAL_L{line_no}_{order}",
                "line": line_no,
                "order": order,
                "command": command,
            })
            rows.append(row)

        return rows

    def _global_net_validate_final_tcl_text(
        self,
        source_text,
    ):
        """
        Final Save gate for overlapping actual __IOPADT_LITERAL_001__/PG-pin targets.

        For every actual ring instance + actual PG pin, run the same scope
        selection used by the Global Net checker. If more than one active
        pg_pin command targets the selected effective scope:

          later overlap without -override/-netlist_override -> ERROR
          later overlap with    -override/-netlist_override -> WARNING

        Any ERROR blocks all Save artifact generation.
        WARNING is allowed after user acknowledgement.
        """
        use_repair = bool(
            self.repair_entries
            and self.repair_facts
        )

        entries = (
            self.repair_entries
            if use_repair
            else (
                self.physical_ring
                or self.entries
            )
        )
        facts = (
            self.repair_facts
            if use_repair
            else self.facts
        )
        display = (
            self._repair_display_name
            if use_repair
            else (lambda x: x)
        )

        if not entries or not facts:
            return {
                "errors": [{
                    "issue": "TARGET_VALIDATION_UNAVAILABLE",
                    "instance": "-",
                    "pin": "-",
                    "scope": "-",
                    "line": "-",
                    "detail": (
                        "Load CHIP.io and Innovus TSV before Save so final "
                        "connect_global_net targets can be validated."
                    ),
                }],
                "warnings": [],
                "checked_targets": 0,
                "rules": 0,
            }

        rules = self._global_net_final_rules_from_text(
            source_text
        )
        io_pd_info = self._global_net_find_io_power_domain(
            rules
        )

        errors = []
        warnings = []
        seen_error = set()
        seen_warning = set()
        checked_targets = 0

        for entry in entries:
            fact = facts.get(entry.name)

            if fact is None or not fact.found:
                continue

            final_name = display(entry.name)

            for pin in sorted(
                set(fact.pg_pins or [])
            ):
                checked_targets += 1

                selected = self._gn_select_rules_for_ring_pin(
                    rules,
                    final_name,
                    pin,
                    io_pd_info,
                    fact,
                )

                candidates = list(
                    selected.get("rules", [])
                )

                if len(candidates) <= 1:
                    continue

                # Candidate list preserves Tcl order.
                for idx in range(1, len(candidates)):
                    previous = candidates[idx - 1]
                    current = candidates[idx]

                    has_override = bool(
                        current.get("override")
                        or current.get(
                            "netlist_override"
                        )
                    )

                    key = (
                        final_name,
                        pin,
                        selected.get("scope", ""),
                        int(previous.get("line", 0) or 0),
                        int(current.get("line", 0) or 0),
                    )

                    record = {
                        "issue": (
                            "TARGET_OVERLAP_OVERRIDE"
                            if has_override
                            else "TARGET_OVERLAP"
                        ),
                        "instance": final_name,
                        "pin": pin,
                        "scope": selected.get(
                            "scope",
                            "-",
                        ),
                        "line": (
                            f"{previous.get('line', '?')}"
                            " -> "
                            f"{current.get('line', '?')}"
                        ),
                        "previous_net": str(
                            previous.get("net", "") or ""
                        ),
                        "current_net": str(
                            current.get("net", "") or ""
                        ),
                        "previous_command": str(
                            previous.get(
                                "command",
                                "",
                            )
                        ),
                        "current_command": str(
                            current.get(
                                "command",
                                "",
                            )
                        ),
                        "detail": (
                            "Same actual target is matched by more than one "
                            "active pg_pin command. "
                            + (
                                "Later command has override; Save is allowed "
                                "with WARNING."
                                if has_override
                                else "Later command has no override; Save is blocked."
                            )
                        ),
                    }

                    if has_override:
                        if key not in seen_warning:
                            seen_warning.add(key)
                            warnings.append(record)
                    else:
                        if key not in seen_error:
                            seen_error.add(key)
                            errors.append(record)

        return {
            "errors": errors,
            "warnings": warnings,
            "checked_targets": checked_targets,
            "rules": len(rules),
        }

    def _global_net_final_validation_text(
        self,
        validation,
    ):
        lines = [
            "configured Library FINAL GLOBAL NET TCL VALIDATION",
            "",
            f"Rules={validation.get('rules', 0)}",
            f"ActualTargetsChecked={validation.get('checked_targets', 0)}",
            f"ERROR={len(validation.get('errors', []))}",
            f"WARNING={len(validation.get('warnings', []))}",
            "",
        ]

        if validation.get("errors"):
            lines.append("ERRORS")
            lines.append("-" * 72)

            for item in validation["errors"]:
                lines += [
                    (
                        f"{item.get('issue')} | "
                        f"{item.get('instance')}.{item.get('pin')} | "
                        f"{item.get('scope')} | lines={item.get('line')}"
                    ),
                    "  " + item.get("detail", ""),
                    (
                        "  Previous: "
                        + item.get(
                            "previous_command",
                            "-",
                        )
                    ),
                    (
                        "  Current : "
                        + item.get(
                            "current_command",
                            "-",
                        )
                    ),
                ]

            lines.append("")

        if validation.get("warnings"):
            lines.append("WARNINGS")
            lines.append("-" * 72)

            for item in validation["warnings"]:
                lines += [
                    (
                        f"{item.get('issue')} | "
                        f"{item.get('instance')}.{item.get('pin')} | "
                        f"{item.get('scope')} | lines={item.get('line')}"
                    ),
                    "  " + item.get("detail", ""),
                    (
                        "  Previous: "
                        + item.get(
                            "previous_command",
                            "-",
                        )
                    ),
                    (
                        "  Current : "
                        + item.get(
                            "current_command",
                            "-",
                        )
                    ),
                ]

        if (
            not validation.get("errors")
            and not validation.get("warnings")
        ):
            lines += [
                "PASS",
                _iopadt_expand_text("No overlapping actual __IOPADT_LITERAL_001__ / PG-pin target was found."),
            ]

        return "\n".join(lines)

    def _global_net_final_text_signature(
        self,
        source_text,
    ):
        """
        Stable signature for the exact Global Net Tcl text checked by V77.
        """
        import hashlib

        return hashlib.sha256(
            str(source_text or "").encode("utf-8")
        ).hexdigest()

    def _global_net_companion_validation(
        self,
        source_text,
    ):
        """
        Validate everything required to generate the V128.6 bound create-net / skip-routing patch before Save.

        This catches errors that previously appeared only after the Save dialog.
        """
        errors = []
        warnings = []

        try:
            original_nets = (
                self._global_net_original_net_names()
            )
            effective_nets = (
                self._global_net_net_names_from_text(
                    source_text
                )
            )
            new_nets = sorted(
                effective_nets - original_nets
            )
        except Exception as exc:
            return {
                "errors": [{
                    "issue": "NEW_NET_DISCOVERY_ERROR",
                    "net": "-",
                    "detail": str(exc),
                }],
                "warnings": [],
                "new_nets": [],
                "create_text": "",
            }

        safe_nets = []

        for net in new_nets:
            try:
                safe_nets.append(
                    self._global_net_tcl_safe_object_name(
                        net
                    )
                )
            except Exception as exc:
                errors.append({
                    "issue": "CREATE_NET_NAME_INVALID",
                    "net": str(net),
                    "detail": str(exc),
                })

        create_text = ""

        if not errors:
            try:
                create_text = (
                    self._render_create_net_skip_route_tcl(
                        safe_nets, source_text=source_text
                    )
                )
            except Exception as exc:
                errors.append({
                    "issue": "CREATE_NET_TCL_GENERATION_ERROR",
                    "net": ",".join(safe_nets) or "-",
                    "detail": str(exc),
                })

        return {
            "errors": errors,
            "warnings": warnings,
            "new_nets": new_nets,
            "create_text": create_text,
        }

    def _global_net_check_save_readiness(
        self,
        source_text,
    ):
        """
        One shared Save-readiness validator used by normal Global Net Check.

        The result is cached inside global_net_last_check_result so all
        Save-blocking Tcl errors are already visible in Issues before Save.
        """
        final_validation = (
            self._global_net_validate_final_tcl_text(
                source_text
            )
        )
        companion = (
            self._global_net_companion_validation(
                source_text
            )
        )

        errors = []
        warnings = []

        for item in final_validation.get(
            "errors",
            [],
        ):
            row = dict(item)
            row["source"] = "FINAL_TCL"
            errors.append(row)

        for item in final_validation.get(
            "warnings",
            [],
        ):
            row = dict(item)
            row["source"] = "FINAL_TCL"
            warnings.append(row)

        for item in companion.get(
            "errors",
            [],
        ):
            row = dict(item)
            row["source"] = "GLOBAL_NET_BOUND_PATCH"
            errors.append(row)

        for item in companion.get(
            "warnings",
            [],
        ):
            row = dict(item)
            row["source"] = "GLOBAL_NET_BOUND_PATCH"
            warnings.append(row)

        return {
            "errors": errors,
            "warnings": warnings,
            "error_count": len(errors),
            "warning_count": len(warnings),
            "final_validation": final_validation,
            "companion_validation": companion,
            "new_nets": list(
                companion.get("new_nets", [])
            ),
            "create_text": str(
                companion.get("create_text", "")
            ),
            "text_signature": (
                self._global_net_final_text_signature(
                    source_text
                )
            ),
        }

    def _global_net_validate_generated_preview(
        self,
        source_text=None,
        parent=None,
        interactive=True,
    ):
        if source_text is None:
            source_text = self._render_global_net_text()

        validation = (
            self._global_net_validate_final_tcl_text(
                source_text
            )
        )
        report = self._global_net_final_validation_text(
            validation
        )

        if validation["errors"]:
            self.global_net_status.set(
                "Final Tcl Validation: ERROR "
                f"{len(validation['errors'])}; Save blocked."
            )

            if interactive:
                self._show_copyable_error(
                    "Final Global Net Tcl Validation - ERROR",
                    report[:12000],
                    parent=parent,
                )

            return False, validation, report

        if validation["warnings"]:
            self.global_net_status.set(
                "Final Tcl Validation: WARNING "
                f"{len(validation['warnings'])}; override overlap present."
            )

            if interactive:
                proceed = self._ask_copyable_yesno(
                    "Final Global Net Tcl Validation - WARNING",
                    report[:12000]
                    + "\n\nContinue with this override-based Tcl?",
                    parent=parent,
                )

                if not proceed:
                    return False, validation, report

            return True, validation, report

        self.global_net_status.set(
            "Final Tcl Validation: PASS"
        )

        if interactive:
            self._show_copyable_info(
                "Final Global Net Tcl Validation",
                report,
                parent=parent,
            )

        return True, validation, report

    def _global_net_open_generated_tcl_editor(self):
        if not self._require_io_pad_pass_for_global_net_edit():
            return

        if not self.global_net_path:
            self._show_copyable_warning(
                "Edit Generated Global Net Tcl",
                "Load Global Net Tcl first.",
            )
            return

        old = self.global_net_generated_tcl_window

        try:
            if old is not None and old.winfo_exists():
                # Do not silently show an old generated Tcl snapshot. If the
                # editor has no uncommitted manual text, re-sync it immediately
                # to the canonical source used by Apply/Save/Export.
                editor = self.global_net_generated_tcl_text
                if editor is not None:
                    if bool(editor.edit_modified()):
                        self.global_net_generated_tcl_status.set(
                            "Generated Tcl Preview: MANUAL EDITS PENDING; Apply/Save use the working model until you press Apply/OK here."
                        )
                    else:
                        art = self._global_net_canonical_artifacts()
                        editor.delete("1.0", "end")
                        editor.insert("1.0", art["source_tcl"])
                        editor.edit_modified(False)
                        self.global_net_generated_tcl_status.set(
                            "Generated Tcl Preview: SYNCED canonical sha256=" + art["source_sha256"]
                        )
                old.lift()
                old.focus_force()
                return
        except Exception:
            pass

        win = self._safe_toplevel(
            "Generated Global Net Tcl - Final Preview Editor"
        )
        self.global_net_generated_tcl_window = win
        win.geometry("1120x780")
        win.minsize(800, 560)

        shell = ttk.Frame(win, padding=10)
        shell.pack(fill="both", expand=True)
        shell.rowconfigure(1, weight=1)
        shell.columnconfigure(0, weight=1)

        ttk.Label(
            shell,
            text=(
                "Canonical Global Net source Tcl. Save/Export use this exact text; "
                "Apply Global Net embeds this exact source block unchanged and only adds an execution wrapper."
            ),
            font=("Segoe UI", 9, "bold"),
        ).grid(
            row=0,
            column=0,
            sticky="ew",
            pady=(0, 6),
        )

        text_shell = ttk.Frame(shell)
        text_shell.grid(
            row=1,
            column=0,
            sticky="nsew",
        )
        text_shell.rowconfigure(0, weight=1)
        text_shell.columnconfigure(0, weight=1)

        editor = tk.Text(
            text_shell,
            wrap="none",
            undo=True,
            font=("Consolas", 9),
        )
        sy = ttk.Scrollbar(
            text_shell,
            orient="vertical",
            command=editor.yview,
        )
        sx = ttk.Scrollbar(
            text_shell,
            orient="horizontal",
            command=editor.xview,
        )
        editor.configure(
            yscrollcommand=sy.set,
            xscrollcommand=sx.set,
        )

        editor.grid(
            row=0,
            column=0,
            sticky="nsew",
        )
        sy.grid(
            row=0,
            column=1,
            sticky="ns",
        )
        sx.grid(
            row=1,
            column=0,
            sticky="ew",
        )

        initial_art = self._global_net_canonical_artifacts()
        editor.insert(
            "1.0",
            initial_art["source_tcl"],
        )
        editor.edit_modified(False)
        self.global_net_generated_tcl_status.set(
            "Generated Tcl Preview: SYNCED canonical sha256=" + initial_art["source_sha256"]
        )
        self.global_net_generated_tcl_text = editor

        action = ttk.Frame(shell)
        action.grid(
            row=2,
            column=0,
            sticky="ew",
            pady=(8, 0),
        )

        def reload_preview():
            art = self._global_net_canonical_artifacts()
            editor.delete("1.0", "end")
            editor.insert("1.0", art["source_tcl"])
            editor.edit_modified(False)
            self.global_net_generated_tcl_status.set(
                "Generated Tcl Preview: SYNCED canonical sha256=" + art["source_sha256"]
            )

        def validate_preview():
            content = editor.get(
                "1.0",
                "end-1c",
            )
            ok, validation, _report = (
                self._global_net_validate_generated_preview(
                    content,
                    parent=win,
                    interactive=True,
                )
            )
            self.global_net_generated_tcl_status.set(
                "Generated Tcl Preview: "
                + (
                    "PASS"
                    if (
                        ok
                        and not validation["warnings"]
                    )
                    else (
                        "WARNING"
                        if (
                            ok
                            and validation["warnings"]
                        )
                        else "ERROR"
                    )
                )
            )

        def apply_preview():
            content = editor.get(
                "1.0",
                "end-1c",
            )
            changed = self._global_net_commit_full_text(
                content,
                "Edit Generated Global Net Tcl",
            )

            if changed:
                # Re-render after commit so managed patch / exact overrides are
                # normalized by the same canonical renderer used by Apply.
                art = self._global_net_canonical_artifacts()
                editor.delete("1.0", "end")
                editor.insert("1.0", art["source_tcl"])
                editor.edit_modified(False)
                self.global_net_generated_tcl_status.set(
                    "Generated Tcl Preview: APPLIED + SYNCED canonical sha256=" + art["source_sha256"]
                )
            else:
                editor.edit_modified(False)
                self.global_net_generated_tcl_status.set(
                    "Generated Tcl Preview: no text change"
                )

        def close_editor():
            self.global_net_generated_tcl_text = None
            self.global_net_generated_tcl_window = None
            win.destroy()

        ttk.Button(
            action,
            text="Reload Current Preview",
            command=reload_preview,
        ).pack(side="left")

        ttk.Button(
            action,
            text="Validate",
            command=validate_preview,
        ).pack(side="left", padx=(5, 0))

        def copy_apply_payload():
            try:
                art = self._global_net_canonical_artifacts()
                self.clipboard_clear()
                self.clipboard_append(art["apply_tcl"])
                self.global_net_generated_tcl_status.set(
                    "Exact Apply payload copied | canonical sha256=" + art["source_sha256"]
                )
            except Exception as exc:
                self._show_copyable_error("Copy Exact Apply Payload", str(exc), parent=win)

        ttk.Button(
            action,
            text="Copy Exact Apply Payload",
            command=copy_apply_payload,
        ).pack(side="left", padx=(5, 0))

        ttk.Button(
            action,
            text="Apply",
            command=apply_preview,
        ).pack(side="left", padx=(5, 0))

        def ok_preview():
            apply_preview()
            close_editor()

        ttk.Button(
            action,
            text="OK",
            command=ok_preview,
        ).pack(side="left", padx=(5, 0))

        ttk.Button(
            action,
            text="Close",
            command=close_editor,
        ).pack(side="right")

        ttk.Label(
            shell,
            textvariable=self.global_net_generated_tcl_status,
        ).grid(
            row=3,
            column=0,
            sticky="ew",
            pady=(6, 0),
        )

        win.protocol(
            "WM_DELETE_WINDOW",
            close_editor,
        )

    def _global_net_full_editor_apply(self):
        if self.global_net_cmd_editor_target:
            return self._global_net_cmd_editor_update()
        return self._global_net_cmd_editor_add()

    def _global_net_full_editor_ok(self):
        success = self._global_net_full_editor_apply()
        if success:
            self._global_net_close_full_editor_popup()
        return success

    def _global_net_effective_text_for_compare(self):
        if not self.global_net_path and not self.global_net_lines:
            return ""

        try:
            return self._render_global_net_text()
        except Exception:
            return "".join(self.global_net_lines)

    def _global_net_io_power_domain_info(self):
        try:
            rules = [
                r
                for r in self._global_net_all_pg_rules()
                if not r.get("disconnect")
            ]
            return self._global_net_find_io_power_domain(rules)
        except Exception:
            logging.exception(_iopadt_expand_text("Failed to infer IO __IOPADT_LITERAL_001__ Power Domain for UI"))
            return {
                "status": "NOT_FOUND",
                "domain": "",
                "qualified_domains": [],
                "domains": {},
            }

    def _global_net_io_power_domain_value(self):
        info = self._global_net_io_power_domain_info()

        if info.get("status") == "PASS":
            return str(info.get("domain", "") or "<NOT FOUND>")

        if info.get("status") == "AMBIGUOUS":
            candidates = ",".join(info.get("qualified_domains", []))
            return (
                "<AMBIGUOUS"
                + (": " + candidates if candidates else "")
                + ">"
            )

        return "<NOT FOUND>"

    def _global_net_refresh_io_power_domain_text(self):
        value = self._global_net_io_power_domain_value()
        self.global_net_io_power_domain_text.set(
            _iopadt_expand_text("IO __IOPADT_LITERAL_001__ Power Domain: ") + value
        )
        return value

    def _global_net_all_commands(self):
        """
        Return every ACTIVE connect_global_net command from the current
        effective edited Tcl. Commented-out commands are intentionally not
        active commands and are not included.
        """
        source = self._global_net_effective_text_for_compare()
        rows = []

        for order, (line_no, command) in enumerate(
            self._gn_logical_commands(source)
        ):
            parsed = self._gn_parse_any_connect_line(command)

            if parsed is None:
                continue

            row = dict(parsed)
            row.update({
                "id": f"ALLCMD_L{line_no}_{order}",
                "line": line_no,
                "order": order,
                "command": command,
            })
            rows.append(row)

        return rows

    def _gn_all_command_selector_text(self, row):
        parts = []

        if row.get("single_inst"):
            parts.append(
                "single=" + str(row["single_inst"])
            )
        if row.get("inst"):
            parts.append(
                "base=" + str(row["inst"])
            )
        if row.get("hinst"):
            parts.append(
                "hinst=" + str(row["hinst"])
            )
        if row.get("power_domain"):
            parts.append(
                "PD=" + str(row["power_domain"])
            )
        if row.get("region"):
            parts.append(
                "region=" + str(row["region"])
            )
        if row.get("net_base_name"):
            parts.append(
                "net_base=" + str(row["net_base_name"])
            )
        if row.get("non_hierarchical"):
            parts.append("non_hier")

        return " | ".join(parts) if parts else "GLOBAL"

    def _gn_all_command_flags_text(self, row):
        flags = []

        for key, label in (
            ("all", "-all"),
            ("auto_tie", "-auto_tie"),
            ("disconnect", "-disconnect"),
            ("netlist_override", "-netlist_override"),
            ("override", "-override"),
            ("verbose", "-verbose"),
        ):
            if row.get(key):
                flags.append(label)

        return " ".join(flags) if flags else "-"

    def _global_net_fill_all_command_tree(self, tree):
        if tree is None:
            return 0

        try:
            if not tree.winfo_exists():
                return 0
        except Exception:
            return 0

        for iid in tree.get_children():
            tree.delete(iid)

        rows = self._global_net_all_commands()
        io_pd = self._global_net_io_power_domain_value()
        self.global_net_all_cmd_cache = {
            row["id"]: row
            for row in rows
        }

        for row in rows:
            tree.insert(
                "",
                "end",
                iid=row["id"],
                values=(
                    row["line"],
                    row.get("type", ""),
                    row.get("net", "") or "<none>",
                    row.get("pin", "") or "-",
                    io_pd,
                    self._gn_all_command_selector_text(row),
                    self._gn_all_command_flags_text(row),
                    row.get("command", ""),
                ),
            )

        return len(rows)

    def _global_net_refresh_all_command_trees(self):
        count = 0

        for tree in (
            getattr(
                self,
                "global_net_tab_all_cmd_tree",
                None,
            ),
            getattr(
                self,
                "global_net_all_cmd_tree",
                None,
            ),
        ):
            n = self._global_net_fill_all_command_tree(tree)
            count = max(count, n)

        # If neither tree exists yet, still compute the correct count.
        if count == 0 and (
            self.global_net_path
            or self.global_net_lines
            or self.global_net_rules
        ):
            count = len(self._global_net_all_commands())

        self.global_net_all_cmd_count.set(
            f"All active connect_global_net commands: {count}"
        )
        self._global_net_refresh_io_power_domain_text()

        self._global_net_repair_update_scrollregion()

    def _global_net_all_pg_rules(self):
        """
        Parse ALL active pg_pin rules from the effective Tcl, including
        -power_domain rules. V48 incorrectly ignored domain-scoped rules.

        A rule such as:
          connect_global_net NET -power_domain PD_X -type pg_pin \
              -pin_base_name __IOPADT_LITERAL_006__ -inst_base_name *
        is a real definition for __IOPADT_LITERAL_006__ on every matching cell in PD_X.

        Different power domains are different scopes and must NOT be reported
        as a net conflict merely because they map __IOPADT_LITERAL_006__ to different nets.
        """
        source = self._global_net_effective_text_for_compare()
        rows = []

        for order, (line_no, command) in enumerate(
            self._gn_logical_commands(source)
        ):
            parsed = self._gn_parse_connect_line(command)
            if not parsed:
                continue

            row = dict(parsed)
            row.update({
                "id": f"ALLGN_L{line_no}",
                "line": line_no,
                "order": order,
                "command": command,
            })
            rows.append(row)

        return rows

    def _gn_instance_leaf(self, full_name):
        return str(full_name or "").split("/")[-1]

    def _gn_numbers(self, value):
        return [
            float(x)
            for x in re.findall(
                r'[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?',
                str(value or ""),
            )
        ]

    def _gn_fact_xy(self, fact):
        if fact is None:
            return None

        # Simulated inserted PADs do not have an authoritative Innovus
        # location yet. Do not reuse an exemplar's cloned location for region
        # matching.
        if str(getattr(fact, "place_status", "") or "") == "SIMULATED":
            return None

        nums = self._gn_numbers(getattr(fact, "location", ""))

        if len(nums) >= 2:
            return (nums[0], nums[1])

        # Fallback to bbox center if .location text is unavailable.
        nums = self._gn_numbers(getattr(fact, "bbox", ""))

        if len(nums) >= 4:
            return (
                (nums[0] + nums[2]) / 2.0,
                (nums[1] + nums[3]) / 2.0,
            )

        return None

    def _gn_region_contains_fact(self, region_text, fact):
        nums = self._gn_numbers(region_text)

        if len(nums) < 4:
            return False

        xy = self._gn_fact_xy(fact)

        if xy is None:
            return False

        x1, y1, x2, y2 = nums[:4]
        lo_x, hi_x = sorted((x1, x2))
        lo_y, hi_y = sorted((y1, y2))
        x, y = xy

        return lo_x <= x <= hi_x and lo_y <= y <= hi_y

    def _gn_rule_matches_instance(
        self,
        rule,
        full_name,
        fact=None,
    ):
        """
        Match the instance selectors supported by connect_global_net.

        No -power_domain means GLOBAL across power domains, but selectors such
        as -single_inst / -inst_base_name / -hinst / -region still restrict
        which cells receive that GLOBAL rule.
        """
        full_name = str(full_name or "")
        leaf = self._gn_instance_leaf(full_name)

        single = str(rule.get("single_inst", "") or "")

        if single:
            if full_name != single and leaf != single:
                return False

        hinst = str(rule.get("hinst", "") or "").strip("/")

        if hinst:
            parent = (
                full_name.rsplit("/", 1)[0]
                if "/" in full_name
                else ""
            )

            if parent != hinst and not parent.startswith(hinst + "/"):
                return False

        if rule.get("non_hierarchical") and "/" in full_name:
            return False

        pattern = str(rule.get("inst", "*") or "*")

        try:
            if not fnmatch.fnmatchcase(leaf, pattern):
                return False
        except Exception:
            return False

        region = str(rule.get("region", "") or "")

        if region and not self._gn_region_contains_fact(region, fact):
            return False

        return True

    def _gn_rule_matches_pin(self, rule, pin_name):
        pattern = str(rule.get("pin", "") or "")
        if not pattern:
            return False
        try:
            return fnmatch.fnmatchcase(str(pin_name), pattern)
        except Exception:
            return False

    def _gn_scope_key(self, rule):
        """
        Rules in different selector scopes are alternatives, not conflicts.
        Most importantly PD_core/__IOPADT_LITERAL_006__ and PD_TOP/__IOPADT_LITERAL_006__ do not conflict merely
        because both use -inst_base_name *.
        """
        return (
            str(rule.get("power_domain", "") or ""),
            str(rule.get("hinst", "") or ""),
            str(rule.get("single_inst", "") or ""),
            bool(rule.get("non_hierarchical")),
            str(rule.get("region", "") or ""),
            str(rule.get("inst", "*") or "*"),
        )

    def _gn_scope_text(self, rule):
        parts = []

        if rule.get("power_domain"):
            parts.append("PD=" + str(rule["power_domain"]))
        if rule.get("hinst"):
            parts.append("HINST=" + str(rule["hinst"]))
        if rule.get("single_inst"):
            parts.append("INST=" + str(rule["single_inst"]))
        elif rule.get("inst"):
            parts.append("BASE=" + str(rule["inst"]))
        if rule.get("non_hierarchical"):
            parts.append("NON_HIER")
        if rule.get("region"):
            parts.append("REGION=" + str(rule["region"]))

        return " ".join(parts) if parts else "GLOBAL"

    def _gn_effective_scope_nets(self, candidates):
        """
        Resolve matching rules in Tcl order for one actual instance + PG pin.

        Once candidates have already passed all selectors, they overlap on the
        same target object/pin.

        - Same net repeated by multiple rules is harmless.
        - A different net without override is a conflict.
        - A later -override / -netlist_override replaces ALL earlier matching
          assignments for this object/pin, including broader wildcard rules.
        - A still-later non-override mapping to a different net conflicts with
          the current effective mapping.
        """
        ordered = sorted(
            candidates,
            key=lambda r: r.get("order", 0),
        )

        effective_rules = []
        conflicts = []

        for rule in ordered:
            net = str(rule.get("net", "") or "")

            if not net:
                continue

            if rule.get("override") or rule.get("netlist_override"):
                effective_rules = [rule]
                conflicts = []
                continue

            if not effective_rules:
                effective_rules = [rule]
                continue

            current_nets = {
                str(r.get("net", "") or "")
                for r in effective_rules
            }

            if net in current_nets:
                effective_rules.append(rule)
                continue

            conflicts.append({
                "scope": (
                    self._gn_scope_text(effective_rules[-1])
                    + " <-> "
                    + self._gn_scope_text(rule)
                ),
                "nets": sorted(current_nets | {net}),
                "rules": list(effective_rules) + [rule],
            })

        effective = []

        if effective_rules:
            # If repeated rules agree on one net, expose one effective mapping.
            nets = {
                str(r.get("net", "") or "")
                for r in effective_rules
                if str(r.get("net", "") or "")
            }

            if len(nets) == 1:
                winner = effective_rules[-1]
                effective.append({
                    "net": next(iter(nets)),
                    "scope": self._gn_scope_text(winner),
                    "rule": winner,
                })

        return effective, conflicts

    def _global_net_find_io_power_domain(self, rules):
        """
        Find the unique IO POWER DOMAIN.

        V59 rule:
          A power domain qualifies if it has an active __IOPADT_LITERAL_004__ definition.
          __IOPADT_LITERAL_005__ is NOT required for IO POWER DOMAIN inference.
        """
        domains = defaultdict(lambda: {_iopadt_expand_text("__IOPADT_LITERAL_004__"): []})

        for rule in rules:
            pd = str(rule.get("power_domain", "") or "")

            if not pd or rule.get("disconnect"):
                continue

            if self._gn_rule_matches_pin(rule, _iopadt_expand_text("__IOPADT_LITERAL_004__")):
                domains[pd][_iopadt_expand_text("__IOPADT_LITERAL_004__")].append(rule)

        qualified = [
            pd
            for pd, pins in sorted(domains.items())
            if pins[_iopadt_expand_text("__IOPADT_LITERAL_004__")]
        ]

        if len(qualified) == 1:
            status = "PASS"
            domain = qualified[0]

        elif len(qualified) == 0:
            status = "NOT_FOUND"
            domain = ""

        else:
            status = "AMBIGUOUS"
            domain = ""

        return {
            "status": status,
            "domain": domain,
            "qualified_domains": qualified,
            "domains": domains,
        }

    def _gn_select_rules_for_ring_pin(
        self,
        rules,
        full_name,
        pin_name,
        io_power_domain_info,
        fact=None,
    ):
        """
        1) no -power_domain => GLOBAL.
        2) if no matching GLOBAL rule => unique IO POWER DOMAIN fallback.
        3) no unique IO POWER DOMAIN => error.
        """
        global_rules = [
            rule
            for rule in rules
            if not str(rule.get("power_domain", "") or "")
            and self._gn_rule_matches_instance(rule, full_name, fact)
            and self._gn_rule_matches_pin(rule, pin_name)
        ]

        if global_rules:
            return {
                "source": "GLOBAL",
                "rules": global_rules,
                "fallback_error": "",
                "scope": "GLOBAL",
            }

        info = io_power_domain_info

        if info["status"] == "PASS":
            pd = info["domain"]
            domain_rules = [
                rule
                for rule in rules
                if str(rule.get("power_domain", "") or "") == pd
                and self._gn_rule_matches_instance(rule, full_name, fact)
                and self._gn_rule_matches_pin(rule, pin_name)
            ]

            return {
                "source": "IO_POWER_DOMAIN",
                "rules": domain_rules,
                "fallback_error": (
                    "" if domain_rules else "MISSING_GLOBAL_NET"
                ),
                "scope": f"PD={pd}",
            }

        if info["status"] == "AMBIGUOUS":
            return {
                "source": "NO_VALID_SCOPE",
                "rules": [],
                "fallback_error": "IO_POWER_DOMAIN_AMBIGUOUS",
                "scope": "IO_POWER_DOMAIN=" + ",".join(
                    info["qualified_domains"]
                ),
            }

        return {
            "source": "NO_VALID_SCOPE",
            "rules": [],
            "fallback_error": "IO_POWER_DOMAIN_NOT_FOUND",
            "scope": "IO_POWER_DOMAIN=<not found>",
        }

    def _gn_resolved_net_set(self, pin_result):
        """
        Return the effective net names already selected by the Global Net
        logical-resolution stage. A logically failing pin is intentionally
        not used as physical-reference evidence.
        """
        if not pin_result:
            return set()

        if pin_result.get("status") != "PASS":
            return set()

        return {
            str(item.get("net", "") or "")
            for item in pin_result.get("effective", [])
            if str(item.get("net", "") or "")
        }

    def _global_net_apply_railcut_supply_segment_rules(
        self,
        result,
        use_repair,
    ):
        """configured Library __IOPADT_LITERAL_003__ Global-Net supply segmentation policy.

        __IOPADT_LITERAL_003__ is a Global-Net consistency boundary for exactly these __IOPADT_LITERAL_001__ PG
        pins:
            __IOPADT_LITERAL_004__
            __IOPADT_LITERAL_005__

        The checker therefore requires one resolved net per pin inside each
        __IOPADT_LITERAL_003__-to-__IOPADT_LITERAL_003__ segment, but deliberately does NOT compare that pin's
        net across a __IOPADT_LITERAL_003__ boundary.  __IOPADT_LITERAL_005__ remains optional: a segment with
        no __IOPADT_LITERAL_005__-bearing __IOPADT_LITERAL_001__ is N/A, not an error.  Missing/conflicting pin
        mappings are owned by the normal Global-Net checker and are not
        duplicated here.

        V128.8 adds a separate cross-domain exclusivity rule: after each
        __IOPADT_LITERAL_003__-to-__IOPADT_LITERAL_003__ segment has a single resolved __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__ net, two
        different IO Domains may NOT reuse that same net.  This helper still
        owns only the within-segment consistency part.
        """
        segments = (
            self.repair_segments
            if use_repair
            else self.segments
        )
        display = (
            self._repair_display_name
            if use_repair
            else (lambda x: x)
        )

        issues = []
        checks = []

        for seg in segments or []:
            domain_id = seg.seg_id
            start_cut = display(seg.start_cut) if seg.start_cut else "<RING_START>"
            end_cut = display(seg.end_cut) if seg.end_cut else "<RING_END>"

            for pin_name in (_iopadt_expand_text("__IOPADT_LITERAL_004__"), _iopadt_expand_text("__IOPADT_LITERAL_005__")):
                items = []
                exposing = 0
                unresolved = 0

                for internal in seg.members:
                    row = result.get(internal)
                    if not row:
                        continue

                    pres = row.get("pin_results", {}).get(pin_name)
                    if not pres:
                        continue

                    exposing += 1
                    nets = self._gn_resolved_net_set(pres)

                    if len(nets) == 1:
                        items.append({
                            "internal": internal,
                            "instance": row.get("instance", display(internal)),
                            "net": next(iter(nets)),
                        })
                    else:
                        unresolved += 1

                nets = sorted({x["net"] for x in items})

                if exposing == 0:
                    status = "N/A"
                elif unresolved and not items:
                    status = "DEFERRED"
                elif len(nets) <= 1:
                    status = "PASS"
                else:
                    status = "FAIL"

                checks.append({
                    "domain_id": domain_id,
                    "pin": pin_name,
                    "start_cut": start_cut,
                    "end_cut": end_cut,
                    "status": status,
                    "exposing_count": exposing,
                    "resolved_count": len(items),
                    "unresolved_count": unresolved,
                    "nets": nets,
                })

                dbg(
                    "GLOBAL_NET_RAILCUT_SUPPLY "
                    f"D{domain_id} pin={pin_name} "
                    f"boundary={start_cut}->{end_cut} "
                    f"status={status} exposing={exposing} "
                    f"resolved={len(items)} unresolved={unresolved} "
                    f"nets={','.join(nets) if nets else '-'}"
                )

                if len(nets) <= 1:
                    continue

                assignments = ", ".join(
                    f"{x['instance']}={x['net']}"
                    for x in items
                )
                issue_name = (
                    "RAILCUT_VDDPST_SEGMENT_MISMATCH"
                    if pin_name == _iopadt_expand_text("__IOPADT_LITERAL_004__")
                    else "RAILCUT_VSSPST_SEGMENT_MISMATCH"
                )
                issues.append({
                    "category": "GLOBAL NET",
                    "issue": issue_name,
                    "object": ", ".join(sorted({x["instance"] for x in items})),
                    "pin": pin_name,
                    "domain_id": domain_id,
                    "start_cut": start_cut,
                    "end_cut": end_cut,
                    "expected": "ONE_NET_BETWEEN_RAILCUTS",
                    "actual": ", ".join(nets),
                    "detail": (
                        _iopadt_expand_text(f"__IOPADT_LITERAL_003__ supply segmentation violation for {pin_name}: "
                        f"inside D{domain_id} between {start_cut} and {end_cut}, "
                        f"all resolved {pin_name} __IOPADT_LITERAL_001__ pins must use one Global Net. "
                        "Consistency stops at __IOPADT_LITERAL_003__; the neighboring segment is "
                        "checked independently, and V128.8 cross-domain exclusivity "
                        "then requires the neighboring IO Domain to use a different "
                        f"{pin_name} net. assignments=") + assignments
                    ),
                })

                for item in items:
                    row = result.get(item["internal"])
                    if not row:
                        continue
                    reason = f"{issue_name}(D{domain_id})"
                    if reason not in row["reasons"]:
                        row["reasons"].append(reason)
                    row["status"] = "FAIL"

        return issues, checks

    def _global_net_apply_policy_rules(
        self,
        result,
        use_repair,
    ):
        """
        V68 project Global Net policy rules.

        Rule 1
        ------
        __IOPADT_LITERAL_008__ actual PG pins resolve to Global Net __IOPADT_LITERAL_008__. __IOPADT_LITERAL_013__ is no longer a
        whole-ring fixed-name rail: __IOPADT_LITERAL_013__ must be consistent inside one IO Domain
        and mutually exclusive across different IO Domains.

        Rule 2
        ------
        Within the same IO Domain, the same actual pin name must resolve to the
        same effective Global Net on every __IOPADT_LITERAL_001__ that exposes that pin, EXCEPT
        __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__ which are owned by the explicit __IOPADT_LITERAL_003__ supply-segment
        checker.

        Rule 3
        ------
        __IOPADT_LITERAL_014__ must resolve consistently inside each IO Domain, then each
        IO Domain must use a DIFFERENT __IOPADT_LITERAL_014__ Global Net.

        Rule 4 (V128.8)
        ---------------
        __IOPADT_LITERAL_004__ / __IOPADT_LITERAL_005__ / __IOPADT_LITERAL_013__ are mutually exclusive across IO Domains:
        different __IOPADT_LITERAL_003__-defined IO Domains may not resolve the same one of
        these pins to the same Global Net.  __IOPADT_LITERAL_005__ remains optional.

        Cross-domain exclusivity added by V128.8 applies to exactly:
          __IOPADT_LITERAL_004__ / __IOPADT_LITERAL_005__ / __IOPADT_LITERAL_013__

        Existing unresolved/missing/conflict mappings are owned by the normal
        Global Net checker and are not duplicated as policy mismatches here.
        """
        domain_by_name = (
            self.repair_domain_by_name
            if use_repair
            else self.domain_by_name
        )
        display = (
            self._repair_display_name
            if use_repair
            else (lambda x: x)
        )

        issues = []
        seen = set()

        def resolved_single(row, pin_name):
            pres = row.get("pin_results", {}).get(pin_name)

            if not pres:
                return None

            nets = self._gn_resolved_net_set(pres)

            if len(nets) != 1:
                return None

            return next(iter(nets))

        def mark_row(internal, reason):
            row = result.get(internal)

            if not row:
                return

            if reason not in row["reasons"]:
                row["reasons"].append(reason)

            row["status"] = "FAIL"

        # --------------------------------------------------------------
        # Rule 1 (V128.8): configured library token remains the whole-ring ground rail.
        # configured library token is domain-scoped now and is checked by same-domain consistency
        # plus the configured library token/configured library token/configured library token cross-domain exclusivity helper below.
        # --------------------------------------------------------------
        for pin_name, expected_net in ((_iopadt_expand_text("__IOPADT_LITERAL_008__"), _iopadt_expand_text("__IOPADT_LITERAL_008__")),):
            bad = []
            for internal, row in result.items():
                if pin_name not in row.get("pin_results", {}):
                    continue
                net = resolved_single(row, pin_name)
                if net is None:
                    continue
                if net != expected_net:
                    bad.append({
                        "internal": internal,
                        "instance": row["instance"],
                        "net": net,
                        "domain_id": domain_by_name.get(internal),
                    })
            if bad:
                issue_name = f"{pin_name}_NET_MISMATCH"
                issues.append({
                    "category": "GLOBAL NET",
                    "issue": issue_name,
                    "object": ", ".join(sorted({x["instance"] for x in bad})),
                    "pin": pin_name,
                    "domain_id": None,
                    "expected": expected_net,
                    "actual": ", ".join(sorted({x["net"] for x in bad})),
                    "detail": (
                        f"Every resolved {pin_name} PG pin must map to Global Net {expected_net}. "
                        + "assignments=" + ", ".join(f"{x['instance']}={x['net']}" for x in bad)
                    ),
                })
                for item in bad:
                    mark_row(item["internal"], issue_name)

        # --------------------------------------------------------------
        # Rule 2: same IO Domain + same pin -> same effective net.
        # --------------------------------------------------------------
        by_domain_pin = {}

        for internal, row in result.items():
            domain_id = domain_by_name.get(internal)

            if domain_id is None:
                continue

            for pin_name in row.get("pin_results", {}):
                # Explicit configured library token supply-segment checker owns these two pins.
                # Do not duplicate them as generic IO_DOMAIN_NET_MISMATCH.
                if pin_name in (_iopadt_expand_text("__IOPADT_LITERAL_004__"), _iopadt_expand_text("__IOPADT_LITERAL_005__")):
                    continue

                net = resolved_single(row, pin_name)

                if net is None:
                    continue

                by_domain_pin.setdefault(
                    (domain_id, pin_name),
                    [],
                ).append({
                    "internal": internal,
                    "instance": row["instance"],
                    "net": net,
                })

        domain_pin_consistent_net = {}

        for (domain_id, pin_name), items in sorted(
            by_domain_pin.items(),
            key=lambda kv: (
                int(kv[0][0])
                if str(kv[0][0]).isdigit()
                else str(kv[0][0]),
                kv[0][1],
            ),
        ):
            nets = sorted({
                item["net"]
                for item in items
            })

            if len(nets) == 1:
                domain_pin_consistent_net[
                    (domain_id, pin_name)
                ] = nets[0]
                continue

            issue_key = (
                "IO_DOMAIN_NET_MISMATCH",
                domain_id,
                pin_name,
                tuple(nets),
            )

            if issue_key not in seen:
                seen.add(issue_key)

                assignments = ", ".join(
                    f"{item['instance']}={item['net']}"
                    for item in items
                )

                issues.append({
                    "category": "GLOBAL NET",
                    "issue": "IO_DOMAIN_NET_MISMATCH",
                    "object": ", ".join(
                        sorted({
                            item["instance"]
                            for item in items
                        })
                    ),
                    "pin": pin_name,
                    "domain_id": domain_id,
                    "expected": "ONE_NET_INSIDE_DOMAIN",
                    "actual": ", ".join(nets),
                    "detail": (
                        f"All {pin_name} connections inside IO Domain "
                        f"D{domain_id} must resolve to the same Global Net. "
                        "assignments=" + assignments
                    ),
                })

            for item in items:
                mark_row(
                    item["internal"],
                    (
                        "IO_DOMAIN_NET_MISMATCH("
                        f"D{domain_id},{pin_name})"
                    ),
                )

        # --------------------------------------------------------------
        # Rule 3: configured library token net must be unique across IO Domains.
        #
        # V128.8 separately applies cross-domain exclusivity to
        # configured library token/configured library token/configured library token. configured library token and configured library token are not part of that new rule.
        # --------------------------------------------------------------
        pocctrl_by_domain = {}

        for (
            domain_id,
            pin_name,
        ), net in domain_pin_consistent_net.items():
            if pin_name == _iopadt_expand_text("__IOPADT_LITERAL_014__"):
                pocctrl_by_domain[domain_id] = net

        net_to_domains = {}

        for domain_id, net in pocctrl_by_domain.items():
            net_to_domains.setdefault(
                net,
                [],
            ).append(domain_id)

        for net, domains in sorted(
            net_to_domains.items(),
            key=lambda kv: kv[0],
        ):
            domains = sorted(
                domains,
                key=lambda x: (
                    int(x)
                    if str(x).isdigit()
                    else str(x)
                ),
            )

            if len(domains) <= 1:
                continue

            key = (
                "POCCTRL_DOMAIN_NET_NOT_UNIQUE",
                net,
                tuple(domains),
            )

            if key not in seen:
                seen.add(key)

                affected = []

                for internal, row in result.items():
                    domain_id = domain_by_name.get(internal)

                    if domain_id not in domains:
                        continue

                    if _iopadt_expand_text("__IOPADT_LITERAL_014__") not in row.get("pin_results", {}):
                        continue

                    if resolved_single(row, _iopadt_expand_text("__IOPADT_LITERAL_014__")) != net:
                        continue

                    affected.append({
                        "internal": internal,
                        "instance": row["instance"],
                        "domain_id": domain_id,
                    })

                issues.append({
                    "category": "GLOBAL NET",
                    "issue": "POCCTRL_DOMAIN_NET_NOT_UNIQUE",
                    "object": ", ".join(
                        sorted({
                            item["instance"]
                            for item in affected
                        })
                    ),
                    "pin": _iopadt_expand_text("__IOPADT_LITERAL_014__"),
                    "domain_id": None,
                    "expected": "UNIQUE_NET_PER_IO_DOMAIN",
                    "actual": (
                        f"{net} used by "
                        + ",".join(
                            f"D{d}"
                            for d in domains
                        )
                    ),
                    "detail": (
                        _iopadt_expand_text("__IOPADT_LITERAL_014__ must use a different Global Net in every "
                        "IO Domain. "
                        f"Net {net} is shared by ")
                        + ", ".join(
                            f"D{d}"
                            for d in domains
                        )
                        + _iopadt_expand_text(_iopadt_expand_text(". V128.8 additionally checks __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__ "
                        "with their dedicated IO-domain exclusivity rule."))
                    ),
                })

                for item in affected:
                    mark_row(
                        item["internal"],
                        (
                            "POCCTRL_DOMAIN_NET_NOT_UNIQUE("
                            + ",".join(
                                f"D{d}"
                                for d in domains
                            )
                            + ")"
                        ),
                    )

        return issues

    def _global_net_railcut_adjacent_domains(self, use_repair):
        """Return {railcut_internal:{ccw_domain,cw_domain}} from ring segments.

        This mapping is topological/geometric only (from ring segment
        start_cut/end_cut) and does NOT depend on __IOPADT_LITERAL_009__/__IOPADT_LITERAL_010__ pin
        naming - see _global_net_apply_railcut_vsspst_boundary_rules /
        _global_net_repair_railcut_vsspst_boundary for the (V129-corrected)
        __IOPADT_LITERAL_009__=CW / __IOPADT_LITERAL_010__=CCW pin-side convention that consumes this.

        A segment is start_cut -> clockwise members -> end_cut, therefore a
        __IOPADT_LITERAL_003__ is the end_cut of its CCW domain and the start_cut of its CW
        domain.  This mapping is topological and does not depend on side/H/V.
        """
        segments = self.repair_segments if use_repair else self.segments
        out = {}
        for seg in segments or []:
            if seg.end_cut:
                out.setdefault(seg.end_cut, {})["ccw_domain"] = seg.seg_id
            if seg.start_cut:
                out.setdefault(seg.start_cut, {})["cw_domain"] = seg.seg_id
        return out

    def _global_net_domain_vsspst_targets(self, result, use_repair):
        """Return unique member-__IOPADT_LITERAL_001__ __IOPADT_LITERAL_005__ net per __IOPADT_LITERAL_003__-defined IO Domain.

        __IOPADT_LITERAL_003__ cells themselves are excluded; they are the boundary consumers
        of the two adjacent domain targets.  Raw effective nets are used so a
        cross-domain exclusivity FAIL does not hide an otherwise unambiguous
        same-domain __IOPADT_LITERAL_005__ target.
        """
        segments = self.repair_segments if use_repair else self.segments
        targets = {}
        for seg in segments or []:
            nets = set()
            exposed = 0
            unresolved = False
            for internal in seg.members:
                row = result.get(internal)
                if not row:
                    continue
                pres = row.get("pin_results", {}).get(_iopadt_expand_text("__IOPADT_LITERAL_005__"))
                if pres is None:
                    continue
                exposed += 1
                cur = {
                    str(item.get("net", "") or "")
                    for item in (pres.get("effective", []) or [])
                    if str(item.get("net", "") or "")
                }
                if len(cur) != 1:
                    unresolved = True
                nets.update(cur)
            if exposed and not unresolved and len(nets) == 1:
                targets[seg.seg_id] = next(iter(nets))
        return targets

    def _global_net_apply_railcut_vsspst_boundary_rules(self, result, use_repair):
        """Check __IOPADT_LITERAL_003__ __IOPADT_LITERAL_009__/__IOPADT_LITERAL_010__ against adjacent IO-domain __IOPADT_LITERAL_005__.

        V129 CORRECTION: this was __IOPADT_LITERAL_009__=CCW/__IOPADT_LITERAL_010__=CW, confirmed by
        physical layout inspection to be backwards for this __IOPADT_LITERAL_003__ cell -
        the actual placement is __IOPADT_LITERAL_009__=CW, __IOPADT_LITERAL_010__=CCW. Swapped below.

        __IOPADT_LITERAL_009__ must equal the __IOPADT_LITERAL_005__ net of the CW domain starting at this cut.
        __IOPADT_LITERAL_010__ must equal the __IOPADT_LITERAL_005__ net of the CCW domain ending at this cut.
        If an adjacent domain has no unambiguous __IOPADT_LITERAL_005__ target, this check is
        DEFERRED/N/A and the normal __IOPADT_LITERAL_005__ checker owns that upstream problem.
        """
        adjacent = self._global_net_railcut_adjacent_domains(use_repair)
        domain_targets = self._global_net_domain_vsspst_targets(result, use_repair)
        issues = []
        checks = []

        def mark(row, reason):
            if reason not in row["reasons"]:
                row["reasons"].append(reason)
            if reason not in row["blocking_reasons"]:
                row["blocking_reasons"].append(reason)
            row["status"] = "FAIL"

        for cut, sides in adjacent.items():
            row = result.get(cut)
            if not row or str(row.get("role", "")) != _iopadt_expand_text("__IOPADT_LITERAL_003__"):
                continue
            for pin, side_key, side_label in (
                (_iopadt_expand_text("__IOPADT_LITERAL_009__"), "cw_domain", "CW"),
                (_iopadt_expand_text("__IOPADT_LITERAL_010__"), "ccw_domain", "CCW"),
            ):
                if pin not in row.get("pin_results", {}):
                    continue
                domain_id = sides.get(side_key)
                expected = domain_targets.get(domain_id)
                pres = row.get("pin_results", {}).get(pin)
                actual = {
                    str(item.get("net", "") or "")
                    for item in (pres.get("effective", []) or [])
                    if str(item.get("net", "") or "")
                }
                if domain_id is None:
                    status = "DEFERRED"
                elif not expected:
                    status = "N/A"
                elif actual == {expected}:
                    status = "PASS"
                else:
                    status = "FAIL"
                    issue_name = f"RAILCUT_{pin}_{side_label}_DOMAIN_MISMATCH"
                    mark(row, issue_name)
                    issues.append({
                        "category": "GLOBAL NET",
                        "issue": issue_name,
                        "object": row.get("instance", cut),
                        "master": row.get("master", ""),
                        "pin": pin,
                        "domain_id": domain_id,
                        "expected": expected,
                        "actual": "/".join(sorted(actual)) or "<MISSING>",
                        "expected_domain": f"D{domain_id}",
                        "actual_domain": "RAILCUT_BOUNDARY",
                        "detail": (
                            _iopadt_expand_text(f"__IOPADT_LITERAL_003__ {pin} must follow the {side_label} adjacent "
                            f"IO Domain D{domain_id} __IOPADT_LITERAL_005__ net. configured Library convention: "
                            "__IOPADT_LITERAL_009__=CW, __IOPADT_LITERAL_010__=CCW.")
                        ),
                    })
                checks.append({
                    "cut": cut,
                    "instance": row.get("instance", cut),
                    "pin": pin,
                    "side": side_label,
                    "domain_id": domain_id,
                    "expected": expected or "",
                    "actual": sorted(actual),
                    "status": status,
                })
                dbg(
                    "GLOBAL_NET_RAILCUT_BOUNDARY "
                    f"cut={row.get('instance', cut)} pin={pin} side={side_label} "
                    f"domain=D{domain_id if domain_id is not None else '?'} "
                    f"expected={expected or '-'} actual={','.join(sorted(actual)) or '-'} "
                    f"status={status}"
                )
        return issues, checks

    def _global_net_apply_io_domain_exclusivity_rules(
        self,
        result,
        use_repair,
    ):
        """V128.8 IO-domain mutual-exclusion policy.

        Exactly these actual __IOPADT_LITERAL_001__ PG pins are exclusive between different
        __IOPADT_LITERAL_003__-defined IO Domains:
            __IOPADT_LITERAL_004__
            __IOPADT_LITERAL_005__
            __IOPADT_LITERAL_013__

        __IOPADT_LITERAL_002__ (V129, 2nd pass): also exclusive per IO Domain, but it is a
        SIGNAL pin, not a PG pin. _global_net_compare_design() synthesizes
        pin_results["__IOPADT_LITERAL_002__"] directly from live d.pin_nets["__IOPADT_LITERAL_002__"] evidence
        (not from connect_global_net rule matching, which cannot see
        SIGNAL pins at all) specifically so this generic exclusivity loop
        works for it unchanged - see the GLOBAL_NET_DOMAIN_EXCLUSIVE_PINS
        comment for the full history/rationale.

        A domain contributes to the exclusivity comparison only when that pin
        resolves to exactly one effective net inside the domain.  Intra-domain
        disagreements/missing mappings are owned by the normal checker (and,
        for __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__, by the __IOPADT_LITERAL_003__ segment checker) so this rule does not
        guess through an already-invalid domain.  __IOPADT_LITERAL_005__ remains optional.
        """
        domain_by_name = (
            self.repair_domain_by_name
            if use_repair
            else self.domain_by_name
        )

        issues = []
        seen = set()

        def mark_row(internal, reason):
            row = result.get(internal)
            if not row:
                return
            if reason not in row["reasons"]:
                row["reasons"].append(reason)
            row["status"] = "FAIL"

        for pin_name in (_iopadt_expand_text("__IOPADT_LITERAL_004__"), _iopadt_expand_text("__IOPADT_LITERAL_005__"), _iopadt_expand_text("__IOPADT_LITERAL_013__"), _iopadt_expand_text("__IOPADT_LITERAL_002__")):
            by_domain = {}

            for internal, row in result.items():
                domain_id = domain_by_name.get(internal)
                if domain_id is None:
                    continue
                pres = row.get("pin_results", {}).get(pin_name)
                if not pres:
                    continue
                nets = self._gn_resolved_net_set(pres)
                if len(nets) != 1:
                    continue
                net = next(iter(nets))
                rec = by_domain.setdefault(
                    domain_id,
                    {"nets": set(), "items": []},
                )
                rec["nets"].add(net)
                rec["items"].append({
                    "internal": internal,
                    "instance": row.get("instance", internal),
                    "net": net,
                })

            # Only a domain with exactly one resolved net is valid evidence.
            domain_net = {}
            domain_items = {}
            for domain_id, rec in by_domain.items():
                if len(rec["nets"]) != 1:
                    continue
                domain_net[domain_id] = next(iter(rec["nets"]))
                domain_items[domain_id] = rec["items"]

            net_to_domains = {}
            for domain_id, net in domain_net.items():
                net_to_domains.setdefault(net, []).append(domain_id)

            for net, domains in sorted(net_to_domains.items(), key=lambda kv: kv[0]):
                domains = sorted(
                    domains,
                    key=lambda x: (int(x) if str(x).isdigit() else str(x)),
                )
                if len(domains) <= 1:
                    continue

                issue_name = f"{pin_name}_DOMAIN_NET_NOT_UNIQUE"
                key = (issue_name, net, tuple(domains))
                if key in seen:
                    continue
                seen.add(key)

                affected = []
                assignments = []
                for domain_id in domains:
                    for item in domain_items.get(domain_id, []):
                        affected.append(item)
                        assignments.append(
                            f"D{domain_id}:{item['instance']}={item['net']}"
                        )

                issues.append({
                    "category": "GLOBAL NET",
                    "issue": issue_name,
                    "object": ", ".join(sorted({x["instance"] for x in affected})),
                    "pin": pin_name,
                    "domain_id": None,
                    "domains": list(domains),
                    "shared_net": net,
                    "expected": "UNIQUE_NET_PER_IO_DOMAIN",
                    "actual": f"{net} used by " + ",".join(f"D{d}" for d in domains),
                    "detail": (
                        f"{pin_name} is mutually exclusive across IO Domains. "
                        f"Global Net {net} is reused by "
                        + ", ".join(f"D{d}" for d in domains)
                        + _iopadt_expand_text(". Different __IOPADT_LITERAL_003__-defined IO Domains must use different "
                        f"{pin_name} nets. assignments=") + ", ".join(assignments)
                    ),
                })

                reason = issue_name + "(" + ",".join(f"D{d}" for d in domains) + ")"
                for item in affected:
                    mark_row(item["internal"], reason)

                dbg(
                    "GLOBAL_NET_DOMAIN_EXCLUSIVE "
                    f"pin={pin_name} net={net} domains="
                    + ",".join(f"D{d}" for d in domains)
                    + " status=FAIL"
                )

        return issues

    def _global_net_apply_physical_power_compare(
        self,
        result,
        use_repair,
    ):
        """
        Compare the resolved Global Net assignment with __IOPADT_LITERAL_001__-ring physical
        source propagation.

        Physical authority:
          CORE POWER -> __IOPADT_LITERAL_006__ -> CORE_POWER source_map
          IO POWER   -> __IOPADT_LITERAL_004__ -> IO_POWER source_map

        For a carrier cell physically reached by source __IOPADT_LITERAL_001__(s):
          - resolve source __IOPADT_LITERAL_001__ pin net(s);
          - all physical source PADs in that rail/domain must agree;
          - the carrier's resolved net must equal the physical source net.

        Logical Global Net errors are not duplicated here. Physical comparison
        only runs when both source and carrier mappings resolved cleanly.
        """
        rail_models = (
            self.repair_rail_models
            if use_repair
            else self.rail_models
        )
        domain_by_name = (
            self.repair_domain_by_name
            if use_repair
            else self.domain_by_name
        )
        display = (
            self._repair_display_name
            if use_repair
            else (lambda x: x)
        )

        cfgs = (
            ("CORE POWER", _iopadt_expand_text("__IOPADT_LITERAL_006__"), "CORE_POWER"),
            ("IO POWER", _iopadt_expand_text("__IOPADT_LITERAL_004__"), "IO_POWER"),
        )

        physical_issues = []
        seen_group = set()

        for rail_name, pin_name, source_role in cfgs:
            model = rail_models.get(rail_name, {})
            carriers = set(model.get("carriers", set()))
            source_map = model.get("source_map", {})

            # ----------------------------------------------------------
            # First determine source-net consistency per physical domain.
            # ----------------------------------------------------------
            domain_source_info = {}

            for internal in sorted(carriers):
                sources = sorted(source_map.get(internal, set()))

                if not sources:
                    # IO FILE FLOAT already owns this problem.
                    continue

                domain_id = domain_by_name.get(internal)
                key = (rail_name, domain_id)

                if key in domain_source_info:
                    continue

                # The source_map of any powered carrier in the same physical
                # configured library token segment should represent the physically reachable
                # source set for that rail.
                source_net_map = {}
                all_source_nets = set()
                unresolved_sources = []

                for src in sources:
                    src_row = result.get(src)
                    src_pin = (
                        src_row.get("pin_results", {}).get(pin_name)
                        if src_row
                        else None
                    )
                    nets = self._gn_resolved_net_set(src_pin)

                    source_net_map[src] = sorted(nets)

                    if nets:
                        all_source_nets.update(nets)
                    else:
                        unresolved_sources.append(src)

                domain_source_info[key] = {
                    "sources": sources,
                    "source_net_map": source_net_map,
                    "nets": sorted(all_source_nets),
                    "unresolved_sources": unresolved_sources,
                }

                # If two legal physical source PADs are assigned to
                # different Global Nets, topology is physically inconsistent.
                if (
                    not unresolved_sources
                    and len(all_source_nets) > 1
                ):
                    group_key = (
                        "SOURCE_NET_CONFLICT",
                        rail_name,
                        domain_id,
                        tuple(sorted(all_source_nets)),
                    )

                    if group_key not in seen_group:
                        seen_group.add(group_key)

                        physical_issues.append({
                            "category": "GLOBAL NET",
                            "issue": "PHYSICAL_SOURCE_NET_CONFLICT",
                            "rail": rail_name,
                            "pin": pin_name,
                            "domain_id": domain_id,
                            "object": ", ".join(
                                display(s) for s in sources
                            ),
                            "expected": "-",
                            "actual": ", ".join(
                                f"{display(s)}="
                                + (
                                    "/".join(source_net_map[s])
                                    if source_net_map[s]
                                    else "<UNRESOLVED>"
                                )
                                for s in sources
                            ),
                            "detail": (
                                _iopadt_expand_text(f"Physical {rail_name} source PADs in the "
                                "same __IOPADT_LITERAL_003__ domain resolve to different "
                                "Global Nets.")
                            ),
                        })

            # ----------------------------------------------------------
            # Compare every powered carrier against its physical source net.
            # ----------------------------------------------------------
            for internal in sorted(carriers):
                sources = sorted(source_map.get(internal, set()))

                if not sources:
                    # FLOAT belongs to IO FILE issues.
                    continue

                row = result.get(internal)
                if not row:
                    continue

                pin_result = row.get("pin_results", {}).get(pin_name)
                actual_nets = self._gn_resolved_net_set(pin_result)

                # Do not derive a physical mismatch from an unresolved logical
                # Global Net pin; MISSING/DOMAIN errors already explain it.
                if not actual_nets:
                    continue

                domain_id = domain_by_name.get(internal)
                info = domain_source_info.get(
                    (rail_name, domain_id)
                )

                if not info:
                    continue

                if info["unresolved_sources"]:
                    continue

                expected_nets = set(info["nets"])

                # A multi-net source set is already reported once as source
                # conflict. Mark affected carriers red without duplicating one
                # issue row per cell.
                if len(expected_nets) > 1:
                    physical_reason = (
                        f"PHYSICAL_{source_role}_SOURCE_NET_CONFLICT"
                    )
                    if physical_reason not in row["reasons"]:
                        row["reasons"].append(physical_reason)
                    row["status"] = "FAIL"
                    continue

                if len(expected_nets) != 1:
                    continue

                if actual_nets == expected_nets:
                    continue

                expected_text = "/".join(sorted(expected_nets))
                actual_text = "/".join(sorted(actual_nets))
                source_text = ", ".join(
                    display(s) for s in sources
                )

                issue_name = (
                    "PHYSICAL_CORE_POWER_MISMATCH"
                    if rail_name == "CORE POWER"
                    else "PHYSICAL_IO_POWER_MISMATCH"
                )

                row_reason = (
                    f"{issue_name}("
                    f"expected={expected_text},actual={actual_text})"
                )

                if row_reason not in row["reasons"]:
                    row["reasons"].append(row_reason)

                row["status"] = "FAIL"

                physical_issues.append({
                    "category": "GLOBAL NET",
                    "issue": issue_name,
                    "rail": rail_name,
                    "pin": pin_name,
                    "domain_id": domain_id,
                    "object": row["instance"],
                    "sources": source_text,
                    "expected": expected_text,
                    "actual": actual_text,
                    "detail": (
                        _iopadt_expand_text(f"Physical {rail_name} topology reaches source "
                        f"__IOPADT_LITERAL_001__(s) [{source_text}], so {pin_name} must resolve "
                        f"to {expected_text}, but Global Net resolves it to "
                        f"{actual_text}.")
                    ),
                })

        return physical_issues

    def _global_net_power_domain_supply_catalog(self):
        """Return DB-query metadata as {domain:{primary_power,primary_ground,available}}."""
        meta = self.meta if isinstance(self.meta, dict) else {}
        names = [x for x in str(meta.get("power_domain_names", "") or "").split() if x]
        # Also recover names from keyed metadata in case Tcl list formatting differs.
        prefix = "power_domain::"
        for key in meta:
            if str(key).startswith(prefix) and "::" in str(key)[len(prefix):]:
                pd = str(key)[len(prefix):].split("::", 1)[0]
                if pd and pd not in names:
                    names.append(pd)
        out = {}
        for pd in names:
            out[pd] = {
                "primary_power": str(meta.get(f"power_domain::{pd}::primary_power", "") or "").strip(),
                "primary_ground": str(meta.get(f"power_domain::{pd}::primary_ground", "") or "").strip(),
                "available": [x for x in str(meta.get(f"power_domain::{pd}::available_supply_nets", "") or "").split() if x],
            }
        return out

    def _global_net_expected_domain_from_supply(self, role, pin, expected_nets):
        """DEPRECATED (V129): no longer called.

        Previously inferred a CORE_POWER pad's expected domain purely by
        matching its net name against the power-domain supply catalog's
        primary_power field. Removed from the expected_domain computation in
        _global_net_apply_db_connectivity_compare because this is unsound
        whenever more than one domain shares the same primary supply net
        (produced false GLOBAL_NET_WRONG_DOMAIN failures despite a correct
        net connection). Domain membership is only asserted via __IOPADT_LITERAL_004__/
        __IOPADT_LITERAL_005__ (IO_POWER/__IOPADT_LITERAL_003__) or an explicit rule -power_domain scope now.
        Kept only for reference; not deleted so history/diffs stay legible.
        """
        if str(role or "") != "CORE_POWER":
            return ""
        if str(pin or "").upper() in (_iopadt_expand_text("__IOPADT_LITERAL_008__"), _iopadt_expand_text("__IOPADT_LITERAL_005__"), _iopadt_expand_text("__IOPADT_LITERAL_015__")):
            return ""
        nets = set(str(x) for x in (expected_nets or []) if str(x))
        if len(nets) != 1:
            return ""
        target = next(iter(nets))
        matches = []
        for pd, info in self._global_net_power_domain_supply_catalog().items():
            if str(info.get("primary_power", "")) == target:
                matches.append(pd)
        return matches[0] if len(matches) == 1 else ""

    def _global_net_apply_db_connectivity_compare(self, result, use_repair, io_pd_info):
        """Compare expected GUI Global Net mapping against FRESH Innovus DB.

        This check is authoritative only when connectivity_queried=1. A
        post-apply check therefore fails if fresh connectivity evidence is not
        available instead of silently reusing pre-apply Python memory.
        """
        meta = self.meta if isinstance(self.meta, dict) else {}
        connectivity_ok = str(meta.get("connectivity_queried", "0")).strip() == "1"
        facts = self.repair_facts if use_repair else self.facts
        issues = []

        def mark(row, reason):
            if reason not in row["reasons"]:
                row["reasons"].append(reason)
            if reason not in row["blocking_reasons"]:
                row["blocking_reasons"].append(reason)
            row["status"] = "FAIL"

        for internal, row in result.items():
            fact = facts.get(internal) if isinstance(facts, dict) else None
            master = str(row.get("master", "") or getattr(fact, "exact_master", "") or "")
            actual_domain = str(getattr(fact, "power_domain", "") or "") if fact else ""
            domain_query_ok = bool(getattr(fact, "power_domain_query_ok", False)) if fact else False

            for pin, pres in row.get("pin_results", {}).items():
                expected = sorted(self._gn_resolved_net_set(pres))
                expected_domain = str(pres.get("expected_domain", "") or "")
                actual = sorted(set((getattr(fact, "pin_nets", {}) or {}).get(pin, []))) if fact else []
                pin_query_ok = bool((getattr(fact, "pin_net_query_ok", {}) or {}).get(pin, False)) if fact else False

                # Ambiguous GUI expectation: never guess a winner.
                if pres.get("conflicts") or len(expected) > 1:
                    reason = "GLOBAL_NET_AMBIGUOUS"
                    mark(row, reason)
                    issues.append({
                        "issue": reason, "object": row["instance"], "master": master,
                        "pin": pin, "expected": "/".join(expected) or "<AMBIGUOUS>",
                        "actual": "/".join(actual) or "<FLOATING>",
                        "expected_domain": expected_domain or "-",
                        "actual_domain": actual_domain or "-",
                        "detail": _iopadt_expand_text("GUI model resolves this __IOPADT_LITERAL_001__ pin to multiple candidate Global Nets; no net was guessed."),
                    })
                    continue

                if not expected:
                    # Logical missing mapping is already represented by
                    # MISSING_GLOBAL_NET; expose the project-standard issue name.
                    if "MISSING_GLOBAL_NET" in pres.get("blocking_reasons", []):
                        reason = "GLOBAL_NET_MISSING"
                        mark(row, reason)
                        issues.append({
                            "issue": reason, "object": row["instance"], "master": master,
                            "pin": pin, "expected": "<MISSING>",
                            "actual": "/".join(actual) or "<FLOATING>",
                            "expected_domain": expected_domain or "-",
                            "actual_domain": actual_domain or "-",
                            "detail": _iopadt_expand_text("No unambiguous expected Global Net exists for this __IOPADT_LITERAL_001__ pin."),
                        })
                    continue

                if (not connectivity_ok) or (not pin_query_ok):
                    reason = "GLOBAL_NET_FLOATING_PIN"
                    mark(row, reason)
                    issues.append({
                        "issue": reason, "object": row["instance"], "master": master,
                        "pin": pin, "expected": "/".join(expected),
                        "actual": "<CONNECTIVITY_QUERY_UNAVAILABLE>",
                        "expected_domain": expected_domain or "-",
                        "actual_domain": actual_domain or "-",
                        "detail": _iopadt_expand_text("Fresh Innovus connectivity query for this exact __IOPADT_LITERAL_001__ pin failed/unavailable; DB correctness cannot be proven."),
                    })
                    continue

                if not actual:
                    reason = "GLOBAL_NET_FLOATING_PIN"
                    mark(row, reason)
                    issues.append({
                        "issue": reason, "object": row["instance"], "master": master,
                        "pin": pin, "expected": "/".join(expected), "actual": "<FLOATING>",
                        "expected_domain": expected_domain or "-",
                        "actual_domain": actual_domain or "-",
                        "detail": _iopadt_expand_text("Innovus reports no connected net on this __IOPADT_LITERAL_001__ pin after apply/query."),
                    })
                elif set(actual) != set(expected):
                    reason = "GLOBAL_NET_MISMATCH"
                    mark(row, reason)
                    issues.append({
                        "issue": reason, "object": row["instance"], "master": master,
                        "pin": pin, "expected": "/".join(expected), "actual": "/".join(actual),
                        "expected_domain": expected_domain or "-",
                        "actual_domain": actual_domain or "-",
                        "detail": _iopadt_expand_text("Expected GUI __IOPADT_LITERAL_001__ pin -> net mapping differs from fresh Innovus DB connectivity."),
                    })

                if expected_domain:
                    if (not domain_query_ok) or (not actual_domain) or actual_domain != expected_domain:
                        reason = "GLOBAL_NET_WRONG_DOMAIN"
                        mark(row, reason)
                        issues.append({
                            "issue": reason, "object": row["instance"], "master": master,
                            "pin": pin, "expected": "/".join(expected),
                            "actual": "/".join(actual) or "<FLOATING>",
                            "expected_domain": expected_domain,
                            "actual_domain": actual_domain or ("<QUERY_UNAVAILABLE>" if not domain_query_ok else "<NO_DOMAIN>"),
                            "detail": _iopadt_expand_text("__IOPADT_LITERAL_001__ power-domain membership does not match the GUI/domain model. IO-domain inference requires __IOPADT_LITERAL_004__ only; __IOPADT_LITERAL_005__ is optional."),
                        })

        return issues

    def _global_net_compare_design(self, force_db_actual=False):
        """
        For every actual ring PG pin:
          - matching no--power_domain rule is GLOBAL;
          - otherwise use the unique IO POWER DOMAIN;
          - IO POWER DOMAIN is the unique domain defining __IOPADT_LITERAL_004__;
          - no GLOBAL match and no unique IO POWER DOMAIN is an error.
        """
        use_repair = bool(self.repair_entries and self.repair_facts) and not bool(force_db_actual)

        entries = (
            self.repair_entries
            if use_repair
            else (self.physical_ring or self.entries)
        )
        facts = self.repair_facts if use_repair else self.facts
        display = self._repair_display_name if use_repair else (lambda x: x)
        domain_by_name = (
            self.repair_domain_by_name
            if use_repair
            else self.domain_by_name
        )

        rules = [
            r for r in self._global_net_all_pg_rules()
            if not r.get("disconnect")
        ]
        loaded = bool(self.global_net_path or self.global_net_lines)
        io_pd_info = self._global_net_find_io_power_domain(rules)

        result = {}
        fallback_needed = False

        for e in entries or []:
            d = facts.get(e.name) if facts else None
            if d is None or not d.found:
                continue

            pg_pins = sorted(set(d.pg_pins or []))
            # V129: an configured library token-role configured library token (configured library token family) genuinely has ZERO
            # pg_pins - its configured library token/configured library token pins are both SIGNAL type, not PG.
            # Previously this meant the row was skipped entirely and configured library token
            # was invisible to Check/Repair. Let an configured library token-role configured library token through
            # even with no pg_pins so the synthetic configured library token pin_results entry
            # below can still be attached to a real row.
            if not pg_pins and d.role != _iopadt_expand_text("__IOPADT_LITERAL_002__"):
                continue

            final_name = display(e.name)
            pin_results = {}
            missing = []
            scope_errors = []
            conflict_text = []

            for pin in pg_pins:
                selected = self._gn_select_rules_for_ring_pin(
                    rules,
                    final_name,
                    pin,
                    io_pd_info,
                    d,
                )

                if selected["source"] != "GLOBAL":
                    fallback_needed = True

                candidates = selected["rules"]
                effective, conflicts = self._gn_effective_scope_nets(
                    candidates
                )

                reasons = []
                blocking_reasons = []
                warning_reasons = []
                info_reasons = []

                if not loaded:
                    info_reasons.append("GLOBAL_NET_NOT_LOADED")
                    reasons.append("GLOBAL_NET_NOT_LOADED")

                err = selected["fallback_error"]

                if err:
                    reasons.append(err)

                    if err == "MISSING_GLOBAL_NET":
                        # E: blocking + auto-repairable.
                        blocking_reasons.append(err)
                        missing.append(pin)
                    else:
                        # D: fallback/domain inference is informational.
                        info_reasons.append(err)
                        scope_errors.append(f"{pin}:{err}")

                if conflicts:
                    # C: Tcl-order / override conflicts are WARNING only.
                    warning_reasons.append("NET_CONFLICT")
                    reasons.append("NET_CONFLICT")

                    for c in conflicts:
                        conflict_text.append(
                            f"{pin}@{c['scope']}="
                            + ",".join(c["nets"])
                        )

                pin_status = "PASS"

                if blocking_reasons:
                    pin_status = "FAIL"
                elif warning_reasons:
                    pin_status = "WARNING"
                elif info_reasons:
                    pin_status = "INFO"

                pin_results[pin] = {
                    "status": pin_status,
                    "rules": candidates,
                    "effective": effective,
                    "conflicts": conflicts,
                    "reasons": reasons,
                    "blocking_reasons": blocking_reasons,
                    "warning_reasons": warning_reasons,
                    "info_reasons": info_reasons,
                    "rule_source": selected["source"],
                    "selected_scope": selected["scope"],
                    "expected_domain": (
                        io_pd_info.get("domain", "")
                        if (d.role == "IO_POWER" and io_pd_info.get("status") == "PASS")
                        else (
                            selected["scope"][3:]
                            if str(selected.get("scope", "")).startswith("PD=")
                            # V129 FIX: removed the net-name-matching fallback
                            # (_global_net_expected_domain_from_supply). configured library token
                            # domain membership is only well-defined via
                            # configured library token/configured library token (IO_POWER/configured library token membership,
                            # handled above) or an explicit -power_domain
                            # scope on the rule itself (PD= case above).
                            # Guessing a CORE_POWER pad's domain by matching
                            # its net name against the power-domain supply
                            # catalog is unsound whenever more than one
                            # domain legitimately shares the same primary
                            # supply net (e.g. an always-on PD_TOP sharing
                            # VDD_LEVEL_02 with PD_core) - it produced false
                            # GLOBAL_NET_WRONG_DOMAIN failures even though
                            # the actual net connection was correct and
                            # Innovus's own queried power_domain fact
                            # (actual_domain) was never wrong. No domain
                            # expectation is now reported for this case,
                            # which correctly disables that comparison
                            # instead of asserting a guessed answer.
                            else ""
                        )
                    ),
                }

            reasons = []
            blocking_reasons = []
            warning_reasons = []
            info_reasons = []

            if not loaded:
                info_reasons.append("GLOBAL_NET_NOT_LOADED")
                reasons.append("GLOBAL_NET_NOT_LOADED")

            if missing:
                msg = (
                    "MISSING_GLOBAL_NET("
                    + ",".join(missing)
                    + ")"
                )
                blocking_reasons.append(msg)
                reasons.append(msg)

            if scope_errors:
                msg = (
                    "GLOBAL_NET_SCOPE_INFO("
                    + ";".join(scope_errors)
                    + ")"
                )
                info_reasons.append(msg)
                reasons.append(msg)

            if conflict_text:
                msg = (
                    "NET_CONFLICT("
                    + ";".join(conflict_text)
                    + ")"
                )
                warning_reasons.append(msg)
                reasons.append(msg)

            row_status = "PASS"

            if blocking_reasons:
                row_status = "FAIL"
            elif warning_reasons:
                row_status = "WARNING"
            elif info_reasons:
                row_status = "INFO"

            # V129: configured library token is a SIGNAL pin (see GLOBAL_NET_DOMAIN_EXCLUSIVE_PINS
            # comment), so it never goes through the pg_pins/connect_global_net
            # rule-matching loop above. Instead, synthesize a pin_results["configured library token"]
            # entry directly.
            #
            # V129 FIX (3rd pass): a PLAIN Check (force_db_actual=False, the
            # normal button in the Global Net page) must validate the CURRENT
            # PLAN - exactly like PG pins do, which check the declarative
            # connect_global_net rules text (not live DB) in this mode. configured library token
            # has no rules text, so its "plan" is whatever is recorded in
            # global_net_domain_pin_manual_targets (Set / auto-Repair). Only
            # a forced post-apply re-verification (force_db_actual=True, run
            # automatically right after Apply Global Net) should fall back to
            # asking Innovus what is ACTUALLY connected right now. Without
            # this distinction, a plain Check always reported the pre-Apply
            # live state (e.g. everyone still sharing "io_rte") even after a
            # correct D2..D8 Repair, which looked exactly like Repair having
            # no effect at all.
            #
            # V129 FIX (2nd pass, still true): shape MUST match the full
            # canonical pin_results[pin] dict (status/rules/effective/
            # conflicts/reasons/blocking_reasons/warning_reasons/info_reasons/
            # rule_source/selected_scope/expected_domain) - _global_net_issue_
            # rows() indexes several of these fields directly with pres["..."]
            # (KeyError: 'conflicts' was the 2nd-pass bug). Neutral/empty
            # values are used for fields with no SIGNAL-pin equivalent.
            # V129 FIX (4th pass): "configured library token" is not exclusive to the role=="configured library token"
            # tie-cell-owning configured library token - confirmed by a real design where a plain
            # IO_POWER configured library token (FILL_IN_CELL_IO_POWER_PAD_055) ALSO exposes an configured library token SIGNAL pin that
            # must be domain-consistent, exactly like configured library token/configured library token/configured library token/
            # configured library token are on every relevant configured library token in a domain, not just one
            # "source". Restricting this to d.role=="configured library token" meant Check never
            # even looked at (and Apply's connect_pin block never touched)
            # every OTHER pad in the domain carrying an configured library token pin - Apply
            # reported success while those pads stayed on the old shared
            # net. Now synthesized for ANY pad exposing "configured library token" in its pins,
            # regardless of role.
            if _iopadt_expand_text("__IOPADT_LITERAL_002__") in (getattr(d, "pins", None) or set()):
                domain_for_rte = domain_by_name.get(e.name)
                manual_rte_target = (
                    self._global_net_get_domain_manual_target(
                        domain_for_rte, _iopadt_expand_text("__IOPADT_LITERAL_002__")
                    )
                    if domain_for_rte is not None
                    else ""
                )
                live_rte_nets = list(dict.fromkeys(
                    n for n in (d.pin_nets.get(_iopadt_expand_text("__IOPADT_LITERAL_002__")) or []) if n
                ))
                if not force_db_actual and manual_rte_target:
                    # Pre-apply PLAN validation: simulate "if Apply Global Net
                    # ran right now with the current Set/Repair targets, what
                    # would this pin's net be" - the same semantic PG-pin
                    # rule matching already provides in this mode.
                    rte_nets = [manual_rte_target]
                    rte_source = "PENDING_MANUAL_TARGET"
                else:
                    # Post-apply verification, or nothing planned yet: fall
                    # back to what Innovus is actually connected to right now.
                    rte_nets = live_rte_nets
                    rte_source = "SIGNAL_PIN_LIVE_QUERY"
                rte_reasons = [] if rte_nets else ["RTE_SIGNAL_NOT_CONNECTED"]
                pin_results[_iopadt_expand_text("__IOPADT_LITERAL_002__")] = {
                    "status": "PASS" if rte_nets else "FAIL",
                    "rules": [],
                    "effective": [{"net": n} for n in rte_nets],
                    "conflicts": [],
                    "reasons": rte_reasons,
                    "blocking_reasons": [],
                    "warning_reasons": [],
                    "info_reasons": list(rte_reasons),
                    "rule_source": rte_source,
                    "selected_scope": "-",
                    "expected_domain": "",
                }

            result[e.name] = {
                "internal_id": e.name,
                "instance": final_name,
                "role": d.role,
                "master": d.exact_master,
                "pg_pins": pg_pins,
                "side": e.side,
                "domain_id": domain_by_name.get(e.name),
                "status": row_status,
                "reasons": reasons,
                "blocking_reasons": blocking_reasons,
                "warning_reasons": warning_reasons,
                "info_reasons": info_reasons,
                "pin_results": pin_results,
            }

        if loaded:
            railcut_supply_issues, railcut_supply_checks = (
                self._global_net_apply_railcut_supply_segment_rules(
                    result,
                    use_repair,
                )
            )
            railcut_boundary_issues, railcut_boundary_checks = (
                self._global_net_apply_railcut_vsspst_boundary_rules(
                    result,
                    use_repair,
                )
            )
            policy_issues = (
                self._global_net_apply_policy_rules(
                    result,
                    use_repair,
                )
                + railcut_supply_issues
                + railcut_boundary_issues
                + self._global_net_apply_io_domain_exclusivity_rules(
                    result,
                    use_repair,
                )
            )
        else:
            railcut_supply_issues = []
            railcut_supply_checks = []
            railcut_boundary_issues = []
            railcut_boundary_checks = []
            policy_issues = []

        physical_issues = (
            self._global_net_apply_physical_power_compare(
                result,
                use_repair,
            )
            if loaded
            else []
        )

        include_db_actual = bool(force_db_actual) or self.global_net_apply_state in (
            "GLOBAL_NET_PASS", "GLOBAL_NET_FAIL", "GLOBAL_NET_CHECKING"
        )
        db_connectivity_issues = (
            self._global_net_apply_db_connectivity_compare(
                result, use_repair, io_pd_info
            )
            if loaded and include_db_actual
            else []
        )

        fail_rows = [
            row for row in result.values()
            if row["status"] == "FAIL"
        ]
        warning_rows = [
            row for row in result.values()
            if row["status"] == "WARNING"
        ]
        info_rows = [
            row for row in result.values()
            if row["status"] == "INFO"
        ]
        pass_rows = [
            row for row in result.values()
            if row["status"] == "PASS"
        ]

        return {
            "loaded": loaded,
            "source": (
                str(self.global_net_path)
                if self.global_net_path
                else "<in-memory>"
            ),
            "model": (
                "EDITED WORKING COPY"
                if use_repair
                else "LOADED DESIGN"
            ),
            "pads": result,
            "checked_count": len(result),
            "pass_count": len(pass_rows),
            "fail_count": len(fail_rows),
            "warning_count": len(warning_rows),
            "info_count": len(info_rows),
            "active_rule_count": len(rules),
            "io_power_domain": io_pd_info,
            "fallback_needed": fallback_needed,
            "policy_issues": policy_issues,
            "policy_issue_count": len(policy_issues),
            "railcut_supply_checks": railcut_supply_checks,
            "railcut_supply_checked_count": sum(
                1 for x in railcut_supply_checks
                if x.get("status") in ("PASS", "FAIL")
            ),
            "railcut_supply_issue_count": len(railcut_supply_issues),
            "railcut_boundary_checks": railcut_boundary_checks,
            "railcut_boundary_checked_count": sum(
                1 for x in railcut_boundary_checks
                if x.get("status") in ("PASS", "FAIL")
            ),
            "railcut_boundary_issue_count": len(railcut_boundary_issues),
            "physical_issues": physical_issues,
            "physical_issue_count": len(physical_issues),
            "db_connectivity_issues": db_connectivity_issues,
            "db_connectivity_issue_count": len(db_connectivity_issues),
            "db_connectivity_queried": str((self.meta or {}).get("connectivity_queried", "0")) == "1",
            "db_actual_check_enabled": include_db_actual,
        }

    def _global_net_compare_status_for_internal(self, internal):
        comp = self._global_net_checked_result()

        if comp is None:
            return self.global_net_check_state, []

        row = comp["pads"].get(internal)

        if row is None:
            return "N/A", []

        return row["status"], list(row["reasons"])


    def _refresh_global_net_ring_compare_if_visible(self):
        self._refresh_combined_issue_views()

        if (
            hasattr(self, "canvas")
            and hasattr(self, "ring_view")
            and self.ring_view.get() == "GLOBAL NET"
        ):
            try:
                self.draw_ring()
            except Exception:
                logging.exception(
                    "GLOBAL NET ring compare redraw failed"
                )

    def _global_net_rule_power_pad_matches(self, parsed):
        selector = (
            str(parsed.get("single_inst", "") or "")
            or str(parsed.get("inst", "") or "")
        )

        if not selector:
            return []

        return self._global_net_match_power_pads(selector)

    def _global_net_rule_is_editable_power_pad(
        self,
        parsed,
        in_power_section=False,
    ):
        """
        Checker scope is broad; editor scope remains narrow.

        Do not expose whole-design/domain/region rules merely because '*'
        happens to include Power PADs. Preserve those Tcl lines verbatim.
        """
        if parsed.get("power_domain"):
            return False
        if parsed.get("region"):
            return False
        if parsed.get("hinst"):
            return False
        if parsed.get("net_base_name"):
            return False
        if parsed.get("all"):
            return False

        single = str(parsed.get("single_inst", "") or "")
        inst = str(parsed.get("inst", "") or "")

        if single:
            return bool(
                self._global_net_match_power_pads(single)
            )

        if in_power_section:
            return True

        if not inst or inst == "*":
            return False

        return bool(self._global_net_match_power_pads(inst))

    # =================================================================
    # V61 Global Net working-copy Undo / Reset
    # =================================================================

    def _global_net_snapshot(self, action=""):
        return {
            "action": str(action or "Global Net edit"),
            "lines": copy.deepcopy(self.global_net_lines),
            "rules": copy.deepcopy(self.global_net_rules),
            "rule_seq": int(self.global_net_rule_seq),
            "selected_id": str(self.global_net_selected_id or ""),
            "edit_net": self.global_net_edit_net.get(),
            "edit_pin": self.global_net_edit_pin.get(),
            "edit_inst": self.global_net_edit_inst.get(),
            "edit_override": bool(
                self.global_net_edit_override.get()
            ),
            "repair_selected_internal": str(
                self.global_net_repair_selected_internal or ""
            ),
            "repair_pin": self.global_net_repair_pin.get(),
            "full_cmd_edits": copy.deepcopy(
                self.global_net_full_cmd_edits
            ),
            "full_cmd_edit_seq": int(
                self.global_net_full_cmd_edit_seq
            ),
            "cmd_editor_target": copy.deepcopy(
                self.global_net_cmd_editor_target
            ),
            # V128.26: Set/Repair target state is part of the Global Net
            # working copy and must move with Undo snapshots too.
            "domain_pin_manual_targets": copy.deepcopy(
                self.global_net_domain_pin_manual_targets
            ),
        }

    def _global_net_update_history_text(self):
        self.global_net_history_text.set(
            f"Global Net Undo: {len(self.global_net_undo_stack)}"
        )

    def _global_net_clear_undo(self):
        self.global_net_undo_stack = []
        self._global_net_update_history_text()

    def _global_net_push_undo(self, action):
        if not self.global_net_path:
            return

        self.global_net_undo_stack.append(
            self._global_net_snapshot(action)
        )

        if len(self.global_net_undo_stack) > self.global_net_undo_limit:
            self.global_net_undo_stack = (
                self.global_net_undo_stack[
                    -self.global_net_undo_limit:
                ]
            )

        self._global_net_update_history_text()

    def _global_net_is_dirty(self):
        if not self.global_net_path:
            return False

        try:
            return (
                self._render_global_net_text()
                != self.global_net_original_text
            )
        except Exception:
            return False

    def _global_net_refresh_after_history_change(self, status_text):
        self.global_net_selected_id = (
            self.global_net_selected_id
            if self._global_net_rule_by_id(
                self.global_net_selected_id
            )
            else ""
        )

        self.global_net_status.set(status_text)
        self.global_net_repair_status.set(status_text)
        self._global_net_mark_check_stale(
            "working copy changed by Undo/Reset"
        )

        self._global_net_refresh_tree()
        self._global_net_repair_refresh()
        self._global_net_cmd_editor_update_preview()

    def _global_net_restore_snapshot(self, snapshot):
        self.global_net_lines = copy.deepcopy(
            snapshot.get("lines", [])
        )
        self.global_net_rules = copy.deepcopy(
            snapshot.get("rules", [])
        )
        self.global_net_rule_seq = int(
            snapshot.get("rule_seq", 0)
        )
        self.global_net_selected_id = str(
            snapshot.get("selected_id", "") or ""
        )

        self.global_net_edit_net.set(
            snapshot.get("edit_net", "")
        )
        self.global_net_edit_pin.set(
            snapshot.get("edit_pin", _iopadt_expand_text("__IOPADT_LITERAL_006__"))
        )
        self.global_net_edit_inst.set(
            snapshot.get("edit_inst", "")
        )
        self.global_net_edit_override.set(
            bool(snapshot.get("edit_override", True))
        )

        self.global_net_repair_selected_internal = str(
            snapshot.get(
                "repair_selected_internal",
                "",
            )
            or ""
        )
        self.global_net_repair_pin.set(
            snapshot.get("repair_pin", "")
        )
        self.global_net_full_cmd_edits = copy.deepcopy(
            snapshot.get("full_cmd_edits", [])
        )
        self.global_net_full_cmd_edit_seq = int(
            snapshot.get("full_cmd_edit_seq", 0)
        )
        self.global_net_cmd_editor_target = copy.deepcopy(
            snapshot.get("cmd_editor_target")
        )
        self.global_net_domain_pin_manual_targets = copy.deepcopy(
            snapshot.get("domain_pin_manual_targets", {}) or {}
        )

    def undo_global_net_tcl(self):
        if not self._require_io_pad_pass_for_global_net_edit():
            return False

        _iopadt_expand_text("""
        Undo exactly one Global Net working-copy mutation.

        Separate from physical IO __IOPADT_LITERAL_001__ Repair Undo.
        """)
        if not self.global_net_path:
            self.global_net_status.set(
                "Global Net Tcl: not loaded"
            )
            return

        if not self.global_net_undo_stack:
            msg = "Global Net Undo: nothing to undo."
            self.global_net_status.set(msg)
            self.global_net_repair_status.set(msg)
            self._global_net_update_history_text()
            return

        snapshot = self.global_net_undo_stack.pop()
        action = snapshot.get(
            "action",
            "Global Net edit",
        )

        self._global_net_restore_snapshot(snapshot)
        self._global_net_update_history_text()
        self._global_net_refresh_after_history_change(
            f"Undo Global Net: {action}"
        )

    def reset_global_net_tcl(self):
        if not self._require_io_pad_pass_for_global_net_edit():
            return False

        """
        Reset the edited Global Net working copy to the exact content captured
        when this file was loaded.

        Reset itself is undoable: one Undo restores the pre-reset edits.
        """
        if not self.global_net_path:
            self.global_net_status.set(
                "Global Net Tcl: not loaded"
            )
            return

        if not self._global_net_is_dirty():
            msg = "Global Net Reset: already matches loaded original."
            self.global_net_status.set(msg)
            self.global_net_repair_status.set(msg)
            return

        ok = self._ask_copyable_yesno(
            "Reset Global Net Working Copy",
            "Reset ALL in-memory Global Net edits back to the file state "
            "captured when global_net.tcl was loaded?\n\n"
            "This reset can be undone with Global Net Undo.",
        )

        if not ok:
            return

        self._global_net_push_undo(
            "Reset to loaded original"
        )

        self.global_net_lines = copy.deepcopy(
            self.global_net_original_lines
        )
        self.global_net_full_cmd_edits = []
        self.global_net_full_cmd_edit_seq = 0
        self.global_net_cmd_editor_target = None
        self._global_net_detect_rules()
        # V128.26: Reset means exact loaded-file state. Do not retain
        # Set/Repair targets from the edited working copy. Rehydrate only
        # configured library token targets that are actually persisted in the loaded original Tcl.
        self.global_net_domain_pin_manual_targets = {}
        for domain_id, net in self._global_net_parse_rte_pending_targets_block(
            self.global_net_original_text
        ).items():
            self.global_net_domain_pin_manual_targets[(str(domain_id), _iopadt_expand_text("__IOPADT_LITERAL_002__"))] = str(net)
        self.global_net_selected_id = ""

        self.global_net_edit_net.set("")
        self.global_net_edit_pin.set(_iopadt_expand_text("__IOPADT_LITERAL_006__"))
        self.global_net_edit_inst.set("")
        self.global_net_edit_override.set(True)

        self.global_net_repair_selected_internal = ""
        self.global_net_repair_pin.set("")
        self.global_net_repair_pad_label.set(
            _iopadt_expand_text("Selected __IOPADT_LITERAL_001__: -")
        )

        self._global_net_refresh_after_history_change(
            "Global Net Reset: restored loaded original "
            "(Undo can restore previous edits)."
        )

    def reset_all_global_net(self):
        """Unload every Global Net working state so a file can be loaded fresh again."""
        if not (self.global_net_path or self.global_net_lines or self.global_net_source_path):
            self.global_net_status.set("Global Net Tcl: already empty")
            return
        if not self._ask_copyable_yesno(
            "Reset ALL Global Net",
            "Clear the loaded Global Net snapshot, all edits, checks, selections and Undo history?\n\n"
            "The original source file on disk is NOT deleted or modified. After reset you can Load it again.",
        ):
            return
        self.global_net_path = None
        self.global_net_source_path = None
        self.global_net_lines = []
        self.global_net_rules = []
        self.global_net_rule_seq = 0
        self.global_net_selected_id = ""
        self.global_net_original_lines = []
        self.global_net_original_text = ""
        self.global_net_full_cmd_edits = []
        self.global_net_full_cmd_edit_seq = 0
        self.global_net_cmd_editor_target = None
        self.global_net_domain_pin_manual_targets = {}
        self._global_net_clear_undo()
        self.global_net_edit_net.set("")
        self.global_net_edit_pin.set(_iopadt_expand_text("__IOPADT_LITERAL_006__"))
        self.global_net_edit_inst.set("")
        self.global_net_edit_override.set(True)
        self.global_net_repair_selected_internal = ""
        self.global_net_repair_pin.set("")
        self.global_net_repair_pad_label.set(_iopadt_expand_text("Selected __IOPADT_LITERAL_001__: -"))
        self.global_net_repair_effective.set("Global Net is reset; Load a Tcl file.")
        self.global_net_repair_status.set("Global Net is reset; Load a Tcl file.")
        self._global_net_set_check_state("NOT_CHECKED", "all state reset", clear_result=True)
        self.global_net_status.set("Global Net Tcl: not loaded | ALL state reset")
        self._global_net_refresh_tree()
        self._global_net_repair_refresh()
        self._refresh_combined_issue_views()
        if self.ring_view.get() == "GLOBAL NET":
            self.draw_ring()

    def _global_net_detect_rules(self):
        self.global_net_rules = []
        self.global_net_rule_seq = 0
        in_power_section = False

        for idx, line in enumerate(self.global_net_lines):
            stripped = line.strip()

            # Actual POWER configured library token matching against loaded IO data is primary.
            # The sample's "power port" banner is the fallback before TSV.
            if stripped.startswith("#"):
                comment = stripped.lstrip("#").strip().lower()
                if "power port" in comment or "power pad" in comment:
                    in_power_section = True
                elif re.fullmatch(r'pd\s*\d+.*', comment, re.I):
                    in_power_section = False

            parsed = self._gn_parse_connect_line(line)
            if parsed is None:
                continue

            if not self._global_net_rule_is_editable_power_pad(
                parsed,
                in_power_section,
            ):
                continue

            self.global_net_rule_seq += 1
            rule = {
                "id": f"GN{self.global_net_rule_seq:04d}",
                "line_index": idx,
                "line": line,
                "deleted": False,
                "added": False,
            }

            # V129 FIX (TARGET_OVERLAP_OVERRIDE duplication): a rule
            # restored/parsed from a previously-saved Global Net Tcl used to
            # carry NO target_internal/target_pin/origin metadata at all, so
            # _global_net_find_gui_single_pad_override (which auto-repair
            # calls before writing a new override) could never recognize an
            # already-written single-pad override after a Save+reload -
            # every subsequent Auto Prepare/Repair pass would append another
            # near-identical copy instead of updating the existing line,
            # piling up duplicates across repeated load/repair cycles
            # (this is exactly how AUTO_RTE_D4 accumulated ~16 copies).
            #
            # Fix: backfill target_internal/target_pin right at parse time
            # for any restored rule that already has the same single-pad
            # shape auto-repair itself writes (-single_inst X -pin_base_name
            # Y -type pg_pin), tagged with a distinct restored-origin so it
            # is visibly different from a rule created in this session but
            # still recognized by the lookup below.
            single_inst = str(parsed.get("single_inst", "") or "")
            pin_for_target = str(parsed.get("pin", "") or "")
            if single_inst and pin_for_target and pin_for_target != "*":
                rule["target_internal"] = single_inst
                rule["target_pin"] = pin_for_target
                rule["origin"] = "GN_RESTORED_SINGLE_PAD"

            self.global_net_rules.append(rule)

    def _global_net_rule_by_id(self, rid):
        for r in self.global_net_rules:
            if r["id"] == rid:
                return r
        return None

    def _global_net_refresh_tree(self):
        if not hasattr(self, "global_net_tree"):
            return

        for x in self.global_net_tree.get_children():
            self.global_net_tree.delete(x)

        active_count = 0
        for r in self.global_net_rules:
            if r.get("deleted"):
                continue
            parsed = self._gn_parse_connect_line(r["line"])
            if parsed is None:
                continue
            matches = self._global_net_rule_power_pad_matches(
                parsed
            )
            match_text = ", ".join(
                f"{name}({role})" for name, role in matches
            ) or _iopadt_expand_text("<no current POWER __IOPADT_LITERAL_001__ match>")
            self.global_net_tree.insert(
                "", "end", iid=r["id"],
                values=(
                    parsed["net"],
                    parsed["pin"],
                    parsed["inst"],
                    "YES" if parsed["override"] else "NO",
                    match_text,
                    "ADDED" if r.get("added") else "FILE",
                ),
            )
            active_count += 1

        pads = self._global_net_power_pad_names()
        covered = set()
        for r in self.global_net_rules:
            if r.get("deleted"):
                continue
            parsed = self._gn_parse_connect_line(r["line"])
            if not parsed:
                continue
            for name, _role in self._global_net_rule_power_pad_matches(
                parsed
            ):
                covered.add(name)

        uncovered = [
            name for name, _role in pads
            if name not in covered
        ]
        self.global_net_summary.set(
            _iopadt_expand_text(f"Editable POWER __IOPADT_LITERAL_001__ rules={active_count} | "
            f"POWER PADs={len(pads)} | covered={len(covered)} | "
            f"uncovered={len(uncovered)}")
            + (" | " + ", ".join(uncovered) if uncovered else "")
        )
        self._global_net_refresh_all_command_trees()

        if hasattr(self, "global_net_page_issues"):
            self._populate_issue_tree(
                self.global_net_page_issues,
                self._global_net_issue_rows(),
                compact=False,
            )

        # Refreshing command tables never runs a Global Net check.

    # =================================================================
    # V57 GLOBAL NET Ring Repair
    # =================================================================

    def _global_net_repair_current_fact(self):
        internal = self.global_net_repair_selected_internal

        if not internal:
            return None, None

        facts = (
            self.repair_facts
            if self.repair_facts
            else self.facts
        )

        return internal, facts.get(internal)

    def _global_net_repair_select_pad(self, internal):
        facts = (
            self.repair_facts
            if self.repair_facts
            else self.facts
        )

        d = facts.get(internal)

        if d is None or not d.found:
            self.global_net_repair_status.set(
                f"No Innovus fact for {internal}."
            )
            return

        self.global_net_repair_selected_internal = internal

        display = (
            self._repair_display_name(internal)
            if self.repair_entries
            else internal
        )

        self.global_net_repair_pad_label.set(
            _iopadt_expand_text("Selected __IOPADT_LITERAL_001__: ")
            + display
            + f" | role={d.role} | master={d.exact_master}"
            + _iopadt_expand_text(" | IO __IOPADT_LITERAL_001__ Power Domain=")
            + self._global_net_io_power_domain_value()
        )

        pins = sorted(set(d.pg_pins or []))

        if (
            self.global_net_repair_pin.get()
            not in pins
        ):
            self.global_net_repair_pin.set(
                pins[0] if pins else ""
            )

        self.global_net_repair_status.set(
            f"Selected {display}. "
            f"Actual PG pins={len(pins)}."
        )

        # V80: in GLOBAL NET Ring view, selection gets the same spatial cue
        # as the other views: selected configured library token is depressed/thick-bordered and
        # the normal orange target arrow points immediately after it.
        if self.ring_view.get() == "GLOBAL NET":
            self._ring_set_target_after_name(internal)
            self._ring_refresh_click_styles()

        self._global_net_repair_refresh()

    def _global_net_repair_select_pin(self, pin):
        self.global_net_repair_pin.set(str(pin))
        self._global_net_repair_refresh_mapping()

    def _global_net_repair_refresh_pin_buttons(self):
        frame = getattr(
            self,
            "global_net_repair_pin_frame",
            None,
        )

        if frame is None:
            return

        try:
            if not frame.winfo_exists():
                return
        except Exception:
            return

        for child in list(frame.winfo_children()):
            try:
                child.destroy()
            except Exception:
                pass

        _internal, fact = self._global_net_repair_current_fact()

        pins = (
            sorted(set(fact.pg_pins or []))
            if fact is not None
            else []
        )

        if not pins:
            ttk.Label(
                frame,
                text="<no actual PG pin data>",
            ).pack(anchor="w")
            return

        for pin in pins:
            ttk.Radiobutton(
                frame,
                text=pin,
                value=pin,
                variable=self.global_net_repair_pin,
                command=lambda p=pin: self._safe_ring_command(
                    f"gn_select_pin:{p}",
                    self._global_net_repair_select_pin,
                    p,
                ),
            ).pack(anchor="w")

    def _global_net_repair_refresh_mapping(self):
        tree = getattr(
            self,
            "global_net_repair_mapping_tree",
            None,
        )

        if tree is None:
            return

        try:
            if not tree.winfo_exists():
                return
        except Exception:
            return

        for iid in tree.get_children():
            tree.delete(iid)

        internal, fact = self._global_net_repair_current_fact()

        if internal is None or fact is None:
            self.global_net_repair_effective.set(
                _iopadt_expand_text("Select a __IOPADT_LITERAL_001__ / ring object in GLOBAL NET view.")
            )
            return

        if not (
            self.global_net_path
            or self.global_net_lines
            or self.global_net_rules
        ):
            self.global_net_repair_effective.set(
                "Global Net Tcl is not loaded."
            )
            return

        comp = self._global_net_checked_result()
        preview_mode = False

        if comp is None:
            try:
                # Do not change official PASS/FAIL/STALE state here.
                # This is a live display-only comparison for the selected configured library token.
                comp = self._global_net_compare_design()
                preview_mode = True
            except Exception as exc:
                self.global_net_repair_effective.set(
                    "Effective mapping preview failed: "
                    + str(exc)
                )
                return

        row = comp.get("pads", {}).get(internal)

        if row is None:
            self.global_net_repair_effective.set(
                "Selected object has no Global Net comparison row."
            )
            return

        selected_pin = self.global_net_repair_pin.get()
        selected_detail = []

        for pin in row.get("pg_pins", []):
            pres = row.get("pin_results", {}).get(pin, {})
            nets = sorted(
                self._gn_resolved_net_set(pres)
            )
            net_text = (
                "/".join(nets)
                if nets
                else "<UNRESOLVED>"
            )
            scope = pres.get(
                "selected_scope",
                "-",
            )
            status = pres.get(
                "status",
                "FAIL",
            )

            tree.insert(
                "",
                "end",
                values=(
                    pin,
                    net_text,
                    self._global_net_io_power_domain_value(),
                    scope,
                    status,
                ),
                tags=(
                    "pass"
                    if status == "PASS"
                    else (
                        "warning"
                        if status == "WARNING"
                        else (
                            "info"
                            if status == "INFO"
                            else "fail"
                        )
                    ),
                ),
            )

            if pin == selected_pin:
                selected_detail = [
                    f"Pin={pin}",
                    f"Net={net_text}",
                    _iopadt_expand_text("IO __IOPADT_LITERAL_001__ Power Domain=")
                    + self._global_net_io_power_domain_value(),
                    f"Scope={scope}",
                    f"Status={status}",
                ]

        prefix = (
            "LIVE PREVIEW | "
            if preview_mode
            else ""
        )

        self.global_net_repair_effective.set(
            prefix
            + (
                " | ".join(selected_detail)
                if selected_detail
                else _iopadt_expand_text(f"__IOPADT_LITERAL_001__ status={row.get('status', '-')}")
            )
        )

    def _global_net_repair_refresh(self):
        internal, fact = self._global_net_repair_current_fact()

        if internal is None or fact is None:
            self.global_net_repair_pad_label.set(
                _iopadt_expand_text("Selected __IOPADT_LITERAL_001__: -")
            )

        self._global_net_refresh_all_command_trees()
        self._global_net_repair_refresh_pin_buttons()
        self._global_net_repair_refresh_mapping()
        self._global_net_repair_update_scrollregion()

    def _gn_build_command(
        self,
        net="",
        rule_type="pg_pin",
        pin="",
        inst_base_name="",
        single_inst="",
        hinst="",
        power_domain="",
        net_base_name="",
        region="",
        all_flag=False,
        auto_tie=False,
        disconnect=False,
        netlist_override=False,
        non_hierarchical=False,
        override=False,
        verbose=False,
    ):
        parts = ["connect_global_net"]

        if str(net or "").strip():
            parts.append(
                self._gn_quote_word(
                    str(net).strip()
                )
            )

        if all_flag:
            parts.append("-all")

        if auto_tie:
            parts.append("-auto_tie")

        if disconnect:
            parts.append("-disconnect")

        if hinst:
            parts += [
                "-hinst",
                self._gn_quote_word(hinst),
            ]

        if inst_base_name:
            parts += [
                "-inst_base_name",
                self._gn_quote_word(inst_base_name),
            ]

        if net_base_name:
            parts += [
                "-net_base_name",
                self._gn_quote_word(net_base_name),
            ]

        if netlist_override:
            parts.append("-netlist_override")

        if non_hierarchical:
            parts.append("-non_hierarchical")

        if override:
            parts.append("-override")

        if pin:
            parts += [
                "-pin_base_name",
                self._gn_quote_word(pin),
            ]

        if power_domain:
            parts += [
                "-power_domain",
                self._gn_quote_word(power_domain),
            ]

        if region:
            nums = self._gn_numbers(region)

            if len(nums) != 4:
                raise ValueError(
                    "Region requires exactly four numbers: x1 y1 x2 y2"
                )

            region_text = " ".join(
                f"{x:g}" for x in nums
            )
            parts += [
                "-region",
                "{" + region_text + "}",
            ]

        if single_inst:
            parts += [
                "-single_inst",
                self._gn_quote_word(single_inst),
            ]

        if rule_type:
            parts += [
                "-type",
                self._gn_quote_word(rule_type),
            ]

        if verbose:
            parts.append("-verbose")

        return " ".join(parts) + "\n"

    # =================================================================
    # V70 Global Net auto-repair engine
    # =================================================================

    def _global_net_batch_append_command(
        self,
        line,
        origin,
        metadata=None,
    ):
        """
        Append one GUI-generated command without creating another Undo entry.
        The caller owns one batch snapshot.
        """
        self.global_net_rule_seq += 1
        rid = f"GN{self.global_net_rule_seq:04d}"

        row = {
            "id": rid,
            "line_index": None,
            "line": line,
            "deleted": False,
            "added": True,
            "origin": origin,
        }

        if metadata:
            row.update(metadata)

        self.global_net_rules.append(row)
        self.global_net_selected_id = rid
        return rid

    def _global_net_batch_exact_override(
        self,
        comp,
        internal,
        pin,
        net,
        origin,
        domain_id=None,
    ):
        """Create/update one exact PG-pin override for an individual __IOPADT_LITERAL_001__.

        V128.15: Domain-scoped __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__ repair must be able to
        override BOTH earlier Global-Net rules and PG connectivity imported
        from the netlist. Cadence distinguishes -override from
        -netlist_override; the latter is required for netlist-specified PG
        connections. Auto-repair therefore emits both flags.

        This remains GUI pending Tcl only. No Innovus mutation occurs here.
        """
        row = comp.get("pads", {}).get(internal)

        if row is None:
            return False

        final_name = str(row.get("instance", "") or "")
        pin = str(pin or "").strip()
        net = str(net or "").strip()

        if not final_name or not pin or not net:
            return False

        pres = row.get("pin_results", {}).get(pin)
        current = self._gn_resolved_net_set(pres)

        line = self._gn_build_command(
            net=net,
            rule_type="pg_pin",
            pin=pin,
            single_inst=final_name,
            netlist_override=True,
            override=True,
        )

        existing = self._global_net_find_gui_single_pad_override(
            internal,
            pin,
            include_auto=True,
        )

        if existing is not None:
            # Upgrade older V128.x auto-repair commands that had only
            # -override. Do this even when the logical pending model already
            # resolves to the requested net; otherwise Apply can execute OK
            # while the fresh Innovus DB remains on its netlist PG net.
            desired_norm = self._gn_normalize_command_text(line)
            current_norm = self._gn_normalize_command_text(existing.get("line", ""))
            metadata_changed = (
                existing.get("target_internal") != internal
                or existing.get("target_pin") != pin
                or existing.get("origin") != origin
                or existing.get("auto_repair_domain") != domain_id
            )
            if current_norm != desired_norm or metadata_changed:
                existing["line"] = line
                existing["target_internal"] = internal
                existing["target_pin"] = pin
                existing["origin"] = origin
                existing["auto_repair_domain"] = domain_id
                return True
            return False

        if current == {net}:
            return False

        self._global_net_batch_append_command(
            line,
            origin,
            {
                "target_internal": internal,
                "target_pin": pin,
                "auto_repair_domain": domain_id,
            },
        )
        return True

    def _global_net_candidate_records(
        self,
        comp,
        domain_id,
        pin,
        include_ring=False,
    ):
        """
        Existing resolved rules/nets that can be selected by the user.

        Each candidate exposes net, matching instances, and the effective
        source command(s), so the popup really lets the user select a rule,
        not just a bare net string.
        """
        records = {}

        for internal, row in comp.get("pads", {}).items():
            row_domain = row.get("domain_id")

            if (
                not include_ring
                and row_domain != domain_id
            ):
                continue

            pres = row.get("pin_results", {}).get(pin)

            if not pres:
                continue

            for item in pres.get("effective", []) or []:
                net = str(item.get("net", "") or "")

                if not net:
                    continue

                rec = records.setdefault(
                    net,
                    {
                        "net": net,
                        "instances": set(),
                        "commands": set(),
                    },
                )
                rec["instances"].add(
                    str(row.get("instance", internal))
                )

                rule = item.get("rule") or {}
                command = str(
                    rule.get("command", "") or ""
                ).strip()

                if command:
                    rec["commands"].add(command)

        out = []

        for net in sorted(records):
            rec = records[net]
            out.append({
                "net": net,
                "instances": sorted(rec["instances"]),
                "commands": sorted(rec["commands"]),
            })

        return out

    def _global_net_choose_rule_popup(
        self,
        title,
        heading,
        candidates,
        detail="",
    ):
        """
        Modal candidate-rule selector.

        Returns selected net, or None on cancel.
        """
        if not candidates:
            return None

        distinct_nets = sorted({
            str(rec.get("net", "") or "")
            for rec in candidates
            if str(rec.get("net", "") or "")
        })

        if len(distinct_nets) == 1:
            self.global_net_repair_status.set(
                f"Auto Repair: one unambiguous candidate -> {distinct_nets[0]}"
            )
            return distinct_nets[0]

        win = self._safe_toplevel(title)
        win.geometry("820x560")
        win.minsize(700, 420)

        result = {"net": None}
        selected = tk.StringVar(
            value=str(candidates[0]["net"])
        )

        outer = ttk.Frame(win, padding=12)
        outer.pack(fill="both", expand=True)

        ttk.Label(
            outer,
            text=heading,
            font=("Segoe UI", 10, "bold"),
            wraplength=780,
            justify="left",
        ).pack(anchor="w")

        if detail:
            ttk.Label(
                outer,
                text=detail,
                wraplength=780,
                justify="left",
            ).pack(anchor="w", pady=(5, 10))

        list_box = ttk.LabelFrame(
            outer,
            text="Choose authoritative rule / net",
            padding=8,
        )
        list_box.pack(
            fill="both",
            expand=True,
        )

        canvas = tk.Canvas(
            list_box,
            highlightthickness=0,
        )
        scroll = ttk.Scrollbar(
            list_box,
            orient="vertical",
            command=canvas.yview,
        )
        canvas.configure(
            yscrollcommand=scroll.set,
        )
        canvas.pack(
            side="left",
            fill="both",
            expand=True,
        )
        scroll.pack(
            side="right",
            fill="y",
        )

        body = ttk.Frame(canvas)
        window_id = canvas.create_window(
            (0, 0),
            window=body,
            anchor="nw",
        )

        def update_scroll():
            try:
                canvas.configure(
                    scrollregion=canvas.bbox("all")
                )
                canvas.itemconfigure(
                    window_id,
                    width=max(
                        1,
                        canvas.winfo_width() - 4,
                    ),
                )
            except Exception:
                pass
            return ""

        cmd = self.register(update_scroll)
        self.global_net_editor_tcl_commands.append(cmd)
        self.tk.call(
            "bind",
            body._w,
            "<Configure>",
            cmd,
        )

        for rec in candidates:
            net = rec["net"]
            item = ttk.Frame(body, padding=(2, 5))
            item.pack(fill="x")

            ttk.Radiobutton(
                item,
                text=f"Use net: {net}",
                variable=selected,
                value=net,
            ).pack(anchor="w")

            inst_text = ", ".join(
                rec.get("instances", [])
            ) or "-"
            ttk.Label(
                item,
                text="Instances: " + inst_text,
                wraplength=720,
            ).pack(anchor="w", padx=(24, 0))

            commands = rec.get("commands", [])

            if commands:
                for command in commands[:6]:
                    ttk.Label(
                        item,
                        text="Rule: " + command,
                        font=("Consolas", 8),
                        wraplength=720,
                    ).pack(anchor="w", padx=(24, 0))

                if len(commands) > 6:
                    ttk.Label(
                        item,
                        text=f"... {len(commands)-6} more rule(s)",
                    ).pack(anchor="w", padx=(24, 0))

            ttk.Separator(
                body,
                orient="horizontal",
            ).pack(fill="x", pady=2)

        buttons = ttk.Frame(outer)
        buttons.pack(fill="x", pady=(10, 0))

        status = tk.StringVar(
            value="Choose a rule/net, then Apply or OK."
        )
        ttk.Label(
            outer,
            textvariable=status,
        ).pack(anchor="w", pady=(6,0))

        def apply_choice(close_after=False):
            result["net"] = selected.get().strip() or None
            status.set(
                "Applied selection: "
                + str(result["net"] or "<none>")
            )
            if close_after:
                try:
                    win.grab_release()
                except Exception:
                    pass
                win.destroy()

        def cancel():
            result["net"] = None
            try:
                win.grab_release()
            except Exception:
                pass
            win.destroy()

        ttk.Button(
            buttons,
            text="Apply",
            command=lambda: apply_choice(False),
        ).pack(side="left")

        ttk.Button(
            buttons,
            text="OK",
            command=lambda: apply_choice(True),
        ).pack(side="left", padx=(6,0))

        ttk.Button(
            buttons,
            text="Cancel",
            command=cancel,
        ).pack(side="right")

        win.protocol("WM_DELETE_WINDOW", cancel)

        try:
            win.transient(self)
            win.grab_set()
        except Exception:
            pass

        self.wait_window(win)
        return result["net"]

    def _global_net_resolved_domain_pin_nets(
        self,
        comp,
        domain_id,
        pin,
    ):
        nets = set()

        for row in comp.get("pads", {}).values():
            if row.get("domain_id") != domain_id:
                continue

            pres = row.get("pin_results", {}).get(pin)
            nets.update(
                self._gn_resolved_net_set(pres)
            )

        return nets

    def _global_net_db_pg_net_polarities(self):
        """Return fresh Innovus PG-net polarity metadata as {name: power|ground|...}.

        V128.20 uses this to avoid reusing stale auto-net names that were
        created with the wrong polarity by older tool revisions.
        """
        out = {}
        prefix = "pg_net_polarity::"
        for key, value in (self.meta or {}).items():
            key = str(key or "")
            if not key.startswith(prefix):
                continue
            name = key[len(prefix):].strip()
            if name:
                out[name] = str(value or "").strip().lower()
        return out

    def _global_net_db_net_polarity(self, net):
        return self._global_net_db_pg_net_polarities().get(str(net or "").strip(), "")

    def _global_net_expected_net_polarity(self, net, pin_name=""):
        pin_pol = self._global_net_pin_polarity(pin_name) if pin_name else ""
        if pin_pol:
            return pin_pol
        u = str(net or "").strip().upper()
        if u == _iopadt_expand_text("__IOPADT_LITERAL_004__") or u.startswith("VDDPST_D"):
            return "power"
        if (u == _iopadt_expand_text("__IOPADT_LITERAL_005__") or u.startswith("VSSPST_D") or
                u == _iopadt_expand_text("__IOPADT_LITERAL_013__") or u.startswith("ESD_D") or
                u == _iopadt_expand_text("__IOPADT_LITERAL_014__") or u.startswith("POCCTRL_D")):
            return "ground"
        return ""

    def _global_net_db_polarity_compatible(self, net, pin_name=""):
        """Missing DB evidence is not a failure; explicit opposite polarity is."""
        actual = self._global_net_db_net_polarity(net)
        expected = self._global_net_expected_net_polarity(net, pin_name)
        return not (actual in ("power", "ground") and expected in ("power", "ground") and actual != expected)

    def _global_net_unique_autonet(
        self,
        base,
        reserved,
    ):
        base = re.sub(
            r"[^A-Za-z0-9_]+",
            "_",
            str(base or "AUTO_NET"),
        ).strip("_") or "AUTO_NET"

        # Fresh DB PG-net names are occupied even if they do not appear in the
        # loaded source Tcl. This is important after an older run left a stale
        # VDDPST_D* GROUND net in the current Innovus session.
        occupied = set(reserved)
        occupied.update(self._global_net_db_pg_net_polarities())

        candidate = base
        idx = 1
        while candidate in occupied:
            candidate = f"{base}_{idx}"
            idx += 1

        reserved.add(candidate)
        return candidate

    def _global_net_auto_repair_missing(
        self,
        comp,
        ensure_undo,
        changes,
        skipped,
    ):
        """
        E: MISSING_GLOBAL_NET automatic repair.

        Safe preference:
          1) same-domain same-pin single resolved net
          2) whole-ring same-pin single resolved net
          3) __IOPADT_LITERAL_014__ -> deterministic J naming

        __IOPADT_LITERAL_008__, __IOPADT_LITERAL_006__/__IOPADT_LITERAL_004__, and ambiguous domain choices are intentionally
        handled by H/F/G/I/J/K rather than guessed here. __IOPADT_LITERAL_013__ is domain-scoped
        in V128.8; missing __IOPADT_LITERAL_013__ without safe evidence remains unresolved.
        """
        reserved = {
            str(r.get("net", "") or "")
            for r in self._global_net_all_pg_rules()
            if str(r.get("net", "") or "")
        }

        for internal, row in comp.get("pads", {}).items():
            domain_id = row.get("domain_id")

            for pin, pres in row.get("pin_results", {}).items():
                reasons = set(
                    pres.get("reasons", [])
                )

                if "MISSING_GLOBAL_NET" not in reasons:
                    continue

                candidate = None
                same_domain = self._global_net_resolved_domain_pin_nets(
                    comp,
                    domain_id,
                    pin,
                )

                if len(same_domain) == 1:
                    candidate = next(iter(same_domain))
                else:
                    global_nets = set()

                    for other in comp.get("pads", {}).values():
                        global_nets.update(
                            self._gn_resolved_net_set(
                                other.get(
                                    "pin_results",
                                    {},
                                ).get(pin)
                            )
                        )

                    if len(global_nets) == 1:
                        candidate = next(iter(global_nets))

                if (
                    candidate is None
                    and pin == _iopadt_expand_text("__IOPADT_LITERAL_014__")
                    and domain_id is not None
                ):
                    candidate = self._global_net_unique_autonet(
                        f"POCCTRL_D{domain_id}",
                        reserved,
                    )

                if candidate is None:
                    skipped.append(
                        f"E MISSING_GLOBAL_NET: "
                        f"{row['instance']}.{pin} has no safe existing rule"
                    )
                    continue

                ensure_undo()

                if self._global_net_batch_exact_override(
                    comp,
                    internal,
                    pin,
                    candidate,
                    "GN_AUTO_REPAIR_E_MISSING",
                    domain_id,
                ):
                    changes.append(
                        f"E {row['instance']}.{pin}->{candidate}"
                    )

    def _global_net_auto_repair_h(
        self,
        comp,
        ensure_undo,
        changes,
        skipped,
    ):
        """V128.8 H rule: only whole-ring __IOPADT_LITERAL_008__->__IOPADT_LITERAL_008__ is global.

        __IOPADT_LITERAL_013__ is intentionally NOT forced to one ring-wide net anymore because
        V128.8 requires __IOPADT_LITERAL_013__ to be mutually exclusive between IO Domains.
        """
        needed = any(
            p.get("issue") == "VSS_NET_MISMATCH"
            for p in comp.get("policy_issues", [])
        )
        unresolved = False
        for row in comp.get("pads", {}).values():
            pres = row.get("pin_results", {}).get(_iopadt_expand_text("__IOPADT_LITERAL_008__"))
            if pres and not self._gn_resolved_net_set(pres):
                unresolved = True
        if not needed and not unresolved:
            return
        ensure_undo()
        active_norm = {
            self._gn_normalize_command_text(r.get("command", ""))
            for r in self._global_net_all_commands()
        }
        line = self._gn_build_command(
            net=_iopadt_expand_text("__IOPADT_LITERAL_008__"),
            rule_type="pg_pin",
            pin=_iopadt_expand_text("__IOPADT_LITERAL_008__"),
            override=True,
        )
        norm = self._gn_normalize_command_text(line)
        if norm in active_norm:
            return
        self._global_net_batch_append_command(
            line,
            "GN_AUTO_REPAIR_H_EXACT_VSS",
            {
                "target_pin": _iopadt_expand_text("__IOPADT_LITERAL_008__"),
                "auto_repair_scope": "GLOBAL",
                "auto_repair_net": _iopadt_expand_text("__IOPADT_LITERAL_008__"),
            },
        )
        changes.append(_iopadt_expand_text("H GLOBAL __IOPADT_LITERAL_008__->__IOPADT_LITERAL_008__ commands=1"))
    def _global_net_auto_repair_domain_choices(
        self,
        comp,
        ensure_undo,
        changes,
        skipped,
    ):
        """
        F/G/I:
          F physical CORE POWER -> __IOPADT_LITERAL_006__
          G physical IO POWER   -> __IOPADT_LITERAL_004__
          I same-domain same-pin mismatch

        Each affected IO Domain + pin gets its own popup. The user selects
        which existing effective rule/net becomes authoritative.
        """
        groups = {}

        for p in comp.get("physical_issues", []):
            issue = p.get("issue")
            domain_id = p.get("domain_id")
            rail = p.get("rail")

            if domain_id is None:
                continue

            if rail == "CORE POWER" and issue in (
                "PHYSICAL_CORE_POWER_MISMATCH",
                "PHYSICAL_SOURCE_NET_CONFLICT",
            ):
                groups[(domain_id, _iopadt_expand_text("__IOPADT_LITERAL_006__"))] = "F CORE POWER"

            if rail == "IO POWER" and issue in (
                "PHYSICAL_IO_POWER_MISMATCH",
                "PHYSICAL_SOURCE_NET_CONFLICT",
            ):
                groups[(domain_id, _iopadt_expand_text("__IOPADT_LITERAL_004__"))] = "G IO POWER"

        for p in comp.get("policy_issues", []):
            if p.get("issue") != "IO_DOMAIN_NET_MISMATCH":
                continue

            domain_id = p.get("domain_id")
            pin = p.get("pin")

            # H owns only whole-ring configured library token. configured library token is domain-scoped in V128.8.
            # J owns configured library token.
            if pin in (_iopadt_expand_text("__IOPADT_LITERAL_008__"), _iopadt_expand_text("__IOPADT_LITERAL_014__")):
                continue

            groups.setdefault(
                (domain_id, pin),
                "I SAME-DOMAIN PIN",
            )

        # V128.8: configured library token configured library token/configured library token intra-domain disagreements also
        # enter the same authoritative-net repair path before exclusivity.
        for p in comp.get("policy_issues", []):
            issue = p.get("issue")
            if issue not in (
                "RAILCUT_VDDPST_SEGMENT_MISMATCH",
                "RAILCUT_VSSPST_SEGMENT_MISMATCH",
            ):
                continue
            domain_id = p.get("domain_id")
            pin = p.get("pin")
            if domain_id is None or pin not in (_iopadt_expand_text("__IOPADT_LITERAL_004__"), _iopadt_expand_text("__IOPADT_LITERAL_005__")):
                continue
            groups.setdefault(
                (domain_id, pin),
                _iopadt_expand_text("I __IOPADT_LITERAL_003__ SAME-DOMAIN PIN"),
            )

        for (domain_id, pin), reason in sorted(
            groups.items(),
            key=lambda x: (
                int(x[0][0])
                if str(x[0][0]).isdigit()
                else str(x[0][0]),
                x[0][1],
            ),
        ):
            candidates = self._global_net_candidate_records(
                comp,
                domain_id,
                pin,
            )

            if not candidates:
                skipped.append(
                    f"{reason} D{domain_id} {pin}: no candidate rule"
                )
                continue

            chosen = self._global_net_choose_rule_popup(
                f"Global Net Auto Repair - D{domain_id} {pin}",
                (
                    f"{reason}: choose the authoritative rule/net "
                    f"for IO Domain D{domain_id}, pin {pin}."
                ),
                candidates,
                (
                    "All actual PADs in this IO Domain exposing this pin "
                    "will receive an exact later -single_inst -override "
                    "to the selected net."
                ),
            )

            if not chosen:
                skipped.append(
                    f"{reason} D{domain_id} {pin}: user cancelled"
                )
                continue

            ensure_undo()

            for internal, row in comp.get("pads", {}).items():
                if row.get("domain_id") != domain_id:
                    continue

                if pin not in row.get("pin_results", {}):
                    continue

                if self._global_net_batch_exact_override(
                    comp,
                    internal,
                    pin,
                    chosen,
                    (
                        "GN_AUTO_REPAIR_F_CORE"
                        if reason.startswith("F ")
                        else (
                            "GN_AUTO_REPAIR_G_IO"
                            if reason.startswith("G ")
                            else "GN_AUTO_REPAIR_I_DOMAIN"
                        )
                    ),
                    domain_id,
                ):
                    changes.append(
                        f"{reason} D{domain_id} "
                        f"{row['instance']}.{pin}->{chosen}"
                    )

    def _global_net_auto_repair_domain_exclusivity(
        self,
        comp,
        ensure_undo,
        changes,
        skipped,
    ):
        """V128.8 K: make __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__ unique per IO Domain.

        For a shared net, the first deterministic domain keeps the existing
        net to minimize edits.  Every later conflicting domain receives a new
        deterministic <PIN>_D<domain> Global Net and exact per-instance
        overrides.  Save/Apply already carries the idempotent create-net
        prerequisite patch, so the new net is created safely when needed.
        """
        conflicts = [
            p for p in comp.get("policy_issues", [])
            if p.get("issue") in (
                "VDDPST_DOMAIN_NET_NOT_UNIQUE",
                "VSSPST_DOMAIN_NET_NOT_UNIQUE",
                "ESD_DOMAIN_NET_NOT_UNIQUE",
            )
        ]
        if not conflicts:
            return

        reserved = set(self._global_net_effective_net_names())
        reserved.update(
            str(r.get("net", "") or "")
            for r in self._global_net_all_pg_rules()
            if str(r.get("net", "") or "")
        )

        processed = set()
        for issue in conflicts:
            pin = str(issue.get("pin", "") or "").upper()
            shared_net = str(issue.get("shared_net", "") or "")
            domains = list(issue.get("domains", []) or [])
            domains = sorted(
                domains,
                key=lambda x: (int(x) if str(x).isdigit() else str(x)),
            )
            key = (pin, shared_net, tuple(domains))
            if key in processed or len(domains) <= 1:
                continue
            processed.add(key)

            owner = domains[0]
            changes.append(
                f"K {pin}: keep {shared_net} on D{owner}; split "
                + ",".join(f"D{d}" for d in domains[1:])
            )

            for domain_id in domains[1:]:
                new_net = self._global_net_unique_autonet(
                    f"{pin}_D{domain_id}",
                    reserved,
                )
                touched = 0
                for internal, row in comp.get("pads", {}).items():
                    if row.get("domain_id") != domain_id:
                        continue
                    if pin not in row.get("pin_results", {}):
                        continue
                    ensure_undo()
                    if self._global_net_batch_exact_override(
                        comp,
                        internal,
                        pin,
                        new_net,
                        "GN_AUTO_REPAIR_K_DOMAIN_EXCLUSIVE",
                        domain_id,
                    ):
                        touched += 1
                        changes.append(
                            f"K D{domain_id} {row['instance']}.{pin}->{new_net}"
                        )

                if touched == 0:
                    skipped.append(
                        _iopadt_expand_text(f"K D{domain_id} {pin}: no resolvable __IOPADT_LITERAL_001__ instance to override")
                    )

    def _global_net_auto_repair_j(
        self,
        comp,
        ensure_undo,
        changes,
        skipped,
        only_domain_id=None,
    ):
        """
        J: __IOPADT_LITERAL_014__ unique per IO Domain with automatic deterministic naming.

        V71 selector rule:
          - Repair by exact INSTANCE NAME only.
          - Emit -single_inst <actual instance name>.
          - Never use -power_domain for J repair.

        The generated net remains one unique __IOPADT_LITERAL_014__ net per IO Domain so the
        same-domain consistency rule is preserved.

        V129: a manually-set target (IO Domain Sources editor,
        _global_net_get_domain_manual_target) always wins over the
        auto-generated POCCTRL_D<n> name, for the same reason as the
        __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__ reconcile helper. only_domain_id, when given,
        restricts repair to that one IO Domain (used by "Repair This
        Domain"); default None preserves the original all-domains
        behavior exactly.
        """
        domain_rows = {}

        for internal, row in comp.get("pads", {}).items():
            domain_id = row.get("domain_id")

            if domain_id is None:
                continue

            if only_domain_id is not None and str(domain_id) != str(only_domain_id):
                continue

            if _iopadt_expand_text("__IOPADT_LITERAL_014__") not in row.get("pin_results", {}):
                continue

            domain_rows.setdefault(
                domain_id,
                [],
            ).append((internal, row))

        if not domain_rows:
            return

        resolved = {}
        net_domains = {}

        for domain_id, rows in domain_rows.items():
            nets = set()

            for _internal, row in rows:
                nets.update(
                    self._gn_resolved_net_set(
                        row["pin_results"].get(_iopadt_expand_text("__IOPADT_LITERAL_014__"))
                    )
                )

            resolved[domain_id] = nets

            if len(nets) == 1:
                net = next(iter(nets))
                net_domains.setdefault(
                    net,
                    [],
                ).append(domain_id)

        target_domains = set()

        for domain_id, nets in resolved.items():
            if len(nets) != 1:
                target_domains.add(domain_id)

            # V129: a domain with an explicit manual configured library token target that
            # differs from what it currently resolves to also needs repair,
            # even though it isn't otherwise flagged as ambiguous/colliding.
            manual = self._global_net_get_domain_manual_target(
                domain_id, _iopadt_expand_text("__IOPADT_LITERAL_014__")
            )
            if manual and nets != {manual}:
                target_domains.add(domain_id)

        for _net, domains in net_domains.items():
            if len(domains) > 1:
                target_domains.update(domains)

        for p in comp.get("policy_issues", []):
            if p.get("issue") != "POCCTRL_DOMAIN_NET_NOT_UNIQUE":
                continue

            actual = str(p.get("actual", "") or "")

            for mm in re.finditer(r"\bD(\d+)\b", actual):
                domain_id = int(mm.group(1))
                if only_domain_id is not None and str(domain_id) != str(only_domain_id):
                    continue
                target_domains.add(domain_id)

        if not target_domains:
            return

        reserved = {
            str(r.get("net", "") or "")
            for r in self._global_net_all_pg_rules()
            if str(r.get("net", "") or "")
        }

        # Keep already-valid unique domain nets untouched/reserved.
        for domain_id, nets in resolved.items():
            if (
                domain_id not in target_domains
                and len(nets) == 1
            ):
                reserved.update(nets)

        for domain_id in sorted(
            target_domains,
            key=lambda x: int(x) if str(x).isdigit() else str(x),
        ):
            rows = domain_rows.get(domain_id, [])

            if not rows:
                skipped.append(
                    _iopadt_expand_text(f"J D{domain_id}: no actual __IOPADT_LITERAL_014__ pin")
                )
                continue

            manual = self._global_net_get_domain_manual_target(
                domain_id, _iopadt_expand_text("__IOPADT_LITERAL_014__")
            )
            auto_net = manual or self._global_net_unique_autonet(
                f"POCCTRL_D{domain_id}",
                reserved,
            )
            reserved.add(auto_net)

            ensure_undo()

            for internal, row in rows:
                # _global_net_batch_exact_override() always emits:
                #   -single_inst <row.instance>
                # and never emits -power_domain.
                changed = self._global_net_batch_exact_override(
                    comp,
                    internal,
                    _iopadt_expand_text("__IOPADT_LITERAL_014__"),
                    auto_net,
                    "GN_AUTO_REPAIR_J_POCCTRL_INST",
                    domain_id,
                )

                if not changed:
                    continue

                # Verify the newest/edited command really uses instance-name
                # selection and does not fall back to power-domain scope.
                found_inst_rule = False

                for rule in reversed(self.global_net_rules):
                    if rule.get("origin") != "GN_AUTO_REPAIR_J_POCCTRL_INST":
                        continue

                    if rule.get("target_internal") != internal:
                        continue

                    parsed = self._gn_parse_any_connect_line(
                        rule.get("line", "")
                    )

                    if (
                        parsed
                        and parsed.get("single_inst") == row["instance"]
                        and not parsed.get("power_domain")
                        and parsed.get("pin") == _iopadt_expand_text("__IOPADT_LITERAL_014__")
                        and parsed.get("net") == auto_net
                    ):
                        found_inst_rule = True
                    break

                if not found_inst_rule:
                    raise RuntimeError(
                        "J repair must use exact instance-name "
                        f"mapping for {row['instance']}."
                    )

                changes.append(
                    _iopadt_expand_text(f"J D{domain_id} "
                    f"{row['instance']}.__IOPADT_LITERAL_014__->{auto_net} "
                    "[single_inst]")
                )

    def _global_net_auto_repair_vdd_consistency(
        self,
        comp,
        ensure_undo,
        changes,
        skipped,
        only_domain_id=None,
    ):
        """V129 (L): __IOPADT_LITERAL_006__ must be CONSISTENT within one IO Domain, but is
        explicitly NOT required to be unique BETWEEN IO Domains - multiple
        domains legitimately sharing one __IOPADT_LITERAL_006__ rail is normal. This is why
        __IOPADT_LITERAL_006__ is handled by its own function instead of being folded into
        _global_net_reconcile_domain_supply_pins_pending (which enforces
        cross-domain exclusivity for __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__).

        Rules:
          * A domain already resolving __IOPADT_LITERAL_006__ to exactly one net is left
            untouched UNLESS a manual target (IO Domain Sources editor)
            says otherwise.
          * A domain with an explicit manual __IOPADT_LITERAL_006__ target is pushed to that
            net across every member, same mechanism as the other pins.
          * A domain with genuinely AMBIGUOUS __IOPADT_LITERAL_006__ (members disagree, no
            manual target set) is never guessed - it is reported in
            `skipped` so the person can look at it and set one explicitly.
            This matches the "never guess a winner" policy already used
            elsewhere (GLOBAL_NET_AMBIGUOUS).
        """
        domain_rows = {}
        for internal, row in comp.get("pads", {}).items():
            domain_id = row.get("domain_id")
            if domain_id is None:
                continue
            if only_domain_id is not None and str(domain_id) != str(only_domain_id):
                continue
            if _iopadt_expand_text("__IOPADT_LITERAL_006__") not in row.get("pin_results", {}):
                continue
            domain_rows.setdefault(domain_id, []).append((internal, row))

        if not domain_rows:
            return

        for domain_id in sorted(
            domain_rows,
            key=lambda x: (0, int(x)) if str(x).isdigit() else (1, str(x)),
        ):
            rows = domain_rows[domain_id]
            nets = set()
            for _internal, row in rows:
                nets.update(
                    self._gn_resolved_net_set(
                        row["pin_results"].get(_iopadt_expand_text("__IOPADT_LITERAL_006__"))
                    )
                )

            manual = self._global_net_get_domain_manual_target(domain_id, _iopadt_expand_text("__IOPADT_LITERAL_006__"))

            if manual:
                target = manual
            elif len(nets) == 1:
                # Already consistent; nothing to do for this domain.
                continue
            else:
                skipped.append(
                    _iopadt_expand_text(f"L D{domain_id} __IOPADT_LITERAL_006__: ambiguous (")
                    + (",".join(sorted(nets)) if nets else "no resolved net")
                    + _iopadt_expand_text(") - set an explicit __IOPADT_LITERAL_006__ target for this IO Domain "
                    "in IO Domain Sources to repair.")
                )
                continue

            ensure_undo()
            touched = 0
            for internal, row in rows:
                if self._global_net_batch_exact_override(
                    comp, internal, _iopadt_expand_text("__IOPADT_LITERAL_006__"), target,
                    "GN_AUTO_REPAIR_L_VDD_CONSISTENCY", domain_id,
                ):
                    touched += 1
                    changes.append(
                        _iopadt_expand_text(f"L D{domain_id} {row['instance']}.__IOPADT_LITERAL_006__->{target}")
                    )
            if touched == 0:
                skipped.append(
                    _iopadt_expand_text(f"L D{domain_id} __IOPADT_LITERAL_006__: no resolvable __IOPADT_LITERAL_001__ instance to override")
                )

    def _global_net_auto_repair_rte_signal(
        self,
        comp,
        ensure_undo,
        changes,
        skipped,
        only_domain_id=None,
    ):
        """M (V129): __IOPADT_LITERAL_002__ is a SIGNAL pin, repaired via connect_pin, NOT
        connect_global_net - see the GLOBAL_NET_DOMAIN_EXCLUSIVE_PINS
        comment for the full rationale. There is no declarative rules
        file for SIGNAL pins the way there is for PG pins, so "repair"
        here does not write a pending connect_global_net rule. Instead it
        ensures every IO Domain that has exactly one __IOPADT_LITERAL_002__-role __IOPADT_LITERAL_001__ gets an
        explicit target recorded in the SAME manual-target store the
        "Set Pin Target..." button uses (auto-assigning a deterministic
        RTE_D<domain> if nothing is set yet, unique against every other
        domain's already-assigned __IOPADT_LITERAL_002__ target). _global_net_rte_apply_tcl_block()
        turns whatever is recorded there into create_net/connect_pin
        commands, appended to the Apply Global Net payload.

        This NEVER touches the __IOPADT_LITERAL_002__-role __IOPADT_LITERAL_001__ instance itself or its
        __IOPADT_LITERAL_007__-side private tie net - that remains entirely owned by
        ioPADt's own IO/DB-patch Auto Repair, independent of this.
        """
        domain_rows = {}
        for internal, row in comp.get("pads", {}).items():
            domain_id = row.get("domain_id")
            if domain_id is None:
                continue
            if only_domain_id is not None and str(domain_id) != str(only_domain_id):
                continue
            if row.get("role") != _iopadt_expand_text("__IOPADT_LITERAL_002__"):
                continue
            domain_rows.setdefault(domain_id, []).append((internal, row))

        if not domain_rows:
            return

        # Reserve every net already manually targeted for configured library token elsewhere, so
        # a freshly auto-assigned default never collides with one already
        # chosen (by a prior Repair pass or an explicit Set).
        reserved = {
            str(net)
            for (_d, pin), net in self.global_net_domain_pin_manual_targets.items()
            if pin == _iopadt_expand_text("__IOPADT_LITERAL_002__") and net
        }

        for domain_id in sorted(
            domain_rows,
            key=lambda x: (0, int(x)) if str(x).isdigit() else (1, str(x)),
        ):
            rows = domain_rows[domain_id]
            if len(rows) != 1:
                skipped.append(
                    _iopadt_expand_text(f"M D{domain_id} __IOPADT_LITERAL_002__: expected exactly 1 __IOPADT_LITERAL_002__-role __IOPADT_LITERAL_001__, "
                    f"found {len(rows)} - resolve the extra __IOPADT_LITERAL_002__ source(s) "
                    "first (Ring View MULTIPLE_SOURCE repair).")
                )
                continue

            existing_manual = self._global_net_get_domain_manual_target(
                domain_id, _iopadt_expand_text("__IOPADT_LITERAL_002__")
            )
            if existing_manual:
                # Already has an explicit target (user Set, or a prior
                # Repair pass already assigned one) - leave it alone.
                continue

            base = f"RTE_D{domain_id}"
            target = self._global_net_unique_autonet(base, reserved)

            ensure_undo()
            try:
                self._global_net_set_domain_manual_target(
                    domain_id, _iopadt_expand_text("__IOPADT_LITERAL_002__"), target
                )
            except ValueError as exc:
                skipped.append(_iopadt_expand_text(f"M D{domain_id} __IOPADT_LITERAL_002__: {exc}"))
                continue

            _internal, row = rows[0]
            changes.append(
                _iopadt_expand_text(f"M D{domain_id} {row['instance']}.__IOPADT_LITERAL_002__->{target} "
                "[connect_pin, applied with Apply Global Net]")
            )

    def _global_net_rte_domain_pad_instances(self, domain_id):
        """Return [(internal_name, display_instance), ...] for EVERY __IOPADT_LITERAL_001__ in
        the given IO Domain that exposes an __IOPADT_LITERAL_002__ pin - NOT just the single
        role=="__IOPADT_LITERAL_002__" tie-cell-owning __IOPADT_LITERAL_001__. Used at Apply time to know every
        instance's __IOPADT_LITERAL_002__ pin that needs connect_pin.

        V129 FIX (4th pass): originally only looked for the one role=="__IOPADT_LITERAL_002__"
        __IOPADT_LITERAL_001__, matching how __IOPADT_LITERAL_007__/the tie cell is special-cased. But "__IOPADT_LITERAL_002__" the
        public SIGNAL pin is NOT exclusive to that __IOPADT_LITERAL_001__ - confirmed by a real
        design where a plain IO_POWER __IOPADT_LITERAL_001__ (FILL_IN_CELL_IO_POWER_PAD_055) also carries an __IOPADT_LITERAL_002__
        pin that must be domain-consistent, exactly like __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__/
        __IOPADT_LITERAL_014__ are on every relevant __IOPADT_LITERAL_001__, not just one "source". Only
        looking at the role=="__IOPADT_LITERAL_002__" __IOPADT_LITERAL_001__ meant Apply reported success while
        every OTHER pad with an __IOPADT_LITERAL_002__ pin in that domain stayed on the old
        shared net.
        """
        comp = self._global_net_compare_design(force_db_actual=False)
        rows = [
            (internal, row)
            for internal, row in comp.get("pads", {}).items()
            if _iopadt_expand_text("__IOPADT_LITERAL_002__") in row.get("pin_results", {})
            and str(row.get("domain_id")) == str(domain_id)
        ]
        return [
            (internal, row.get("instance", internal))
            for internal, row in rows
        ]

    def _global_net_render_rte_pending_targets_block(self):
        """V129: render the current __IOPADT_LITERAL_002__ Set/Repair targets as a comment-only
        block (plain # lines, never executed) so Save can embed them in the
        .tcl text and Load can round-trip them back into
        self.global_net_domain_pin_manual_targets. Returns "" if there is
        nothing to record (keeps a clean file when __IOPADT_LITERAL_002__ was never touched)."""
        targets = {
            d: net
            for (d, pin), net in self.global_net_domain_pin_manual_targets.items()
            if pin == _iopadt_expand_text("__IOPADT_LITERAL_002__") and net
        }
        if not targets:
            return ""
        lines = [GLOBAL_NET_SOURCE_RTE_TARGETS_BEGIN.rstrip("\n")]
        for domain_id in sorted(
            targets, key=lambda x: (0, int(x)) if str(x).isdigit() else (1, str(x))
        ):
            lines.append(_iopadt_expand_text(f"# D{domain_id}=__IOPADT_LITERAL_002__={targets[domain_id]}"))
        lines.append(GLOBAL_NET_SOURCE_RTE_TARGETS_END.rstrip("\n"))
        return "\n".join(lines) + "\n"

    def _global_net_parse_rte_pending_targets_block(self, source_text):
        """V129: parse the block _global_net_render_rte_pending_targets_block
        writes, returning {domain_id: net}. Returns {} if the block is
        absent (older file, or __IOPADT_LITERAL_002__ was never Set/Repaired before Save)."""
        begin = GLOBAL_NET_SOURCE_RTE_TARGETS_BEGIN.rstrip("\n")
        end = GLOBAL_NET_SOURCE_RTE_TARGETS_END.rstrip("\n")
        start_idx = source_text.find(begin)
        if start_idx < 0:
            return {}
        end_idx = source_text.find(end, start_idx)
        if end_idx < 0:
            return {}
        body = source_text[start_idx + len(begin):end_idx]
        out = {}
        for line in body.splitlines():
            m = re.match(_iopadt_expand_text(r"#\s*D(\S+)=__IOPADT_LITERAL_002__=(\S+)\s*$"), line.strip())
            if m:
                out[m.group(1)] = m.group(2)
        return out

    def _global_net_bind_rte_pending_targets_block(self, source_text):
        """V128.25: idempotently persist the current __IOPADT_LITERAL_002__ target metadata.

        Older V129 Save/Export code appended this block outside the canonical
        source while Apply-to-disk wrote only canonical["source_tcl"].  That
        meant Apply could leave an executable __IOPADT_LITERAL_002__ topology on disk without the
        metadata needed to reconstruct the GUI target store after reload.
        Canonical rendering now owns this block and replaces any older copy.
        """
        text = str(source_text or "")
        begin = re.escape(GLOBAL_NET_SOURCE_RTE_TARGETS_BEGIN.strip())
        end = re.escape(GLOBAL_NET_SOURCE_RTE_TARGETS_END.strip())
        text = re.sub(
            r"(?ms)^\s*" + begin + r".*?^\s*" + end + r"\s*",
            "",
            text,
        )
        block = self._global_net_render_rte_pending_targets_block()
        if not block:
            return text
        if text and not text.endswith("\n"):
            text += "\n"
        return text + "\n" + block

    def _global_net_bind_rte_connectivity_block(self, source_text):
        """V128.25: persist __IOPADT_LITERAL_002__ create_net/connect_pin in global_net.tcl.

        This is the missing persistence path fixed in V128.25.  __IOPADT_LITERAL_002__ remains a
        normal SIGNAL network (never connect_global_net); however the source
        file now carries the exact executable create_net/connect_pin commands
        that Apply Global Net uses.  A managed BEGIN/END block makes repeated
        Save/Export/Apply idempotent instead of accumulating duplicate commands.
        """
        text = str(source_text or "")
        begin = re.escape(GLOBAL_NET_SOURCE_RTE_CONNECT_BEGIN.strip())
        end = re.escape(GLOBAL_NET_SOURCE_RTE_CONNECT_END.strip())
        text = re.sub(
            r"(?ms)^\s*" + begin + r".*?^\s*" + end + r"\s*",
            "",
            text,
        )

        rte_block, _applied, _notes = self._global_net_rte_apply_tcl_block(
            include_protection=False
        )
        if not rte_block:
            return text

        block = (
            GLOBAL_NET_SOURCE_RTE_CONNECT_BEGIN.rstrip("\n")
            + "\n"
            + "# Auto-generated by ioPADt V128.25.\n"
            + _iopadt_expand_text("# __IOPADT_LITERAL_002__ is a SIGNAL pin: create_net/connect_pin, not connect_global_net.\n")
            + rte_block.rstrip("\n")
            + "\n"
            + GLOBAL_NET_SOURCE_RTE_CONNECT_END.rstrip("\n")
            + "\n"
        )
        if text and not text.endswith("\n"):
            text += "\n"
        return text + "\n" + block

    def _global_net_rte_runtime_dont_touch_tcl_block(self):
        """V128.24: runtime fallback that protects every ioPADt domain __IOPADT_LITERAL_002__ net.

        This intentionally discovers RTE_D* from the live Innovus DB when the
        generated Tcl is sourced.  It therefore does not depend on the GUI's
        cached __IOPADT_LITERAL_001__/fact model being populated at render time.  The operation is
        idempotent and changes preservation only; it does not alter connectivity.
        """
        return "\n".join(
            [
                _iopadt_expand_text("# V128.24 runtime __IOPADT_LITERAL_002__ dont_touch fallback (live Innovus DB)"),
                "set TT_IOPAD_RTE_DONT_TOUCH_COUNT 0",
                "foreach TT_IOPAD_RTE_NET_OBJ [get_db nets RTE_D*] {",
                "    set TT_IOPAD_RTE_NET_NAME [get_db $TT_IOPAD_RTE_NET_OBJ .name]",
                "    if {[llength [get_nets $TT_IOPAD_RTE_NET_NAME]] == 1} {",
                "        set_dont_touch [get_nets $TT_IOPAD_RTE_NET_NAME] true",
                "        incr TT_IOPAD_RTE_DONT_TOUCH_COUNT",
                _iopadt_expand_text('        puts "INFO: ioPADt __IOPADT_LITERAL_002__ dont_touch applied: $TT_IOPAD_RTE_NET_NAME"'),
                "    }",
                "}",
                _iopadt_expand_text('puts "INFO: ioPADt __IOPADT_LITERAL_002__ dont_touch total=$TT_IOPAD_RTE_DONT_TOUCH_COUNT"'),
                "unset -nocomplain TT_IOPAD_RTE_NET_OBJ TT_IOPAD_RTE_NET_NAME TT_IOPAD_RTE_DONT_TOUCH_COUNT",
            ]
        ) + "\n"

    def _global_net_bind_rte_dont_touch_block(self, source_text):
        """V128.24: persist __IOPADT_LITERAL_002__ preservation in emitted global_net.tcl.

        V128.23 depended only on the GUI's cached __IOPADT_LITERAL_002__ model when rendering the
        source file.  That can legitimately be empty/stale even though RTE_D*
        exists in the live Innovus DB, which made the emitted protection block
        disappear.  V128.24 keeps the explicit model-derived nets when present
        and ALWAYS adds a live-DB RTE_D* fallback.  The managed block is placed
        at the END of global_net.tcl so it runs after the file's normal global
        net commands.
        """
        text = str(source_text or "")
        begin = re.escape(GLOBAL_NET_SOURCE_RTE_DONT_TOUCH_BEGIN.strip())
        end = re.escape(GLOBAL_NET_SOURCE_RTE_DONT_TOUCH_END.strip())
        text = re.sub(
            r"(?ms)^\s*" + begin + r".*?^\s*" + end + r"\s*",
            "",
            text,
            count=1,
        )

        use_repair = bool(self.repair_entries and self.repair_facts)
        entries = (
            self.repair_entries
            if use_repair
            else (self.physical_ring or self.entries)
        )
        facts = self.repair_facts if use_repair else self.facts
        domain_by_name = (
            self.repair_domain_by_name
            if use_repair
            else self.domain_by_name
        )
        protect_nets = set()
        for entry in entries or []:
            fact = facts.get(entry.name) if facts else None
            if fact is None or not fact.found:
                continue
            if _iopadt_expand_text("__IOPADT_LITERAL_002__") not in (getattr(fact, "pins", None) or set()):
                continue
            domain_id = domain_by_name.get(entry.name)
            target = (
                self._global_net_get_domain_manual_target(domain_id, _iopadt_expand_text("__IOPADT_LITERAL_002__"))
                if domain_id is not None
                else ""
            )
            if target:
                protect_nets.add(str(target))
            else:
                for net in (fact.pin_nets.get(_iopadt_expand_text("__IOPADT_LITERAL_002__")) or []):
                    if net:
                        protect_nets.add(str(net))

        lines = [
            GLOBAL_NET_SOURCE_RTE_DONT_TOUCH_BEGIN.rstrip("\n"),
            "# Auto-generated by ioPADt V128.24.",
            _iopadt_expand_text("# __IOPADT_LITERAL_002__ is an IO-ring SIGNAL network, not a PG global net."),
            _iopadt_expand_text("# Preserve known __IOPADT_LITERAL_002__ targets plus a live-DB RTE_D* fallback."),
        ]
        for net in sorted(protect_nets):
            net_q = self._tcl_brace(net)
            lines += [
                f"if {{[llength [get_db nets {net_q}]] == 1}} {{",
                f"    set_dont_touch [get_nets {net_q}] true",
                _iopadt_expand_text(f'    puts "INFO: global_net.tcl __IOPADT_LITERAL_002__ ring net {net} dont_touch=true"'),
                "} else {",
                _iopadt_expand_text(f'    puts "**WARN: global_net.tcl __IOPADT_LITERAL_002__ ring net {net} missing/ambiguous; explicit dont_touch skipped"'),
                "}",
            ]

        lines.append(self._global_net_rte_runtime_dont_touch_tcl_block().rstrip("\n"))
        lines.append(GLOBAL_NET_SOURCE_RTE_DONT_TOUCH_END.rstrip("\n"))
        block = "\n".join(lines) + "\n"

        # Important: append, do not prepend.  The protection must execute after
        # the ordinary global_net.tcl commands in case the file creates/changes
        # a net before preservation is applied.
        if text and not text.endswith("\n"):
            text += "\n"
        return text + "\n" + block

    def _global_net_rte_apply_tcl_block(self, include_protection=True):
        """V129 + V128.25: build the managed __IOPADT_LITERAL_002__ SIGNAL connectivity patch.

        Existing V129 behavior is intentionally preserved: domains with an
        explicit __IOPADT_LITERAL_002__ target are connected with create_net/connect_pin and __IOPADT_LITERAL_002__
        is never converted into a connect_global_net PG rule.

        V128.25 uses include_protection=False when embedding the connectivity
        in canonical global_net.tcl, because dont_touch has its own managed
        source block.  The default True keeps backward-compatible callers safe.

        Returns (tcl_text, applied_domains, skipped_notes).
        """
        targets = {
            d: net
            for (d, pin), net in self.global_net_domain_pin_manual_targets.items()
            if pin == _iopadt_expand_text("__IOPADT_LITERAL_002__") and net
        }

        # V128.22: protect ALL configured library token nets represented by the current IO-ring
        # model, not only domains that happen to have a pending Set/Repair.
        # For a domain with a pending manual target, protect the target that
        # this Apply is about to create/connect. Otherwise protect the live
        # configured library token net already queried from Innovus. This keeps the protection
        # attached to the actual IO-ring connectivity without hard-coding
        # RTE_D1..RTE_D8 names.
        use_repair = bool(self.repair_entries and self.repair_facts)
        entries = (
            self.repair_entries
            if use_repair
            else (self.physical_ring or self.entries)
        )
        facts = self.repair_facts if use_repair else self.facts
        domain_by_name = (
            self.repair_domain_by_name
            if use_repair
            else self.domain_by_name
        )
        protect_nets = set()
        for entry in entries or []:
            fact = facts.get(entry.name) if facts else None
            if fact is None or not fact.found:
                continue
            if _iopadt_expand_text("__IOPADT_LITERAL_002__") not in (getattr(fact, "pins", None) or set()):
                continue
            domain_id = domain_by_name.get(entry.name)
            target = (
                self._global_net_get_domain_manual_target(domain_id, _iopadt_expand_text("__IOPADT_LITERAL_002__"))
                if domain_id is not None
                else ""
            )
            if target:
                protect_nets.add(str(target))
            else:
                for net in (fact.pin_nets.get(_iopadt_expand_text("__IOPADT_LITERAL_002__")) or []):
                    if net:
                        protect_nets.add(str(net))

        if not targets and not protect_nets:
            return "", [], []

        lines = [
            "# =============================================================",
            _iopadt_expand_text("# V129 MANAGED __IOPADT_LITERAL_002__ SIGNAL PATCH (connect_pin, not connect_global_net)"),
        ]
        if include_protection:
            lines += [
                _iopadt_expand_text("# V128.22: __IOPADT_LITERAL_002__ IO-ring nets are also protected with set_dont_touch"),
                "# so Innovus optimization cannot insert core buffers/repeaters.",
            ]
        else:
            lines += [
                "# V128.25: connectivity-only canonical-source form.",
                "# dont_touch is emitted by its separate managed source block.",
            ]
        lines.append("# =============================================================")
        applied = []
        notes = []
        for domain_id in sorted(
            targets, key=lambda x: (0, int(x)) if str(x).isdigit() else (1, str(x))
        ):
            target = targets[domain_id]
            instances = self._global_net_rte_domain_pad_instances(domain_id)
            if not instances:
                notes.append(
                    _iopadt_expand_text(f"D{domain_id} __IOPADT_LITERAL_002__: target {target} set, but this domain "
                    "has no __IOPADT_LITERAL_001__ exposing an __IOPADT_LITERAL_002__ pin right now - skipped.")
                )
                continue
            net_q = self._tcl_brace(target)
            lines += [
                # V129 FIX: create_net in this Innovus environment requires
                # the Common UI -name flag (bare positional `create_net
                # {name}` errors out - "while executing create_net {RTE_D1}"
                # was the exact failure reported). Matches the already-
                # working TT_IOPAD_CREATE_SIGNAL_NET_IF_MISSING pattern the
                # DB patch uses for the configured library token private tie net: `create_net
                # -name $name`, `get_db nets $name` (no -quiet).
                f"if {{[llength [get_db nets {net_q}]] == 0}} {{",
                f"    create_net -name {net_q}",
                _iopadt_expand_text(f'    puts "INFO: __IOPADT_LITERAL_002__ D{domain_id} created net {target}"'),
                "}",
            ]
            for _internal, instance in instances:
                inst_q = self._tcl_brace(instance)
                lines += [
                    _iopadt_expand_text(f"connect_pin -inst {inst_q} -pin __IOPADT_LITERAL_002__ -net {net_q}"),
                    # V129 FIX: this puts message originally wrote a literal
                    # "[connect_pin]" tag for the log, but Tcl double-quoted
                    # strings treat [...] as COMMAND SUBSTITUTION - it was
                    # actually re-invoking connect_pin with ZERO arguments,
                    # which is exactly the "Wrong number of arguments
                    # specified for command connect_pin" (IMPTCM-32) error
                    # reported, immediately AFTER the real, correctly-argued
                    # connect_pin call two lines above had already run fine.
                    # Parentheses instead of brackets avoid the substitution
                    # entirely - no escaping to get subtly wrong a second time.
                    _iopadt_expand_text(f'puts "INFO: __IOPADT_LITERAL_002__ D{domain_id} {instance}.__IOPADT_LITERAL_002__ -> {target} (connect_pin)"'),
                ]
            applied.append(domain_id)

        if include_protection and protect_nets:
            lines += [
                "",
                "# -------------------------------------------------------------",
                _iopadt_expand_text("# V128.22 __IOPADT_LITERAL_002__ IO-RING OPTIMIZATION PROTECTION"),
                "# Preservation only: do not alter routing/connectivity here.",
                "# -------------------------------------------------------------",
            ]
            for net in sorted(protect_nets):
                net_q = self._tcl_brace(net)
                lines += [
                    f"if {{[llength [get_db nets {net_q}]] > 0}} {{",
                    f"    set_dont_touch [get_nets {net_q}] true",
                    _iopadt_expand_text(f'    puts "INFO: __IOPADT_LITERAL_002__ ring net {net} protected (set_dont_touch=true)"'),
                    "} else {",
                    _iopadt_expand_text(f'    puts "WARN: __IOPADT_LITERAL_002__ ring net {net} was not found; protection skipped"'),
                    "}",
                ]

        return "\n".join(lines) + "\n", applied, notes

    def _global_net_span_at_line(
        self,
        source_text,
        line_no,
        command_text="",
    ):
        """
        Find one active logical Tcl command span by its checked start line.
        Command text is used as a safety discriminator when available.
        """
        try:
            target_line = int(line_no)
        except Exception:
            target_line = -1

        target_norm = self._gn_normalize_command_text(
            command_text
        )

        candidates = []

        for span in self._gn_logical_command_spans(
            source_text
        ):
            parsed = self._gn_parse_any_connect_line(
                span.get("command", "")
            )

            if parsed is None:
                continue

            if (
                target_line > 0
                and int(span.get("start_line", -1))
                != target_line
            ):
                continue

            if (
                target_norm
                and span.get("norm", "")
                != target_norm
            ):
                continue

            candidates.append(span)

        if len(candidates) == 1:
            return candidates[0]

        # Fallback to exact normalized command when line number moved after
        # a previous repair iteration.
        if target_norm:
            matches = []

            for span in self._gn_logical_command_spans(
                source_text
            ):
                if span.get("norm", "") == target_norm:
                    matches.append(span)

            if len(matches) == 1:
                return matches[0]

        return None

    def _global_net_command_with_override(
        self,
        command_text,
    ):
        """
        Return a one-line active connect_global_net command with -override.

        This intentionally preserves all existing command tokens and only
        appends -override when neither override form is already present.
        """
        command = self._gn_normalize_command_text(
            command_text
        )

        parsed = self._gn_parse_any_connect_line(
            command
        )

        if parsed is None:
            raise ValueError(
                "Cannot add -override to non-connect_global_net command."
            )

        if (
            parsed.get("override")
            or parsed.get("netlist_override")
        ):
            return command + "\n"

        return command + " -override\n"

    def _global_net_replace_command_span(
        self,
        source_text,
        span,
        replacement_command,
    ):
        replacement = str(
            replacement_command or ""
        )

        if replacement and not replacement.endswith("\n"):
            replacement += "\n"

        return (
            source_text[:span["start"]]
            + replacement
            + source_text[span["end"]:]
        )

    def _global_net_swap_conflict_commands(
        self,
        source_text,
        earlier_span,
        later_span,
        later_replacement,
    ):
        """
        Put the original later command at the earlier position and put the
        selected authoritative earlier command (with override) at the later
        position. Text/comments between the two logical commands are preserved.
        """
        if earlier_span["start"] >= later_span["start"]:
            raise ValueError(
                "Conflict command order is not earlier -> later."
            )

        middle = source_text[
            earlier_span["end"]:
            later_span["start"]
        ]

        earlier_replacement = (
            self._gn_normalize_command_text(
                later_span["command"]
            )
            + "\n"
        )

        later_replacement = str(
            later_replacement or ""
        )

        if not later_replacement.endswith("\n"):
            later_replacement += "\n"

        return (
            source_text[:earlier_span["start"]]
            + earlier_replacement
            + middle
            + later_replacement
            + source_text[later_span["end"]:]
        )

    def _global_net_apply_rebased_text_no_undo(
        self,
        new_text,
    ):
        """
        Materialize generated Tcl as the working copy without pushing another
        Undo snapshot. Auto Repair owns one batch Undo snapshot.
        """
        new_text = str(new_text or "")

        if new_text and not new_text.endswith("\n"):
            new_text += "\n"

        self.global_net_lines = new_text.splitlines(
            keepends=True
        )
        self.global_net_full_cmd_edits = []
        self.global_net_full_cmd_edit_seq = 0
        self.global_net_cmd_editor_target = None
        self.global_net_selected_id = ""
        self._global_net_detect_rules()

    def _global_net_parse_overlap_lines(
        self,
        item,
    ):
        raw = str(item.get("line", "") or "")
        mm = re.match(
            r"\s*(\d+)\s*->\s*(\d+)\s*$",
            raw,
        )

        if not mm:
            return None, None

        return int(mm.group(1)), int(mm.group(2))

    def _global_net_fact_for_display_instance(
        self,
        display_name,
    ):
        use_repair = bool(
            self.repair_entries
            and self.repair_facts
        )

        entries = (
            self.repair_entries
            if use_repair
            else (
                self.physical_ring
                or self.entries
            )
        )
        facts = (
            self.repair_facts
            if use_repair
            else self.facts
        )

        for entry in entries:
            fact = facts.get(
                entry.name
            )

            if fact is None or not fact.found:
                continue

            shown = (
                self._repair_display_name(
                    entry.name
                )
                if use_repair
                else entry.name
            )

            if shown == display_name:
                return (
                    entry.name,
                    shown,
                    fact,
                )

        return (
            "",
            "",
            None,
        )

    def _global_net_conflict_group_for_item(
        self,
        source_text,
        item,
    ):
        """
        Rebuild the COMPLETE current candidate list for one actual target.

        Never reuse pairwise validator spans from a previous mutation.
        """
        instance = str(
            item.get(
                "instance",
                "",
            )
            or ""
        )
        pin = str(
            item.get(
                "pin",
                "",
            )
            or ""
        )

        _internal, shown, fact = (
            self._global_net_fact_for_display_instance(
                instance
            )
        )

        if fact is None:
            raise ValueError(
                "Cannot resolve conflict target instance: "
                + instance
            )

        rules = (
            self._global_net_final_rules_from_text(
                source_text
            )
        )
        io_pd_info = (
            self._global_net_find_io_power_domain(
                rules
            )
        )

        selected = (
            self._gn_select_rules_for_ring_pin(
                rules,
                shown,
                pin,
                io_pd_info,
                fact,
            )
        )

        candidates = list(
            selected.get(
                "rules",
                [],
            )
        )

        group = []

        for idx, rule in enumerate(
            candidates,
            1,
        ):
            command = str(
                rule.get(
                    "command",
                    "",
                )
                or ""
            )
            line = int(
                rule.get(
                    "line",
                    0,
                )
                or 0
            )

            span = (
                self._global_net_span_at_line(
                    source_text,
                    line,
                    command,
                )
            )

            if span is None:
                raise ValueError(
                    "Cannot locate current command span "
                    f"for conflict candidate line={line}."
                )

            group.append({
                "candidate_id": idx,
                "line": line,
                "net": str(
                    rule.get(
                        "net",
                        "",
                    )
                    or ""
                ),
                "override": bool(
                    rule.get(
                        "override"
                    )
                    or rule.get(
                        "netlist_override"
                    )
                ),
                "command": command,
                "rule": rule,
                "span": span,
            })

        return {
            "instance": shown,
            "pin": pin,
            "scope": str(
                selected.get(
                    "scope",
                    "-",
                )
            ),
            "candidates": group,
        }

    def _global_net_rewrite_nway_conflict(
        self,
        source_text,
        group,
        mode,
        selected_index,
    ):
        """
        Resolve one complete N-way target conflict in one atomic text rewrite.

        mode=KEEP_SELECTED_ONLY:
          delete every other command in the target candidate group.

        mode=KEEP_ALL_OVERRIDE:
          preserve all commands, make the selected command authoritative by
          placing it in the last candidate slot, and ensure every command after
          the first has -override. This removes every blocking adjacent overlap.
        """
        candidates = list(
            group.get(
                "candidates",
                [],
            )
        )

        if len(candidates) < 2:
            raise ValueError(
                "N-way conflict group has fewer than two candidates."
            )

        try:
            selected_index = int(
                selected_index
            )
        except Exception:
            selected_index = -1

        if (
            selected_index < 0
            or selected_index >= len(
                candidates
            )
        ):
            raise ValueError(
                "Select one authoritative command."
            )

        replacements = {}

        if mode == "KEEP_SELECTED_ONLY":
            for idx, candidate in enumerate(
                candidates
            ):
                span = candidate[
                    "span"
                ]

                replacements[
                    span["start"]
                ] = (
                    candidate["command"]
                    if idx == selected_index
                    else ""
                )

        elif mode == "KEEP_ALL_OVERRIDE":
            selected = candidates[
                selected_index
            ]

            ordered = [
                c
                for idx, c in enumerate(
                    candidates
                )
                if idx != selected_index
            ] + [
                selected
            ]

            # Fill the existing candidate slots in order. This preserves all
            # comments/text between commands, while selected authoritative cmd
            # becomes the last effective command for this actual target.
            slots = sorted(
                (
                    c["span"]
                    for c in candidates
                ),
                key=lambda span: span[
                    "start"
                ],
            )

            for idx, (
                slot,
                command_source,
            ) in enumerate(
                zip(
                    slots,
                    ordered,
                )
            ):
                command = str(
                    command_source[
                        "command"
                    ]
                )

                if idx > 0:
                    command = (
                        self._global_net_command_with_override(
                            command
                        )
                    )

                replacements[
                    slot["start"]
                ] = command

        else:
            raise ValueError(
                "Unknown N-way conflict mode: "
                + str(mode)
            )

        spans = sorted(
            (
                c["span"]
                for c in candidates
            ),
            key=lambda span: span[
                "start"
            ],
        )

        out = []
        cursor = 0

        for span in spans:
            out.append(
                source_text[
                    cursor:
                    span["start"]
                ]
            )

            replacement = replacements.get(
                span["start"],
                span["command"],
            )

            if replacement:
                replacement = str(
                    replacement
                )

                if not replacement.endswith(
                    "\n"
                ):
                    replacement += "\n"

                out.append(
                    replacement
                )

            cursor = span[
                "end"
            ]

        out.append(
            source_text[cursor:]
        )

        return "".join(
            out
        )

    def _global_net_choose_nway_conflict_action(
        self,
        group,
        apply_callback,
    ):
        """
        One popup for all commands targeting the same actual __IOPADT_LITERAL_001__/PG pin.
        """
        candidates = list(
            group.get(
                "candidates",
                [],
            )
        )

        win = self._safe_toplevel(
            "Global Net Auto Repair - N-Way Command Conflict"
        )
        win.geometry(
            "1040x720"
        )
        win.minsize(
            860,
            560,
        )

        result = {
            "applied": False,
            "mode": None,
            "selected_index": None,
        }

        outer = ttk.Frame(
            win,
            padding=12,
        )
        outer.pack(
            fill="both",
            expand=True,
        )
        outer.columnconfigure(
            0,
            weight=1,
        )
        outer.rowconfigure(
            2,
            weight=1,
        )

        ttk.Label(
            outer,
            text=(
                "connect_global_net N-Way Command Conflict"
            ),
            font=(
                "Segoe UI",
                11,
                "bold",
            ),
        ).grid(
            row=0,
            column=0,
            sticky="w",
        )

        ttk.Label(
            outer,
            text=(
                f"Target={group.get('instance','-')}."
                f"{group.get('pin','-')} | "
                f"Scope={group.get('scope','-')} | "
                f"Commands={len(candidates)}"
            ),
        ).grid(
            row=1,
            column=0,
            sticky="w",
            pady=(4,8),
        )

        columns = (
            "idx",
            "line",
            "net",
            "override",
            "command",
        )

        tree = ttk.Treeview(
            outer,
            columns=columns,
            show="headings",
            selectmode="browse",
            height=12,
        )
        tree.grid(
            row=2,
            column=0,
            sticky="nsew",
        )

        widths = {
            "idx": 55,
            "line": 65,
            "net": 150,
            "override": 90,
            "command": 620,
        }

        headings = {
            "idx": "#",
            "line": "Line",
            "net": "Net",
            "override": "Override",
            "command": "Command",
        }

        for col in columns:
            tree.heading(
                col,
                text=headings[col],
            )
            tree.column(
                col,
                width=widths[col],
                stretch=(
                    col == "command"
                ),
            )

        for idx, candidate in enumerate(
            candidates
        ):
            tree.insert(
                "",
                "end",
                iid=str(idx),
                values=(
                    idx + 1,
                    candidate[
                        "line"
                    ],
                    candidate[
                        "net"
                    ],
                    (
                        "YES"
                        if candidate[
                            "override"
                        ]
                        else "NO"
                    ),
                    self._gn_normalize_command_text(
                        candidate[
                            "command"
                        ]
                    ),
                ),
            )

        if candidates:
            tree.selection_set(
                "0"
            )
            tree.focus(
                "0"
            )

        options = ttk.LabelFrame(
            outer,
            text="Repair Mode",
            padding=10,
        )
        options.grid(
            row=3,
            column=0,
            sticky="ew",
            pady=(10,0),
        )

        mode_var = tk.StringVar(
            value="KEEP_ALL_OVERRIDE"
        )

        ttk.Radiobutton(
            options,
            text=(
                "Keep ALL commands; selected command becomes authoritative "
                "(move it to last effective slot and add -override to every "
                "later overlapping command)"
            ),
            variable=mode_var,
            value="KEEP_ALL_OVERRIDE",
        ).pack(
            anchor="w",
            pady=(0,8),
        )

        ttk.Radiobutton(
            options,
            text=(
                _iopadt_expand_text("Keep SELECTED command only; delete every other command "
                "that targets this same actual __IOPADT_LITERAL_001__/PG pin")
            ),
            variable=mode_var,
            value="KEEP_SELECTED_ONLY",
        ).pack(
            anchor="w",
        )

        status = tk.StringVar(
            value=(
                "Select the authoritative command, choose repair mode, "
                "then Apply or OK."
            )
        )

        ttk.Label(
            outer,
            textvariable=status,
            foreground="#c00000",
        ).grid(
            row=4,
            column=0,
            sticky="w",
            pady=(8,0),
        )

        buttons = ttk.Frame(
            outer
        )
        buttons.grid(
            row=5,
            column=0,
            sticky="e",
            pady=(10,0),
        )

        applied_button = {
            "widget": None,
        }

        def selected_index():
            sel = tree.selection()

            if not sel:
                return None

            try:
                return int(
                    sel[0]
                )
            except Exception:
                return None

        def execute():
            if result[
                "applied"
            ]:
                return True

            idx = selected_index()

            if idx is None:
                status.set(
                    "Select one authoritative command."
                )
                return False

            mode = (
                mode_var.get().strip()
            )

            try:
                ok = bool(
                    apply_callback(
                        mode,
                        idx,
                    )
                )
            except Exception as exc:
                status.set(
                    "Apply failed: "
                    + str(exc)
                )
                return False

            if not ok:
                status.set(
                    "Apply produced no Tcl change."
                )
                return False

            result[
                "applied"
            ] = True
            result[
                "mode"
            ] = mode
            result[
                "selected_index"
            ] = idx

            status.set(
                "Applied: "
                + mode
                + f" | authoritative command #{idx + 1}"
            )

            try:
                applied_button[
                    "widget"
                ].configure(
                    state="disabled"
                )
            except Exception:
                pass

            return True

        def do_apply():
            execute()

        def do_ok():
            if execute():
                try:
                    win.grab_release()
                except Exception:
                    pass
                win.destroy()

        def do_cancel():
            try:
                win.grab_release()
            except Exception:
                pass
            win.destroy()

        apply_btn = ttk.Button(
            buttons,
            text="Apply",
            command=do_apply,
        )
        applied_button[
            "widget"
        ] = apply_btn
        apply_btn.pack(
            side="left"
        )

        ttk.Button(
            buttons,
            text="OK",
            command=do_ok,
        ).pack(
            side="left",
            padx=(6,0),
        )

        ttk.Button(
            buttons,
            text="Cancel",
            command=do_cancel,
        ).pack(
            side="left",
            padx=(6,0),
        )

        win.protocol(
            "WM_DELETE_WINDOW",
            do_cancel,
        )

        try:
            win.transient(
                self
            )
            win.grab_set()
        except Exception:
            pass

        win.wait_window()

        return (
            result
            if result[
                "applied"
            ]
            else None
        )

    def _global_net_choose_cmd_conflict_action(
        self,
        item,
        previous_command,
        current_command,
        apply_callback,
    ):
        """
        Explicit user decision for every blocking command overlap.

        Apply:
          execute the selected repair immediately and keep popup open.

        OK:
          execute if not already applied, then close.

        Return selected action when a repair was actually applied,
        otherwise None.
        """
        prev = self._gn_parse_any_connect_line(
            previous_command
        ) or {}
        curr = self._gn_parse_any_connect_line(
            current_command
        ) or {}

        win = self._safe_toplevel(
            "Global Net Auto Repair - Command Conflict"
        )
        win.geometry("920x650")
        win.minsize(760, 520)

        result = {
            "action": None,
            "applied": False,
        }

        outer = ttk.Frame(
            win,
            padding=12,
        )
        outer.pack(
            fill="both",
            expand=True,
        )
        outer.columnconfigure(
            0,
            weight=1,
        )
        outer.rowconfigure(
            4,
            weight=1,
        )

        ttk.Label(
            outer,
            text="connect_global_net Command Conflict",
            font=("Segoe UI", 11, "bold"),
        ).grid(
            row=0,
            column=0,
            sticky="w",
        )

        target = (
            f"Target: {item.get('instance','-')}."
            f"{item.get('pin','-')} | "
            f"Scope={item.get('scope','-')} | "
            f"Lines={item.get('line','-')}"
        )

        ttk.Label(
            outer,
            text=target,
            wraplength=860,
        ).grid(
            row=1,
            column=0,
            sticky="w",
            pady=(4,10),
        )

        compare = ttk.Frame(outer)
        compare.grid(
            row=2,
            column=0,
            sticky="ew",
        )
        compare.columnconfigure(
            0,
            weight=1,
        )
        compare.columnconfigure(
            1,
            weight=1,
        )

        left = ttk.LabelFrame(
            compare,
            text=(
                "Earlier Command"
                + (
                    f" | Net={prev.get('net','')}"
                    if prev.get("net")
                    else ""
                )
            ),
            padding=8,
        )
        left.grid(
            row=0,
            column=0,
            sticky="nsew",
            padx=(0,5),
        )

        right = ttk.LabelFrame(
            compare,
            text=(
                "Later Command"
                + (
                    f" | Net={curr.get('net','')}"
                    if curr.get("net")
                    else ""
                )
            ),
            padding=8,
        )
        right.grid(
            row=0,
            column=1,
            sticky="nsew",
            padx=(5,0),
        )

        for parent, command in (
            (left, previous_command),
            (right, current_command),
        ):
            box = tk.Text(
                parent,
                height=8,
                wrap="word",
                font=("Consolas", 9),
            )
            box.pack(
                fill="both",
                expand=True,
            )
            box.insert(
                "1.0",
                self._gn_normalize_command_text(
                    command
                ),
            )
            box.configure(
                state="disabled",
            )

        ttk.Label(
            outer,
            text=(
                "Choose how Auto Repair should resolve this conflict. "
                "Apply executes immediately and keeps this popup open; "
                "OK executes and closes."
            ),
            wraplength=860,
        ).grid(
            row=3,
            column=0,
            sticky="w",
            pady=(12,6),
        )

        action = tk.StringVar(
            value="ADD_OVERRIDE_LATER"
        )

        options = ttk.LabelFrame(
            outer,
            text="Repair Action",
            padding=10,
        )
        options.grid(
            row=4,
            column=0,
            sticky="nsew",
        )

        radios = []

        rb = ttk.Radiobutton(
            options,
            text=(
                "Add -override to Later Command "
                "(keep both commands; later command wins where they overlap)"
            ),
            variable=action,
            value="ADD_OVERRIDE_LATER",
        )
        rb.pack(
            anchor="w",
            pady=(0,8),
        )
        radios.append(rb)

        rb = ttk.Radiobutton(
            options,
            text=(
                "Keep Earlier Command Only "
                "(delete the later conflicting command)"
            ),
            variable=action,
            value="KEEP_EARLIER",
        )
        rb.pack(
            anchor="w",
            pady=(0,8),
        )
        radios.append(rb)

        rb = ttk.Radiobutton(
            options,
            text=(
                "Keep Later Command Only "
                "(delete the earlier conflicting command)"
            ),
            variable=action,
            value="KEEP_LATER",
        )
        rb.pack(
            anchor="w",
        )
        radios.append(rb)

        status = tk.StringVar(
            value="Choose an action, then Apply or OK."
        )

        ttk.Label(
            outer,
            textvariable=status,
        ).grid(
            row=5,
            column=0,
            sticky="w",
            pady=(10,0),
        )

        buttons = ttk.Frame(outer)
        buttons.grid(
            row=6,
            column=0,
            sticky="e",
            pady=(12,0),
        )

        apply_button = None

        def execute_choice():
            if result["applied"]:
                return True

            selected = (
                action.get().strip()
                or None
            )

            if not selected:
                status.set(
                    "No repair action selected."
                )
                return False

            try:
                ok = bool(
                    apply_callback(selected)
                )
            except Exception as exc:
                status.set(
                    "Apply failed: "
                    + str(exc)
                )
                return False

            if not ok:
                status.set(
                    "Apply failed; no Tcl change was made."
                )
                return False

            result["action"] = selected
            result["applied"] = True

            status.set(
                "Applied: " + selected
            )

            for radio in radios:
                try:
                    radio.configure(
                        state="disabled"
                    )
                except Exception:
                    pass

            try:
                apply_button.configure(
                    state="disabled"
                )
            except Exception:
                pass

            return True

        def apply_choice():
            execute_choice()

        def ok_choice():
            if execute_choice():
                try:
                    win.grab_release()
                except Exception:
                    pass
                win.destroy()

        def cancel():
            # Cancel never rolls back an already executed Apply.
            try:
                win.grab_release()
            except Exception:
                pass
            win.destroy()

        apply_button = ttk.Button(
            buttons,
            text="Apply",
            command=apply_choice,
        )
        apply_button.pack(
            side="left",
        )

        ttk.Button(
            buttons,
            text="OK",
            command=ok_choice,
        ).pack(
            side="left",
            padx=(6,0),
        )

        ttk.Button(
            buttons,
            text="Cancel",
            command=cancel,
        ).pack(
            side="left",
            padx=(6,0),
        )

        win.protocol(
            "WM_DELETE_WINDOW",
            cancel,
        )

        try:
            win.transient(self)
        except Exception:
            pass

        try:
            win.grab_set()
        except Exception:
            pass

        win.wait_window()

        return (
            result["action"]
            if result["applied"]
            else None
        )

    def _global_net_auto_repair_cmd_conflicts(
        self,
        ensure_undo,
        changes,
        skipped,
    ):
        """
        V84 N-way command-conflict repair.

        One actual target with N=2/3/4/... active commands is handled in ONE
        popup. After each repair, the tool completely re-renders and re-parses
        the final Tcl before discovering the next target conflict.
        """
        max_iterations = 500
        iteration = 0
        changed = 0

        while iteration < max_iterations:
            iteration += 1

            # CRITICAL: every iteration starts from the CURRENT authoritative
            # working text. No span/line/rule from a previous mutation survives.
            source_text = (
                self._render_global_net_text()
            )

            readiness = (
                self._global_net_check_save_readiness(
                    source_text
                )
            )

            overlap_errors = [
                item
                for item in readiness.get(
                    "errors",
                    [],
                )
                if item.get(
                    "issue"
                ) == "TARGET_OVERLAP"
            ]

            if not overlap_errors:
                break

            # Any pairwise overlap record identifies the target. Rebuild the
            # complete current N-way candidate group for that target.
            item = overlap_errors[
                0
            ]

            try:
                group = (
                    self._global_net_conflict_group_for_item(
                        source_text,
                        item,
                    )
                )
            except Exception as exc:
                skipped.append(
                    "CMD CONFLICT: cannot rebuild current N-way group | "
                    + str(exc)
                )
                break

            candidates = group.get(
                "candidates",
                [],
            )

            if len(candidates) < 2:
                skipped.append(
                    "CMD CONFLICT: rebuilt target group has fewer than "
                    "two commands."
                )
                break

            def apply_action(
                mode,
                selected_index,
            ):
                ensure_undo()

                # Use exactly the source/group captured for THIS popup.
                # After this callback completes, this popup is done; the outer
                # loop will rebuild everything from scratch.
                new_text = (
                    self._global_net_rewrite_nway_conflict(
                        source_text,
                        group,
                        mode,
                        selected_index,
                    )
                )

                if new_text == source_text:
                    return False

                self._global_net_apply_rebased_text_no_undo(
                    new_text
                )

                selected = candidates[
                    selected_index
                ]

                if mode == "KEEP_SELECTED_ONLY":
                    description = (
                        "CMD CONFLICT "
                        f"{group.get('instance','-')}."
                        f"{group.get('pin','-')} "
                        f"N={len(candidates)} "
                        f"-> keep command #{selected_index + 1} only "
                        f"net={selected.get('net','-')}"
                    )
                else:
                    description = (
                        "CMD CONFLICT "
                        f"{group.get('instance','-')}."
                        f"{group.get('pin','-')} "
                        f"N={len(candidates)} "
                        f"-> keep all + explicit overrides; "
                        f"authoritative command #{selected_index + 1} "
                        f"net={selected.get('net','-')}"
                    )

                changes.append(
                    description
                )

                return True

            result = (
                self._global_net_choose_nway_conflict_action(
                    group,
                    apply_action,
                )
            )

            if not result:
                skipped.append(
                    "CMD CONFLICT: user closed/cancelled without applying "
                    f"{group.get('instance','-')}."
                    f"{group.get('pin','-')} "
                    f"N={len(candidates)}"
                )
                break

            changed += 1

        if iteration >= max_iterations:
            skipped.append(
                "CMD CONFLICT: iteration limit reached."
            )

        return changed

    def _global_net_domain_manual_target_key(self, domain_id, pin):
        return (str(domain_id), str(pin))

    def _global_net_get_domain_manual_target(self, domain_id, pin):
        return self.global_net_domain_pin_manual_targets.get(
            self._global_net_domain_manual_target_key(domain_id, pin), ""
        )

    def _global_net_set_domain_manual_target(self, domain_id, pin, net):
        """Record (or clear, if net is blank) an explicit user-set target
        net for one (IO Domain, pin). This is the "Set" half of the new IO
        Domain Sources editor; "Repair This Domain" is the half that
        actually pushes it into pending Global Net Tcl by reusing the same
        per-pad override machinery Auto Repair already uses.

        Exclusive pins (__IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__/__IOPADT_LITERAL_014__) are validated here so a
        typo can't silently create a cross-domain collision the user won't
        notice until Apply fails; __IOPADT_LITERAL_006__ is exempt because sharing one __IOPADT_LITERAL_006__
        rail across multiple IO Domains is normal, not an error.
        """
        pin = str(pin or "").strip()
        net = str(net or "").strip()
        domain_key = str(domain_id)

        if pin not in GLOBAL_NET_DOMAIN_SETTABLE_PINS:
            raise ValueError(
                f"{pin} is not settable at IO Domain granularity "
                f"(only {', '.join(GLOBAL_NET_DOMAIN_SETTABLE_PINS)} are)."
            )

        key = self._global_net_domain_manual_target_key(domain_id, pin)
        if not net:
            self.global_net_domain_pin_manual_targets.pop(key, None)
            return

        if pin in GLOBAL_NET_DOMAIN_EXCLUSIVE_PINS:
            for (d, p), existing_net in self.global_net_domain_pin_manual_targets.items():
                if p == pin and d != domain_key and existing_net == net:
                    raise ValueError(
                        f"{pin}={net} is already manually assigned to IO "
                        f"Domain D{d}. {pin} must be unique per IO Domain - "
                        "choose a different net, or clear that domain's "
                        "setting first."
                    )

        self.global_net_domain_pin_manual_targets[key] = net
        dbg(f"GLOBAL_NET_DOMAIN_MANUAL_SET D{domain_key} pin={pin} net={net}")

    def _global_net_domain_pin_matrix(self):
        """Return {domain_id: {pin: display_string}} for the 5 IO-Domain-
        settable pins (__IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__/__IOPADT_LITERAL_014__/__IOPADT_LITERAL_006__), for the "IO Domain
        Sources" editor columns. One _global_net_compare_design() call,
        reused across every domain/pin rather than recomputed per cell.

        Display string is the resolved net when every member pad in that
        domain agrees, "<mixed>" when they disagree, "" when none resolve
        at all, with " -> <manual> (pending)" appended whenever a manual
        target (Set) differs from what is currently actually resolved -
        so the table visibly shows "this domain still needs Repair".
        """
        if not (self.global_net_path or self.global_net_lines):
            return {}
        try:
            comp = self._global_net_compare_design(force_db_actual=False)
        except Exception:
            return {}

        raw = {}
        for _internal, row in comp.get("pads", {}).items():
            domain_id = row.get("domain_id")
            if domain_id is None:
                continue
            domain_key = str(domain_id)
            bucket = raw.setdefault(
                domain_key,
                {p: set() for p in GLOBAL_NET_DOMAIN_SETTABLE_PINS},
            )
            for pin in GLOBAL_NET_DOMAIN_SETTABLE_PINS:
                pres = row.get("pin_results", {}).get(pin)
                if pres is None:
                    continue
                bucket[pin].update(self._gn_resolved_net_set(pres))

        display = {}
        for domain_key, pins in raw.items():
            display[domain_key] = {}
            for pin, nets in pins.items():
                if len(nets) == 1:
                    val = next(iter(nets))
                elif not nets:
                    val = ""
                else:
                    val = "<mixed>"
                manual = self._global_net_get_domain_manual_target(domain_key, pin)
                if manual and manual != val:
                    display[domain_key][pin] = f"{val or '-'} -> {manual} (pending)"
                else:
                    display[domain_key][pin] = val
        return display

    def _global_net_reconcile_domain_supply_pins_pending(
        self,
        comp,
        ensure_undo,
        changes,
        skipped,
        origin="GN_AUTO_DOMAIN_RECONCILE",
        only_domain_id=None,
    ):
        """Deterministically reconcile __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__ per __IOPADT_LITERAL_003__ IO
        Domain (__IOPADT_LITERAL_014__ uses its own dedicated J-naming function).

        This helper is intentionally independent of policy-issue generation.
        It derives the desired mapping directly from actual __IOPADT_LITERAL_001__-pin membership
        in each __IOPADT_LITERAL_003__-defined IO Domain, so an already-broken checker state
        cannot prevent repair from seeing the PADs that need repair.

        Rules:
          * __IOPADT_LITERAL_005__ is optional; a domain with no __IOPADT_LITERAL_005__ pin is skipped.
          * Within one domain every exposed pin gets one authoritative net.
          * Different domains never share the same net for the same pin.
          * A manually-set target (IO Domain Sources editor) always wins
            over the deterministic <PIN>_D<domain> guess (V129).
          * Only GUI pending Tcl is changed; this helper never calls Innovus.

        only_domain_id: V129, optional. When given (as int or the same type
        stored in row["domain_id"]), every OTHER domain is left completely
        untouched - used by the new "Repair This Domain" button so it never
        has side effects on the other 7 domains. Default None preserves the
        original all-domains behavior exactly.
        """
        existing_names = set(self._global_net_effective_net_names())
        existing_names.update(
            str(r.get("net", "") or "")
            for r in self._global_net_all_pg_rules()
            if str(r.get("net", "") or "")
        )
        # Also reserve every PG net reported by the fresh Innovus query.
        # A stale wrong-polarity net must never be silently reused.
        existing_names.update(self._global_net_db_pg_net_polarities())
        allocated_names = set(existing_names)
        targets = {}

        def sort_domain(value):
            return (0, int(value)) if str(value).isdigit() else (1, str(value))

        # V129 CORRECTION: configured library token was briefly added and reverted - see the
        # GLOBAL_NET_DOMAIN_EXCLUSIVE_PINS comment. configured library token is a SIGNAL pin,
        # not a PG pin, so it never appears in pin_results here at all.
        for pin in (_iopadt_expand_text("__IOPADT_LITERAL_004__"), _iopadt_expand_text("__IOPADT_LITERAL_005__"), _iopadt_expand_text("__IOPADT_LITERAL_013__")):
            domain_rows = {}
            for internal, row in comp.get("pads", {}).items():
                domain_id = row.get("domain_id")
                if domain_id is None:
                    continue
                pres = row.get("pin_results", {}).get(pin)
                if pres is None:
                    continue
                domain_rows.setdefault(domain_id, []).append((internal, row, pres))

            used_targets = {}
            for domain_id in sorted(domain_rows, key=sort_domain):
                if (
                    only_domain_id is not None
                    and str(domain_id) != str(only_domain_id)
                ):
                    continue

                rows = domain_rows[domain_id]

                # Use raw effective mappings even when the surrounding row is
                # already FAIL because of cross-domain policy. Repair must not
                # become blind merely because the checker has marked a row red.
                candidate_nets = set()
                per_row_nets = {}
                for internal, row, pres in rows:
                    nets = {
                        str(item.get("net", "") or "")
                        for item in (pres.get("effective", []) or [])
                        if str(item.get("net", "") or "")
                    }
                    per_row_nets[internal] = nets
                    candidate_nets.update(nets)

                reason = "REPAIR"
                target = None

                # V129: an explicit manual target (IO Domain Sources editor)
                # always wins over every automatic guess below. "Set" is
                # intent, "Repair" enforces it - they must never fight.
                manual_target = self._global_net_get_domain_manual_target(
                    domain_id, pin
                )
                if manual_target:
                    target = manual_target
                    reason = "MANUAL_SET"
                    allocated_names.add(target)

                # V129 FIX: configured library token/configured library token/configured library token are confirmed domain-exclusive
                # (each configured library token IO Domain must have its OWN net for each of
                # these three pins). The previous "keep existing singleton"
                # shortcut let the FIRST domain processed (D1, since domains
                # are walked in sorted order) silently keep a shared/bare
                # net name (e.g. plain "configured library token" with no _D<n> suffix) simply
                # because used_targets was still empty at that point in the
                # loop - it had no way to know a LATER domain (D2..D8) also
                # currently resolves to that exact same net. Every later
                # domain then correctly got renamed to <PIN>_D<domain>, but
                # D1 was left on the shared bare name, which is exactly the
                # GLOBAL_NET_DOMAIN_EXCLUSIVE pin=configured library token net=configured library token
                # domains=D1..D8 status=FAIL failure seen post-Apply: D1's
                # PST pins were never told to reconnect, so Innovus never
                # moved them off the shared net.
                #
                # Fix: for these three domain-exclusive pins, ALWAYS assign
                # the deterministic <PIN>_D<domain_id> target. No domain -
                # including the first one processed - is allowed to keep an
                # existing bare/shared name. This trades a slightly larger
                # first-run diff (D1 now gets renamed too) for an actually
                # domain-exclusive result on every domain, every time.
                candidate_singleton = (
                    next(iter(candidate_nets)) if len(candidate_nets) == 1 else None
                )
                if candidate_singleton is not None and not self._global_net_db_polarity_compatible(
                    candidate_singleton, pin
                ):
                    dbg(
                        "GLOBAL_NET_STALE_POLARITY_REJECT "
                        f"D{domain_id} pin={pin} net={candidate_singleton} "
                        f"db_polarity={self._global_net_db_net_polarity(candidate_singleton)} "
                        f"expected={self._global_net_expected_net_polarity(candidate_singleton, pin)}"
                    )

                if target is None:
                    base = f"{pin}_D{domain_id}"
                    target = base

                    # Reuse the deterministic base only when it is not already
                    # owned by another domain and either does not exist yet or
                    # is already one of this domain's observed candidates.
                    base_safe = (
                        base not in used_targets
                        and (base not in existing_names or base in candidate_nets)
                        and self._global_net_db_polarity_compatible(base, pin)
                    )
                    if not base_safe:
                        target = self._global_net_unique_autonet(
                            base,
                            allocated_names,
                        )
                    else:
                        allocated_names.add(target)

                    reason = (
                        "SPLIT_SHARED"
                        if len(candidate_nets) == 1
                        else ("CREATE_MISSING" if not candidate_nets else "RESOLVE_AMBIGUOUS")
                    )

                used_targets[target] = domain_id
                targets[(domain_id, pin)] = target

                dbg(
                    "GLOBAL_NET_AUTO_DOMAIN_TARGET "
                    f"D{domain_id} pin={pin} target={target} reason={reason} "
                    f"candidates={','.join(sorted(candidate_nets)) or '-'} pads={len(rows)}"
                )

                for internal, row, _pres in rows:
                    current = per_row_nets.get(internal, set())
                    if current == {target}:
                        continue
                    ensure_undo()
                    if self._global_net_batch_exact_override(
                        comp,
                        internal,
                        pin,
                        target,
                        origin,
                        domain_id,
                    ):
                        changes.append(
                            f"AUTO D{domain_id} {row['instance']}.{pin}->{target}"
                        )
                    else:
                        skipped.append(
                            f"AUTO D{domain_id} {row['instance']}.{pin}: override not changed"
                        )

        return targets

    def _global_net_reconcile_railcut_vsspst_boundary_pending(
        self,
        comp,
        targets,
        ensure_undo,
        changes,
        skipped,
        origin="GN_AUTO_RAILCUT_VSSPST_BOUNDARY",
    ):
        """Repair __IOPADT_LITERAL_003__ __IOPADT_LITERAL_009__/__IOPADT_LITERAL_010__ from adjacent domain __IOPADT_LITERAL_005__ targets.

        V129 CORRECTION: swapped to __IOPADT_LITERAL_009__=CW/__IOPADT_LITERAL_010__=CCW, matching the
        physical-layout-confirmed fix in
        _global_net_apply_railcut_vsspst_boundary_rules (was __IOPADT_LITERAL_009__=CCW/
        __IOPADT_LITERAL_010__=CW, backwards for this __IOPADT_LITERAL_003__ cell).

        This is pending Tcl only.  It never mutates Innovus DB.  Exact
        -single_inst -override commands are emitted for each __IOPADT_LITERAL_003__ pin.
        """
        use_repair = bool(self.repair_segments)
        adjacent = self._global_net_railcut_adjacent_domains(use_repair)
        changed = 0
        for cut, sides in adjacent.items():
            row = comp.get("pads", {}).get(cut)
            if not row or str(row.get("role", "")) != _iopadt_expand_text("__IOPADT_LITERAL_003__"):
                continue
            for pin, side_key, side_label in (
                (_iopadt_expand_text("__IOPADT_LITERAL_009__"), "cw_domain", "CW"),
                (_iopadt_expand_text("__IOPADT_LITERAL_010__"), "ccw_domain", "CCW"),
            ):
                if pin not in row.get("pin_results", {}):
                    continue
                domain_id = sides.get(side_key)
                target = targets.get((domain_id, _iopadt_expand_text("__IOPADT_LITERAL_005__"))) if domain_id is not None else None
                if not target:
                    skipped.append(
                        _iopadt_expand_text(f"__IOPADT_LITERAL_003__ {row.get('instance', cut)}.{pin}: "
                        f"no D{domain_id if domain_id is not None else '?'} __IOPADT_LITERAL_005__ target")
                    )
                    continue
                current = {
                    str(item.get("net", "") or "")
                    for item in (row.get("pin_results", {}).get(pin, {}).get("effective", []) or [])
                    if str(item.get("net", "") or "")
                }
                if current == {target}:
                    continue
                ensure_undo()
                if self._global_net_batch_exact_override(
                    comp,
                    cut,
                    pin,
                    target,
                    origin,
                    domain_id,
                ):
                    changed += 1
                    changes.append(
                        _iopadt_expand_text(f"__IOPADT_LITERAL_003__ {row.get('instance', cut)}.{pin}->{target} "
                        f"[{side_label}=D{domain_id}]")
                    )
                    dbg(
                        "GLOBAL_NET_AUTO_RAILCUT "
                        f"cut={row.get('instance', cut)} pin={pin} side={side_label} "
                        f"domain=D{domain_id} target={target}"
                    )
        return changed

    def _global_net_domain_supply_residuals(self, comp):
        """Return residual __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__ mapping faults after repair."""
        residual = []
        pins = {_iopadt_expand_text("__IOPADT_LITERAL_004__"), _iopadt_expand_text("__IOPADT_LITERAL_005__"), _iopadt_expand_text("__IOPADT_LITERAL_013__")}

        for internal, row in comp.get("pads", {}).items():
            domain_id = row.get("domain_id")
            for pin in pins:
                pres = row.get("pin_results", {}).get(pin)
                if pres is None:
                    continue
                nets = {
                    str(item.get("net", "") or "")
                    for item in (pres.get("effective", []) or [])
                    if str(item.get("net", "") or "")
                }
                if len(nets) != 1:
                    residual.append(
                        f"D{domain_id} {row.get('instance', internal)}.{pin} "
                        f"effective={','.join(sorted(nets)) or '<none>'}"
                    )

        watched = {
            "RAILCUT_VDDPST_SEGMENT_MISMATCH",
            "RAILCUT_VSSPST_SEGMENT_MISMATCH",
            # V129 CORRECTION: swapped to match the configured library token=CW/configured library token=CCW
            # fix - these strings must match whatever
            # _global_net_apply_railcut_vsspst_boundary_rules actually emits
            # (issue_name = f"RAILCUT_{pin}_{side_label}_DOMAIN_MISMATCH").
            "RAILCUT_VSSPST1_CW_DOMAIN_MISMATCH",
            "RAILCUT_VSSPST2_CCW_DOMAIN_MISMATCH",
            "VDDPST_DOMAIN_NET_NOT_UNIQUE",
            "VSSPST_DOMAIN_NET_NOT_UNIQUE",
            "ESD_DOMAIN_NET_NOT_UNIQUE",
        }
        for issue in comp.get("policy_issues", []):
            name = str(issue.get("issue", "") or "")
            pin = str(issue.get("pin", "") or "").upper()
            if name in watched or (
                name == "IO_DOMAIN_NET_MISMATCH" and pin == _iopadt_expand_text("__IOPADT_LITERAL_013__")
            ):
                residual.append(
                    f"{name}: {issue.get('detail', issue.get('actual', ''))}"
                )

        # Stable de-dup for concise diagnostics.
        out = []
        seen = set()
        for item in residual:
            if item in seen:
                continue
            seen.add(item)
            out.append(item)
        return out

    def _global_net_auto_prepare_domain_supplies_pending(self, reason="IO working copy PASS"):
        """Prepare __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__ in GUI memory and verify the repair.

        V128.13 keeps deterministic domain repair and additionally repairs __IOPADT_LITERAL_003__ __IOPADT_LITERAL_009__/__IOPADT_LITERAL_010__ boundary pins.
        The repair derives directly from __IOPADT_LITERAL_003__ domain membership, then runs a
        fresh logical comparison and reports whether the three-pin repair is
        complete. Innovus DB remains untouched until Apply Global Net.
        """
        if not self.entries or not self.facts:
            return False
        if not (self.global_net_path or self.global_net_lines):
            return False

        comp = self._global_net_compare_design(force_db_actual=False)
        changes = []
        skipped = []
        undo_taken = {"value": False}

        def ensure_undo():
            if undo_taken["value"]:
                return
            self._global_net_push_undo(
                "Auto Prepare Domain Global Nets after IO PASS"
            )
            undo_taken["value"] = True

        targets = self._global_net_reconcile_domain_supply_pins_pending(
            comp,
            ensure_undo,
            changes,
            skipped,
            origin="GN_AUTO_PREPARE_IO_PASS_DOMAIN_SUPPLY",
        )
        # V128.13: configured library token itself has configured library token/configured library token rather than configured library token.
        # Bind the two boundary pins to the already-reconciled adjacent domain
        # targets: pin1=CW, pin2=CCW (V129: swapped from CCW/CW per physical
        # layout). Still pending-only until Apply GN.
        self._global_net_reconcile_railcut_vsspst_boundary_pending(
            comp, targets, ensure_undo, changes, skipped,
            origin="GN_AUTO_PREPARE_IO_PASS_RAILCUT_VSSPST",
        )

        if changes:
            self._global_net_mark_check_stale(
                _iopadt_expand_text(_iopadt_expand_text("IO PASS auto-prepared __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__ pending mappings"))
            )
            self._global_net_refresh_tree()
            self._global_net_repair_refresh()

        # Always verify the current pending Tcl, even if this invocation made
        # no textual change. That makes an already-correct pending model visible
        # as repaired instead of silently returning "no change".
        self._menu_check_global_net(
            force_db_actual=False,
            post_apply=False,
            interactive=False,
        )
        verified = self.global_net_last_check_result or self._global_net_compare_design(force_db_actual=False)
        residual = self._global_net_domain_supply_residuals(verified)
        complete = not residual

        if changes:
            self._set_global_net_apply_state(
                "GLOBAL_NET_DIRTY",
                apply_result="PENDING",
                check_result=self.global_net_check_state,
            )

        if undo_taken["value"] and not changes and self.global_net_undo_stack:
            self.global_net_undo_stack.pop()
            self._global_net_update_history_text()

        target_text = ", ".join(
            f"D{d}:{pin}={net}"
            for (d, pin), net in sorted(
                targets.items(),
                key=lambda kv: (
                    (0, int(kv[0][0])) if str(kv[0][0]).isdigit() else (1, str(kv[0][0])),
                    kv[0][1],
                ),
            )
        )
        state_text = "PASS" if complete else "INCOMPLETE"
        msg = (
            f"AUTO DOMAIN SUPPLY REPAIR: {state_text} | "
            f"changed={len(changes)} | targets={len(targets)}"
        )
        if changes:
            msg += " | APPLY GLOBAL NET REQUIRED"
        if residual:
            msg += f" | residual={len(residual)}"
        if skipped:
            msg += f" | skipped={len(skipped)}"

        self.global_net_repair_status.set(msg)
        self.global_net_status.set(msg)
        self.status.set(msg)
        dbg(
            "GLOBAL_NET_AUTO_PREPARE_IO_PASS "
            f"reason={reason} changed={len(changes)} targets={len(targets)} "
            f"complete={int(complete)} residual={len(residual)} skipped={len(skipped)} "
            f"targets=[{target_text}] residual_detail=[{' | '.join(residual)}] "
            f"apply_state={self.global_net_apply_state} check_state={self.global_net_check_state}"
        )
        return bool(changes)

    def _io_domain_id_from_tree_label(self, label):
        """"D3" -> "3" (matches the str(domain_id) keys used everywhere
        else); returns "" if the row's IO Domain cell doesn't parse."""
        m = re.match(r"^D(\S+)$", str(label or "").strip())
        return m.group(1) if m else ""

    def _io_domain_cell_resolve(self, event):
        """Shared hit-testing for the IO Domain Sources tree: given a
        click event, return (domain_id, pin) if it landed on a settable
        Net column of a valid row, else (None, None). Also selects that
        row so right-click/double-click both leave a visible selection
        matching what a left-click would have done."""
        tree = self.domains
        row_id = tree.identify_row(event.y)
        col_id = tree.identify_column(event.x)
        if not row_id or not col_id:
            return None, None

        tree.selection_set(row_id)
        tree.focus(row_id)

        cols = tree.cget("columns")
        try:
            col_index = int(col_id[1:]) - 1
            col_key = cols[col_index]
        except (ValueError, IndexError):
            return None, None

        pin = IO_DOMAIN_TREE_COLUMN_TO_PIN.get(col_key)
        if pin is None:
            return None, None
        values = tree.item(row_id, "values")
        if not values:
            return None, None
        domain_id = self._io_domain_id_from_tree_label(values[0])
        if not domain_id:
            return None, None
        return domain_id, pin

    def _on_io_domain_cell_right_click(self, event):
        """V129: PRIMARY way to Set a value - left-click selects a row
        (native Treeview behavior), right-click on a __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__/
        __IOPADT_LITERAL_014__/__IOPADT_LITERAL_006__ Net cell selects that row AND opens the Set
        prompt for it directly, in one action. Right-clicking any other
        column just selects the row, same as a left-click would."""
        domain_id, pin = self._io_domain_cell_resolve(event)
        if domain_id is None:
            return
        self._global_net_prompt_set_domain_pin(domain_id, pin)

    def _on_io_domain_cell_double_click(self, event):
        """V129: double-click a __IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__/__IOPADT_LITERAL_014__/__IOPADT_LITERAL_006__ Net cell on
        the IO Domain Sources table to Set (or clear) a manual target for
        that (IO Domain, pin). Clicking any other column does nothing.

        This is a secondary shortcut kept for anyone used to that
        gesture; right-click (_on_io_domain_cell_right_click) and the
        explicit "Set Pin Target..." button are the primary, documented
        ways to do the same thing."""
        domain_id, pin = self._io_domain_cell_resolve(event)
        if domain_id is None:
            return
        self._global_net_prompt_set_domain_pin(domain_id, pin)

    def _global_net_prompt_set_domain_pin(self, domain_id, pin):
        """Shared prompt-and-apply logic for setting one (IO Domain, pin)
        manual Global Net target. Called from both the cell double-click
        shortcut and the explicit "Set Pin Target..." button."""
        if not (self.global_net_path or self.global_net_lines):
            self._show_copyable_warning(
                "Set IO Domain Global Net",
                "Load Global Net Tcl first.",
            )
            return

        current_manual = self._global_net_get_domain_manual_target(domain_id, pin)
        new_value = simpledialog.askstring(
            f"Set {pin} for IO Domain D{domain_id}",
            f"{pin} net for IO Domain D{domain_id}\n"
            + (
                "(unique across every IO Domain)"
                if pin in GLOBAL_NET_DOMAIN_EXCLUSIVE_PINS
                else "(shared across IO Domains is fine; must just be "
                "consistent within this one)"
            )
            + "\n\nLeave blank to clear the manual target and fall back "
            "to the automatic guess.",
            initialvalue=current_manual,
            parent=self,
        )
        if new_value is None:
            return  # Cancelled.

        try:
            self._global_net_set_domain_manual_target(domain_id, pin, new_value)
        except ValueError as exc:
            self._show_copyable_error("Set IO Domain Global Net", str(exc))
            return

        self.global_net_repair_status.set(
            f"D{domain_id} {pin} target set to "
            f"{new_value.strip() or '<cleared>'}. Press Repair Selected "
            "Domain (or Auto Repair) to push it into pending Tcl."
        )
        if self.repair_entries:
            self._repair_simulate()
        else:
            self.refresh_all()

    def _global_net_set_selected_domain_pin(self):
        """V129: explicit, discoverable "Set Pin Target..." button - does
        not depend on a double-click landing on the exact right cell.
        Select a domain row, click this, pick a pin, type a net."""
        sel = self.domains.selection()
        if not sel:
            self.global_net_repair_status.set(
                "Select an IO Domain row first."
            )
            return
        values = self.domains.item(sel[0], "values")
        domain_id = self._io_domain_id_from_tree_label(values[0]) if values else ""
        if not domain_id:
            return

        pin_choice = simpledialog.askstring(
            f"Set Pin Target for IO Domain D{domain_id}",
            "Which pin? One of:\n  "
            + ", ".join(GLOBAL_NET_DOMAIN_SETTABLE_PINS)
            + _iopadt_expand_text(_iopadt_expand_text("\n\n(__IOPADT_LITERAL_004__/__IOPADT_LITERAL_005__/__IOPADT_LITERAL_013__/__IOPADT_LITERAL_014__ must be unique per IO "
            "Domain; __IOPADT_LITERAL_006__ may be shared across domains.)")),
            parent=self,
        )
        if pin_choice is None:
            return  # Cancelled.
        pin = pin_choice.strip().upper()
        if pin not in GLOBAL_NET_DOMAIN_SETTABLE_PINS:
            self._show_copyable_error(
                "Set Pin Target",
                f"'{pin_choice}' is not one of: "
                + ", ".join(GLOBAL_NET_DOMAIN_SETTABLE_PINS),
            )
            return

        self._global_net_prompt_set_domain_pin(domain_id, pin)

    def _global_net_clear_selected_domain_manual_targets(self):
        sel = self.domains.selection()
        if not sel:
            self.global_net_repair_status.set(
                "Select an IO Domain row first."
            )
            return
        values = self.domains.item(sel[0], "values")
        domain_id = self._io_domain_id_from_tree_label(values[0]) if values else ""
        if not domain_id:
            return
        cleared = 0
        for pin in GLOBAL_NET_DOMAIN_SETTABLE_PINS:
            if self._global_net_get_domain_manual_target(domain_id, pin):
                self._global_net_set_domain_manual_target(domain_id, pin, "")
                cleared += 1
        self.global_net_repair_status.set(
            f"D{domain_id}: cleared {cleared} manual target(s)."
        )
        if self.repair_entries:
            self._repair_simulate()
        else:
            self.refresh_all()

    def _global_net_repair_selected_domain(self):
        """V129: run the same deterministic repair as the big Auto Repair
        button, but scoped to ONLY the selected IO Domain (via
        only_domain_id on the three per-pin repair helpers), so the other
        7 domains are never touched. Whatever was Set (double-click) wins;
        pins with no manual target still get the automatic guess, exactly
        like a normal Auto Repair would for that domain."""
        if not self._require_io_pad_pass_for_global_net_edit():
            return

        sel = self.domains.selection()
        if not sel:
            self.global_net_repair_status.set(
                "Select an IO Domain row first."
            )
            return
        values = self.domains.item(sel[0], "values")
        domain_id = self._io_domain_id_from_tree_label(values[0]) if values else ""
        if not domain_id:
            return

        if not self.entries or not self.facts:
            self._show_copyable_warning(
                "Repair Selected Domain",
                "Load CHIP.io and Innovus TSV first.",
            )
            return
        if not (self.global_net_path or self.global_net_lines):
            self._show_copyable_warning(
                "Repair Selected Domain",
                "Load global_net.tcl first.",
            )
            return

        self._menu_check_global_net()
        comp = self._global_net_checked_result()
        if comp is None:
            self.global_net_repair_status.set(
                f"Repair D{domain_id}: no current comparison result."
            )
            return

        changes = []
        skipped = []
        undo_taken = {"value": False}

        def ensure_undo():
            if undo_taken["value"]:
                return
            self._global_net_push_undo(
                f"Repair IO Domain D{domain_id}"
            )
            undo_taken["value"] = True

        comp = self._global_net_compare_design(force_db_actual=False)
        self._global_net_reconcile_domain_supply_pins_pending(
            comp, ensure_undo, changes, skipped,
            origin="GN_AUTO_REPAIR_DOMAIN_SUPPLY",
            only_domain_id=domain_id,
        )

        comp = self._global_net_compare_design(force_db_actual=False)
        self._global_net_auto_repair_j(
            comp, ensure_undo, changes, skipped,
            only_domain_id=domain_id,
        )

        comp = self._global_net_compare_design(force_db_actual=False)
        self._global_net_auto_repair_vdd_consistency(
            comp, ensure_undo, changes, skipped,
            only_domain_id=domain_id,
        )

        comp = self._global_net_compare_design(force_db_actual=False)
        self._global_net_auto_repair_rte_signal(
            comp, ensure_undo, changes, skipped,
            only_domain_id=domain_id,
        )

        if changes:
            self._global_net_mark_check_stale(
                f"Repaired IO Domain D{domain_id}"
            )
            self._global_net_refresh_tree()
            self._global_net_repair_refresh()

        msg = (
            f"Repair D{domain_id}: changed={len(changes)} skipped={len(skipped)}"
        )
        self.global_net_repair_status.set(msg)
        self.global_net_status.set(msg)
        self.status.set(msg)
        dbg(
            "GLOBAL_NET_REPAIR_ONE_DOMAIN "
            f"domain={domain_id} changed={len(changes)} skipped={len(skipped)} "
            f"changes=[{' | '.join(changes)}] skipped_detail=[{' | '.join(skipped)}]"
        )

        if self.repair_entries:
            self._repair_simulate()
        else:
            self.refresh_all()

        if changes or skipped:
            self._show_copyable_info(
                f"Repair IO Domain D{domain_id}",
                f"Changed: {len(changes)}\n"
                + "\n".join(changes[:30])
                + ("\n..." if len(changes) > 30 else "")
                + (
                    f"\n\nSkipped: {len(skipped)}\n" + "\n".join(skipped[:30])
                    if skipped
                    else ""
                ),
            )

    def _global_net_auto_repair(self):
        if not self._require_io_pad_pass_for_global_net_edit():
            return

        """
        User-triggered Global Net repair.

        Check itself never mutates Tcl. This function is the explicit repair
        entry point requested for E/F/G/H/I/J.
        """
        if not self.entries or not self.facts:
            self._show_copyable_warning(
                "Auto Repair Global Net",
                "Load CHIP.io and Innovus TSV first.",
            )
            return False

        if not (self.global_net_path or self.global_net_lines):
            self._show_copyable_warning(
                "Auto Repair Global Net",
                "Load global_net.tcl first.",
            )
            return False

        # Explicit repair action gets one current comparison. A failing check
        # is expected; the cached result is still the repair input.
        self._menu_check_global_net()
        comp = self._global_net_checked_result()

        if comp is None:
            self.global_net_repair_status.set(
                "Auto Repair Global Net: no current comparison result."
            )
            return False

        changes = []
        skipped = []
        undo_taken = {"value": False}

        def ensure_undo():
            if undo_taken["value"]:
                return

            self._global_net_push_undo(
                "Auto Repair Global Net"
            )
            undo_taken["value"] = True

        # H first: keep only the whole-ring configured library token authority; configured library token is domain-scoped.
        self._global_net_auto_repair_h(
            comp,
            ensure_undo,
            changes,
            skipped,
        )

        # V128.13: deterministically repair domain supplies plus configured library token configured library token/configured library token
        # directly from domain membership BEFORE legacy F/G/I popup rules.
        # This does not touch Innovus DB; it only appends/updates pending Tcl.
        comp = self._global_net_compare_design(force_db_actual=False)
        targets = self._global_net_reconcile_domain_supply_pins_pending(
            comp,
            ensure_undo,
            changes,
            skipped,
            origin="GN_AUTO_REPAIR_DOMAIN_SUPPLY",
        )
        self._global_net_reconcile_railcut_vsspst_boundary_pending(
            comp, targets, ensure_undo, changes, skipped,
            origin="GN_AUTO_REPAIR_RAILCUT_VSSPST",
        )

        # Recompute effective working Tcl after deterministic domain repair.
        comp = self._global_net_compare_design(force_db_actual=False)

        # F/G/I domain-specific choices for the remaining policies.
        self._global_net_auto_repair_domain_choices(
            comp,
            ensure_undo,
            changes,
            skipped,
        )

        comp = self._global_net_compare_design()

        # K V128.8: configured library token/configured library token/configured library token must be mutually exclusive between
        # different configured library token-defined IO Domains.
        self._global_net_auto_repair_domain_exclusivity(
            comp,
            ensure_undo,
            changes,
            skipped,
        )

        comp = self._global_net_compare_design()

        # J deterministic configured library token naming.
        self._global_net_auto_repair_j(
            comp,
            ensure_undo,
            changes,
            skipped,
        )

        comp = self._global_net_compare_design()

        # L (V129): configured library token domain-consistency only (no cross-domain exclusivity
        # requirement - sharing one configured library token across multiple IO Domains is fine).
        self._global_net_auto_repair_vdd_consistency(
            comp,
            ensure_undo,
            changes,
            skipped,
        )

        comp = self._global_net_compare_design()

        # M (V129): configured library token is a SIGNAL pin repaired via connect_pin, not a
        # connect_global_net rule - see _global_net_auto_repair_rte_signal.
        # It only records/updates the manual target here; the actual
        # create_net/connect_pin commands are generated at Apply Global
        # Net time by _global_net_rte_apply_tcl_block().
        self._global_net_auto_repair_rte_signal(
            comp,
            ensure_undo,
            changes,
            skipped,
        )

        comp = self._global_net_compare_design()

        # E safe automatic missing mapping cleanup.
        self._global_net_auto_repair_missing(
            comp,
            ensure_undo,
            changes,
            skipped,
        )

        # V79: resolve final Tcl command conflicts too. This runs after the
        # electrical/domain repair because those mutations may create or expose
        # overlapping connect_global_net targets.
        self._global_net_auto_repair_cmd_conflicts(
            ensure_undo,
            changes,
            skipped,
        )

        if not changes:
            if undo_taken["value"] and self.global_net_undo_stack:
                self.global_net_undo_stack.pop()
                self._global_net_update_history_text()

            msg = "Auto Repair Global Net: no change."

            if skipped:
                msg += " | " + "; ".join(skipped)

            self.global_net_repair_status.set(msg)
            self.global_net_status.set(msg)
            return False

        self._global_net_mark_check_stale(
            "auto repair changed working copy"
        )
        self._global_net_refresh_tree()
        self._global_net_repair_refresh()

        # V129 FIX: this main pipeline never refreshed the IO Domain
        # Sources table (self.domains), unlike _global_net_repair_selected_
        # domain() which already does. configured library token repair in particular only
        # updates state that table displays (self.global_net_domain_pin_
        # manual_targets, read by _global_net_domain_pin_matrix()) - with
        # no rebuild here, D2..D8 getting auto-assigned RTE_D2..RTE_D8 was
        # correctly recorded (confirmed in the debug log) but never became
        # visible, looking exactly like "Auto Repair does nothing" even
        # though it worked.
        if self.repair_entries:
            self._repair_simulate()
        else:
            self.refresh_all()

        # One final explicit verification after all repair mutations.
        self._menu_check_global_net(force_db_actual=False)
        _domain_supply_residual = self._global_net_domain_supply_residuals(
            self.global_net_last_check_result or {}
        )
        dbg(
            "GLOBAL_NET_AUTO_REPAIR_DOMAIN_VERIFY "
            f"residual={len(_domain_supply_residual)} "
            + " | ".join(_domain_supply_residual)
        )

        msg = (
            "Auto Repair Global Net: "
            f"changed={len(changes)}"
        )

        if skipped:
            msg += (
                f" | skipped={len(skipped)}"
                " | "
                + "; ".join(skipped[:10])
            )

            if len(skipped) > 10:
                msg += f"; ... +{len(skipped)-10} more"

        self.global_net_repair_status.set(msg)
        self.global_net_status.set(msg)
        return True

    def _global_net_append_gui_command(
        self,
        line,
        origin,
        metadata=None,
    ):
        if not self._require_io_pad_pass_for_global_net_edit(
            interactive=False,
        ):
            raise PermissionError(
                _iopadt_expand_text("IO __IOPADT_LITERAL_001__ Check must be current PASS before Global Net edit.")
            )

        if not self.global_net_path:
            raise ValueError(
                "Load Global Net Tcl before creating edited commands."
            )

        self._global_net_push_undo(
            "Add "
            + (
                _iopadt_expand_text("Single-__IOPADT_LITERAL_001__ Global Net override")
                if origin == "GN_SINGLE_PAD_EDIT"
                else "connect_global_net command"
            )
        )

        self.global_net_rule_seq += 1
        rid = f"GN{self.global_net_rule_seq:04d}"

        row = {
            "id": rid,
            "line_index": None,
            "line": line,
            "deleted": False,
            "added": True,
            "origin": origin,
        }

        if metadata:
            row.update(metadata)

        self.global_net_rules.append(row)
        self.global_net_selected_id = rid

        self._global_net_mark_check_stale(
            "command added"
        )
        self._global_net_refresh_tree()
        self._global_net_repair_refresh()

        return rid

    def _global_net_new_cmd_commit(
        self,
        win,
        vars_,
        close_after=True,
    ):
        try:
            rule_type = vars_["type"].get().strip()
            net = vars_["net"].get().strip()
            pin = vars_["pin"].get().strip()

            if not net and not vars_["disconnect"].get():
                raise ValueError(
                    "Global Net Name is required unless -disconnect is used."
                )

            if (
                rule_type == "pg_pin"
                and not pin
                and not vars_["all"].get()
            ):
                raise ValueError(
                    "pg_pin requires Pin Base Name, or enable -all."
                )

            line = self._gn_build_command(
                net=net,
                rule_type=rule_type,
                pin=pin,
                inst_base_name=vars_["inst"].get().strip(),
                single_inst=vars_["single"].get().strip(),
                hinst=vars_["hinst"].get().strip(),
                power_domain=vars_["pd"].get().strip(),
                net_base_name=vars_["netbase"].get().strip(),
                region=vars_["region"].get().strip(),
                all_flag=vars_["all"].get(),
                auto_tie=vars_["autotie"].get(),
                disconnect=vars_["disconnect"].get(),
                netlist_override=vars_["netlist_override"].get(),
                non_hierarchical=vars_["nonhier"].get(),
                override=vars_["override"].get(),
                verbose=vars_["verbose"].get(),
            )

            self._global_net_validate_manual_command(
                line
            )

            rid = self._global_net_append_gui_command(
                line,
                "GN_GENERIC_CMD",
            )

            self.global_net_repair_status.set(
                f"Added {rid}: {line.strip()}"
            )
            if close_after:
                win.destroy()
            return True

        except Exception as exc:
            self._show_copyable_error(
                "New Global Net Command",
                str(exc),
                parent=win,
            )

