    def _global_net_find_gui_single_pad_override(
        self,
        internal,
        pin,
        include_auto=False,
    ):
        """Find an in-memory exact single-__IOPADT_LITERAL_001__ tool override.

        Manual editing should only reuse GN_SINGLE_PAD_EDIT. Auto-repair may
        also reuse its own prior GN_AUTO* rows, AND (V129 fix) rows restored
        by parsing a previously-saved Global Net Tcl
        (GN_RESTORED_SINGLE_PAD, backfilled in _global_net_detect_rules),
        so repeated repair across a Save+reload cycle does not keep
        appending duplicate exact rules for the same target.
        """
        for r in reversed(self.global_net_rules):
            if r.get("deleted"):
                continue

            origin = str(r.get("origin", "") or "")
            if origin != "GN_SINGLE_PAD_EDIT":
                if not (
                    include_auto
                    and (
                        origin.startswith("GN_AUTO")
                        or origin == "GN_RESTORED_SINGLE_PAD"
                    )
                ):
                    continue

            if (
                r.get("target_internal") == internal
                and r.get("target_pin") == pin
            ):
                return r

        return None

    def _global_net_single_pad_commit(
        self,
        win,
        vars_,
        original_internal,
        original_pin,
        close_after=True,
    ):
        try:
            net = vars_["net"].get().strip()
            inst = vars_["inst"].get().strip()
            pin = vars_["pin"].get().strip()
            pd = vars_["pd"].get().strip()

            if not net or not inst or not pin:
                raise ValueError(
                    "Net / Instance / Pin cannot be empty."
                )

            line = self._gn_build_command(
                net=net,
                rule_type="pg_pin",
                pin=pin,
                single_inst=inst,
                power_domain=pd,
                override=vars_["override"].get(),
                netlist_override=vars_["netlist_override"].get(),
            )

            self._global_net_validate_manual_command(
                line
            )

            existing = self._global_net_find_gui_single_pad_override(
                original_internal,
                original_pin,
            )

            if existing is None:
                rid = self._global_net_append_gui_command(
                    line,
                    "GN_SINGLE_PAD_EDIT",
                    {
                        "target_internal": original_internal,
                        "target_pin": original_pin,
                    },
                )
            else:
                self._global_net_push_undo(
                    _iopadt_expand_text("Edit Single-__IOPADT_LITERAL_001__ Global Net override ")
                    + str(existing.get("id", ""))
                )
                existing["line"] = line
                existing["target_internal"] = original_internal
                existing["target_pin"] = original_pin
                rid = existing["id"]
                self._global_net_mark_check_stale(
                    _iopadt_expand_text("Single-__IOPADT_LITERAL_001__ mapping updated")
                )
                self._global_net_refresh_tree()
                self._global_net_repair_refresh()

            self.global_net_repair_pin.set(pin)
            self.global_net_repair_status.set(
                _iopadt_expand_text(f"Single-__IOPADT_LITERAL_001__ mapping {rid}: {line.strip()}")
            )
            if close_after:
                win.destroy()
            return True

        except Exception as exc:
            self._show_copyable_error(
                _iopadt_expand_text("Edit Single __IOPADT_LITERAL_001__ Global Net"),
                str(exc),
                parent=win,
            )

    def _global_net_open_single_pad_dialog(self):
        if not self._require_io_pad_pass_for_global_net_edit():
            return

        internal, fact = self._global_net_repair_current_fact()

        if internal is None or fact is None:
            self._show_copyable_warning(
                _iopadt_expand_text("Edit Single __IOPADT_LITERAL_001__ Global Net"),
                _iopadt_expand_text("Select a __IOPADT_LITERAL_001__ / ring object first."),
            )
            return

        pin = self.global_net_repair_pin.get().strip()

        if not pin:
            self._show_copyable_warning(
                _iopadt_expand_text("Edit Single __IOPADT_LITERAL_001__ Global Net"),
                "Select one actual PG pin first.",
            )
            return

        if not self.global_net_path:
            self._show_copyable_warning(
                _iopadt_expand_text("Edit Single __IOPADT_LITERAL_001__ Global Net"),
                "Load global_net.tcl first.",
            )
            return

        display = (
            self._repair_display_name(internal)
            if self.repair_entries
            else internal
        )

        current_net = ""
        current_pd = ""

        try:
            comp = self._global_net_checked_result()

            if comp is None:
                raise LookupError("Global Net check is not current")

            pres = (
                comp.get("pads", {})
                .get(internal, {})
                .get("pin_results", {})
                .get(pin, {})
            )
            nets = sorted(
                self._gn_resolved_net_set(pres)
            )
            current_net = nets[0] if len(nets) == 1 else ""
            scope = str(pres.get("selected_scope", "") or "")

            if scope.startswith("PD="):
                current_pd = scope[3:]
        except Exception:
            pass

        existing = self._global_net_find_gui_single_pad_override(
            internal,
            pin,
        )

        if existing:
            parsed = self._gn_parse_connect_line(
                existing["line"]
            )

            if parsed:
                current_net = parsed.get("net", current_net)
                display = parsed.get("single_inst", display) or display
                pin = parsed.get("pin", pin) or pin
                current_pd = parsed.get("power_domain", current_pd)

        old = self.global_net_single_pad_dialog
